/** Small numeric helpers shared by the simulation. All allocation-free. */

export const DEG = Math.PI / 180;

export function clamp(value: number, min: number, max: number): number {
  return value < min ? min : value > max ? max : value;
}

export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

/** Hermite 0..1 between `edge0` and `edge1`; works with edge0 > edge1 (falling). */
export function smoothstep(edge0: number, edge1: number, x: number): number {
  if (edge1 === edge0) return x < edge0 ? 0 : 1;
  const t = clamp((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

/** Move `value` towards `target` by at most `maxDelta`. */
export function approach(value: number, target: number, maxDelta: number): number {
  return value < target ? Math.min(target, value + maxDelta) : Math.max(target, value - maxDelta);
}

/** Fraction of the remaining gap a first-order lag with time constant `tauS` closes in `dtS`. */
export function follow(dtS: number, tauS: number): number {
  return tauS <= 0 ? 1 : 1 - Math.exp(-dtS / tauS);
}

/** `value` if it is a finite number, else `fallback`. */
export function finite(value: number, fallback: number): number {
  return Number.isFinite(value) ? value : fallback;
}

/** Rounds points to the nearest 10 so the numbers that pop up look tidy. */
export function tidyPoints(points: number): number {
  return Math.max(10, Math.round(points / 10) * 10);
}
