/** Allocation-free measurements for `VisionStats`. Pure: no DOM. */

/** Events per second over a sliding time window. */
export class RateMeter {
  private readonly times: Float64Array;
  private head = 0;
  private count = 0;

  /** `capacity` must exceed the most events expected within one window. */
  constructor(
    private readonly windowMs = 1000,
    capacity = 128,
  ) {
    this.times = new Float64Array(capacity);
  }

  record(timeMs: number): void {
    this.times[this.head] = timeMs;
    this.head = (this.head + 1) % this.times.length;
    if (this.count < this.times.length) this.count++;
  }

  /**
   * The rate over the window ending at `nowMs`. Steady streams read their exact rate; when
   * events stop, the reading decays to zero instead of freezing at the last value.
   */
  rate(nowMs: number): number {
    const { times } = this;
    const capacity = times.length;
    let n = 0;
    let oldest = 0;
    let newest = Number.NEGATIVE_INFINITY;
    for (let i = 0; i < this.count; i++) {
      const time = times[(this.head - 1 - i + capacity) % capacity] as number;
      if (nowMs - time > this.windowMs) break;
      if (n === 0) newest = time;
      oldest = time;
      n++;
    }
    if (n < 2) return 0;
    const span = newest - oldest;
    if (span <= 0) return 0;
    const interval = span / (n - 1);
    // A gap well beyond the usual interval means the stream stalled: count it.
    const stalled = nowMs - newest > 2 * interval;
    return ((n - 1) * 1000) / (stalled ? nowMs - oldest : span);
  }

  reset(): void {
    this.head = 0;
    this.count = 0;
  }
}

/** Percentiles over the most recent `capacity` samples. */
export class RollingPercentiles {
  /** Samples in arrival order (ring buffer). */
  private readonly ring: Float64Array;
  /** The same samples, kept sorted. */
  private readonly sorted: Float64Array;
  private head = 0;
  private count = 0;

  constructor(capacity = 120) {
    this.ring = new Float64Array(capacity);
    this.sorted = new Float64Array(capacity);
  }

  get size(): number {
    return this.count;
  }

  add(value: number): void {
    const { ring, sorted } = this;
    if (this.count === ring.length) {
      // Evict the oldest sample from the sorted copy.
      const evicted = ring[this.head] as number;
      const at = this.lowerBound(evicted);
      sorted.copyWithin(at, at + 1, this.count);
      this.count--;
    }
    ring[this.head] = value;
    this.head = (this.head + 1) % ring.length;
    const at = this.lowerBound(value);
    sorted.copyWithin(at + 1, at, this.count);
    sorted[at] = value;
    this.count++;
  }

  /** Nearest-rank percentile, `p` in 0..1; 0 when empty. */
  percentile(p: number): number {
    if (this.count === 0) return 0;
    const rank = Math.min(this.count - 1, Math.max(0, Math.ceil(p * this.count) - 1));
    return this.sorted[rank] as number;
  }

  reset(): void {
    this.head = 0;
    this.count = 0;
  }

  private lowerBound(value: number): number {
    let low = 0;
    let high = this.count;
    while (low < high) {
      const mid = (low + high) >>> 1;
      if ((this.sorted[mid] as number) < value) low = mid + 1;
      else high = mid;
    }
    return low;
  }
}
