/**
 * The HUD font: Fredoka Bold (SIL Open Font License, see public/art/CREDITS.md), a chunky
 * rounded face that reads from across a room. Loaded from `public/art/fonts` relative to
 * the page, like every public asset, because the site is served under a sub-path.
 */
export const FONT_FAMILY = 'Fredoka';
/** Used until the font has loaded, or if it never does. */
export const FONT_STACK = `${FONT_FAMILY}, "Arial Rounded MT Bold", "Trebuchet MS", system-ui, sans-serif`;

const FONT_FILE = 'art/fonts/fredoka-700-latin.woff2';
/** A slow network must not hold up the game: after this the fallback font is used. */
const LOAD_TIMEOUT_MS = 4000;

let loading: Promise<void> | null = null;

export function loadFonts(): Promise<void> {
  if (loading) return loading;
  loading = (async () => {
    if (typeof FontFace === 'undefined') return;
    try {
      const base = new URL(import.meta.env.BASE_URL, document.baseURI);
      const face = new FontFace(FONT_FAMILY, `url(${new URL(FONT_FILE, base).href})`, {
        weight: '700',
      });
      const timeout = new Promise<null>((resolve) =>
        setTimeout(() => resolve(null), LOAD_TIMEOUT_MS),
      );
      const loaded = await Promise.race([face.load(), timeout]);
      if (loaded) document.fonts.add(loaded);
    } catch {
      // The fallback stack still looks fine.
    }
  })();
  return loading;
}
