/**
 * `showCamera`: the whole camera picture over the game, semi-transparent and mirrored like
 * the view, with the mask tint and the pose skeleton on top, so tracking can be checked
 * against what the game does with it. Off by default; costs nothing while off.
 */
import { Container, Graphics, Sprite, type Texture } from 'pixi.js';
import type { Tunables } from '../config/tunables';
import type { PersonMask } from '../core/mask';
import { Landmark, POSE_STRIDE, type PoseFrame } from '../core/pose';
import { sourceToWorld, type ViewTransform } from '../core/view';
import { MaskOverlay, placeOnVideo } from './maskOverlay';
import { PALETTE as P } from './palette';

const PICTURE_ALPHA = 0.55;

/** Pairs of landmarks joined by the skeleton's bones. */
const BONES: readonly (readonly [number, number])[] = [
  [Landmark.leftShoulder, Landmark.rightShoulder],
  [Landmark.leftShoulder, Landmark.leftElbow],
  [Landmark.leftElbow, Landmark.leftWrist],
  [Landmark.rightShoulder, Landmark.rightElbow],
  [Landmark.rightElbow, Landmark.rightWrist],
  [Landmark.leftShoulder, Landmark.leftHip],
  [Landmark.rightShoulder, Landmark.rightHip],
  [Landmark.leftHip, Landmark.rightHip],
  [Landmark.leftHip, Landmark.leftKnee],
  [Landmark.leftKnee, Landmark.leftAnkle],
  [Landmark.rightHip, Landmark.rightKnee],
  [Landmark.rightKnee, Landmark.rightAnkle],
  [Landmark.leftAnkle, Landmark.leftFoot],
  [Landmark.rightAnkle, Landmark.rightFoot],
];

export class DebugView {
  readonly container = new Container();
  private readonly tunables: Tunables;
  private readonly picture = new Sprite();
  private readonly mask: MaskOverlay;
  private readonly skeleton = new Graphics();
  private view: ViewTransform | null = null;
  private drawnPose: PoseFrame | null = null;
  private drawnView: ViewTransform | null = null;
  private placedTexture: Texture | null = null;
  private placedWidth = 0;
  private placedView: ViewTransform | null = null;
  private shownMask: PersonMask | null = null;

  constructor(tunables: Tunables) {
    this.tunables = tunables;
    this.mask = new MaskOverlay(tunables);
    this.picture.alpha = PICTURE_ALPHA;
    this.container.addChild(this.picture, this.mask.sprite, this.skeleton);
    this.container.visible = false;
  }

  setView(view: ViewTransform): void {
    this.view = view;
    this.mask.setView(view);
  }

  update(picture: Texture | null, mask: PersonMask | null, pose: PoseFrame | null): void {
    const on = this.tunables.showCamera && this.view !== null;
    this.container.visible = on;
    if (!on || !this.view) return;
    const view = this.view;

    this.picture.visible = picture !== null;
    if (
      picture &&
      (picture !== this.placedTexture ||
        picture.width !== this.placedWidth ||
        view !== this.placedView)
    ) {
      this.picture.texture = picture;
      placeOnVideo(this.picture, view);
      this.placedTexture = picture;
      this.placedWidth = picture.width;
      this.placedView = view;
    }

    if (mask !== this.shownMask) {
      this.shownMask = mask;
      this.mask.setMask(mask, null);
    }
    this.mask.sync();

    if (pose !== this.drawnPose || view !== this.drawnView) {
      this.drawnPose = pose;
      this.drawnView = view;
      this.drawSkeleton(pose, view);
    }
  }

  private drawSkeleton(pose: PoseFrame | null, view: ViewTransform): void {
    const g = this.skeleton;
    g.clear();
    if (!pose?.present) return;
    const lm = pose.landmarks;
    const at = (index: number) =>
      sourceToWorld(
        view,
        (lm[index * POSE_STRIDE] as number) * pose.sourceWidth,
        (lm[index * POSE_STRIDE + 1] as number) * pose.sourceHeight,
        pose.sourceWidth,
        pose.sourceHeight,
      );
    const visible = (index: number) => (lm[index * POSE_STRIDE + 3] as number) >= 0.5;
    for (const [a, b] of BONES) {
      if (!visible(a) || !visible(b)) continue;
      const p = at(a);
      const q = at(b);
      g.moveTo(p.x, p.y).lineTo(q.x, q.y);
    }
    g.stroke({ width: 6, color: P.accent, alpha: 0.9, cap: 'round' });
    for (let i = 0; i < 33; i++) {
      if (!visible(i)) continue;
      const p = at(i);
      g.circle(p.x, p.y, 7);
    }
    g.fill({ color: P.warm, alpha: 0.95 });
  }

  dispose(): void {
    this.mask.dispose();
    this.container.destroy({ children: true });
  }
}
