/**
 * What floats on the wave: sea creatures to collect, boost strips to ride over, hazards to
 * steer round. They arrive in short patterns from beyond the right edge and drift left with
 * the water. Each pickup pattern teaches one move:
 *
 * - `line`: clams in a row along the middle of the face (hold a line).
 * - `wave`: clams weaving gently across the middle of the face (small turns).
 * - `dip`: clams curving down to a crab and a boost strip at the bottom, then back up
 *   (drop, bottom turn, climb): the bottom of a dive is where speed is.
 * - `launch`: a boost strip low on the face, clams climbing to the lip and crabs in an
 *   arc above it (a fast climb into the lip is an air).
 * - `air`: crabs in an arc above the lip.
 * - `deep`: clams leading down to crabs low near the flats (go down, come back up).
 *
 * Hazards (a whirlpool or a buoy) come one at a time in a slot of their own between
 * patterns, never on a pattern's path, with room above and below to pass. None arrive in
 * the first `hazardStartS` of a ride; after that they come a little more often as the ride
 * goes on.
 *
 * The first rides see `line`, `dip`, `launch`, `deep` in that order; after that patterns
 * are drawn at random from the injected rng, so a seed replays the same ride. Objects are
 * pooled: spawning and collecting allocate nothing once the pools have grown.
 */
import type { Tunables } from '../config/tunables';
import type { Rng } from '../core/rng';
import { clamp } from './math';
import type { BoostStrip, Hazard, HazardKind, Pickup, PickupKind } from './types';

export interface Item extends Pickup {
  id: number;
  kind: PickupKind;
  x: number;
  y: number;
  r: number;
  points: number;
}

export interface Strip extends BoostStrip {
  id: number;
  x: number;
  y: number;
  r: number;
}

export interface Danger extends Hazard {
  id: number;
  kind: HazardKind;
  x: number;
  y: number;
  r: number;
  grip: number;
  /** Already hit (buoy) or holding the board this encounter (whirlpool). */
  engaged: boolean;
}

export type PatternKind = 'line' | 'wave' | 'dip' | 'launch' | 'air' | 'deep';

const TEACHING: readonly PatternKind[] = ['line', 'dip', 'launch', 'deep'];
const KINDS: readonly PatternKind[] = ['line', 'wave', 'dip', 'launch', 'air', 'deep'];
const WEIGHTS: readonly number[] = [2, 2, 3, 2, 1, 2];
const CLAM_R = 34;
const CRAB_R = 38;
/** Half the length of a boost strip along the face. */
export const STRIP_R = 85;
export const WHIRLPOOL_R = 80;
export const BUOY_R = 30;
/** Pickups appear this far beyond the right edge. */
const SPAWN_MARGIN = 80;
/** First pattern of a ride starts this far beyond the edge (a moment to settle in). */
const FIRST_DELAY = 500;
/** Gap between the end of one pattern and the start of the next, world units. */
const GAP_MIN = 350;
const GAP_MAX = 750;
/**
 * Clear water before and after a hazard: even when the water brings things slowest this
 * is over half a second to get round it after leaving a pattern, on top of the second or
 * more of seeing it come in from the edge.
 */
export const HAZARD_GAP = 520;
/** Hazard depths: room to pass above and below (a whirlpool is 0.34 of the face across). */
const WHIRLPOOL_DEPTH: readonly [number, number] = [0.45, 0.7];
const BUOY_DEPTH: readonly [number, number] = [0.3, 0.8];
/** Gone this far past the left edge. */
const DESPAWN_X = -160;

export class WaterField {
  /** Live pickups, in no particular order. */
  readonly items: Item[] = [];
  readonly strips: Strip[] = [];
  readonly hazards: Danger[] = [];
  private readonly itemPool: Item[] = [];
  private readonly stripPool: Strip[] = [];
  private readonly hazardPool: Danger[] = [];
  private nextId = 1;
  private taught = 0;
  /** Screen x of the far end of the newest pattern; the next one waits until it is in. */
  private tailX = 0;
  private gap = 0;
  /** The last thing spawned was a hazard (two never come in a row). */
  private lastWasHazard = false;

  /** New ride: clear the water and wait a moment before the first pattern. */
  reset(worldWidth: number): void {
    this.clear();
    this.tailX = worldWidth + FIRST_DELAY;
    this.gap = 0;
    this.lastWasHazard = false;
  }

  clear(): void {
    for (const item of this.items) this.itemPool.push(item);
    for (const strip of this.strips) this.stripPool.push(strip);
    for (const hazard of this.hazards) this.hazardPool.push(hazard);
    this.items.length = 0;
    this.strips.length = 0;
    this.hazards.length = 0;
  }

  /** Drift everything by `dx` and drop what has left the screen. */
  drift(dx: number): void {
    driftList(this.items, this.itemPool, dx);
    driftList(this.strips, this.stripPool, dx);
    driftList(this.hazards, this.hazardPool, dx);
    this.tailX += dx;
  }

  /** The screen changed width: keep everything (and the next pattern) where it was on it. */
  scaleX(scale: number): void {
    for (const item of this.items) item.x *= scale;
    for (const strip of this.strips) strip.x *= scale;
    for (const hazard of this.hazards) hazard.x *= scale;
    this.tailX *= scale;
  }

  /** Take the pickup at `index` out of play (collected). */
  remove(index: number): void {
    removeAt(this.items, this.itemPool, index);
  }

  /** Take the strip at `index` out of play (ridden over). */
  removeStrip(index: number): void {
    removeAt(this.strips, this.stripPool, index);
  }

  /**
   * Start the next pattern once the previous one has come fully into view (plus a gap).
   * `rideS` decides whether a hazard may come instead.
   */
  spawn(
    rng: Rng,
    t: Tunables,
    rideS: number,
    worldWidth: number,
    lipY: number,
    bottomY: number,
  ): void {
    if (this.tailX > worldWidth - this.gap) return;
    const x0 = worldWidth + SPAWN_MARGIN;
    const face = bottomY - lipY;
    const late = rideS - t.hazardStartS;
    if (this.taught >= TEACHING.length && late >= 0 && !this.lastWasHazard) {
      const chance = clamp(t.hazardChance + t.hazardChanceGain * late, 0, t.hazardChanceMax);
      if (rng.next() < chance) {
        const kind: HazardKind = rng.next() < 0.5 ? 'whirlpool' : 'buoy';
        const [lo, hi] = kind === 'whirlpool' ? WHIRLPOOL_DEPTH : BUOY_DEPTH;
        this.addHazard(kind, x0 + HAZARD_GAP, lipY + rng.range(lo, hi) * face);
        this.tailX = x0 + HAZARD_GAP;
        this.gap = HAZARD_GAP;
        this.lastWasHazard = true;
        return;
      }
    }
    this.lastWasHazard = false;
    const kind =
      this.taught < TEACHING.length ? (TEACHING[this.taught++] as PatternKind) : pick(rng);
    const clam = (dx: number, depth: number): void =>
      this.addItem('clam', x0 + dx, lipY + depth * face, t.clamPoints);
    const crab = (dx: number, depth: number): void =>
      this.addItem('crab', x0 + dx, lipY + depth * face, t.crabPoints);
    const strip = (dx: number, depth: number): void => this.addStrip(x0 + dx, lipY + depth * face);
    /** Crabs in an arc above the lip, starting `dx` in; returns where it ends. */
    const arc = (dx: number, n: number): number => {
      const apex = rng.range(100, 200);
      for (let i = 0; i < n; i++) {
        const s = Math.sin((Math.PI * (i + 0.5)) / n);
        this.addItem('crab', x0 + dx + i * 80, lipY - 20 - (apex - 20) * s, t.crabPoints);
      }
      return dx + (n - 1) * 80;
    };
    let length = 0;
    switch (kind) {
      case 'line': {
        const depth = rng.range(0.3, 0.55);
        for (let i = 0; i < 5; i++) clam(i * 120, depth);
        length = 4 * 120;
        break;
      }
      case 'wave': {
        const mid = rng.range(0.38, 0.5);
        for (let i = 0; i < 6; i++) clam(i * 130, mid + 0.1 * Math.sin((Math.PI * i) / 2.5));
        length = 5 * 130;
        break;
      }
      case 'dip': {
        const top = rng.range(0.25, 0.4);
        const n = 7;
        for (let i = 0; i < n; i++) {
          if (i === 3) crab(i * 150, 0.9);
          else clam(i * 150, top + (0.88 - top) * Math.sin((Math.PI * i) / (n - 1)));
        }
        strip(3 * 150 + 110, 0.86);
        length = (n - 1) * 150;
        break;
      }
      case 'launch': {
        strip(0, 0.62);
        const n = 4;
        for (let i = 0; i < n; i++) clam(170 + i * 110, 0.45 - (0.4 * i) / (n - 1));
        length = arc(170 + n * 110, 4);
        break;
      }
      case 'air':
        length = arc(0, 5);
        break;
      case 'deep': {
        clam(0, 0.55);
        clam(130, 0.75);
        for (let i = 0; i < 3; i++) crab(260 + i * 130, 0.96 + 0.04 * Math.sin(i * 1.3));
        clam(650, 0.75);
        length = 650;
        break;
      }
    }
    this.tailX = x0 + length;
    this.gap = rng.range(GAP_MIN, GAP_MAX);
  }

  private addItem(kind: PickupKind, x: number, y: number, points: number): void {
    const item = this.itemPool.pop() ?? {
      id: 0,
      kind: 'clam' as PickupKind,
      x: 0,
      y: 0,
      r: CLAM_R,
      points: 0,
    };
    item.id = this.nextId++;
    item.kind = kind;
    item.x = x;
    item.y = y;
    item.r = kind === 'crab' ? CRAB_R : CLAM_R;
    item.points = points;
    this.items.push(item);
  }

  private addStrip(x: number, y: number): void {
    const strip = this.stripPool.pop() ?? { id: 0, x: 0, y: 0, r: STRIP_R };
    strip.id = this.nextId++;
    strip.x = x;
    strip.y = y;
    strip.r = STRIP_R;
    this.strips.push(strip);
  }

  private addHazard(kind: HazardKind, x: number, y: number): void {
    const hazard = this.hazardPool.pop() ?? {
      id: 0,
      kind: 'buoy' as HazardKind,
      x: 0,
      y: 0,
      r: BUOY_R,
      grip: 0,
      engaged: false,
    };
    hazard.id = this.nextId++;
    hazard.kind = kind;
    hazard.x = x;
    hazard.y = y;
    hazard.r = kind === 'whirlpool' ? WHIRLPOOL_R : BUOY_R;
    hazard.grip = 0;
    hazard.engaged = false;
    this.hazards.push(hazard);
  }
}

function driftList<T extends { x: number }>(list: T[], pool: T[], dx: number): void {
  let kept = 0;
  for (let i = 0; i < list.length; i++) {
    const thing = list[i] as T;
    thing.x += dx;
    if (thing.x < DESPAWN_X) pool.push(thing);
    else list[kept++] = thing;
  }
  list.length = kept;
}

function removeAt<T>(list: T[], pool: T[], index: number): void {
  const thing = list[index];
  if (thing === undefined) return;
  pool.push(thing);
  list[index] = list[list.length - 1] as T;
  list.length--;
}

function pick(rng: Rng): PatternKind {
  let total = 0;
  for (const w of WEIGHTS) total += w;
  let roll = rng.next() * total;
  for (let i = 0; i < KINDS.length; i++) {
    roll -= WEIGHTS[i] as number;
    if (roll < 0) return KINDS[i] as PatternKind;
  }
  return 'line';
}
