/**
 * Debug tools for judging detection quality and tuning the game: a HUD of render, camera
 * and model health, a lil-gui tuning panel (loaded the first time the tools are shown, so
 * lil-gui stays out of the main bundle), camera switching, clip loading by picker or drag
 * and drop, and a recorder for the camera stream.
 *
 * Everything sits at the screen edges (HUD bottom-left, panel top-right) so the middle of
 * the play area stays visible, and nothing here runs while the tools are hidden.
 */
import './debug.css';
import type { Game } from '../game/types';
import { errorMessage, formatBytes, formatDuration, isPromiseLike, isVideoFile } from './format';
import { createHudView } from './hud';
import { buildHudRows, type HudGame, type Level } from './hudModel';
import type { Panel } from './panel';
import { createClipRecorder, recordingLabel } from './recorder';
import type { DebugDeps, DebugUi } from './types';

const REFRESH_MS = 250;
const NOTICE_MS = 6000;
const ERROR_NOTICE_MS = 12_000;

const DEG = 180 / Math.PI;

function hudGame(game: Game): HudGame {
  const { control, surfer } = game;
  return {
    phase: game.phase,
    score: game.score,
    rideS: game.rideS,
    speed: surfer.speed,
    boardDeg: surfer.angle * DEG,
    tiltDeg: control.tilt * DEG,
    source: control.source,
    tracked: control.tracked,
    posed: control.posed,
  };
}

function describeSource(kind: string, label: string, width: number, height: number): string {
  return `${label || kind} (${width}×${height})`;
}

export function createDebugUi(deps: DebugDeps): DebugUi {
  // `display: contents`, so each tool is laid out (and catches pointer events) on its own
  // instead of one full-screen box covering the boot screen's controls.
  const root = document.createElement('div');
  root.className = 'dbg-root';
  const hud = createHudView();
  const panelHost = document.createElement('div');
  panelHost.className = 'dbg-panel';
  const dropZone = document.createElement('div');
  dropZone.className = 'dbg-drop';
  dropZone.innerHTML =
    '<span>Drop the video to play it instead of the camera</span>' +
    '<small>It loops until you switch back to a camera</small>';
  const recordingPill = document.createElement('div');
  recordingPill.className = 'dbg-rec-pill';
  hud.element.hidden = true;
  panelHost.hidden = true;
  dropZone.hidden = true;
  recordingPill.hidden = true;
  root.append(hud.element, panelHost, dropZone, recordingPill);
  deps.root.appendChild(root);

  let visible = false;
  let disposed = false;
  let lastRefreshMs = Number.NEGATIVE_INFINITY;
  let panel: Panel | null = null;
  let panelLoading = false;
  let noticeTimer: ReturnType<typeof setTimeout> | undefined;
  let lastDropped: { count: number; atMs: number } | null = null;
  let droppedPerS = 0;
  /** Identity of the current source, to announce changes; null right after showing. */
  let sourceKey: string | null = null;
  let dragDepth = 0;

  const notify = (text: string, level: Level = 'ok'): void => {
    if (disposed) return;
    hud.setNotice(text, level);
    clearTimeout(noticeTimer);
    noticeTimer = setTimeout(
      () => hud.setNotice(null),
      level === 'bad' ? ERROR_NOTICE_MS : NOTICE_MS,
    );
  };

  /** Report a failed action when the owner hands back its promise (see DebugDeps). */
  const reportFailure = (result: unknown, what: string): void => {
    if (!isPromiseLike(result)) return;
    result.then(undefined, (error: unknown) => notify(`${what}: ${errorMessage(error)}`, 'bad'));
  };

  const updateRecordingUi = (): void => {
    const text = recorder.recording
      ? `● REC ${formatDuration(recorder.elapsedMs)} · ${formatBytes(recorder.bytes)}`
      : null;
    hud.setRecording(text);
    // While the tools are hidden a small pill is the reminder that the camera is recording.
    recordingPill.hidden = !(text && !visible);
    if (text && recordingPill.textContent !== text) recordingPill.textContent = text;
    panel?.setRecording(recorder.recording, recordingLabel(recorder));
  };

  const recorder = createClipRecorder({
    onChange: updateRecordingUi,
    onSaved: (clip) => {
      const why =
        clip.endedBy === 'camera'
          ? 'The camera stopped, so recording ended. '
          : clip.endedBy === 'limit'
            ? `Recording stopped at the ${formatDuration(clip.durationMs)} limit. `
            : '';
      notify(
        `${why}Saved ${clip.name} (${formatDuration(clip.durationMs)}, ${formatBytes(clip.bytes)}).`,
        clip.endedBy === 'user' ? 'ok' : 'warn',
      );
    },
    onError: (message) => notify(message, 'bad'),
  });

  const toggleRecording = (): void => {
    if (recorder.recording) {
      recorder.stop();
      return;
    }
    const vision = deps.getVision();
    if (!vision) {
      notify('Start the game first: recording captures the live camera.', 'warn');
      return;
    }
    const stream = vision.stream;
    if (!stream) {
      const kind = vision.sourceInfo?.kind ?? 'not a camera';
      notify(`Recording needs the live camera, but the source is ${kind}.`, 'warn');
      return;
    }
    try {
      recorder.start(stream);
      notify('Recording the camera. Press Stop recording to save the clip.');
    } catch (error) {
      notify(`Could not start recording: ${errorMessage(error)}`, 'bad');
    }
  };

  const loadClipFile = (file: File): void => {
    if (!isVideoFile(file)) {
      notify(`${file.name} is not a video file.`, 'bad');
      return;
    }
    if (!deps.getVision()) {
      notify('Start the game first, then load the clip.', 'warn');
      return;
    }
    notify(`Loading ${file.name}…`, 'dim');
    reportFailure(deps.actions.loadClip(file), `Could not play ${file.name}`);
  };

  const switchCamera = (deviceId: string, name: string): void => {
    notify(`Switching to ${name}…`, 'dim');
    reportFailure(deps.actions.switchCamera(deviceId), `Could not switch to ${name}`);
  };

  const refresh = (nowMs: number): void => {
    lastRefreshMs = nowMs;
    const vision = deps.getVision();
    const stats = vision?.stats ?? null;
    const now = performance.now();

    if (stats) {
      if (lastDropped && now > lastDropped.atMs) {
        const rate = ((stats.droppedFrames - lastDropped.count) * 1000) / (now - lastDropped.atMs);
        droppedPerS += (Math.max(0, rate) - droppedPerS) * 0.3;
      }
      lastDropped = { count: stats.droppedFrames, atMs: now };
    }

    const game = deps.getGame();
    const mask = deps.getLastMask();
    hud.setRows(
      buildHudRows({
        nowMs: now,
        render: deps.getRenderStats(),
        status: vision?.status ?? null,
        stats,
        source: vision?.sourceInfo ?? null,
        segmenter: vision?.segmenterInfo ?? null,
        mask,
        game: game ? hudGame(game) : null,
        droppedPerS,
      }),
    );

    const info = vision?.sourceInfo ?? null;
    const key = info
      ? `${info.kind}|${info.deviceId}|${info.label}|${info.width}x${info.height}`
      : '';
    // Announce switches only: not the first source, and not what was there before showing.
    if (sourceKey && key !== sourceKey && info) {
      notify(
        `The source is now ${describeSource(info.kind, info.label, info.width, info.height)}.`,
      );
    }
    sourceKey = key;
    panel?.sync();
  };

  const loadPanel = async (): Promise<void> => {
    if (panel || panelLoading) return;
    panelLoading = true;
    try {
      const { createPanel } = await import('./panel');
      if (disposed) return;
      panel = createPanel(panelHost, {
        deps,
        notify,
        loadClipFile,
        switchCamera,
        toggleRecording,
      });
      if (visible) panel.onShow();
      updateRecordingUi();
    } catch (error) {
      console.error(error);
      notify('The tuning panel failed to load. Press D twice to try again.', 'bad');
    } finally {
      panelLoading = false;
    }
  };

  const hasFiles = (event: DragEvent): boolean =>
    event.dataTransfer?.types.includes('Files') ?? false;

  const onDragEnter = (event: DragEvent): void => {
    if (!hasFiles(event)) return;
    event.preventDefault();
    dragDepth++;
    dropZone.hidden = false;
  };
  const onDragOver = (event: DragEvent): void => {
    if (!hasFiles(event)) return;
    // Without this the browser would navigate to the file and end the game.
    event.preventDefault();
    if (event.dataTransfer) event.dataTransfer.dropEffect = 'copy';
  };
  const onDragLeave = (event: DragEvent): void => {
    if (!hasFiles(event)) return;
    dragDepth = Math.max(0, dragDepth - 1);
    if (dragDepth === 0) dropZone.hidden = true;
  };
  const onDrop = (event: DragEvent): void => {
    if (!hasFiles(event)) return;
    event.preventDefault();
    dragDepth = 0;
    dropZone.hidden = true;
    const file = event.dataTransfer?.files[0];
    if (file) loadClipFile(file);
  };

  const listenForDrops = (on: boolean): void => {
    if (on) {
      window.addEventListener('dragenter', onDragEnter);
      window.addEventListener('dragover', onDragOver);
      window.addEventListener('dragleave', onDragLeave);
      window.addEventListener('drop', onDrop);
    } else {
      window.removeEventListener('dragenter', onDragEnter);
      window.removeEventListener('dragover', onDragOver);
      window.removeEventListener('dragleave', onDragLeave);
      window.removeEventListener('drop', onDrop);
    }
  };

  const setVisible = (next: boolean): void => {
    if (disposed || next === visible) return;
    visible = next;
    hud.element.hidden = !next;
    panelHost.hidden = !next;
    listenForDrops(next);
    if (next) {
      sourceKey = null;
      lastDropped = null;
      droppedPerS = 0;
      refresh(performance.now());
      panel?.onShow();
      void loadPanel();
    } else {
      dragDepth = 0;
      dropZone.hidden = true;
      panel?.onHide();
    }
    updateRecordingUi();
  };

  return {
    get visible() {
      return visible;
    },
    setVisible,
    toggle() {
      setVisible(!visible);
    },
    update(nowMs) {
      if (!visible || nowMs - lastRefreshMs < REFRESH_MS) return;
      refresh(nowMs);
    },
    dispose() {
      if (disposed) return;
      if (visible) listenForDrops(false);
      disposed = true;
      visible = false;
      clearTimeout(noticeTimer);
      recorder.dispose();
      panel?.destroy();
      panel = null;
      root.remove();
    },
  };
}
