/**
 * Keeps a high jump on screen. The camera zooms out about the middle of the bottom edge
 * (so the water stays put and more sky comes into view) and, once it has zoomed out as far
 * as allowed, pans up. Both ease in and out so it never jerks; coming back down is slower
 * than going up, the way a camera operator would follow.
 *
 * It also leans sideways (`shift`) when asked, slowly, like an operator reframing.
 *
 * A world point (x, y) appears on screen at
 *   x' = (x - pivotX) * zoom + pivotX + shift
 *   y' = (y - pivotY) * zoom + pivotY + pan
 */
export interface CameraTarget {
  /** Highest world y that must stay on screen (the top of the surfer's head). */
  topY: number;
  /** Screen y it must stay below (inside the safe area). */
  limitY: number;
  /** World height: the zoom pivots on the bottom edge. */
  pivotY: number;
  /** Most the camera may zoom out, as a fraction (0.2 = down to 80 %). */
  maxZoomOut: number;
  /** Sideways lean wanted, world units (positive moves the picture right). */
  shiftX: number;
}

/** Seconds to settle when the target moves up (following a jump) or back down. */
const FOLLOW_S = 0.3;
const RETURN_S = 0.7;
/** Seconds the sideways lean takes to settle. */
const SHIFT_S = 0.9;
/** The jolt's spring: frequency and damping ratio. */
const KICK_HZ = 3.2;
const KICK_DAMPING = 0.45;

export class CameraRig {
  zoom = 1;
  pan = 0;
  shift = 0;
  /** A short vertical jolt on top of the follow (landings, wipeouts), world units. */
  kickY = 0;
  private kickV = 0;
  /** A short sideways push (a speed boost), world units. */
  kickX = 0;
  private kickXV = 0;

  /** The zoom and pan that just keep `topY` at `limitY`. */
  static solve(target: CameraTarget, out: { zoom: number; pan: number }): void {
    const { topY, limitY, pivotY } = target;
    if (topY >= limitY) {
      out.zoom = 1;
      out.pan = 0;
      return;
    }
    const minZoom = 1 - Math.max(0, Math.min(0.6, target.maxZoomOut));
    // (topY - pivotY) * zoom + pivotY = limitY, with no pan.
    const needed = (pivotY - limitY) / Math.max(1, pivotY - topY);
    out.zoom = Math.max(minZoom, needed);
    out.pan = Math.max(0, limitY - ((topY - pivotY) * out.zoom + pivotY));
  }

  private readonly goal = { zoom: 1, pan: 0 };

  update(target: CameraTarget, dtS: number): void {
    CameraRig.solve(target, this.goal);
    const outward = this.goal.pan > this.pan || this.goal.zoom < this.zoom;
    const k = 1 - Math.exp(-dtS / (outward ? FOLLOW_S : RETURN_S));
    this.zoom += (this.goal.zoom - this.zoom) * k;
    this.pan += (this.goal.pan - this.pan) * k;
    this.shift += (target.shiftX - this.shift) * (1 - Math.exp(-dtS / SHIFT_S));
    // The jolt is a damped spring, so it bounces once and settles without drifting.
    const w = 2 * Math.PI * KICK_HZ;
    this.kickV += (-w * w * this.kickY - 2 * KICK_DAMPING * w * this.kickV) * dtS;
    this.kickY += this.kickV * dtS;
    this.kickXV += (-w * w * this.kickX - 2 * KICK_DAMPING * w * this.kickXV) * dtS;
    this.kickX += this.kickXV * dtS;
  }

  /** Push the picture sideways by about `amount` world units (negative = left). */
  push(amount: number): void {
    this.kickXV += amount * 2 * Math.PI * KICK_HZ;
  }

  /** Jolt the picture down by about `amount` world units. */
  kick(amount: number): void {
    this.kickV += amount * 2 * Math.PI * KICK_HZ;
  }

  reset(): void {
    this.zoom = 1;
    this.pan = 0;
    this.shift = 0;
    this.kickY = 0;
    this.kickV = 0;
    this.kickX = 0;
    this.kickXV = 0;
  }
}
