/**
 * The surf simulation behind the `Game` contract.
 *
 * Frame: the screen travels with the wave at speed c, so the water flows left at c. On the
 * water the rails grip and the board moves along its nose:
 *
 *   vx = v·cos θ − c        vy = −v·sin θ + slide·slope      (y down, θ + = nose up)
 *   dv/dt = P·power(x, y) − g·slope(y)·sin θ − k·v + pump − skid
 *
 * - power: the wave's push, full in the pocket just ahead of the curl and on the
 *   upper-middle face, fading out on the shoulder (right) and on the flats. Trimming level
 *   in the pocket settles at v ≈ P/k; c grows every second, so that stops being enough.
 * - gravity along the face is conservative (dropping gains what climbing costs), so speed
 *   is only made by the push and by turning at the top and bottom of the face (pump).
 *   Flapping mid-face pumps nothing, and very fast flapping skids.
 * - slide: a level board slowly slides down the face, so nobody steering ends up bogged on
 *   the flats and caught; holding a line takes a few degrees of nose up.
 * - Lip: arriving with an upward speed ≥ launchSpeed launches (ballistic, airGravity);
 *   slower, the board floats along the lip, nose turned level, until it is pointed down.
 * - Floor: the board cannot go below it; out there it slows (bog) but does not wipe out.
 *   Some push remains, so turning up in time climbs back out.
 * - Easy start (for first-timers): for `easyRideS` there is no slide down, a gentler angle
 *   limit, little skid and roomier landings; these ramp to full over the same time again.
 *   For `protectS` nothing ends the ride (the white water spits the board forward, bad
 *   landings are saved); after that `closeCalls` such rescues remain per ride. A rescue
 *   is a shove that swells and fades over about half a second (a `closeCall` event).
 * - The curl catches boards on the water only: an air is judged where it comes down.
 * - Every published field moves continuously from phase to phase (takeoff picks the board
 *   up, a wipeout settles it level, the glide back to the waiting spot eases in and out):
 *   the renderer and the sound follow them every frame.
 *
 * Integration is semi-implicit Euler in substeps of at most `MAX_SUBSTEP_S`, so 30, 60 and
 * 144 Hz frames give nearly the same ride. Control runs inside the same substeps.
 */
import type { PoseFrame } from '../core/pose';
import type { ViewTransform } from '../core/view';
import { ControlTracker } from './control';
import { approach, clamp, DEG, finite, follow, lerp, smoothstep, tidyPoints } from './math';
import { WaterField } from './pickups';
import type {
  BoostStrip,
  Game,
  GameEvent,
  GameOptions,
  GamePhase,
  Hazard,
  LandingQuality,
  Pickup,
} from './types';
import {
  BOTTOM_Y,
  CURL_FLAT_FRAC,
  CURL_FRAC,
  depthOf,
  FLOOR_Y,
  facePower,
  floorDepth,
  lipAt,
  PARK_FRAC,
  pocketPower,
  slopeAt,
} from './wave';

const MAX_STEP_S = 0.1;
const MAX_SUBSTEP_S = 1 / 240;

/** Water drift while waiting (units/s): a little life in the scenery. */
const WAIT_DRIFT = 40;
/** Seconds the wait must have run before a held pose counts (lets the water settle). */
const WAIT_SETTLE_S = 0.6;
/**
 * The glide to the waiting spot (from the white water after a wipeout, or from wherever
 * `reset` leaves the board): it closes the gap with this time constant, but never faster
 * than `PARK_MAX_SPEED` and changing speed by at most `PARK_ACCEL`, so it sets off and
 * arrives gently instead of leaping off at thousands of units per second.
 */
const PARK_TAU_S = 0.35;
const PARK_MAX_SPEED = 1300;
const PARK_ACCEL = 2400;
/** Takeoff lets whatever glide is left die away over about this long. */
const TAKEOFF_GLIDE_TAU_S = 0.2;
/** Takeoff carries the board to this depth; steering blends in over the second part. */
const TAKEOFF_DEPTH = 0.4;
const TAKEOFF_BLEND_FROM = 0.4;
/** Speed through the water at the end of takeoff, relative to the wave. */
const TAKEOFF_SPEED = 1.05;

/** Slowest the board can go through the water. */
const MIN_SPEED = 250;
/**
 * Extra drag on the floor (per second): bogging down. It builds up over `FLOOR_BOG_S` so
 * that brushing the flats in a deep bottom turn costs little and sitting there costs a lot.
 * Slow enough to build that a player who turns up within about half a second still climbs
 * out (with 0.4 s and 1.2, half a second on the flats was fatal anywhere on the screen).
 */
const FLOOR_DRAG = 0.8;
const FLOOR_BOG_S = 1;
/** Extra drag ramping in over the right edge of the screen, so nobody leaves it. */
const EDGE_DRAG = 2;
const EDGE_FROM = 0.78;
/** A carve's speed (see `pumpGain`) is fed in at this rate (units/s²), so it feels like a pump. */
const PUMP_RATE = 600;
/** Swing beyond this (radians) pumps no more. */
const PUMP_MAX_SWING = 80 * DEG;
/**
 * Pumping works fully up to the wave's speed and fades out at this multiple of it, so
 * carving keeps you up with the wave but cannot run away (keyboard turns are instant).
 */
const PUMP_FADE_TO = 1.6;
/** Turning faster than this (rad/s) skids: speed lost per rad/s over it. */
const SKID_RATE = 8;
const SKID_LOSS = 40;
/** Share of the skid loss while the ride is still easy. */
const SKID_EARLY = 0.3;

/**
 * In the air the lip throws the surfer along with the wave: only this share of the drift
 * the board had at launch (v·cos θ − c, strongly negative for a steep launch) remains.
 */
const AIR_DRIFT = 0.35;
/** The lip's throw takes over over this long after launch, so the path bends, not kinks. */
const AIR_DRIFT_BLEND_S = 0.12;
/**
 * Riding along the lip without the speed to launch (a floater): a nose-up board is turned
 * level along the lip over about this long, instead of sitting there pointing at the sky
 * while it slides along the top (it used to, for the whole ride if the arms stayed up).
 */
const FLOAT_TAU_S = 0.2;
/**
 * Extra drag (per second) while floating: the lip's spray holds the board back a little, so
 * arms held up on the lip last about as long as not steering at all (≈ 44 s against 43),
 * not longer (59 s without). Sensitive: the ride ends about when the floater's top speed in
 * the pocket falls behind the wave, so 0.25 would end it in 13 s.
 */
const FLOAT_DRAG = 0.03;
/** Board must come back this far below the lip to land. */
const LAND_DEPTH = 30;
/** The ideal landing angle is this share of the falling path's angle (0 = level). */
const LAND_IDEAL_SHARE = 0.5;
/** Nose down beyond the path by more than this (radians) wipes out (rarely reachable). */
const LAND_NOSE_DOWN_SLACK = 30 * DEG;
/** Fed in like a pump, so the speed glides up after the splash rather than jumping. */
const PERFECT_SPEED_BONUS = 80;
/** Extra nose-up allowance (degrees) on landing while the ride is easy. */
const EASY_LAND_EXTRA_DEG = 20;
const GOOD_SPEED_KEEP = 0.95;

/** Caught at once this far behind the front of the white water. */
const CURL_DEEP = 140;
/**
 * A rescue (protected start or close call): the white water shoves the board forward. The
 * shove is a kick of `RESCUE_KICK` (screen units/s) decaying with `SHOVE_TAU_S` that the
 * board's push follows with `SHOVE_RISE_S`, so the push swells over a tenth of a second,
 * peaks at about 0.8 × the kick and fades: about `RESCUE_KICK × SHOVE_TAU_S` = 420 units
 * in all, enough to carry a board from deep in the white water to well clear of its front.
 * Moving it there in one step instead reads as a teleport.
 */
const RESCUE_KICK = 1050;
const SHOVE_TAU_S = 0.4;
const SHOVE_RISE_S = 0.08;
/** The white water cannot catch the board again while it is still spitting it out. */
const RESCUE_S = 0.7;
/**
 * Meanwhile the white water carries the board along at least at the wave's speed, the
 * board's speed brought up at this rate (units/s²) rather than at once.
 */
const RESCUE_SPEED_RATE = 2500;

/** A carve is a swing through ±this angle… */
const CARVE_ANGLE = 15 * DEG;
/** …completed within this long… */
const CARVE_WINDOW_S = 1.3;
/** …at least this long after the previous one… */
const CARVE_GAP_S = 0.6;
/** …after moving at least this share of the face up or down since the previous one… */
const CARVE_TRAVEL = 0.3;
/** …at this speed or more. */
const CARVE_MIN_SPEED = 400;
const CARVE_TOP_DEPTH = 0.35;
const CARVE_BOTTOM_DEPTH = 0.62;

/**
 * Speed kicks from pickups and boost strips are fed in at this rate (units/s²): a strip's
 * kick takes about a fifth of a second, a clam's a few hundredths. At most `KICK_CAP` can be
 * waiting at once, so a burst of them cannot stack into a launch.
 */
const KICK_RATE = 1400;
const KICK_CAP = 450;
/** A strip's kick fades this much later (× the wave's speed) than a pickup's. */
const STRIP_ROOM = 0.25;
/** `surfer.boost` fades with this time constant after a kick. */
const BOOST_FADE_S = 0.6;
/** The board crosses a strip when it passes within this far of its line (units). */
const STRIP_HALF_WIDTH = 34;
/** A whirlpool's grip eases in and out with this time constant, and is news above this. */
const GRIP_TAU_S = 0.12;
const GRIP_EVENT = 0.08;
/** A buoy is hit within this far of its edge; the speed it costs goes at `BUMP_RATE`. */
const BUOY_HIT = 22;
const BUMP_RATE = 2500;
/** A buoy's knock aside fades with this time constant. */
const KNOCK_TAU_S = 0.25;

/** Points per second at full power (the pocket trickle). */
const POCKET_POINTS = 15;
const POCKET_MIN_POWER = 0.6;

/** Wipeout: how the board tumbles and drifts in the white water. */
const TUMBLE_SPIN = 9;
const TUMBLE_DECAY_S = 1.2;
const WIPE_STOP_S = 0.25;
/** The wave lies down over the last part of the wipeout; the board settles level with it. */
const FLATTEN_FROM = 0.55;
/**
 * While waiting the board follows the arms at once, but whatever angle it came in with (a
 * tumble, a reset mid-turn) fades out with this time constant instead of snapping.
 */
const WAIT_ANGLE_TAU_S = 0.15;

type Phase = GamePhase;

/** Velocity for the next substep of the glide to the waiting spot, `gap` away. */
function glideSpeed(velocity: number, gap: number, h: number): number {
  const want = clamp(gap / PARK_TAU_S, -PARK_MAX_SPEED, PARK_MAX_SPEED);
  return velocity + clamp(want - velocity, -PARK_ACCEL * h, PARK_ACCEL * h);
}

/** `angle` brought into [−π, π]. */
function wrapAngle(angle: number): number {
  return angle - 2 * Math.PI * Math.round(angle / (2 * Math.PI));
}

export function createGame(options: GameOptions): Game {
  const t = options.tunables;
  const rng = options.rng;
  let view: ViewTransform = options.view;
  const tracker = new ControlTracker();
  const field = new WaterField();

  const surfer = {
    x: view.worldWidth * PARK_FRAC,
    y: BOTTOM_Y,
    vx: 0,
    vy: 0,
    speed: 0,
    angle: 0,
    airborne: false,
    airS: 0,
    height: 0,
    power: 0,
    turn: 0,
    boost: 0,
  };
  const wave = {
    rise: 0,
    lipY: lipAt(0),
    bottomY: BOTTOM_Y,
    floorY: FLOOR_Y,
    curlX: view.worldWidth * CURL_FLAT_FRAC,
    speed: 0,
    distance: 0,
  };
  const events: GameEvent[] = [];
  const drained: GameEvent[] = [];

  let phase: Phase = 'waiting';
  let phaseS = 0;
  let score = 0;
  let scoreFrac = 0;
  let best = Math.max(0, finite(options.best ?? 0, 0));
  let rideS = 0;

  // Ride state that is not published.
  let v = 0;
  let prevAngle = 0;
  let behindS = 0;
  let floorS = 0;
  /** Forward push from the white water after a rescue (screen units/s), and what drives it. */
  let shove = 0;
  let shoveKick = 0;
  /** Seconds left of the current rescue, during which the curl cannot catch the board. */
  let rescueS = 0;
  let closeCallsLeft = 0;
  let airU = 0;
  let airVy = 0;
  let launchV = 0;
  let apex = 0;
  let spin = 0;
  let wipeSpeed = 0;
  let poseHold = 0;
  let waitAngleOffset = 0;
  /** Takeoff: how far the player has steered away from where the wave carries the board. */
  let takeoffOffset = 0;
  /** Takeoff starts from the wave and speed as they were (flat and 0 from a wait). */
  let takeoffRise = 0;
  let takeoffSpeed = 0;
  let takeoffGlide = 0;
  // Carve tracking.
  let upSince = Number.NEGATIVE_INFINITY;
  let downSince = Number.NEGATIVE_INFINITY;
  let swingMax = 0;
  let swingMin = 0;
  let lastCarveS = Number.NEGATIVE_INFINITY;
  let travelMinY = 0;
  let travelMaxY = 0;
  /** Speed still to be fed in from the last carve. */
  let pumpLeft = 0;
  /** 0..1: how far the lip has turned a floating board level. */
  let float = 0;
  /** Speed still to be fed in from pickups and strips, and still to be lost to a buoy. */
  let kickLeft = 0;
  let stripLeft = 0;
  let bumpLeft = 0;
  /** Pickups chained so far, and when the last one was taken (ride seconds). */
  let combo = 0;
  let lastPickupS = Number.NEGATIVE_INFINITY;
  /** A buoy's knock aside (screen units/s, y), fading. */
  let knockVy = 0;
  // What the hazards do to the board this substep (see `stepHazards`).
  let pullVx = 0;
  let pullVy = 0;
  let hazardDrag = 0;

  const setPhase = (next: Phase): void => {
    phase = next;
    phaseS = 0;
    events.push({ type: 'phase', phase: next });
  };

  const clearRide = (): void => {
    score = 0;
    scoreFrac = 0;
    rideS = 0;
    wave.distance = 0;
    surfer.airborne = false;
    surfer.airS = 0;
    surfer.height = 0;
    behindS = 0;
    floorS = 0;
    shove = 0;
    shoveKick = 0;
    rescueS = 0;
    closeCallsLeft = Math.max(0, Math.round(t.closeCalls));
    spin = 0;
    upSince = Number.NEGATIVE_INFINITY;
    downSince = Number.NEGATIVE_INFINITY;
    lastCarveS = Number.NEGATIVE_INFINITY;
    pumpLeft = 0;
    float = 0;
    kickLeft = 0;
    stripLeft = 0;
    bumpLeft = 0;
    combo = 0;
    lastPickupS = Number.NEGATIVE_INFINITY;
    knockVy = 0;
    pullVx = 0;
    pullVy = 0;
    hazardDrag = 0;
    surfer.boost = 0;
    swingMax = 0;
    swingMin = 0;
    travelMinY = surfer.y;
    travelMaxY = surfer.y;
  };

  const beginTakeoff = (): void => {
    clearRide();
    field.reset(view.worldWidth);
    poseHold = 0;
    tracker.state.poseHold = 0;
    v = t.waveSpeed;
    // From a wait the board floats where the takeoff carries it from, so the offset is 0;
    // `startRide` mid-ride starts from wherever the board is instead of jumping.
    takeoffRise = wave.rise;
    takeoffSpeed = surfer.airborne ? 0 : surfer.speed;
    takeoffGlide = phase === 'waiting' ? surfer.vx : 0;
    takeoffOffset = surfer.y - takeoffCarryY(lipAt(takeoffRise));
    prevAngle = surfer.angle;
    surfer.airborne = false;
    surfer.airS = 0;
    surfer.height = 0;
    setPhase('takeoff');
  };

  const takeoffCarryY = (lipY: number): number => lipY + TAKEOFF_DEPTH * (BOTTOM_Y - lipY);

  const addPoints = (points: number): void => {
    score += points;
  };

  const waveSpeedNow = (): number => t.waveSpeed + t.waveSpeedGain * rideS;
  /**
   * 0 for the first `easyRideS` of a ride, rising to 1 over the same time again. Scales what
   * makes riding hard for a first-timer: the slide down the face and the steepest angle.
   */
  const challenge = (): number =>
    t.easyRideS > 0 ? smoothstep(t.easyRideS, 2 * t.easyRideS, rideS) : 1;
  const angleLimit = (): number =>
    phase === 'riding' ? lerp(t.easyMaxAngle, t.maxAngle, challenge()) : t.easyMaxAngle;
  /** No wipeout of any kind yet: the start of a ride always lasts. */
  const protectedNow = (): boolean => phase === 'riding' && rideS < t.protectS;

  // --- Phases -------------------------------------------------------------------------

  const stepWaiting = (h: number, cmd: number): void => {
    wave.rise = approach(wave.rise, 0, h / 0.6);
    wave.speed = approach(wave.speed, WAIT_DRIFT, h * 600);
    const px = view.worldWidth * PARK_FRAC;
    surfer.vx = glideSpeed(surfer.vx, px - surfer.x, h);
    surfer.vy = glideSpeed(surfer.vy, BOTTOM_Y - surfer.y, h);
    surfer.x += surfer.vx * h;
    surfer.y += surfer.vy * h;
    // First substep of the wait: what the board's angle differs from the arms' fades out.
    if (phaseS <= h * 1.5) waitAngleOffset = wrapAngle(surfer.angle - cmd);
    waitAngleOffset *= Math.exp(-h / WAIT_ANGLE_TAU_S);
    surfer.angle = cmd + waitAngleOffset;
    surfer.speed = 0;
    surfer.airborne = false;
    surfer.airS = 0;
    surfer.height = 0;
    surfer.power = 0;
    surfer.turn = approach(surfer.turn, 0, h * 4);
    // Fill while the arms are out, drain twice as fast when they drop.
    const fill = h / Math.max(0.05, t.poseHoldS);
    if (tracker.state.posed && phaseS >= WAIT_SETTLE_S) poseHold = Math.min(1, poseHold + fill);
    else poseHold = Math.max(0, poseHold - 2 * fill);
    tracker.state.poseHold = poseHold;
    if (poseHold >= 1) beginTakeoff();
  };

  const stepTakeoff = (h: number, cmd: number): void => {
    const p = clamp(phaseS / Math.max(0.1, t.takeoffS), 0, 1);
    wave.rise = lerp(takeoffRise, 1, smoothstep(0, 1, p));
    const c = t.waveSpeed;
    wave.speed = lerp(WAIT_DRIFT, c, wave.rise);
    const lipY = lipAt(wave.rise);
    // The board shows what the arms ask for all along; it only steers as `blend` grows.
    const blend = smoothstep(TAKEOFF_BLEND_FROM, 1, p);
    const steer = cmd * blend;
    v = lerp(c, c * TAKEOFF_SPEED, blend);
    // Carried towards mid-face; the player's steering takes over as `blend` grows.
    const carryY = takeoffCarryY(lipY);
    const freeVy = -v * Math.sin(steer);
    takeoffGlide *= Math.exp(-h / TAKEOFF_GLIDE_TAU_S);
    const vx = (v * Math.cos(steer) - c) * blend + takeoffGlide;
    const y0 = surfer.y;
    // The offset from the carry fades while the wave takes the board, then steering adds.
    takeoffOffset *= 1 - follow(h, 0.3) * (1 - blend);
    takeoffOffset += freeVy * blend * h;
    surfer.y = clamp(carryY + takeoffOffset, lipY, FLOOR_Y);
    takeoffOffset = surfer.y - carryY;
    surfer.x += vx * h;
    surfer.vx = vx;
    surfer.vy = (surfer.y - y0) / h;
    const omega = (cmd - prevAngle) / h;
    surfer.angle = cmd;
    prevAngle = cmd;
    // The board is picked up from floating: its speed (and so the water's rush) swells
    // with the wave instead of starting at full.
    surfer.speed = lerp(takeoffSpeed, v, smoothstep(0, 0.6, p));
    // The same power field as riding, faded in with the wave, so it does not step at `go`.
    surfer.power =
      pocketPower(surfer.x - wave.curlX) *
      facePower(depthOf(surfer.y, lipY), floorDepth(lipY)) *
      wave.rise;
    surfer.turn += (clamp(omega / 3, -1, 1) - surfer.turn) * follow(h, 0.08);
    travelMinY = surfer.y;
    travelMaxY = surfer.y;
    if (p >= 1) setPhase('riding');
  };

  const wipeout = (cause: 'curl' | 'landing'): void => {
    const previous = best;
    best = Math.max(best, score);
    events.push({
      type: 'wipeout',
      x: surfer.x,
      y: surfer.y,
      cause,
      score,
      best,
      newBest: score > previous,
    });
    wipeSpeed = wave.speed;
    // Thrown off the back from the air or a nose-up landing; tumbled forward by the curl.
    spin = (surfer.airborne || cause === 'landing' ? 1 : -1) * TUMBLE_SPIN;
    surfer.airborne = false;
    surfer.airS = 0;
    surfer.height = 0;
    surfer.turn = 0;
    setPhase('wipeout');
  };

  const land = (): void => {
    const angle = surfer.angle;
    // The falling path through the water; the board should point between level and it.
    const path = Math.atan2(-airVy, Math.max(1, airU));
    const ideal = path * LAND_IDEAL_SHARE;
    const err = Math.abs(angle - ideal);
    // Landings are more forgiving while the ride is easy, both ways.
    const extra = EASY_LAND_EXTRA_DEG * DEG * (1 - challenge());
    const noseUp = angle > t.landNoseUpDeg * DEG + extra;
    const tooSteep = angle < path - LAND_NOSE_DOWN_SLACK - extra;
    const height = apex;
    const airS = surfer.airS;
    surfer.airborne = false;
    surfer.height = 0;
    surfer.airS = 0;
    surfer.y = wave.lipY + LAND_DEPTH;
    if ((noseUp || tooSteep) && !protectedNow()) {
      wipeout('landing');
      return;
    }
    // A protected bad landing is saved as a plain good one.
    const quality: LandingQuality =
      err <= t.landPerfectDeg * DEG && !noseUp && !tooSteep ? 'perfect' : 'good';
    if (quality === 'perfect') {
      v = launchV;
      pumpLeft += PERFECT_SPEED_BONUS;
    } else {
      v = launchV * GOOD_SPEED_KEEP;
    }
    const base = 100 + height + 150 * airS;
    const points = tidyPoints(quality === 'perfect' ? base * 1.5 : base);
    addPoints(points);
    prevAngle = angle;
    // Back in the water: its push applies from this frame, not from the next substep.
    surfer.power =
      pocketPower(surfer.x - wave.curlX) *
      facePower(depthOf(surfer.y, wave.lipY), floorDepth(wave.lipY));
    events.push({ type: 'land', x: surfer.x, y: surfer.y, quality, airS, height, points });
  };

  /**
   * Speed `amount` to feed in from now (pickups, strips). `boost` is what the board shows
   * for it (1 for a strip, less for a pickup's small kick).
   */
  const kick = (amount: number, boost: number, strip: boolean): void => {
    if (!(amount > 0)) return;
    if (strip) stripLeft = Math.min(KICK_CAP, stripLeft + amount);
    else kickLeft = Math.min(KICK_CAP, kickLeft + amount);
    surfer.boost = Math.max(surfer.boost, clamp(boost, 0, 1));
  };
  /**
   * Share of a kick that still adds speed: less the faster than the wave the board is. A
   * strip's fades `STRIP_ROOM` later, so it is a clear kick even for a board already fast.
   */
  const kickRoom = (c: number, extra: number): number => {
    const from = (t.kickFadeFrom + extra) * c;
    const to = (t.kickFadeTo + extra) * c;
    return clamp((to - v) / Math.max(1, to - from), 0, 1);
  };

  const collect = (): void => {
    const items = field.items;
    // Body: a segment from the board up along the board's normal.
    const nx = -Math.sin(surfer.angle);
    const ny = -Math.cos(surfer.angle);
    const len = t.avatarHeight;
    for (let i = items.length - 1; i >= 0; i--) {
      const star = items[i];
      if (!star) continue;
      const rx = star.x - surfer.x;
      const ry = star.y - surfer.y;
      const along = clamp(rx * nx + ry * ny, 0, len);
      const ex = rx - along * nx;
      const ey = ry - along * ny;
      const reach = t.pickupReach + star.r;
      if (ex * ex + ey * ey <= reach * reach) {
        combo = rideS - lastPickupS <= t.comboWindowS ? combo + 1 : 1;
        lastPickupS = rideS;
        const links = Math.min(combo, Math.max(1, Math.round(t.comboMax))) - 1;
        const base = star.kind === 'crab' ? t.crabKick : t.clamKick;
        const amount = base * (1 + t.comboKickStep * links);
        kick(amount, amount / Math.max(1, t.boostKick), false);
        addPoints(star.points);
        events.push({
          type: 'pickup',
          id: star.id,
          kind: star.kind,
          x: star.x,
          y: star.y,
          points: star.points,
          combo,
        });
        field.remove(i);
      }
    }
    // Boost strips: the board itself has to cross one, on the water.
    if (surfer.airborne) return;
    const strips = field.strips;
    for (let i = strips.length - 1; i >= 0; i--) {
      const strip = strips[i];
      if (!strip) continue;
      if (
        Math.abs(strip.x - surfer.x) <= strip.r &&
        Math.abs(strip.y - surfer.y) <= STRIP_HALF_WIDTH
      ) {
        kick(t.boostKick, 1, true);
        events.push({ type: 'boost', x: surfer.x, y: surfer.y });
        field.removeStrip(i);
      }
    }
  };

  /**
   * What the hazards do to the board from where it is now: a whirlpool pulls it towards its
   * centre and drags while it has hold (its `grip` eases in and out); a buoy knocks speed
   * off and the board aside, once. Neither ends a ride.
   */
  const stepHazards = (h: number): void => {
    pullVx = 0;
    pullVy = 0;
    hazardDrag = 0;
    const hazards = field.hazards;
    for (let i = 0; i < hazards.length; i++) {
      const hz = hazards[i];
      if (!hz) continue;
      const dx = surfer.x - hz.x;
      const dy = surfer.y - hz.y;
      const d = Math.max(1, Math.hypot(dx, dy));
      if (hz.kind === 'whirlpool') {
        const want = surfer.airborne ? 0 : smoothstep(hz.r, 0.35 * hz.r, d);
        hz.grip += (want - hz.grip) * follow(h, GRIP_TAU_S);
        if (hz.grip < 0.002) hz.grip = 0;
        if (!hz.engaged && hz.grip > GRIP_EVENT) {
          hz.engaged = true;
          events.push({ type: 'hazard', kind: 'whirlpool', id: hz.id, x: hz.x, y: hz.y });
        } else if (hz.engaged && hz.grip === 0) {
          hz.engaged = false;
        }
        pullVx -= (dx / d) * t.whirlpoolPull * hz.grip;
        pullVy -= (dy / d) * t.whirlpoolPull * hz.grip;
        hazardDrag += t.whirlpoolDrag * hz.grip;
      } else if (!hz.engaged && !surfer.airborne && d <= hz.r + BUOY_HIT) {
        hz.engaged = true;
        bumpLeft += t.buoySpeedLoss * v;
        knockVy = (dy >= 0 ? 1 : -1) * t.buoyKnock;
        events.push({ type: 'hazard', kind: 'buoy', id: hz.id, x: hz.x, y: hz.y });
      }
    }
  };

  const trackCarves = (angle: number, depth: number): void => {
    if (surfer.y < travelMinY) travelMinY = surfer.y;
    if (surfer.y > travelMaxY) travelMaxY = surfer.y;
    if (angle >= CARVE_ANGLE) {
      if (angle > swingMax || upSince < downSince) swingMax = angle;
      upSince = rideS;
    }
    if (angle <= -CARVE_ANGLE) {
      if (angle < swingMin || downSince < upSince) swingMin = angle;
      downSince = rideS;
    }
    const face = BOTTOM_Y - wave.lipY;
    const travelled = travelMaxY - travelMinY >= CARVE_TRAVEL * face;
    const ready = rideS - lastCarveS >= CARVE_GAP_S && travelled && v >= CARVE_MIN_SPEED;
    if (!ready) return;
    let where: 'top' | 'bottom' | null = null;
    let amp = 0;
    // Top: nose was up recently and has just swung down, high on the face.
    if (angle <= -CARVE_ANGLE && rideS - upSince <= CARVE_WINDOW_S && depth <= CARVE_TOP_DEPTH) {
      where = 'top';
      amp = swingMax - angle;
    } else if (
      angle >= CARVE_ANGLE &&
      rideS - downSince <= CARVE_WINDOW_S &&
      depth >= CARVE_BOTTOM_DEPTH
    ) {
      where = 'bottom';
      amp = angle - swingMin;
    }
    if (!where) return;
    const ampN = clamp((amp - 30 * DEG) / (60 * DEG), 0, 1);
    const speedN = clamp((v - 500) / 600, 0, 1);
    const points = tidyPoints(60 + 120 * ampN + 70 * speedN);
    addPoints(points);
    // Pumping: speed comes from turning hard at the top and bottom, not from flapping.
    const efficiency = clamp(
      (PUMP_FADE_TO * wave.speed - v) / ((PUMP_FADE_TO - 1) * wave.speed),
      0,
      1,
    );
    pumpLeft += t.pumpGain * Math.min(amp, PUMP_MAX_SWING) * efficiency;
    events.push({ type: 'carve', x: surfer.x, y: surfer.y, where, points });
    lastCarveS = rideS;
    travelMinY = surfer.y;
    travelMaxY = surfer.y;
    // The swing is spent: the next carve needs a fresh one.
    if (where === 'top') upSince = Number.NEGATIVE_INFINITY;
    else downSince = Number.NEGATIVE_INFINITY;
  };

  const stepRiding = (h: number, cmd: number): void => {
    rideS += h;
    const c = waveSpeedNow();
    wave.speed = c;
    wave.rise = 1;
    const lipY = wave.lipY;
    const width = view.worldWidth;
    const curlX = wave.curlX;
    const floor = floorDepth(lipY);
    surfer.boost *= Math.exp(-h / BOOST_FADE_S);
    knockVy *= Math.exp(-h / KNOCK_TAU_S);
    stepHazards(h);

    if (surfer.airborne) {
      surfer.airS += h;
      airVy += t.airGravity * h;
      const drift = lerp(1, AIR_DRIFT, smoothstep(0, AIR_DRIFT_BLEND_S, surfer.airS));
      const airVx = (airU - c) * drift + shove;
      surfer.x += airVx * h;
      surfer.y += airVy * h;
      surfer.vx = airVx;
      surfer.vy = airVy;
      surfer.angle = cmd;
      // The speed it carries through the air, so the number does not dip and jump back.
      surfer.speed = launchV;
      surfer.height = Math.max(0, lipY - surfer.y);
      if (surfer.height > apex) apex = surfer.height;
      surfer.power = 0;
      surfer.turn = approach(surfer.turn, 0, h * 4);
      prevAngle = cmd;
      if (airVy > 0 && surfer.y >= lipY + LAND_DEPTH) land();
    } else {
      const onFloor = surfer.y >= FLOOR_Y - 0.5;
      const onLip = surfer.y <= lipY + 0.5;
      // A floater: on the lip without the speed to leave it, the lip turns a nose-up board
      // along itself and holds it there until the nose goes down.
      const floating = onLip && cmd > 0;
      float += ((floating ? 1 : 0) - float) * follow(h, FLOAT_TAU_S);
      const angle = cmd > 0 ? cmd * (1 - float) : cmd;
      const omega = (angle - prevAngle) / h;
      prevAngle = angle;
      const depth = depthOf(surfer.y, lipY);
      const slope = slopeAt(depth, floor);
      const power = pocketPower(surfer.x - curlX) * facePower(depth, floor);
      const sin = Math.sin(angle);
      const cos = Math.cos(angle);
      // Gravity only works while the board actually moves up or down the face.
      const blocked = (onFloor && sin < 0) || (onLip && sin > 0);
      const gravity = blocked ? 0 : -t.faceGravity * slope * sin;
      const pump = Math.min(pumpLeft, PUMP_RATE * h);
      pumpLeft -= pump;
      const feed = Math.min(kickLeft, KICK_RATE * h);
      kickLeft -= feed;
      const stripFeed = Math.min(stripLeft, KICK_RATE * h);
      stripLeft -= stripFeed;
      const kicked = feed * kickRoom(c, 0) + stripFeed * kickRoom(c, STRIP_ROOM);
      const bumped = Math.min(bumpLeft, BUMP_RATE * h);
      bumpLeft -= bumped;
      // While the white water spits the board out it carries it along at least as fast as
      // the wave travels, whichever way the nose points.
      const carried = c / Math.max(0.6, Math.cos(angle));
      const boost = rescueS > 0 ? clamp(carried - v, 0, RESCUE_SPEED_RATE * h) : 0;
      // Skidding is part of the challenge: wild early flapping costs a little, later a lot.
      const skid =
        SKID_LOSS * lerp(SKID_EARLY, 1, challenge()) * Math.max(0, Math.abs(omega) - SKID_RATE);
      const edge = EDGE_DRAG * smoothstep(EDGE_FROM * width, width, surfer.x);
      floorS = onFloor ? floorS + h : 0;
      const drag =
        t.waterDrag +
        FLOOR_DRAG * smoothstep(0, FLOOR_BOG_S, floorS) +
        FLOAT_DRAG * (floating ? float : 0) +
        hazardDrag +
        edge;
      v += pump + boost + kicked - bumped + (t.wavePower * power + gravity - skid - drag * v) * h;
      if (v < MIN_SPEED) v = MIN_SPEED;

      let vy = -v * sin + t.slideDown * challenge() * slope + pullVy + knockVy;
      const vx = v * cos - c + shove + pullVx;
      if (floating) vy = Math.min(vy, 0);
      let y = surfer.y + vy * h;
      if (y >= FLOOR_Y) {
        y = FLOOR_Y;
        vy = 0;
      }
      if (y <= lipY) {
        if (-vy >= t.launchSpeed) {
          // Off the lip: ballistic from here, keeping the speed along the water.
          surfer.airborne = true;
          surfer.airS = 0;
          airU = v * cos;
          airVy = vy;
          launchV = v;
          apex = 0;
          events.push({ type: 'launch', x: surfer.x, y: lipY, speed: v });
        } else {
          y = lipY;
          vy = 0;
        }
      }
      surfer.x += vx * h;
      surfer.y = y;
      surfer.vx = vx;
      surfer.vy = vy;
      surfer.angle = angle;
      surfer.speed = v;
      surfer.power = surfer.airborne ? 0 : power;
      surfer.turn += (clamp(omega / 3, -1, 1) - surfer.turn) * follow(h, 0.08);
      if (!surfer.airborne) trackCarves(angle, depth);
      if (power >= POCKET_MIN_POWER) {
        scoreFrac += POCKET_POINTS * power * h;
        if (scoreFrac >= 1) {
          const whole = Math.floor(scoreFrac);
          scoreFrac -= whole;
          addPoints(whole);
        }
      }
    }
    if (phase !== 'riding') return;

    field.drift(-c * t.pickupDrift * h);
    field.spawn(rng, t, rideS, width, lipY, BOTTOM_Y);
    collect();

    shove += (shoveKick - shove) * follow(h, SHOVE_RISE_S);
    shoveKick *= Math.exp(-h / SHOVE_TAU_S);
    if (rescueS > 0) {
      // Still being spat out: the white water does not take the board back meanwhile.
      rescueS = Math.max(0, rescueS - h);
      behindS = 0;
      return;
    }
    // Caught by the white water: a moment's grace just behind its front. Not in the air:
    // nobody can steer there, so it is judged where the board comes down.
    if (surfer.airborne) return;
    if (surfer.x < curlX) behindS += h;
    else behindS = Math.max(0, behindS - h);
    if (behindS > t.curlGraceS || surfer.x < curlX - CURL_DEEP) {
      const rescue = protectedNow() || closeCallsLeft > 0;
      if (!rescue) {
        wipeout('curl');
        return;
      }
      // A close call: the white water spits the board forward instead of taking it.
      if (!protectedNow()) closeCallsLeft--;
      behindS = 0;
      rescueS = RESCUE_S;
      shoveKick = RESCUE_KICK;
      floorS = 0;
      events.push({ type: 'closeCall', x: surfer.x, y: surfer.y });
    }
  };

  const stepWipeout = (h: number): void => {
    const restart = Math.max(0.5, t.restartS);
    const p = clamp(phaseS / restart, 0, 1);
    wave.speed = lerp(wipeSpeed, WAIT_DRIFT, smoothstep(0, 1, p));
    wave.rise = 1 - smoothstep(FLATTEN_FROM, 1, p);
    // Tumbling in the white water, which pushes the surfer back a little and down.
    spin *= Math.exp(-h / TUMBLE_DECAY_S);
    surfer.angle = wrapAngle(surfer.angle + spin * h);
    // As the wave lies down the board comes to rest level, ready for the next wait.
    const settle = smoothstep(FLATTEN_FROM, 1, p);
    if (settle > 0) {
      spin *= Math.exp((-h * settle) / 0.15);
      surfer.angle -= surfer.angle * follow(h, lerp(1, 0.15, settle));
    }
    const k = follow(h, 0.5);
    const tx = wave.curlX - 60;
    const ty = Math.min(FLOOR_Y, lipAt(wave.rise) + 0.7 * (BOTTOM_Y - lipAt(wave.rise)));
    const dx = (tx - surfer.x) * k;
    const dy = (ty - surfer.y) * k;
    surfer.x += dx;
    surfer.y += dy;
    surfer.vx = dx / h;
    surfer.vy = dy / h;
    // The board stops in the white water quickly but not in an instant (the water's sound
    // and spray follow these).
    const stop = Math.exp(-h / WIPE_STOP_S);
    surfer.speed *= stop;
    surfer.power *= stop;
    surfer.boost *= stop;
    surfer.turn = 0;
    const hazards = field.hazards;
    for (let i = 0; i < hazards.length; i++) (hazards[i] as Hazard & { grip: number }).grip *= stop;
    field.drift(-wave.speed * t.pickupDrift * h);
    if (p >= 1) {
      field.clear();
      setPhase('waiting');
    }
  };

  const substep = (h: number): void => {
    tracker.step(h, t);
    const cmd = tracker.command(t, angleLimit());
    phaseS += h;
    switch (phase) {
      case 'waiting':
        stepWaiting(h, cmd);
        break;
      case 'takeoff':
        stepTakeoff(h, cmd);
        break;
      case 'riding':
        stepRiding(h, cmd);
        break;
      case 'wipeout':
        stepWipeout(h);
        break;
    }
    wave.lipY = lipAt(wave.rise);
    wave.curlX = view.worldWidth * lerp(CURL_FLAT_FRAC, CURL_FRAC, wave.rise);
    wave.distance += wave.speed * h;
  };

  const game: Game = {
    get phase() {
      return phase;
    },
    get phaseS() {
      return phaseS;
    },
    get control() {
      return tracker.state;
    },
    get surfer() {
      return surfer;
    },
    get wave() {
      return wave;
    },
    get pickups(): readonly Pickup[] {
      return field.items;
    },
    get hazards(): readonly Hazard[] {
      return field.hazards;
    },
    get boosts(): readonly BoostStrip[] {
      return field.strips;
    },
    get score() {
      return score;
    },
    get best() {
      return best;
    },
    get rideS() {
      return rideS;
    },
    setView(next) {
      // A new screen width (a resize, entering full screen) scales everything across the
      // screen with it, the way the picture itself rescales: the curl, the board and the
      // stars keep their places relative to the screen, nothing ends up beyond its edge.
      const scale = next.worldWidth / Math.max(1, view.worldWidth);
      view = next;
      if (!Number.isFinite(scale) || Math.abs(scale - 1) < 1e-9) return;
      surfer.x *= scale;
      wave.curlX *= scale;
      field.scaleX(scale);
    },
    applyPose(pose: PoseFrame | null, timeMs: number) {
      tracker.applyPose(pose, timeMs, view, t);
    },
    setManualTilt(tilt) {
      tracker.setManual(tilt);
    },
    step(dtS) {
      const dt = clamp(finite(dtS, 0), 0, MAX_STEP_S);
      if (dt <= 0) return;
      const n = Math.ceil(dt / MAX_SUBSTEP_S - 1e-9);
      const h = dt / n;
      tracker.beginFrame(dt);
      for (let i = 0; i < n; i++) substep(h);
    },
    drainEvents() {
      drained.length = 0;
      for (let i = 0; i < events.length; i++) drained.push(events[i] as GameEvent);
      events.length = 0;
      return drained;
    },
    reset() {
      clearRide();
      field.clear();
      poseHold = 0;
      tracker.state.poseHold = 0;
      setPhase('waiting');
    },
    startRide() {
      beginTakeoff();
    },
  };
  return game;
}
