/**
 * Every live-tunable number in the game. One mutable object is created at boot and shared;
 * modules read values from it each frame (never cache them) so the debug panel takes effect
 * immediately. This file is pure data: no DOM access, so game logic can import it.
 */

/** Bump when a default changes meaning, so stale saved values are discarded. */
export const TUNABLES_VERSION = 1;

export interface Tunables {
  // --- Control ---
  /** Board angle per unit of arm tilt. Above 1 a small tilt steers a lot. */
  tiltGain: number;
  /** Arm tilt (degrees) below which the board stays level. */
  tiltDeadzone: number;
  /** Steepest board angle, degrees. */
  maxAngle: number;
  /** Seconds the arms must be held out to start a ride. */
  poseHoldS: number;
  /** Shoulder-line tilt is multiplied by this when the arms cannot be used (shoulders tilt less). */
  shoulderGain: number;
  /** One Euro filter cutoff when the arms are still (Hz). Lower = steadier, laggier at rest. */
  filterMinCutoff: number;
  /**
   * How much the filter opens up with arm speed (Hz per rad/s). Higher = less lag when
   * moving and a quicker stop, at the cost of overshoot on a flick (e2e/latency-check.mjs).
   */
  filterBeta: number;
  /** Time constant of the follow that smooths 30 Hz poses to the frame rate (ms). */
  smoothMs: number;
  /** Extrapolate the arms this far ahead of the newest pose (ms; adds overshoot). */
  predictMs: number;

  // --- Ride ---
  /** How fast the wave travels at the start of a ride, world units per second. */
  waveSpeed: number;
  /** How much faster it gets per second of riding. */
  waveSpeedGain: number;
  /** Seconds between a wipeout and the next wait. */
  restartS: number;
  /** Seconds the wave takes to rise under the board. */
  takeoffS: number;
  /** The wave's push at full power (units/s²): sets the top speed trimming in the pocket. */
  wavePower: number;
  /** Water drag per second: how quickly speed settles. */
  waterDrag: number;
  /** Speed gained per unit dropped down the face, and lost climbing (units/s² at 90°). */
  faceGravity: number;
  /** How fast a level board slides down the face (units/s). Angle up a little to hold a line. */
  slideDown: number;
  /** Speed a carve adds (units/s per radian of swing), fed in over a moment like a pump. */
  pumpGain: number;
  /** Upward speed at the lip (units/s) above which the board takes off. */
  launchSpeed: number;
  /** Gravity in the air (units/s²). */
  airGravity: number;
  /** Landing within this many degrees of the ideal angle is perfect. */
  landPerfectDeg: number;
  /** Nose up by more than this (degrees) on landing wipes out. */
  landNoseUpDeg: number;
  /** Seconds the board may sit behind the front of the white water before it is caught. */
  curlGraceS: number;
  /**
   * Seconds of easy riding at the start of every ride; the challenge (slide down the face,
   * full board angle) then ramps in over the same time again.
   */
  easyRideS: number;
  /** Steepest board angle (degrees) while the ride is easy; rises to `maxAngle`. */
  easyMaxAngle: number;
  /** For this long after takeoff nothing ends the ride: the curl spits you out, landings are saved. */
  protectS: number;
  /** After that, how many times per ride the white water spits the board out instead of catching it. */
  closeCalls: number;
  /** Drift of everything floating (pickups, strips, hazards) as a share of the wave speed. */
  pickupDrift: number;
  /** Height of the body that collects stars, above the board (units). */
  avatarHeight: number;
  /** Extra reach around that body (units). */
  pickupReach: number;
  /** Points for a clam (easy lines across the middle of the face) and a crab (risky spots). */
  clamPoints: number;
  crabPoints: number;
  /** Speed (units/s) a clam and a crab add, fed in over a fraction of a second. */
  clamKick: number;
  crabKick: number;
  /** A pickup within this long of the previous one chains a combo. */
  comboWindowS: number;
  /** Each chained pickup's kick is this share bigger than a lone one's, up to `comboMax` links. */
  comboKickStep: number;
  comboMax: number;
  /** Speed (units/s) a boost strip adds. */
  boostKick: number;
  /**
   * Kicks fade out as the board's speed goes from `kickFadeFrom` to `kickFadeTo` times the
   * wave's: they keep you up with the wave rather than fling you out onto the shoulder
   * (where the push is weak and the board then sinks back through the pocket too slowly
   * to recover), and chaining them cannot run away.
   */
  kickFadeFrom: number;
  kickFadeTo: number;
  /** Seconds into a ride before hazards may come (after the easy start). */
  hazardStartS: number;
  /** Chance that the next thing on the water is a hazard, rising per second, to a cap. */
  hazardChance: number;
  hazardChanceGain: number;
  hazardChanceMax: number;
  /** A whirlpool's pull towards its centre at full grip (units/s) and its drag (per s). */
  whirlpoolPull: number;
  whirlpoolDrag: number;
  /** Share of the speed a buoy knocks off, and how hard it knocks the board aside (units/s). */
  buoySpeedLoss: number;
  buoyKnock: number;

  // --- Vision ---
  /**
   * Feed the whole frame to the segmentation model squashed to a square (one inference).
   * Off = square tiles, which the model segments far better.
   */
  stretchInput: boolean;
  /**
   * One player: segment a single tile centred on the tracked person instead of tiles across
   * the whole frame (one inference instead of two for a 16:9 camera). Falls back to the
   * tiles while nobody is tracked or the person is wider than a tile.
   */
  followPlayer: boolean;
  /**
   * Tile side as a fraction of frame height. 1 covers the whole frame; smaller zooms in so
   * small or distant players look bigger to the model, leaving the top of the frame uncovered.
   */
  tileHeight: number;
  /** A mask texel counts as "person" at or above this probability (0..1). */
  maskThreshold: number;
  /**
   * Cutout against steering, where the segmenter cannot do a pose and a mask for every
   * camera frame: how long (in frames) a mask may make the next pose wait. 0 = poses always
   * on time, the cutout gets what is left; 1 = every mask, poses up to a frame late.
   */
  maskPoseWait: number;

  // --- View ---
  mirror: boolean;
  /** HUD inset as a fraction of screen height, for TV overscan. */
  safeMargin: number;
  /** Cap on backbuffer pixels (width × height). */
  maxRenderPixels: number;
  /** How far the camera may zoom out to keep a high jump on screen (0 = pan only). */
  cameraZoomOut: number;

  // --- Look ---
  /**
   * How much of the board's angle the cutout leans with. The player already tilts their
   * real arms, so 1 would double the lean.
   */
  avatarLean: number;
  /** Seconds the cutout's size takes to follow the player stepping nearer or further. */
  avatarScaleSmoothS: number;
  /** Seconds the cutout's feet take to follow the player's feet in the camera picture. */
  avatarAnchorSmoothS: number;
  /** Width of the white sticker outline round the cutout, world units. */
  avatarOutline: number;
  /** Width of the soft edge round the mask threshold (probability units). */
  maskSoftness: number;
  /** Multiplier on spray and foam particles. */
  sprayAmount: number;

  // --- Audio ---
  masterVolume: number;
  /** Music level relative to the master volume. */
  musicVolume: number;
  /** One-shots (splashes, dings, signals) relative to the master volume. */
  effectsVolume: number;
  /** Continuous layers (water, wind, ocean, the curl's roar) relative to the master volume. */
  ambienceVolume: number;

  // --- Debug ---
  /** Show the whole camera picture, with the mask and the skeleton, over the game. */
  showCamera: boolean;
  maskOpacity: number;
}

