/**
 * One Euro filter (Casiez, Roussel, Vogel 2012): a low-pass whose cutoff rises with the
 * signal's speed. Held still it filters hard (rock-steady board); moved fast the cutoff
 * opens up so the lag nearly vanishes. That trade is exactly what arm steering needs.
 *
 *   dx̂ = lowpass(dx, dCutoff)          (smoothed speed, drives the cutoff only)
 *   fc  = minCutoff + beta·max(0, |dx̂| − speedFloor)
 *   x̂  = lowpass(x, fc)
 *
 * with lowpass alpha = 1 / (1 + τ/Te), τ = 1/(2π fc), Te the sample spacing. Samples may
 * be irregular, so Te is passed with each one.
 *
 * `speedFloor` is a small addition to the published filter: landmark noise alone produces
 * a speed estimate of a few tenths of a rad/s, which would keep the cutoff open while the
 * player holds still. Speeds under the floor count as still.
 */
import { clamp } from './math';

function alpha(cutoffHz: number, dtS: number): number {
  const tau = 1 / (2 * Math.PI * cutoffHz);
  return 1 / (1 + tau / dtS);
}

export class OneEuroFilter {
  /** Filtered value. */
  value = 0;
  /** Smoothed derivative (units per second) that drives the cutoff. */
  speed = 0;
  /** Slope of the filtered output between the last two samples (units per second). */
  slope = 0;
  ready = false;

  reset(): void {
    this.ready = false;
    this.value = 0;
    this.speed = 0;
    this.slope = 0;
  }

  update(
    x: number,
    dtS: number,
    minCutoffHz: number,
    beta: number,
    dCutoffHz: number,
    speedFloor = 0,
  ): number {
    if (!this.ready) {
      this.ready = true;
      this.value = x;
      this.speed = 0;
      this.slope = 0;
      return x;
    }
    const dt = clamp(dtS, 1e-3, 1);
    const rawSpeed = (x - this.value) / dt;
    this.speed += alpha(dCutoffHz, dt) * (rawSpeed - this.speed);
    const cutoff = Math.max(
      1e-3,
      minCutoffHz + beta * Math.max(0, Math.abs(this.speed) - speedFloor),
    );
    const next = this.value + alpha(cutoff, dt) * (x - this.value);
    this.slope = (next - this.value) / dt;
    this.value = next;
    return next;
  }
}
