/**
 * Pickups drawn as sea creatures, a golden scallop (common) and a chunky orange crab (rarer,
 * worth more), each with a white sticker edge, a friendly face and a warm glow behind,
 * bobbing and wobbling so they read as alive and collectable. Sprites come from a small
 * pool and are matched to the game's pickups by id each frame; nothing is allocated while
 * riding. A pickup without a `kind` (an older game) is drawn as a scallop.
 */
import { Container, Sprite, type Texture } from 'pixi.js';
import type { Pickup } from '../game/types';
import type { StageTextures } from './textures';

const POOL = 24;
/** Seconds a new star takes to pop in. */
const APPEAR_S = 0.3;

interface Star {
  id: number;
  body: Sprite;
  glow: Sprite;
  age: number;
  phase: number;
  /** Seen in this frame's pickups. */
  seen: boolean;
}

export class PickupView {
  readonly glows = new Container();
  readonly stars = new Container();
  private readonly pool: Star[] = [];
  private timeS = 0;
  private readonly clam: Texture;
  private readonly crab: Texture;

  constructor(textures: StageTextures) {
    this.clam = textures.clam;
    this.crab = textures.crab;
    for (let i = 0; i < POOL; i++) {
      const glow = new Sprite(textures.glow);
      glow.anchor.set(0.5);
      glow.blendMode = 'add';
      glow.visible = false;
      const body = new Sprite(textures.clam);
      body.anchor.set(0.5);
      body.visible = false;
      this.glows.addChild(glow);
      this.stars.addChild(body);
      this.pool.push({ id: -1, body, glow, age: 0, phase: i * 1.7, seen: false });
    }
  }

  update(pickups: readonly Pickup[], dtS: number): void {
    this.timeS += dtS;
    for (const star of this.pool) star.seen = false;
    for (const pickup of pickups) {
      let star = this.find(pickup.id);
      if (!star) {
        star = this.claim(pickup.id);
        if (!star) continue;
      }
      star.seen = true;
      star.age += dtS;
      const crab = pickup.kind === 'crab';
      const texture = crab ? this.crab : this.clam;
      if (star.body.texture !== texture) star.body.texture = texture;
      const t = this.timeS + star.phase;
      const pop = Math.min(1, star.age / APPEAR_S);
      // An overshooting pop-in, then a gentle breathing; the crab dances a little.
      const grow = pop < 1 ? 1 + 0.25 * Math.sin(pop * Math.PI) : 1 + 0.04 * Math.sin(t * 4);
      const size = (pickup.r * (crab ? 3.2 : 3.0)) / 96;
      star.body.visible = true;
      star.body.position.set(pickup.x, pickup.y + 6 * Math.sin(t * 2.6));
      star.body.scale.set(size * grow * pop);
      star.body.rotation = (crab ? 0.22 : 0.12) * Math.sin(t * (crab ? 3.1 : 1.9));
      star.glow.visible = true;
      star.glow.position.copyFrom(star.body.position);
      star.glow.scale.set(((pickup.r * 5) / 128) * (0.9 + 0.12 * Math.sin(t * 3.3)) * pop);
      star.glow.alpha = 0.55;
    }
    // Stars the game no longer has were collected or scrolled away; the burst is the
    // effects' job.
    for (const star of this.pool) {
      if (!star.seen && star.id !== -1) this.release(star);
    }
  }

  clear(): void {
    for (const star of this.pool) this.release(star);
  }

  dispose(): void {
    this.glows.destroy({ children: true });
    this.stars.destroy({ children: true });
  }

  private find(id: number): Star | null {
    for (const star of this.pool) if (star.id === id) return star;
    return null;
  }

  private claim(id: number): Star | null {
    for (const star of this.pool) {
      if (star.id === -1) {
        star.id = id;
        star.age = 0;
        return star;
      }
    }
    return null;
  }

  private release(star: Star): void {
    star.id = -1;
    star.body.visible = false;
    star.glow.visible = false;
  }
}
