/**
 * The Pixi stage: one WebGL renderer, a world-unit scene graph and the frame loop.
 *
 * Everything lives under one container scaled by `view.screenScale`, so all placement is
 * in world units (1080 high) and comes from the ViewTransform. Layers, bottom to top:
 *
 *   sky and clouds (screen space)
 *   camera (zooms out and pans up to follow big jumps, leans left to show the curl):
 *     distant land, water (sea, face, barrel), spray behind the surfer, reflection, wake
 *     and shadow, pickups, the surfer, the curl's curtain and white water, spray and foam
 *     in front, score popups
 *   debug camera view (screen space)
 *   HUD (screen space, inside the safe area)
 */
import { autoDetectRenderer, Container, Ticker, WebGLRenderer } from 'pixi.js';
import type { Tunables } from '../config/tunables';
import { Emitter, type Unsubscribe } from '../core/events';
import type { ViewTransform } from '../core/view';
import type { Game, GameEvent } from '../game/types';
import type { FramePair } from '../vision/types';
import { AvatarCutout } from './avatar';
import { CameraRig, type CameraTarget } from './camera';
import { DebugView } from './debugView';
import { Effects, FX } from './effects';
import { loadFonts } from './fonts';
import { FrameStats } from './frameStats';
import { BoostView, HazardView } from './hazards';
import { HudView, Popups } from './hud';
import { PALETTE as P } from './palette';
import { PickupView } from './pickups';
import { capResolution } from './resolution';
import { SkyLayer } from './sky';
import { SurferView } from './surfer';
import { createStageTextures, type StageTextures } from './textures';
import type { RenderStats, Stage, StageOptions } from './types';
import { CurlLayer, WaterLayer, type WaterState } from './water';

/** Longest frame the simulation is stepped by; a stall longer than this slows time instead. */
const MAX_DT_MS = 50;
/** The horizon sits this far down the screen (above the lip of a full wave). */
const HORIZON_FRACTION = 0.28;
/** The sun, as fractions of the world size. */
const SUN_X = 0.75;
const SUN_Y = 0.11;
const BACK_PARTICLES = 700;
const FRONT_PARTICLES = 900;
/**
 * The game keeps the curl at about an eighth of the width, which leaves the break a sliver
 * at the edge. The camera leans left by this much (world units) once the wave is up, and by
 * up to the second amount more while the surfer is near the curl, so the danger has room.
 * It gives the room back as the surfer heads for the right edge.
 */
const CURL_ROOM = 70;
const CURL_ROOM_NEAR = 120;
/** The white water surging past the curl line: how far, and how long it lasts. */
const CLOSE_CALL_SURGE = 70;
const WIPEOUT_SURGE = 0.3;
/** Popups for moves appear this far ahead of the surfer (world units), clear of the body. */
const POPUP_AHEAD = 200;

/** Everything that exists only after `init`. */
interface Scene {
  renderer: WebGLRenderer;
  textures: StageTextures;
  sky: SkyLayer;
  water: WaterLayer;
  curl: CurlLayer;
  avatar: AvatarCutout;
  surfer: SurferView;
  pickups: PickupView;
  hazards: HazardView;
  boosts: BoostView;
  back: Effects;
  front: Effects;
  popups: Popups;
  hud: HudView;
  debug: DebugView;
}

class PixiStage implements Stage {
  readonly stats: RenderStats = {
    fps: 0,
    frameMsP95: 0,
    bufferWidth: 0,
    bufferHeight: 0,
    resolution: 1,
    particles: 0,
    glRenderer: null,
  };

  private readonly container: HTMLElement;
  private readonly tunables: Tunables;
  private readonly resized = new Emitter<[number, number]>();
  private readonly contextLost = new Emitter<void>();
  private readonly contextRestored = new Emitter<void>();
  private readonly frameStats = new FrameStats();

  private readonly root = new Container();
  private readonly world = new Container();
  private readonly cameraLayer = new Container();
  private readonly camera = new CameraRig();
  /** Reused every frame, so following the surfer allocates nothing. */
  private readonly cameraTarget: CameraTarget = {
    topY: 0,
    limitY: 0,
    pivotY: 1080,
    maxZoomOut: 0,
    shiftX: 0,
  };
  private readonly waterState: WaterState = {
    timeS: 0,
    distance: 0,
    lipY: 0,
    bottomY: 0,
    horizonY: 0,
    curlX: 0,
    rise: 0,
    sunX: 0,
    pixel: 1,
    centerX: 0,
    surge: 0,
  };
  private scene: Scene | null = null;
  /** A frame that arrived before `init` finished; handed over once the avatar exists. */
  private pendingPair: FramePair | null = null;

  private view: ViewTransform | null = null;
  private tick: ((dtMs: number, nowMs: number) => void) | null = null;
  private resizeObserver: ResizeObserver | null = null;
  private cssWidth = 1;
  private cssHeight = 1;
  /** What the renderer was last sized to (Pixi rounds its own screen size). */
  private appliedWidth = 0;
  private appliedHeight = 0;
  private running = false;
  private lost = false;
  private disposed = false;
  private raf = 0;
  private lastFrameMs = 0;
  /** Text was last rendered for this many device pixels per world unit. */
  private textResolution = 0;

  private timeS = 0;
  private horizon = HORIZON_FRACTION * 1080;
  /** Emitter accumulators: fractional particles carried to the next frame. */
  private lipCarry = 0;
  private curlCarry = 0;
  private boardCarry = 0;
  private streakCarry = 0;
  private rippleClock = 0;
  /** Surge of the white water: seconds since the last one started, its size and length. */
  private surgeS = Number.POSITIVE_INFINITY;
  private surgeSize = 0;
  private surgeHoldS = 0.4;

  constructor(options: StageOptions) {
    this.container = options.container;
    this.tunables = options.tunables;
    this.root.addChild(this.world);
  }

  get screenWidth(): number {
    return this.scene?.renderer.screen.width ?? this.cssWidth;
  }

  get screenHeight(): number {
    return this.scene?.renderer.screen.height ?? this.cssHeight;
  }

  async init(): Promise<void> {
    if (this.scene || this.disposed) return;
    this.measure();
    // WebGL only: a list with one entry means no fallback to WebGPU or canvas.
    const [renderer] = await Promise.all([
      autoDetectRenderer({
        preference: ['webgl'],
        width: this.cssWidth,
        height: this.cssHeight,
        resolution: this.targetResolution(),
        autoDensity: true,
        antialias: false,
        background: P.skyLow,
        // Input comes from the camera: no Pixi pointer hit-testing, and no accessibility
        // layer popping up over the canvas when someone tabs to the Start button.
        eventFeatures: { move: false, globalMove: false, click: false, wheel: false },
        accessibilityOptions: { activateOnTab: false },
      }),
      // The HUD text is laid out with the real font, so wait for it (briefly).
      loadFonts(),
    ]);
    if (this.disposed || !(renderer instanceof WebGLRenderer)) {
      renderer.destroy();
      if (this.disposed) return;
      throw new Error('WebGL is not available');
    }
    this.appliedWidth = this.cssWidth;
    this.appliedHeight = this.cssHeight;
    const canvas = renderer.canvas;
    canvas.addEventListener('webglcontextlost', this.handleContextLost);
    canvas.addEventListener('webglcontextrestored', this.handleContextRestored);
    this.container.appendChild(canvas);
    this.stats.glRenderer = readGlRenderer(renderer.gl);

    const textures = createStageTextures();
    const avatar = new AvatarCutout(this.tunables);
    const scene: Scene = {
      renderer,
      textures,
      sky: new SkyLayer(textures),
      water: new WaterLayer(),
      curl: new CurlLayer(),
      avatar,
      surfer: new SurferView(textures, avatar, this.tunables),
      pickups: new PickupView(textures),
      hazards: new HazardView(textures),
      boosts: new BoostView(textures),
      back: new Effects(textures.effects, BACK_PARTICLES),
      front: new Effects(textures.effects, FRONT_PARTICLES),
      popups: new Popups(),
      hud: new HudView(textures),
      debug: new DebugView(this.tunables),
    };
    this.cameraLayer.addChild(
      scene.sky.land,
      scene.water.view,
      scene.boosts.container,
      scene.hazards.whirls,
      scene.back.container,
      scene.surfer.reflection,
      scene.surfer.under,
      scene.pickups.glows,
      scene.pickups.stars,
      scene.hazards.buoys,
      scene.surfer.rig,
      scene.curl.view,
      scene.front.container,
    );
    this.world.addChild(
      scene.sky.back,
      this.cameraLayer,
      scene.popups.container,
      scene.debug.container,
      scene.hud.container,
    );
    this.scene = scene;
    if (this.pendingPair) {
      avatar.setFrame(this.pendingPair);
      this.pendingPair = null;
    }
    if (this.view) this.setView(this.view);
    this.updateBufferStats();

    this.resizeObserver = new ResizeObserver(() => this.applySize());
    this.resizeObserver.observe(this.container);
    // Pixi's own system ticker runs its texture GC; it pauses with the stage.
    if (!this.running) Ticker.system.stop();
  }

  onResize(listener: (screenWidth: number, screenHeight: number) => void): Unsubscribe {
    return this.resized.on(([width, height]) => listener(width, height));
  }

  onContextLost(listener: () => void): Unsubscribe {
    return this.contextLost.on(() => listener());
  }

  onContextRestored(listener: () => void): Unsubscribe {
    return this.contextRestored.on(() => listener());
  }

  setView(view: ViewTransform): void {
    this.view = view;
    this.world.scale.set(view.screenScale);
    const scene = this.scene;
    if (!scene) return;
    scene.sky.setWidth(view.worldWidth);
    scene.debug.setView(view);
    this.textResolution = 0;
    this.applyTextResolution();
  }

  setAvatarFrame(pair: FramePair | null): void {
    if (this.disposed) {
      pair?.image.close();
      return;
    }
    const scene = this.scene;
    if (!scene) {
      if (this.pendingPair && this.pendingPair !== pair) this.pendingPair.image.close();
      this.pendingPair = pair;
      return;
    }
    scene.avatar.setFrame(pair);
  }

  setTick(handler: ((dtMs: number, nowMs: number) => void) | null): void {
    this.tick = handler;
  }

  update(game: Game, events: readonly GameEvent[], dtMs: number): void {
    const scene = this.scene;
    const view = this.view;
    if (!scene || !view) return;
    const dtS = dtMs / 1000;
    this.timeS += dtS;
    const { wave, surfer } = game;
    const width = view.worldWidth;
    const height = view.worldHeight;
    const spray = this.tunables.sprayAmount;

    // The horizon stays put unless a wave taller than expected would reach it.
    const wantHorizon = Math.min(HORIZON_FRACTION * height, wave.lipY - 60);
    this.horizon += (wantHorizon - this.horizon) * Math.min(1, dtS * 2);

    scene.back.waterSpeed = wave.speed;
    scene.front.waterSpeed = wave.speed;
    for (const event of events) this.handleEvent(scene, game, event);

    scene.hazards.update(game.hazards, dtS);
    scene.boosts.update(game.boosts, dtS);
    scene.surfer.update(game, dtS, view.mirrored, scene.hazards.grip);

    // Follow big jumps: keep the rider's head (and raised hands) inside the safe area. On
    // the way up it looks a little ahead, so the follow's lag never cuts the head off.
    const rising = surfer.airborne ? Math.min(0, surfer.vy) * 0.22 : 0;
    const top = game.phase === 'wipeout' ? height : scene.surfer.headY - 60 + rising;
    const target = this.cameraTarget;
    target.topY = top;
    target.limitY = view.safeRect.y + 30;
    target.pivotY = height;
    target.maxZoomOut = this.tunables.cameraZoomOut;
    target.shiftX = this.curlRoom(game, width);
    this.camera.update(target, dtS);
    const { zoom, pan, shift } = this.camera;
    const pivotX = width / 2;
    this.cameraLayer.scale.set(zoom);
    this.cameraLayer.position.set(
      pivotX * (1 - zoom) + shift + this.camera.kickX,
      height * (1 - zoom) + pan + this.camera.kickY,
    );
    const horizonScreen = (this.horizon - height) * zoom + height + pan;

    const sunX = SUN_X * width;
    const sunY = SUN_Y * height + pan * 0.15;
    scene.sky.update(this.timeS, wave.distance, this.horizon, horizonScreen, pan, sunX, sunY);

    const faceHeight = Math.max(0, wave.bottomY - wave.lipY);
    // What the camera sees, in world units.
    const leftSeen = (0 - shift - pivotX) / zoom + pivotX;
    const rightSeen = (width - shift - pivotX) / zoom + pivotX;
    const topSeen = (0 - pan - height) / zoom + height;
    scene.water.setBounds(
      leftSeen - 60,
      Math.max(topSeen, Math.min(this.horizon, wave.lipY - 0.8 * faceHeight) - 40),
      rightSeen + 60,
      height + 20,
    );
    const water = this.waterState;
    water.timeS = this.timeS;
    water.distance = wave.distance;
    water.lipY = wave.lipY;
    water.bottomY = wave.bottomY;
    water.horizonY = this.horizon;
    water.curlX = wave.curlX;
    water.rise = wave.rise;
    water.sunX = (sunX - shift - pivotX) / zoom + pivotX;
    water.pixel = 1 / (view.screenScale * scene.renderer.resolution * zoom);
    water.centerX = pivotX;
    water.surge = this.surge(dtS, faceHeight);
    scene.water.update(water);
    scene.curl.update(water, leftSeen);

    scene.pickups.update(game.pickups, dtS);
    this.emit(scene, game, dtS, spray, faceHeight);
    scene.back.update(dtS);
    scene.front.update(dtS);
    scene.popups.update(dtS);

    // The curl is close behind: warn while there is still room to get away.
    let danger = 0;
    if (game.phase === 'riding' && wave.rise > 0.5) {
      const gap = surfer.x - wave.curlX;
      danger = Math.max(0, Math.min(1, 1 - (gap - 0.5 * faceHeight) / (0.6 * faceHeight + 1)));
    }
    scene.hud.update(game, events, dtS, danger);
    scene.debug.update(scene.avatar.imageTexture, scene.avatar.lastMask, scene.avatar.lastPose);
    this.stats.particles = scene.back.count + scene.front.count;
  }

  /** Where a world point is on screen (before the world scale), with the camera as it is. */
  private screenX(x: number): number {
    const pivotX = (this.view?.worldWidth ?? 1920) / 2;
    return (x - pivotX) * this.camera.zoom + pivotX + this.camera.shift + this.camera.kickX;
  }

  private screenY(y: number): number {
    const height = this.view?.worldHeight ?? 1080;
    return (y - height) * this.camera.zoom + height + this.camera.pan + this.camera.kickY;
  }

  /** A short jolt of the camera (landings, wipeouts), world units. */
  private kick(amount: number): void {
    this.camera.kick(amount);
  }

  /** How far the camera leans left to give the curl room (see CURL_ROOM). */
  private curlRoom(game: Game, width: number): number {
    const { wave, surfer } = game;
    const near = 1 - smoothstep(250, 900, surfer.x - wave.curlX);
    const away = 1 - smoothstep(0.6 * width, 0.8 * width, surfer.x);
    return wave.rise * (CURL_ROOM + CURL_ROOM_NEAR * near * away) * (0.5 + 0.5 * away);
  }

  /** Start a surge of the white water past the curl line. */
  private startSurge(size: number, holdS: number): void {
    this.surgeS = 0;
    this.surgeSize = size;
    this.surgeHoldS = holdS;
  }

  /** The surge right now: a quick shove forward, then it settles back. */
  private surge(dtS: number, faceHeight: number): number {
    this.surgeS += dtS;
    const t = this.surgeS;
    if (!(t < this.surgeHoldS + 3)) return 0;
    const size = this.surgeSize > 1 ? this.surgeSize : this.surgeSize * faceHeight;
    const rise = smoothstep(0, 0.14, t);
    const fall = Math.exp(-Math.max(0, t - this.surgeHoldS) / 0.45);
    return size * rise * fall;
  }

  clear(): void {
    const scene = this.scene;
    if (!scene) return;
    this.surgeS = Number.POSITIVE_INFINITY;
    scene.back.clear();
    scene.front.clear();
    scene.popups.clear();
    scene.pickups.clear();
    scene.hazards.clear();
    scene.boosts.clear();
    scene.hud.clear();
    scene.surfer.clear();
    this.camera.reset();
    this.stats.particles = 0;
  }

  start(): void {
    if (this.running || this.disposed) return;
    this.running = true;
    this.lastFrameMs = 0;
    this.frameStats.reset();
    Ticker.system.start();
    this.raf = requestAnimationFrame(this.frame);
  }

  stop(): void {
    if (!this.running) return;
    this.running = false;
    cancelAnimationFrame(this.raf);
    Ticker.system.stop();
  }

  dispose(): void {
    if (this.disposed) return;
    this.stop();
    this.disposed = true;
    this.resizeObserver?.disconnect();
    this.resizeObserver = null;
    this.resized.clear();
    this.contextLost.clear();
    this.contextRestored.clear();
    this.tick = null;
    this.pendingPair?.image.close();
    this.pendingPair = null;
    const scene = this.scene;
    this.scene = null;
    if (!scene) return;
    scene.avatar.dispose();
    scene.surfer.dispose();
    scene.back.dispose();
    scene.front.dispose();
    scene.pickups.dispose();
    scene.hazards.dispose();
    scene.boosts.dispose();
    scene.popups.container.destroy({ children: true });
    scene.hud.dispose();
    scene.debug.dispose();
    scene.water.dispose();
    scene.curl.dispose();
    scene.sky.dispose();
    scene.textures.destroy();
    this.root.destroy({ children: true });
    const canvas = scene.renderer.canvas;
    canvas.removeEventListener('webglcontextlost', this.handleContextLost);
    canvas.removeEventListener('webglcontextrestored', this.handleContextRestored);
    scene.renderer.destroy({ removeView: true });
    // The renderer was the system ticker's only user; leave it as Pixi expects to find it.
    Ticker.system.start();
  }

  // -------------------------------------------------------------------------------------
  // Effects
  // -------------------------------------------------------------------------------------

  private handleEvent(scene: Scene, game: Game, event: GameEvent): void {
    const { front, popups } = scene;
    const r = Math.random;
    const spray = this.tunables.sprayAmount;
    const n = (count: number) => Math.round(count * Math.max(0.2, spray));
    switch (event.type) {
      case 'launch': {
        scene.surfer.impact(-0.07);
        // A kick of spray off the lip as the board leaves it.
        for (let i = 0; i < n(26); i++) {
          front.spawn(
            FX.droplet,
            event.x + (r() - 0.6) * 90,
            event.y,
            -80 - 380 * r(),
            -250 - 520 * r(),
            3 + 4 * r(),
            2,
            0.7 + 0.4 * r(),
            P.foam,
          );
        }
        // A little spray, small and brief: big puffs at the lip read as smoke on the sky.
        for (let i = 0; i < n(5); i++) {
          front.spawn(
            FX.mist,
            event.x - 60 * r(),
            event.y + 6,
            -120 * r(),
            -80 * r(),
            14,
            34 + 14 * r(),
            0.55,
            P.foam,
            0.32,
            0.3,
          );
        }
        break;
      }
      case 'land': {
        this.splash(scene, event.x, event.y, event.quality === 'perfect' ? 1.1 : 0.85);
        // The knees take it, and the camera feels it a little: more for a bigger drop.
        const drop = Math.min(1, event.height / 200);
        scene.surfer.impact(0.08 + 0.1 * drop);
        this.kick(4 + 8 * drop);
        const perfect = event.quality === 'perfect';
        popups.spawn(
          this.screenX(scene.surfer.drawnX + POPUP_AHEAD),
          this.screenY(scene.surfer.headY + 60),
          perfect ? `Perfect!\n+${event.points}` : `+${event.points}`,
          perfect ? P.accent : P.text,
          perfect ? 'big' : 'normal',
        );
        break;
      }
      case 'carve': {
        const up = event.where === 'top' ? -1 : -0.6;
        for (let i = 0; i < n(30); i++) {
          front.spawn(
            FX.droplet,
            event.x - 60 * r(),
            event.y,
            -150 - 450 * r(),
            up * (300 + 450 * r()),
            2.5 + 4 * r(),
            2,
            0.6 + 0.4 * r(),
            P.foam,
          );
        }
        for (let i = 0; i < n(6); i++) {
          front.spawn(
            FX.mist,
            event.x - 80 * r(),
            event.y - 4,
            -150 * r(),
            -70 * r(),
            14,
            38,
            0.6,
            P.foam,
            0.32,
            0.4,
          );
        }
        popups.spawn(
          this.screenX(scene.surfer.drawnX + POPUP_AHEAD),
          this.screenY(scene.surfer.headY + 90),
          `+${event.points}`,
          P.text,
          'normal',
        );
        break;
      }
      case 'pickup': {
        // Older games send no kind or combo: a scallop, not chained.
        const crab = event.kind === 'crab';
        const combo = Math.max(1, event.combo ?? 1);
        const more = Math.min(5, combo - 1);
        const glow = crab ? 0xffc070 : P.starLight;
        front.spawn(FX.flash, event.x, event.y, 0, 0, 40, 140 + 20 * more, 0.25, glow, 0.9);
        front.spawn(FX.ring, event.x, event.y, 0, 0, 30, 150 + 25 * more, 0.5, glow, 1);
        const bits = 12 + 3 * more + (crab ? 6 : 0);
        for (let i = 0; i < bits; i++) {
          const a = (i / bits) * Math.PI * 2 + r() * 0.4;
          const speed = 260 + 260 * r() + 40 * more;
          front.spawn(
            FX.star,
            event.x,
            event.y,
            Math.cos(a) * speed,
            Math.sin(a) * speed - 120,
            9 + 7 * r(),
            4,
            0.7 + 0.3 * r(),
            r() < 0.5 ? P.star : P.starLight,
          );
        }
        for (let i = 0; i < 5; i++) {
          front.spawn(
            FX.spark,
            event.x + (r() - 0.5) * 80,
            event.y + (r() - 0.5) * 80,
            0,
            -30,
            22 + 14 * r(),
            0,
            0.4 + 0.2 * r(),
            0xffffff,
          );
        }
        // Every pickup is a little push forward: a few gold streaks off the board.
        this.boostStreaks(scene, 4 + more);
        popups.spawnPickup(
          this.screenX(event.x),
          this.screenY(event.y - 50),
          event.points,
          event.combo,
        );
        break;
      }
      case 'boost': {
        // Over a boost strip: a flash of gold under the board, streaks, a push forward.
        front.spawn(FX.flash, event.x, event.y, 0, 0, 60, 220, 0.3, P.star, 0.8);
        front.spawn(FX.ring, event.x, event.y + 4, 0, 0, 40, 220, 0.6, P.star, 0.9, 1);
        for (let i = 0; i < n(26); i++) {
          front.spawn(
            FX.droplet,
            event.x - 60 * r(),
            event.y,
            -200 - 500 * r(),
            -150 - 350 * r(),
            2.5 + 3 * r(),
            2,
            0.5 + 0.4 * r(),
            r() < 0.5 ? P.foam : P.starLight,
          );
        }
        this.boostStreaks(scene, 16);
        this.camera.push(-26);
        popups.spawn(
          this.screenX(scene.surfer.drawnX + POPUP_AHEAD),
          this.screenY(scene.surfer.headY + 60),
          'Boost!',
          P.accent,
          'shout',
        );
        break;
      }
      case 'hazard': {
        if (event.kind === 'buoy') {
          scene.hazards.bonk(event.id, game.surfer.x < event.x);
          front.spawn(FX.flash, event.x, event.y - 40, 0, 0, 40, 150, 0.2, 0xffffff, 0.9);
          front.spawn(FX.ring, event.x, event.y + 4, 0, 0, 30, 170, 0.6, P.foam, 0.9, 1);
          for (let i = 0; i < n(22); i++) {
            const a = -Math.PI * r();
            front.spawn(
              FX.droplet,
              event.x,
              event.y - 20,
              Math.cos(a) * (200 + 300 * r()),
              Math.sin(a) * (250 + 350 * r()),
              3 + 3 * r(),
              2,
              0.6 + 0.3 * r(),
              P.foam,
            );
          }
          for (let i = 0; i < 4; i++) {
            front.spawn(
              FX.spark,
              event.x + (r() - 0.5) * 70,
              event.y - 50 + (r() - 0.5) * 60,
              0,
              -20,
              24 + 12 * r(),
              0,
              0.35,
              0xffffff,
            );
          }
          this.kick(10);
          popups.spawn(
            this.screenX(scene.surfer.drawnX + POPUP_AHEAD),
            this.screenY(scene.surfer.headY + 60),
            'Bonk!',
            P.warm,
            'shout',
          );
        } else {
          // The whirlpool takes hold: a swirl of foam rings, and a word of warning.
          front.spawn(FX.ring, event.x, event.y, 0, 0, 120, 30, 0.7, P.foamShade, 0.8, 1);
          front.spawn(FX.ring, event.x, event.y, 0, 0, 160, 50, 0.9, P.foam, 0.5, 1);
          this.kick(6);
          popups.spawn(
            this.screenX(scene.surfer.drawnX + POPUP_AHEAD),
            this.screenY(scene.surfer.headY + 60),
            'Whirlpool!',
            P.warm,
            'shout',
          );
        }
        break;
      }
      case 'closeCall': {
        // The white water surges, swallows the tail and spits the board out forward.
        this.startSurge(CLOSE_CALL_SURGE, 0.25);
        for (let i = 0; i < n(18); i++) {
          front.spawn(
            FX.foam,
            event.x - 90 + 110 * r(),
            event.y - 50 * r(),
            180 + 380 * r(),
            -120 - 260 * r(),
            12 + 10 * r(),
            26 + 18 * r(),
            0.55 + 0.35 * r(),
            r() < 0.7 ? P.foam : P.foamShade,
            0.95,
            0.3,
          );
        }
        for (let i = 0; i < n(30); i++) {
          front.spawn(
            FX.droplet,
            event.x - 60 + 80 * r(),
            event.y - 30 * r(),
            250 + 550 * r(),
            -200 - 500 * r(),
            2.5 + 4 * r(),
            2,
            0.6 + 0.4 * r(),
            P.foam,
          );
        }
        for (let i = 0; i < n(6); i++) {
          front.spawn(
            FX.mist,
            event.x - 60 * r(),
            event.y - 40 * r(),
            120 + 200 * r(),
            -80 * r(),
            30,
            90 + 40 * r(),
            0.9,
            P.foam,
            0.45,
            0.3,
          );
        }
        popups.spawn(
          this.screenX(scene.surfer.drawnX + POPUP_AHEAD),
          this.screenY(scene.surfer.headY + 40),
          'Close call!',
          P.warm,
          'shout',
        );
        this.kick(14);
        break;
      }
      case 'wipeout': {
        scene.surfer.wipeout();
        if (event.cause === 'curl') {
          // Swallowed: the white water rolls over the surfer.
          this.startSurge(WIPEOUT_SURGE, 0.9);
          this.splash(scene, event.x, event.y, 1.4);
          for (let i = 0; i < n(22); i++) {
            front.spawn(
              FX.foam,
              event.x - 120 + 200 * r(),
              event.y - 160 * r(),
              (r() - 0.3) * 260,
              -80 - 160 * r(),
              16 + 12 * r(),
              34 + 24 * r(),
              0.9 + 0.6 * r(),
              P.foam,
              1,
              0.6,
            );
          }
        } else {
          // A bad landing: a big splash on the face, white water sliding off down it.
          this.splash(scene, event.x, event.y, 1.6);
          for (let i = 0; i < n(18); i++) {
            front.spawn(
              FX.foam,
              event.x + (r() - 0.5) * 220,
              event.y + 10 + 50 * r(),
              (r() - 0.6) * 160,
              30 + 60 * r(),
              10 + 8 * r(),
              24 + 16 * r(),
              1.0 + 0.6 * r(),
              r() < 0.6 ? P.foam : P.foamShade,
              0.9,
              1,
            );
          }
        }
        this.kick(22);
        break;
      }
      case 'phase':
        void game;
        break;
    }
  }

  /** Gold speed lines streaming back off the board: the look of a push forward. */
  private boostStreaks(scene: Scene, count: number): void {
    const { front, surfer } = scene;
    const r = Math.random;
    for (let i = 0; i < count; i++) {
      front.spawn(
        FX.streak,
        surfer.drawnX - 60 + 160 * r(),
        surfer.drawnY - 20 - 260 * r(),
        -1100 - 700 * r(),
        0,
        40 + 50 * r(),
        70,
        0.3 + 0.2 * r(),
        r() < 0.5 ? P.starLight : P.foam,
        0.7,
      );
    }
  }

  /** Water thrown up both ways, a ring on the water, mist and foam. */
  private splash(scene: Scene, x: number, y: number, size: number): void {
    const { front } = scene;
    const r = Math.random;
    const count = Math.round(34 * size * Math.max(0.2, this.tunables.sprayAmount));
    for (let i = 0; i < count; i++) {
      const side = r() < 0.5 ? -1 : 1;
      front.spawn(
        FX.droplet,
        x + side * 30 * r(),
        y,
        side * (60 + 320 * r()) * size,
        -(260 + 520 * r()) * size,
        2.5 + 4.5 * r(),
        2,
        0.6 + 0.5 * r(),
        P.foam,
      );
    }
    front.spawn(FX.ring, x, y + 4, 0, 0, 40 * size, 190 * size, 0.9, P.foam, 0.8, 1);
    // A low puff of spray: kept small and short, or it hangs there like smoke.
    for (let i = 0; i < Math.round(6 * size); i++) {
      front.spawn(
        FX.mist,
        x + (r() - 0.5) * 120 * size,
        y - 10 * r(),
        (r() - 0.5) * 160,
        -90 * r(),
        18 * size,
        (34 + 22 * r()) * size,
        0.55 + 0.3 * r(),
        P.foam,
        0.4,
        0.5,
      );
    }
    // White water left lying on the face, riding away with it.
    for (let i = 0; i < Math.round(10 * size); i++) {
      front.spawn(
        FX.foam,
        x + (r() - 0.5) * 150 * size,
        y + 6 + 14 * r(),
        (r() - 0.5) * 120,
        10 * r(),
        8 * size,
        (16 + 8 * r()) * size,
        0.8 + 0.5 * r(),
        r() < 0.6 ? P.foam : P.foamShade,
        0.9,
        1,
      );
    }
  }

  /** Continuous spray: off the lip, out of the curl, off the board, and speed lines. */
  private emit(scene: Scene, game: Game, dtS: number, spray: number, faceHeight: number): void {
    const { back, front, surfer: view } = scene;
    const { wave, surfer } = game;
    const r = Math.random;
    const width = this.view?.worldWidth ?? 1920;
    const formed = smoothstep(0.35, 0.9, wave.rise);

    // Spray lifting off the lip along the open face, more of it near the curl.
    this.lipCarry += dtS * 34 * spray * formed;
    while (this.lipCarry >= 1 && back.room > 40) {
      this.lipCarry -= 1;
      const span = width + 200 - wave.curlX;
      const x = wave.curlX + span * r() ** 1.6;
      const near = Math.exp(-(x - wave.curlX) / 600);
      back.spawn(
        FX.mist,
        x,
        wave.lipY - 4,
        -40 - 60 * r(),
        -50 - 110 * r(),
        10 + 10 * near,
        34 + 40 * near,
        0.9 + 0.6 * r(),
        P.foam,
        0.28 + 0.25 * near,
        0.25,
      );
      if (r() < 0.5) {
        back.spawn(
          FX.droplet,
          x,
          wave.lipY - 2,
          -30 - 90 * r(),
          -220 - 320 * r() * (0.5 + near),
          2 + 2.5 * r(),
          1.5,
          0.5 + 0.3 * r(),
          P.foam,
          0.9,
        );
      }
    }
    this.lipCarry = Math.min(this.lipCarry, 4);

    // The curl churns: spray blown up off the heap, drops flung off the throw, and white
    // water tumbling out of its front. Drawn over the curl layer, which carries the bulk.
    if (faceHeight > 40 && formed > 0) {
      this.curlCarry += dtS * 70 * spray * formed;
      const H = faceHeight;
      const x0 = wave.curlX + this.waterState.surge;
      while (this.curlCarry >= 1 && front.room > 60) {
        this.curlCarry -= 1;
        const pick = r();
        if (pick < 0.3) {
          const x = x0 - H * (0.35 + 0.8 * r());
          front.spawn(
            FX.mist,
            x,
            wave.lipY - H * (0.12 + 0.1 * r()),
            -40 - 60 * r(),
            -60 - 120 * r(),
            24,
            60 + 40 * r(),
            0.9 + 0.5 * r(),
            P.foam,
            0.3,
            0,
          );
        } else if (pick < 0.65) {
          // Off the throw and out of the foot, flung forward and up.
          const low = r() < 0.5;
          front.spawn(
            FX.droplet,
            x0 + (low ? -0.04 : 0.06) * H,
            wave.lipY + H * (low ? 0.75 + 0.2 * r() : 0.05 + 0.25 * r()),
            100 + 300 * r(),
            -250 - 380 * r(),
            2.5 + 3.5 * r(),
            2,
            0.5 + 0.4 * r(),
            P.foam,
          );
        } else {
          // Spat out along the bottom of the front.
          front.spawn(
            FX.droplet,
            x0 + H * 0.02 * r(),
            wave.lipY + H * (0.7 + 0.35 * r()),
            60 + 220 * r(),
            -120 - 260 * r(),
            3 + 3 * r(),
            2,
            0.4 + 0.3 * r(),
            P.foam,
          );
        }
      }
      this.curlCarry = Math.min(this.curlCarry, 6);
    }

    // Spray off the board: more when it turns hard and goes fast.
    const riding = game.phase === 'riding' || game.phase === 'takeoff';
    if (riding && !surfer.airborne && wave.rise > 0.25) {
      const speed = Math.min(1.5, surfer.speed / 900);
      const turn = Math.abs(surfer.turn);
      this.boardCarry += dtS * 70 * spray * speed * (0.2 + 1.8 * turn);
      while (this.boardCarry >= 1 && front.room > 30) {
        this.boardCarry -= 1;
        const x = view.tailX + (r() - 0.5) * 40;
        const y = view.tailY - 4;
        const lift = 0.5 + turn;
        if (r() < 0.7) {
          front.spawn(
            FX.droplet,
            x,
            y,
            -120 - 320 * r(),
            -(180 + 420 * r()) * lift,
            2 + 3.5 * r(),
            1.5,
            0.45 + 0.35 * r(),
            P.foam,
          );
        } else {
          front.spawn(
            FX.mist,
            x,
            y,
            -100 - 120 * r(),
            -60 - 120 * r() * lift,
            10,
            30 + 20 * turn,
            0.6 + 0.3 * r(),
            P.foam,
            0.4,
            0.3,
          );
        }
      }
      this.boardCarry = Math.min(this.boardCarry, 4);
    }

    // Water streaming off the board in the air: it reads as height and speed.
    if (surfer.airborne && game.phase !== 'wipeout') {
      this.boardCarry += dtS * 28 * spray;
      while (this.boardCarry >= 1 && front.room > 30) {
        this.boardCarry -= 1;
        front.spawn(
          FX.droplet,
          view.drawnX + (r() - 0.6) * 200,
          view.drawnY + 4,
          -60 - 120 * r(),
          40 + 80 * r(),
          2 + 2.5 * r(),
          1.5,
          0.5 + 0.4 * r(),
          P.foam,
          0.85,
        );
      }
      this.boardCarry = Math.min(this.boardCarry, 4);
    }

    // Speed lines streaming past: a whisper when fast, a rush of gold while boosted.
    const boost = Math.max(0, Math.min(1, surfer.boost || 0));
    if (game.phase === 'riding' && (surfer.speed > 750 || boost > 0.05)) {
      this.streakCarry += dtS * (Math.min(30, Math.max(0, surfer.speed - 750) / 25) + 50 * boost);
      while (this.streakCarry >= 1 && back.room > 80) {
        this.streakCarry -= 1;
        const gold = r() < boost;
        const x = view.drawnX - 300 + 900 * r();
        const y = gold
          ? view.drawnY - 300 * r() + 40
          : wave.lipY + (wave.bottomY - wave.lipY) * r();
        (gold ? front : back).spawn(
          FX.streak,
          x,
          y,
          -900 - 500 * r() - 600 * boost,
          0,
          40 + 50 * r() + 40 * boost,
          60,
          0.3 + 0.2 * r(),
          gold ? P.starLight : P.foam,
          gold ? 0.5 : 0.16,
        );
      }
      this.streakCarry = Math.min(this.streakCarry, 4);
    }

    // Calm water: rings spreading slowly round the floating board.
    if (game.phase === 'waiting') {
      this.rippleClock += dtS;
      if (this.rippleClock > 1.3) {
        this.rippleClock = 0;
        back.spawn(
          FX.ring,
          view.drawnX + (r() - 0.5) * 60,
          view.drawnY + 4,
          0,
          0,
          90,
          230,
          2.4,
          P.foamShade,
          0.35,
        );
      }
    }
  }

  // -------------------------------------------------------------------------------------
  // Frame loop and sizing
  // -------------------------------------------------------------------------------------

  private readonly frame = (now: number): void => {
    if (!this.running) return;
    this.raf = requestAnimationFrame(this.frame);
    const scene = this.scene;
    if (!scene || this.lost) return;

    const dtMs = this.lastFrameMs > 0 ? now - this.lastFrameMs : 1000 / 60;
    if (this.lastFrameMs > 0) this.frameStats.add(dtMs);
    this.lastFrameMs = now;

    // The pixel cap and the display's pixel ratio can change at any time.
    if (this.targetResolution() !== scene.renderer.resolution) this.applySize();
    this.applyTextResolution();

    this.tick?.(Math.min(dtMs, MAX_DT_MS), now);
    scene.renderer.render(this.root);

    this.stats.fps = this.frameStats.fps;
    this.stats.frameMsP95 = this.frameStats.frameMsP95;
  };

  /** Re-render text at the size it is shown, when that changes. */
  private applyTextResolution(): void {
    const scene = this.scene;
    const view = this.view;
    if (!scene || !view) return;
    const resolution = scene.renderer.resolution * view.screenScale;
    if (Math.abs(resolution - this.textResolution) < 0.01) return;
    this.textResolution = resolution;
    scene.hud.setLayout(view.safeRect, view.worldWidth, view.worldHeight, resolution);
    scene.popups.setResolution(resolution);
    scene.popups.setSafeArea(view.safeRect);
  }

  private measure(): void {
    this.cssWidth = Math.max(1, Math.round(this.container.clientWidth));
    this.cssHeight = Math.max(1, Math.round(this.container.clientHeight));
  }

  private targetResolution(): number {
    return capResolution(
      this.cssWidth,
      this.cssHeight,
      window.devicePixelRatio,
      this.tunables.maxRenderPixels,
    );
  }

  /** Match the canvas to the container at the capped resolution; tell the owner if it moved. */
  private applySize(): void {
    const scene = this.scene;
    if (!scene) return;
    this.measure();
    const { renderer } = scene;
    const resolution = this.targetResolution();
    const sizeChanged =
      this.cssWidth !== this.appliedWidth || this.cssHeight !== this.appliedHeight;
    if (!sizeChanged && resolution === renderer.resolution) return;
    this.appliedWidth = this.cssWidth;
    this.appliedHeight = this.cssHeight;
    renderer.resize(this.cssWidth, this.cssHeight, resolution);
    this.updateBufferStats();
    if (sizeChanged) this.resized.emit([renderer.screen.width, renderer.screen.height]);
  }

  private updateBufferStats(): void {
    const renderer = this.scene?.renderer;
    if (!renderer) return;
    this.stats.bufferWidth = renderer.canvas.width;
    this.stats.bufferHeight = renderer.canvas.height;
    this.stats.resolution = renderer.resolution;
  }

  private readonly handleContextLost = (): void => {
    this.lost = true;
    this.contextLost.emit();
  };

  private readonly handleContextRestored = (): void => {
    // Pixi rebuilds its GL state; everything we draw re-uploads from what it still holds.
    this.lost = false;
    this.lastFrameMs = 0;
    this.contextRestored.emit();
  };
}

function smoothstep(edge0: number, edge1: number, x: number): number {
  const t = Math.min(1, Math.max(0, (x - edge0) / (edge1 - edge0)));
  return t * t * (3 - 2 * t);
}

function readGlRenderer(gl: WebGL2RenderingContext | WebGLRenderingContext): string | null {
  try {
    const info = gl.getExtension('WEBGL_debug_renderer_info');
    const value = gl.getParameter(info ? info.UNMASKED_RENDERER_WEBGL : gl.RENDERER);
    return typeof value === 'string' ? value : null;
  } catch {
    return null;
  }
}

export function createStage(options: StageOptions): Stage {
  return new PixiStage(options);
}
