/**
 * Body landmarks for one source frame, from MediaPipe's pose landmarker (33 points).
 *
 * - `landmarks` holds 4 numbers per point: x, y, z, visibility.
 * - x and y are normalised to the source frame (0..1, origin top-left) and in camera
 *   orientation: NOT mirrored. To compare distances, scale x by `sourceWidth` and y by
 *   `sourceHeight` first. Points can lie outside 0..1 when the model guesses them off frame.
 * - visibility is 0..1: how likely the point is in frame and not hidden.
 * - Poses are immutable once emitted; consumers may keep references across frames.
 */
export interface PoseFrame {
  /** `POSE_POINTS * 4` long. All zero when `present` is false. */
  readonly landmarks: Float32Array;
  /** False when the model found nobody in this frame. */
  readonly present: boolean;
  /** Sequence number of the source frame; equals `PersonMask.seq` for the same frame. */
  readonly seq: number;
  /** `performance.now()` on the main thread when the source frame was captured. */
  readonly captureTimeMs: number;
  readonly sourceWidth: number;
  readonly sourceHeight: number;
}

export const POSE_POINTS = 33;
export const POSE_STRIDE = 4;

/** Landmark indices. "Left" and "right" are the person's own left and right. */
export const Landmark = {
  nose: 0,
  leftShoulder: 11,
  rightShoulder: 12,
  leftElbow: 13,
  rightElbow: 14,
  leftWrist: 15,
  rightWrist: 16,
  leftHip: 23,
  rightHip: 24,
  leftKnee: 25,
  rightKnee: 26,
  leftAnkle: 27,
  rightAnkle: 28,
  leftHeel: 29,
  rightHeel: 30,
  leftFoot: 31,
  rightFoot: 32,
} as const;
