/**
 * CONTRACT for the vision module (main-thread side). The rest of the app depends only on
 * this file and on `createVision` / `listCameras` exported from `./index`.
 */
import type { Unsubscribe } from '../core/events';
import type { PersonMask } from '../core/mask';
import type { PoseFrame } from '../core/pose';
import type { Delegate, FaultSpec, RegionLayout, SegmenterEngine } from './protocol';
import type { SyntheticPose } from './syntheticFigure';

export type { Delegate, FaultSpec, RegionLayout, SegmenterEngine } from './protocol';
export type { SyntheticPose } from './syntheticFigure';

// ---------------------------------------------------------------------------
// Sources
// ---------------------------------------------------------------------------

export type SourceKind = 'camera' | 'clip' | 'synthetic';

/** Element the renderer shows: a <video> for camera/clip, a <canvas> for synthetic. */
export type DisplaySource = HTMLVideoElement | HTMLCanvasElement;

export interface SourceInfo {
  kind: SourceKind;
  /** Actual frame size in pixels. */
  width: number;
  height: number;
  /** Actual frame rate reported by the device, if known. */
  frameRate: number | null;
  label: string;
  deviceId: string | null;
}

export interface FrameTick {
  /** `performance.now()` for this frame. */
  readonly captureTimeMs: number;
  /**
   * This frame does not follow on from the previous one of the same source (a clip that
   * looped back to its start), so trackers should not carry anything over.
   */
  readonly discontinuity?: boolean;
  /** Snapshot the current frame. The caller owns the result and must `close()` it. */
  grab(): VideoFrame;
}

export interface FrameSource {
  readonly kind: SourceKind;
  /** Null until `start()` resolves. */
  readonly info: SourceInfo | null;
  readonly display: DisplaySource | null;
  /** Camera only: the live stream (used by the clip recorder). */
  readonly stream: MediaStream | null;
  /** Resolves once the first frame is available. Rejects with a `VisionError`. */
  start(): Promise<SourceInfo>;
  /** Stop delivering frames but keep the device open. */
  pause(): void;
  resume(): void;
  /** Release the device. The source cannot be restarted. */
  stop(): void;
  /** Called on the main thread once per new source frame. */
  setFrameHandler(handler: ((tick: FrameTick) => void) | null): void;
  /** Called if the source ends unexpectedly (camera unplugged, track ended, clip error). */
  setEndedHandler(handler: ((error: VisionError) => void) | null): void;
}

export interface CameraDevice {
  deviceId: string;
  /** Empty until camera permission has been granted. */
  label: string;
}

/** A magenta disc for `SyntheticControl.setBlobs`, in source pixels. */
export interface SyntheticBlob {
  x: number;
  y: number;
  r: number;
}

/**
 * Test hooks for the synthetic source. It shows either a stick figure with its arms out
 * (the default) or plain blobs. The chroma engine segments both and finds the figure's
 * pose; blobs have none.
 */
export interface SyntheticControl {
  /**
   * Show these blobs instead of the figure (no pose); null brings the figure back. Kept for
   * mask-only checks.
   */
  setBlobs(blobs: SyntheticBlob[] | null): void;
  /**
   * Pin the figure in this pose (and show it, if blobs were shown). Null restores the
   * default animation: arms out, the tilt swinging slowly between -25° and 25°, centred.
   */
  setPose(pose: SyntheticPose | null): void;
  /**
   * While on, the frame carries a mark that makes the chroma pose engine fail, as a broken
   * pose model would; segmentation is unaffected.
   */
  setPoseFault(enabled: boolean): void;
  /** The figure's pose in the newest frame drawn, or null while blobs are shown. */
  readonly currentPose: SyntheticPose | null;
}

// ---------------------------------------------------------------------------
// Segmenter
// ---------------------------------------------------------------------------

export type SegmenterBackend = 'worker' | 'main';

export interface SegmenterInfo {
  backend: SegmenterBackend;
  engine: SegmenterEngine;
  delegate: Delegate;
  /** Side of the model's square input. Mask size varies with layout and frame aspect. */
  inputSize: number;
  glRenderer: string | null;
  warmupMs: number;
}

export interface SegmentResult {
  /** P(person) as 0..255 for the whole frame, `width * height` long. Owned by the caller. */
  data: Uint8Array;
  width: number;
  height: number;
  /** Total time for this frame, all regions. */
  inferMs: number;
  /** Number of model runs this frame took. */
  regions: number;
  /** When segmentation ran, on the main thread's `performance.now()` clock (tracing). */
  startMs?: number;
  endMs?: number;
}

/** The pose found in a frame, delivered ahead of that frame's mask. */
export interface PoseResult {
  /** `POSE_POINTS * POSE_STRIDE` floats normalised to the frame; zeros when not present. Owned by the receiver. */
  landmarks: Float32Array;
  present: boolean;
  /** Time the pose model took. */
  poseMs: number;
  /**
   * On the main thread's `performance.now()` clock (tracing): when the segmenter got the
   * frame, and when the pose model started and finished on it.
   */
  receivedMs?: number;
  startMs?: number;
  endMs?: number;
}

/**
 * Where one source frame was when, on the main thread's `performance.now()` clock; NaN for
 * a step it never reached. Recorded only while tracing is on (latency checks, debug).
 */
export interface FrameTrace {
  seq: number;
  /** The source's capture time (`FrameTick.captureTimeMs`). */
  captureMs: number;
  /** The frame callback ran. */
  tickMs: number;
  /** Handed to the segmenter (it may have waited for the previous frame). */
  sentMs: number;
  /** The segmenter (worker or main thread) got it. */
  receivedMs: number;
  poseStartMs: number;
  poseEndMs: number;
  /** The pose became available to `takePose`. */
  poseArrivedMs: number;
  /** The game took the pose. */
  poseTakenMs: number;
  segStartMs: number;
  segEndMs: number;
  /** The mask became available to `takeMask`. */
  maskArrivedMs: number;
}

/** What goes with a frame into `Segmenter.segment`. */
export interface SegmentJob {
  /** The frame does not follow on from the previous one: the pose tracker starts over. */
  fresh: boolean;
  /**
   * How soon (ms from the call) the next source frame is expected. The segmenter may then
   * skip this frame's mask rather than hold the next frame's pose back (see maskPacer.ts).
   * Unknown or absent: always segment.
   */
  nextFrameInMs?: number;
  /** The source's frame interval (ms), or absent when unknown. */
  frameIntervalMs?: number;
  /** How long (frames) a mask may make the next pose wait (see maskPacer.ts); default 0.5. */
  poseWaitFrames?: number;
  /**
   * Called at most once, before the returned promise settles, with the frame's pose. A
   * frame whose pose model failed gets a not-present pose and its mask as usual.
   */
  onPose?(pose: PoseResult): void;
}

export interface Segmenter {
  readonly info: SegmenterInfo | null;
  /** Loads the models and runs a warm-up inference. Rejects with a `VisionError`. */
  init(onProgress?: (progress: StartProgress) => void): Promise<SegmenterInfo>;
  /**
   * Find the pose in one frame, then segment it. Takes ownership of `frame` and closes it
   * in every outcome. Resolves with null when the pose was delivered but the mask skipped,
   * to keep the next frame's pose on time (`SegmentJob.nextFrameInMs`). Rejects with a
   * `VisionError`; it must never stay pending forever (implementations time out).
   */
  segment(frame: VideoFrame, job?: SegmentJob): Promise<SegmentResult | null>;
  /** Change which parts of the frame are fed to the model; applies from the next frame. */
  setLayout(layout: RegionLayout): void;
  dispose(): void;
}

// ---------------------------------------------------------------------------
// Pipeline
// ---------------------------------------------------------------------------

export type StartStage = 'camera' | 'download' | 'wasm' | 'warmup';

export interface StartProgress {
  stage: StartStage;
  /** 0..1 within the stage, or null when indeterminate. */
  fraction: number | null;
}

export type VisionErrorCode =
  | 'permission-denied'
  | 'no-camera'
  | 'camera-busy'
  | 'camera-lost'
  | 'clip-failed'
  | 'model-download'
  | 'segmenter-init'
  | 'segmenter-failed'
  | 'unsupported'
  | 'unknown';

export class VisionError extends Error {
  readonly code: VisionErrorCode;

  constructor(code: VisionErrorCode, message: string, options?: { cause?: unknown }) {
    super(message, options);
    this.name = 'VisionError';
    this.code = code;
  }
}

export type VisionStatus = 'idle' | 'starting' | 'running' | 'paused' | 'error' | 'disposed';

export interface VisionStats {
  /** Source frames per second, measured. */
  cameraFps: number;
  /** Masks delivered per second, measured. */
  maskFps: number;
  inferMsP50: number;
  inferMsP95: number;
  /** Age of the newest mask when it arrived: capture → available on the main thread. */
  maskAgeMs: number;
  /** VideoFrames currently open on the main thread or in flight. Should stay ≤ 2. */
  openFrames: number;
  /** Source frames skipped because the segmenter was busy. */
  droppedFrames: number;
  /** Times the segmenter was restarted or fell back. */
  restarts: number;
  masksDelivered: number;
  /** Segmentation model runs per frame with the current layout (the newest mask's, once there is one). */
  regionsPerFrame: number;
  /** Poses delivered per second, measured. */
  poseFps: number;
  /** Pose model time per frame. */
  poseMsP50: number;
  poseMsP95: number;
  /** Age of the newest pose when it arrived: capture → available on the main thread. */
  poseAgeMs: number;
}

export interface VisionOptions {
  source: SourceKind;
  /** Preferred camera. Falls back to the default camera if it is unavailable. */
  deviceId: string | null;
  clipUrl: string | null;
  /** `auto` = worker, falling back to the main thread if the worker cannot start. */
  backend: 'auto' | SegmenterBackend;
  engine: SegmenterEngine;
  delegate: Delegate;
  fault: FaultSpec | null;
  /** `modelUrl` is the segmentation model, `poseModelUrl` the pose landmarker's `.task`. */
  assets: { wasmBaseUrl: string; modelUrl: string; poseModelUrl: string };
  /** Side of the model's square input (256 for SelfieMulticlass). */
  inputSize: number;
  layout: RegionLayout;
}

export interface FramePair {
  /** The exact frame `mask` was computed from. The taker owns it and must `close()` it. */
  image: VideoFrame;
  mask: PersonMask;
  /**
   * The pose of the same frame (`pose.seq === mask.seq`; `present` false when nobody was
   * found), or null if no pose arrived for it.
   */
  pose: PoseFrame | null;
}

export interface VisionPipeline {
  readonly status: VisionStatus;
  readonly display: DisplaySource | null;
  readonly sourceInfo: SourceInfo | null;
  readonly segmenterInfo: SegmenterInfo | null;
  readonly stream: MediaStream | null;
  /** Live object, updated in place; read it whenever. */
  readonly stats: VisionStats;
  /** Present only for the synthetic source. */
  readonly synthetic: SyntheticControl | null;

  /** Open the source, load the model, run a warm-up inference. Rejects with a `VisionError`. */
  start(onProgress?: (progress: StartProgress) => void): Promise<void>;
  /** Stop processing frames (tab hidden). Keeps the camera open. Idempotent. */
  pause(): void;
  resume(): void;
  /** Release everything. Idempotent. */
  dispose(): void;

  /**
   * The newest mask that has not been taken yet, or null. The game calls this once per
   * tick; masks are never pushed into game logic from a message handler.
   */
  takeMask(): PersonMask | null;

  /**
   * The newest pose that has not been taken yet, or null. Poses are made available as soon
   * as the tracker has them, which is before the mask of the same frame: steering must not
   * wait for segmentation. The game calls this once per tick.
   */
  takePose(): PoseFrame | null;

  /** Change which parts of the frame are fed to the model; applies from the next frame. */
  setLayout(layout: RegionLayout): void;

  /** When enabled, each mask's source frame is kept so `takePair` can return it. */
  setPairing(enabled: boolean): void;

  /**
   * Where pose and mask do not both fit in a camera frame: how long (in frames, 0..1) a
   * mask may make the next pose wait. 0 favours steering, 1 the cutout.
   */
  setMaskPoseWait(frames: number): void;
  takePair(): FramePair | null;

  /**
   * Record a `FrameTrace` for each source frame (the newest few hundred are kept). Off by
   * default: it allocates per frame.
   */
  setTracing(enabled: boolean): void;
  /** The recorded traces, oldest first. */
  readTrace(): FrameTrace[];

  /** Switch to another camera without reloading the model. */
  switchCamera(deviceId: string): Promise<SourceInfo>;
  /** Switch to a looping video clip (URL, File or Blob). */
  loadClip(src: string | Blob): Promise<SourceInfo>;

  /** Fatal runtime errors after a successful start (camera lost, segmenter dead). */
  onError(listener: (error: VisionError) => void): Unsubscribe;
  /** Fired when the source or its frame size changes after start. */
  onSourceChange(listener: (info: SourceInfo) => void): Unsubscribe;
}
