/**
 * The boot screen, the game's front door: a title over a sunny beach, three pictograms that
 * show how to play, one Start button (focused; click, Enter or Space), a camera picker when
 * there is a choice, and a status area for progress or the reason starting failed.
 *
 * The picker and status hang below the button and the status area has a fixed height, so
 * nothing moves when the state changes. The three states are one `data-state` attribute
 * that the stylesheet cross-fades.
 */
import { Emitter } from '../core/events';
import type { CameraDevice } from '../vision/types';
import { HOW_TO_STEPS, SCENE_SVG } from './scene';
import type { BootOverlay, BootProgress, BootSelection, OverlayMessage } from './types';

/** The music's attribution, which its licence requires wherever the game is shown. */
export const MUSIC_CREDIT = {
  title: 'Surf Shimmy',
  author: 'Kevin MacLeod (incompetech.com)',
  url: 'https://incompetech.com/music/royalty-free/index.html?isrc=USUAN1700018',
  licence: 'CC BY 4.0',
  licenceUrl: 'https://creativecommons.org/licenses/by/4.0/',
} as const;

const FADE_OUT_MS = 350;
const FADE_IN_MS = 250;

/**
 * Picker labels. Device labels are empty until camera permission is granted, so fall back
 * to "Camera N"; identical labels (two of the same webcam) get a number so they differ.
 */
export function cameraLabels(cameras: readonly CameraDevice[]): string[] {
  const labels = cameras.map((camera, index) => camera.label.trim() || `Camera ${index + 1}`);
  const total = new Map<string, number>();
  for (const label of labels) total.set(label, (total.get(label) ?? 0) + 1);
  const seen = new Map<string, number>();
  return labels.map((label) => {
    if ((total.get(label) ?? 0) < 2) return label;
    const nth = (seen.get(label) ?? 0) + 1;
    seen.set(label, nth);
    return `${label} (${nth})`;
  });
}

function query<T extends Element>(parent: Element, selector: string): T {
  const found = parent.querySelector<T>(selector);
  if (!found) throw new Error(`boot overlay markup is missing ${selector}`);
  return found;
}

export function createBootOverlay(root: HTMLElement): BootOverlay {
  const element = document.createElement('section');
  element.className = 'boot-overlay';
  element.setAttribute('aria-label', "Surf's Up");
  element.dataset.state = 'idle';
  const steps = HOW_TO_STEPS.map(
    (step, index) => `
      <li class="boot-step">
        <span class="boot-step-number" aria-hidden="true">${index + 1}</span>
        <span class="boot-step-icon">${step.svg}</span>
        <span class="boot-step-text">
          <strong class="boot-step-title">${step.title}</strong>
          <span class="boot-step-detail">${step.detail}</span>
        </span>
      </li>`,
  ).join('');
  element.innerHTML = `
    <div class="boot-scene" aria-hidden="true">${SCENE_SVG}</div>
    <div class="boot-content">
      <h1 class="boot-title">Surf's Up</h1>
      <p class="boot-tagline">Stand back, hold your arms out and ride the wave!</p>
      <ol class="boot-steps" aria-label="How to play">${steps}</ol>
      <div class="boot-actions">
        <button class="boot-start" type="button">Start</button>
        <div class="boot-below">
          <label class="boot-camera" hidden>
            <span>Camera</span>
            <span class="boot-select"><select class="boot-camera-select"></select></span>
          </label>
          <div class="boot-status">
            <div class="boot-progress">
              <div class="boot-progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="100">
                <div class="boot-progress-fill"></div>
              </div>
              <div class="boot-progress-text">
                <span class="boot-progress-label" role="status"></span>
                <span class="boot-progress-percent"></span>
              </div>
            </div>
            <div class="boot-error" role="alert"></div>
          </div>
        </div>
      </div>
    </div>
    <div class="boot-footer">
      <p class="boot-keys">
        <span><kbd>F</kbd> Fullscreen</span>
        <span><kbd>M</kbd> Mute</span>
        <span><kbd>C</kbd> Camera</span>
        <span><kbd>D</kbd> Debug</span>
      </p>
      <p class="boot-credits">
        Music: <a href="${MUSIC_CREDIT.url}" target="_blank" rel="noopener">“${MUSIC_CREDIT.title}”</a>
        by ${MUSIC_CREDIT.author},
        <a href="${MUSIC_CREDIT.licenceUrl}" target="_blank" rel="noopener">${MUSIC_CREDIT.licence}</a>
      </p>
    </div>
  `;
  root.appendChild(element);

  const button = query<HTMLButtonElement>(element, '.boot-start');
  const cameraRow = query<HTMLElement>(element, '.boot-camera');
  const select = query<HTMLSelectElement>(element, '.boot-camera-select');
  const progressLabel = query<HTMLElement>(element, '.boot-progress-label');
  const progressPercent = query<HTMLElement>(element, '.boot-progress-percent');
  const track = query<HTMLElement>(element, '.boot-progress-track');
  const fill = query<HTMLElement>(element, '.boot-progress-fill');
  const errorBox = query<HTMLElement>(element, '.boot-error');
  const errorTitle = document.createElement('p');
  errorTitle.className = 'boot-error-title';
  const errorDetail = document.createElement('p');
  errorDetail.className = 'boot-error-detail';
  const errorTechnical = document.createElement('p');
  errorTechnical.className = 'boot-error-technical';

  const started = new Emitter<BootSelection>();
  let visible = true;
  let progress: BootProgress | null = null;
  let error: OverlayMessage | null = null;
  /** Fraction the bar currently shows, or -1 while it is indeterminate. */
  let shownFraction = -1;
  let fade: Animation | null = null;

  const fireStart = (): void => {
    if (!visible || progress) return;
    started.emit({ deviceId: cameraRow.hidden ? null : select.value || null });
  };

  const focusStart = (): void => {
    if (!visible || button.disabled) return;
    // Do not pull focus away from somewhere else the user is typing (the debug panel).
    const active = document.activeElement;
    if (active && active !== document.body && !element.contains(active)) return;
    button.focus({ preventScroll: true });
  };

  const render = (): void => {
    const state = progress ? 'progress' : error ? 'error' : 'idle';
    element.dataset.state = state;
    button.disabled = progress !== null;
    select.disabled = progress !== null;
    button.textContent = state === 'error' ? 'Try again' : 'Start';
  };

  const showFraction = (fraction: number | null): void => {
    const determinate = fraction !== null && Number.isFinite(fraction);
    track.classList.toggle('is-indeterminate', !determinate);
    if (!determinate) {
      shownFraction = -1;
      progressPercent.textContent = '';
      track.removeAttribute('aria-valuenow');
      return;
    }
    const clamped = Math.min(1, Math.max(0, fraction));
    // Animate forward progress only: a new stage starting from zero should jump there.
    const jump = clamped < shownFraction || shownFraction < 0;
    if (jump) fill.style.transition = 'none';
    fill.style.setProperty('--fraction', String(clamped));
    if (jump) {
      void fill.offsetWidth; // commit the jump before the transition comes back
      fill.style.transition = '';
    }
    shownFraction = clamped;
    const percent = Math.round(clamped * 100);
    progressPercent.textContent = `${percent}%`;
    track.setAttribute('aria-valuenow', String(percent));
  };

  button.addEventListener('click', fireStart);

  // Clicking the background must not take focus off Start, or Enter would stop working.
  element.addEventListener('mousedown', (event) => {
    const target = event.target as Element;
    if (!target.closest('button, select, label, .boot-error')) event.preventDefault();
  });

  const onKeyDown = (event: KeyboardEvent): void => {
    if (!visible || event.repeat || event.defaultPrevented) return;
    if (event.ctrlKey || event.metaKey || event.altKey) return;
    if (event.key !== 'Enter' && event.key !== ' ') return;
    // A focused button handles its own keys. Enter on the picker means "go with this
    // camera"; Enter or Space with nothing focused (focus lost to the page) presses Start.
    const target = event.target;
    const onPicker = target === select && event.key === 'Enter';
    const unfocused = !(target instanceof Element) || target === document.body;
    if (!onPicker && !unfocused) return;
    event.preventDefault();
    fireStart();
  };
  window.addEventListener('keydown', onKeyDown);

  focusStart();

  return {
    show() {
      fade?.cancel();
      fade = null;
      if (element.hidden) {
        element.hidden = false;
        element.animate([{ opacity: 0 }, { opacity: 1 }], {
          duration: FADE_IN_MS,
          easing: 'ease-out',
        });
      }
      element.inert = false;
      visible = true;
      focusStart();
    },
    hide() {
      if (!visible) return;
      visible = false;
      // Inert at once so a second press cannot land during the fade.
      element.inert = true;
      const animation = element.animate([{ opacity: 1 }, { opacity: 0 }], {
        duration: FADE_OUT_MS,
        easing: 'ease-in',
        fill: 'forwards',
      });
      fade = animation;
      animation.finished.then(
        () => {
          element.hidden = true;
          animation.cancel();
          if (fade === animation) fade = null;
        },
        () => {}, // cancelled by show()
      );
    },
    setCameras(cameras, selectedId) {
      const labels = cameraLabels(cameras);
      select.replaceChildren(
        ...cameras.map(
          (camera, index) =>
            new Option(labels[index], camera.deviceId, false, camera.deviceId === selectedId),
        ),
      );
      cameraRow.hidden = cameras.length < 2;
    },
    onStart(listener) {
      return started.on(listener);
    },
    setProgress(next) {
      progress = next;
      if (next) {
        progressLabel.textContent = next.label;
        showFraction(next.fraction);
      }
      render();
      if (!next) focusStart();
    },
    setError(message) {
      error = message;
      if (message) {
        errorTitle.textContent = message.title;
        errorDetail.textContent = message.detail;
        errorTechnical.textContent = message.technical ?? '';
        errorTechnical.title = message.technical ?? '';
        // The spaces only matter to textContent (logs and tests read it); the grid
        // layout ignores whitespace between items.
        errorBox.replaceChildren(
          errorTitle,
          ' ',
          errorDetail,
          ...(message.technical ? [' ', errorTechnical] : []),
        );
      } else {
        errorBox.replaceChildren();
      }
      render();
      if (message) focusStart();
    },
    dispose() {
      fade?.cancel();
      fade = null;
      window.removeEventListener('keydown', onKeyDown);
      started.clear();
      element.remove();
    },
  };
}
