/**
 * The musical one-shots: the game's signals, the pickup ding, the chime of a perfect landing,
 * the wipeout's comic jingle and the new-best fanfare. They are drawn from A major
 * pentatonic (A B C# E F#), the notes the music's two candidate keys (E major, B minor)
 * share, so they sit with the track whatever it is playing at the time.
 */
import { bell, noiseBurst, type ToneSpec, tone, type VoiceBuilder } from './synth';

export type Cue =
  /** The camera sees the surf pose: a soft "got you". */
  | 'pose'
  /** The pose was held: the wave is coming. */
  | 'wave'
  /** The ride starts. */
  | 'go'
  /** Bright sparkle on a perfect landing (played with the splash). */
  | 'chime'
  /** Comic falling jingle after the wipeout crash. */
  | 'jingle'
  /** A new best score. */
  | 'fanfare';

/** Equal-tempered pitch, in semitones from A4. */
export const hz = (semitones: number): number => 440 * 2 ** (semitones / 12);

const A4 = 0;
const CS5 = 4;
const E5 = 7;
const A5 = 12;
const CS6 = 16;
const E6 = 19;
const A6 = 24;

/**
 * Pickup notes climb this scale (A major pentatonic from E5, in semitones from A4): a quick
 * run of pickups plays a rising tune, and the top note repeats once it is reached. It stops
 * at A6: a carver takes ~300 stars a ride in runs of 5–7, and the old top (C#7, with its
 * answer at F#7, near 3 kHz) turned shrill by the end of every run.
 */
export const PICKUP_SCALE = [7, 9, 12, 14, 16, 19, 21, 24] as const;

/** A soft plucked note: triangle with a little sine an octave up for shine. */
function pluck(voice: VoiceBuilder, semitones: number, at: number, level: number, decayS: number) {
  tone(voice, { type: 'triangle', hz: hz(semitones), at, level, attackS: 0.006, decayS });
  tone(voice, {
    type: 'sine',
    hz: hz(semitones + 12),
    at,
    level: level * 0.3,
    attackS: 0.004,
    decayS: decayS * 0.6,
  });
}

/**
 * A soft brass note: a sawtooth through a filter that opens or closes over the note (a gentle
 * "wah"), doubled by an unfiltered triangle for a round body.
 */
function horn(voice: VoiceBuilder, spec: Omit<ToneSpec, 'type'>) {
  tone(voice, { ...spec, type: 'sawtooth', level: spec.level * 0.55, lowpassQ: 2 });
  tone(voice, { ...spec, type: 'triangle', lowpassHz: undefined, lowpassToHz: undefined });
}

export function playCue(voice: VoiceBuilder, cue: Cue): void {
  switch (cue) {
    case 'pose':
      pluck(voice, E5, 0, 0.16, 0.25);
      pluck(voice, A5, 0.09, 0.16, 0.4);
      return;
    case 'wave':
      // A rising three-note call while the wave builds underneath.
      pluck(voice, A4, 0, 0.17, 0.35);
      pluck(voice, CS5, 0.14, 0.17, 0.35);
      pluck(voice, E5, 0.28, 0.19, 0.7);
      return;
    case 'go':
      // A bright struck chord: the ride is on.
      for (const [i, note] of [A5, CS6, E6].entries()) pluck(voice, note, i * 0.025, 0.13, 0.9);
      bell(voice, hz(A6), 0.08, 0.07, 0.8);
      return;
    case 'chime':
      for (const [i, note] of [CS6, E6, A6].entries()) bell(voice, hz(note), i * 0.07, 0.12, 1);
      return;
    case 'jingle':
      // "Wah, wah, wah, waaah": a muted horn falling a semitone at a time, the last note
      // wobbling down. Comic rather than sad, and soft.
      for (const [i, note] of [E5, E5 - 1, E5 - 2].entries()) {
        horn(voice, {
          hz: hz(note),
          at: i * 0.2,
          level: 0.12,
          attackS: 0.02,
          holdS: 0.08,
          decayS: 0.1,
          lowpassHz: 500,
          lowpassToHz: 1600,
        });
      }
      horn(voice, {
        hz: hz(E5 - 3),
        toHz: hz(E5 - 8),
        glideS: 0.9,
        at: 0.6,
        level: 0.12,
        attackS: 0.02,
        holdS: 0.45,
        decayS: 0.45,
        vibratoHz: 6,
        vibratoCents: 40,
        vibratoDelayS: 0.1,
        lowpassHz: 1400,
        lowpassToHz: 450,
      });
      return;
    case 'fanfare':
      // Ta-ta-ta-taaa on A major, then bells on top.
      for (const [i, note] of [A4, CS5, E5].entries()) {
        horn(voice, {
          hz: hz(note),
          at: i * 0.11,
          level: 0.1,
          attackS: 0.012,
          holdS: 0.05,
          decayS: 0.08,
          lowpassHz: 2200,
        });
      }
      for (const note of [E5, A5, CS6]) {
        horn(voice, {
          hz: hz(note),
          at: 0.33,
          level: 0.08,
          attackS: 0.02,
          holdS: 0.45,
          decayS: 0.5,
          vibratoHz: 5.5,
          vibratoCents: 12,
          vibratoDelayS: 0.2,
          lowpassHz: 2600,
          lowpassToHz: 1200,
        });
      }
      bell(voice, hz(A6), 0.33, 0.08, 1.2);
      bell(voice, hz(E6 + 12), 0.45, 0.04, 0.9);
      return;
  }
}

/**
 * A crab (the 100-point pickup): richer than a clam's ding. The same scale step as a bell,
 * doubled an octave down by a plucked note for body, a fifth above for shine, and two
 * little claw clicks on top.
 */
export function playCrab(voice: VoiceBuilder, step: number, level = 1): void {
  const last = PICKUP_SCALE.length - 1;
  const index = Math.min(last, Math.max(0, Math.floor(step)));
  const note = PICKUP_SCALE[index] as number;
  pluck(voice, note - 12, 0, 0.14 * level, 0.5);
  bell(voice, hz(note), 0, 0.15 * level, 0.5);
  bell(voice, hz(note + 7), 0.07, 0.1 * level, 0.6);
  for (const at of [0.0, 0.05]) {
    noiseBurst(voice, {
      at,
      level: 0.09 * level,
      attackS: 0.001,
      decayS: 0.02,
      filter: 'bandpass',
      hz: 5200,
      q: 3,
    });
  }
}

/**
 * The pickup ding: a bright bell on the scale step, and a second, quieter one two steps up a
 * moment later ("ding-ding"), like a coin. `level` (0..1) lets a long run of them recede a
 * little, so the tenth star of a line is still a reward, not a nag.
 */
export function playDing(voice: VoiceBuilder, step: number, level = 1): void {
  const last = PICKUP_SCALE.length - 1;
  const index = Math.min(last, Math.max(0, Math.floor(step)));
  const first = PICKUP_SCALE[index] as number;
  // Near the top of the scale the answer is a fourth up, so it still rises.
  const second = index + 2 <= last ? (PICKUP_SCALE[index + 2] as number) : first + 5;
  bell(voice, hz(first), 0, 0.17 * level, 0.42);
  bell(voice, hz(second), 0.06, 0.11 * level, 0.5);
}
