/**
 * The surfer: the board at the game's position and angle, the player's cutout (or a drawn
 * stand-in) standing on it, the wake it leaves on the face, its shadow, and its
 * reflection on flat water. Also the tumble when it wipes out.
 */
import { Container, Sprite } from 'pixi.js';
import type { Tunables } from '../config/tunables';
import type { Game } from '../game/types';
import type { AvatarCutout } from './avatar';
import { BOARD, DUMMY, type StageTextures } from './textures';
import { WakeTrail } from './wake';

/** The wake is laid this far behind the board's middle (share of its length): the rail. */
const WAKE_BACK = 0.18;
/** Seconds for the cutout and the stand-in to crossfade. */
const SWAP_S = 0.35;
/** Wipeout: how long the tumble lasts before the surfer is gone. */
const WIPE_S = 1.3;
/** The squash spring: frequency and damping ratio. */
const SQUASH_HZ = 2.6;
const SQUASH_DAMPING = 0.5;

export class SurferView {
  /** On the water under the surfer: wake and shadow. */
  readonly under = new Container();
  /** The mirror image in flat water. */
  readonly reflection = new Container();
  /** Board and rider. */
  readonly rig = new Container();

  private readonly tunables: Tunables;
  private readonly avatar: AvatarCutout;
  private readonly board: Sprite;
  private readonly boardFront: Sprite;
  /** A gold glow round the board while a speed boost is in effect. */
  private readonly boostGlow: Sprite;
  private readonly rider = new Container();
  private readonly dummy: Sprite;
  private readonly shadow: Sprite;
  private readonly wake: WakeTrail;

  private readonly mirrorRig = new Container();
  private readonly mirrorRider = new Container();
  private readonly mirrorDummy: Sprite;

  /** 0 = stand-in, 1 = the player's cutout. */
  private cutoutMix = 0;
  /** Seconds since the wipeout started, or -1. */
  private wipeS = -1;
  private wipeX = 0;
  private wipeY = 0;
  private appear = 1;
  private timeS = 0;
  /** Squash of the rider (positive = compressed) and its rate: a damped spring. */
  private squash = 0;
  private squashV = 0;

  /** Where the rider's head is, world units, for the camera and popups. */
  headY = 0;
  /** Board middle as drawn (after bobbing and tumbling). */
  drawnX = 0;
  drawnY = 0;
  /** Board-tail point on the water, for spray. */
  tailX = 0;
  tailY = 0;

  constructor(textures: StageTextures, avatar: AvatarCutout, tunables: Tunables) {
    this.tunables = tunables;
    this.avatar = avatar;

    this.wake = new WakeTrail(textures.wake);
    this.shadow = new Sprite(textures.shadow);
    this.shadow.anchor.set(0.5);
    this.under.addChild(this.wake.view, this.shadow);

    this.board = boardSprite(textures);
    this.boardFront = new Sprite(textures.boardFront);
    this.boardFront.anchor.set(BOARD.originX / BOARD.width, BOARD.originY / BOARD.height);
    this.dummy = new Sprite(textures.dummy);
    this.dummy.anchor.set(DUMMY.originX / DUMMY.width, DUMMY.originY / DUMMY.height);
    this.rider.position.set(0, BOARD.standY);
    this.rider.addChild(this.dummy, avatar.view);
    this.boostGlow = new Sprite(textures.glow);
    this.boostGlow.anchor.set(0.62, 0.5);
    this.boostGlow.blendMode = 'add';
    this.boostGlow.tint = 0xffd23f;
    this.boostGlow.position.set(0, -8);
    this.boostGlow.visible = false;
    this.rig.addChild(this.boostGlow, this.board, this.rider, this.boardFront);

    // The reflection: the same pieces under a vertical flip at the waterline.
    this.mirrorDummy = new Sprite(textures.dummy);
    this.mirrorDummy.anchor.copyFrom(this.dummy.anchor);
    this.mirrorRider.position.set(0, BOARD.standY);
    this.mirrorRider.addChild(this.mirrorDummy, avatar.reflection);
    this.mirrorRig.addChild(boardSprite(textures), this.mirrorRider);
    this.reflection.addChild(this.mirrorRig);
    this.reflection.scale.set(1, -0.8);
    this.reflection.alpha = 0;
  }

  /**
   * Knees taking a landing (positive) or springing off the lip (negative): the rider
   * squashes and stretches about the feet, once, and settles.
   */
  impact(amount: number): void {
    this.squashV += amount * 2 * Math.PI * SQUASH_HZ;
  }

  /** Start the tumble; the surfer is gone until the next `waiting`. */
  wipeout(): void {
    if (this.wipeS >= 0) return;
    this.wipeS = 0;
    this.wipeX = 0;
    this.wipeY = 0;
  }

  /** `grip`: how hard a whirlpool has hold of the board (0..1), for the wobble. */
  update(game: Game, dtS: number, mirrored: boolean, grip = 0): void {
    this.timeS += dtS;
    const { surfer, wave, phase } = game;
    const t = this.tunables;

    if (phase !== 'wipeout' && this.wipeS >= 0) {
      // Back on a new board: fade in rather than pop.
      this.wipeS = -1;
      this.appear = 0;
      this.wake.cut();
    }
    this.appear = Math.min(1, this.appear + dtS / 0.5);

    // Calm water rocks the board gently.
    const calm = 1 - wave.rise;
    const bob = surfer.airborne ? 0 : calm * 3 * Math.sin(this.timeS * 2.1);
    const rock = surfer.airborne ? 0 : calm * 0.03 * Math.sin(this.timeS * 1.6 + 0.7);
    let x = surfer.x;
    let y = surfer.y + bob;
    // A whirlpool's grip shakes the board and the rider.
    const wobble = grip > 0 ? grip * Math.sin(this.timeS * 19) : 0;
    let rotation = -surfer.angle + rock + 0.08 * wobble;
    let riderSpin = 0;
    let riderX = 0;
    let riderY = BOARD.standY;
    let alpha = this.appear;
    let riderAlpha = 1;

    if (this.wipeS >= 0) {
      this.wipeS += dtS;
      const w = this.wipeS;
      // Dragged back towards the curl and under; the rider is flung off the board.
      this.wipeX -= (180 + wave.speed * 0.35) * dtS;
      this.wipeY += 70 * dtS;
      x += this.wipeX;
      y += this.wipeY;
      // The board flips up and away; the rider is thrown off and swallowed by the foam.
      rotation += -7 * w * Math.exp(-w * 0.9);
      riderSpin = -6 * w;
      riderX = -200 * w;
      riderY = BOARD.standY - 240 * w + 600 * w * w;
      riderAlpha = 1 - smoothstep(0.15, 0.5, w);
      alpha *= 1 - smoothstep(0.5, WIPE_S, w);
    }

    this.rig.position.set(x, y);
    this.rig.rotation = rotation;
    // Boost: a gold glow streaming back from the board, as long as the boost lasts.
    const boost = Math.max(0, Math.min(1, surfer.boost || 0)) * (this.wipeS < 0 ? 1 : 0);
    this.boostGlow.visible = boost > 0.02;
    if (this.boostGlow.visible) {
      const flicker = 0.9 + 0.1 * Math.sin(this.timeS * 31);
      this.boostGlow.width = BOARD.length * (1.5 + 1.2 * boost);
      this.boostGlow.height = 90 + 60 * boost;
      this.boostGlow.alpha = Math.min(1, 1.3 * boost) * flicker;
    }
    this.rig.alpha = alpha;
    this.rig.visible = alpha > 0.003;
    this.drawnX = x;
    this.drawnY = y;
    // The rider leans with the board by only part of its angle (see `avatarLean`).
    this.rider.rotation = surfer.angle * (1 - t.avatarLean) + riderSpin + 0.06 * wobble;
    const w = 2 * Math.PI * SQUASH_HZ;
    this.squashV += (-w * w * this.squash - 2 * SQUASH_DAMPING * w * this.squashV) * dtS;
    this.squash += this.squashV * dtS;
    const q = Math.max(-0.12, Math.min(0.2, this.squash));
    this.rider.position.set(riderX, riderY);
    this.rider.scale.set(1 + 0.45 * q, 1 - q);
    this.rider.alpha = riderAlpha;
    this.headY = y + BOARD.standY - t.avatarHeight * (1 - q);

    // Cutout when someone is tracked and the mask has them, stand-in otherwise.
    const wantCutout = game.control.tracked && this.avatar.present;
    this.cutoutMix += ((wantCutout ? 1 : 0) - this.cutoutMix) * Math.min(1, dtS / SWAP_S);
    if (Math.abs(this.cutoutMix - (wantCutout ? 1 : 0)) < 0.01) this.cutoutMix = wantCutout ? 1 : 0;
    const dummyScale = t.avatarHeight / DUMMY.height0;
    this.dummy.scale.set(mirrored ? -dummyScale : dummyScale, dummyScale);
    this.dummy.alpha = 1 - this.cutoutMix;
    this.dummy.visible = this.cutoutMix < 0.999;
    this.avatar.update(dtS, mirrored, this.cutoutMix);

    // Tail of the board on the water, where the wake and spray start.
    const cos = Math.cos(rotation);
    const sin = Math.sin(rotation);
    this.tailX = x - 0.28 * BOARD.length * cos;
    this.tailY = y - 0.28 * BOARD.length * sin;

    this.updateWake(game, dtS, x, y, cos, sin);
    this.updateShadow(game, x, y, alpha);
    this.updateReflection(game, x, y, rotation, alpha, mirrored, dummyScale);
  }

  clear(): void {
    this.wake.clear();
    this.wipeS = -1;
    this.appear = 1;
    this.cutoutMix = 0;
  }

  dispose(): void {
    this.wake.dispose();
    this.under.destroy({ children: true });
    this.reflection.destroy({ children: true });
    this.rig.destroy({ children: true });
  }

  private updateWake(game: Game, dtS: number, x: number, y: number, cos: number, sin: number) {
    const { surfer, wave } = game;
    const onWater = !surfer.airborne && this.wipeS < 0;
    // Wider where the board works: speed, and above all a hard turn.
    const speed = Math.min(1.3, surfer.speed / 900);
    const boost = Math.max(0, Math.min(1, surfer.boost || 0));
    const width = 26 + 24 * speed + 44 * Math.abs(surfer.turn) + 30 * boost;
    const back = WAKE_BACK * BOARD.length;
    this.wake.update(dtS, wave.speed * dtS, onWater, x - back * cos, y - back * sin, width);
    // Fainter on calm water.
    this.wake.view.alpha = 0.4 + 0.6 * Math.min(1, wave.rise * 1.5);
  }

  private updateShadow(game: Game, x: number, y: number, alpha: number): void {
    const { surfer, wave } = game;
    const shadow = this.shadow;
    const length = (BOARD.length * 1.15) / 256;
    if (!surfer.airborne) {
      shadow.position.set(x, y + 3);
      shadow.scale.set(length, 1);
      shadow.alpha = 0.5 * alpha;
      return;
    }
    // In the air: a shadow on the wave below, smaller and fainter the higher it goes, and
    // offset away from the sun.
    const h = Math.max(0, surfer.height, wave.lipY - y);
    const k = 1 / (1 + h / 300);
    // Down on the face, where it reads against the turquoise, not lost at the bright lip.
    const face = Math.max(0, wave.bottomY - wave.lipY);
    shadow.position.set(
      x - 0.2 * h,
      Math.min(wave.bottomY, Math.max(y + 40, wave.lipY + 0.22 * face + 0.12 * h)),
    );
    shadow.scale.set(length * (0.55 + 0.45 * k), 0.8 + 0.5 * k);
    shadow.alpha = 0.6 * Math.sqrt(k) * alpha;
  }

  private updateReflection(
    game: Game,
    x: number,
    y: number,
    rotation: number,
    alpha: number,
    mirrored: boolean,
    dummyScale: number,
  ): void {
    const { surfer, wave } = game;
    // Only flat water reflects: on the face the slope hides it.
    const flat = surfer.airborne ? 0 : smoothstep(wave.bottomY - 40, wave.bottomY + 5, y);
    const a = 0.32 * flat * alpha;
    this.reflection.alpha = a;
    this.reflection.visible = a > 0.01;
    const mirror = this.avatar.reflection;
    if (!this.reflection.visible) {
      mirror.visible = false;
      return;
    }
    this.reflection.position.set(x, y + 2);
    this.mirrorRig.rotation = rotation;
    this.mirrorRider.rotation = this.rider.rotation;
    this.mirrorRider.position.copyFrom(this.rider.position);
    this.mirrorRider.alpha = this.rider.alpha;
    this.mirrorDummy.scale.set(mirrored ? -dummyScale : dummyScale, dummyScale);
    this.mirrorDummy.alpha = 1 - this.cutoutMix;
    this.mirrorDummy.visible = this.cutoutMix < 0.999;
    mirror.visible = this.cutoutMix > 0.001;
    mirror.alpha = this.cutoutMix;
    mirror.tint = 0x9fd6e6;
  }
}

function boardSprite(textures: StageTextures): Sprite {
  const sprite = new Sprite(textures.board);
  sprite.anchor.set(BOARD.originX / BOARD.width, BOARD.originY / BOARD.height);
  return sprite;
}

function smoothstep(edge0: number, edge1: number, x: number): number {
  const t = Math.min(1, Math.max(0, (x - edge0) / (edge1 - edge0)));
  return t * t * (3 - 2 * t);
}
