/**
 * Procedural particle artwork, computed into one premultiplied RGBA buffer at init. Pure
 * functions (no Pixi, no DOM) so they can be unit-tested. Every particle shares this one
 * atlas because a ParticleContainer draws from a single texture source.
 *
 * Shapes are white or grey and get their colour from the particle tint. Premultiplied
 * alpha lets one texture both glow and occlude: RGB is light added on top and A is how
 * much of what is behind it hides, so spray reads as bright mist over the dark trough and
 * still as white water over the pale sky.
 */

export interface Image {
  readonly width: number;
  readonly height: number;
  /** Premultiplied RGBA, row-major. */
  readonly data: Uint8Array;
}

export interface Frame {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

const clamp01 = (x: number): number => (x < 0 ? 0 : x > 1 ? 1 : x);

export const smoothstep = (edge0: number, edge1: number, x: number): number => {
  const t = clamp01((x - edge0) / (edge1 - edge0));
  return t * t * (3 - 2 * t);
};

const gauss = (x: number, mu: number, sigma: number): number => {
  const t = (x - mu) / sigma;
  return Math.exp(-0.5 * t * t);
};

/** Deterministic hash in 0..1 for lattice point (i, j) and a seed. */
function hash(i: number, j: number, seed: number): number {
  let h = (i * 374761393 + j * 668265263 + seed * 1442695041) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

/** Smooth value noise, for lumpy outlines. */
export function valueNoise(x: number, y: number, seed: number): number {
  const i = Math.floor(x);
  const j = Math.floor(y);
  const fx = x - i;
  const fy = y - j;
  const u = fx * fx * (3 - 2 * fx);
  const v = fy * fy * (3 - 2 * fy);
  const a = hash(i, j, seed);
  const b = hash(i + 1, j, seed);
  const c = hash(i, j + 1, seed);
  const d = hash(i + 1, j + 1, seed);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}

function writePixel(
  data: Uint8Array,
  index: number,
  r: number,
  g: number,
  b: number,
  a: number,
): void {
  const offset = index * 4;
  data[offset] = Math.round(clamp01(r) * 255);
  data[offset + 1] = Math.round(clamp01(g) * 255);
  data[offset + 2] = Math.round(clamp01(b) * 255);
  data[offset + 3] = Math.round(clamp01(a) * 255);
}

export type EffectFrameName =
  | 'ring'
  | 'mist'
  | 'foam'
  | 'flash'
  | 'droplet'
  | 'spark'
  | 'star'
  | 'streak';

export interface EffectAtlas {
  image: Image;
  frames: Record<EffectFrameName, Frame>;
}

/** Radius of each shape inside its cell, as a fraction of half the cell size. */
export const EFFECT_RADIUS: Record<EffectFrameName, number> = {
  ring: 0.78,
  mist: 0.7,
  foam: 0.72,
  flash: 0.6,
  droplet: 0.76,
  spark: 0.6,
  star: 0.86,
  streak: 0.9,
};

export function effectAtlas(): EffectAtlas {
  const width = 512;
  const height = 256;
  const data = new Uint8Array(width * height * 4);
  const frames: Record<EffectFrameName, Frame> = {
    ring: { x: 0, y: 0, width: 128, height: 128 },
    mist: { x: 128, y: 0, width: 128, height: 128 },
    foam: { x: 256, y: 0, width: 128, height: 128 },
    flash: { x: 384, y: 0, width: 128, height: 128 },
    droplet: { x: 0, y: 128, width: 64, height: 64 },
    spark: { x: 64, y: 128, width: 64, height: 64 },
    star: { x: 128, y: 128, width: 64, height: 64 },
    streak: { x: 192, y: 128, width: 64, height: 64 },
  };

  /** `shade` returns [light, coverage] for a point in -1..1 cell coordinates. */
  const paint = (
    frame: Frame,
    shade: (u: number, v: number, rho: number) => [number, number],
  ): void => {
    const half = frame.width / 2;
    for (let y = 0; y < frame.height; y++) {
      for (let x = 0; x < frame.width; x++) {
        const u = (x + 0.5 - half) / half;
        const v = (y + 0.5 - half) / half;
        const rho = Math.sqrt(u * u + v * v);
        // Keep a transparent margin so neighbouring cells never bleed in under filtering.
        const fade = smoothstep(0.98, 0.9, Math.max(Math.abs(u), Math.abs(v)));
        const [light, coverage] = shade(u, v, rho);
        const a = coverage * fade;
        const l = clamp01(light) * a;
        writePixel(data, (frame.y + y) * width + frame.x + x, l, l, l, a);
      }
    }
  };

  // A splash ring: a bright band with a soft inner halo. Squashed at draw time it lies flat
  // on the water.
  paint(frames.ring, (_u, _v, rho) => {
    const band = gauss(rho, 0.74, 0.06) + 0.35 * gauss(rho, 0.6, 0.1);
    return [1, Math.min(1, band)];
  });

  // Mist: a soft, slightly lumpy puff.
  paint(frames.mist, (u, v, rho) => {
    const angle = Math.atan2(v, u);
    const lump = 0.85 + 0.15 * valueNoise(Math.cos(angle) * 2 + 3, Math.sin(angle) * 2 + 3, 7);
    return [1, 0.8 * Math.exp(-((rho / (0.5 * lump)) ** 2) * 1.4)];
  });

  // Foam: a cauliflower clump of white water, lit from above and shaded underneath.
  paint(frames.foam, (u, v, rho) => {
    const angle = Math.atan2(v, u);
    const lump = 0.7 + 0.3 * valueNoise(Math.cos(angle) * 2.5 + 5, Math.sin(angle) * 2.5 + 5, 11);
    const edge = smoothstep(0.78 * lump, 0.62 * lump, rho);
    const billow = valueNoise(u * 4 + 9, v * 4 + 9, 3);
    const light = 0.88 + 0.12 * smoothstep(0.5, -0.6, v) + 0.1 * (billow - 0.5);
    return [light, edge];
  });

  // A soft glow that flashes for a frame or two.
  paint(frames.flash, (_u, _v, rho) => [1, 0.5 * Math.exp(-rho * rho * 3.2)]);

  // A droplet: a solid bead with an offset highlight.
  paint(frames.droplet, (u, v, rho) => {
    const body = smoothstep(0.84, 0.64, rho);
    const core = gauss(Math.hypot(u + 0.25, v + 0.25), 0, 0.22);
    return [0.95 + 0.3 * core, 0.95 * body];
  });

  // A four-point glint.
  paint(frames.spark, (u, v, rho) => {
    const ax = Math.abs(u);
    const ay = Math.abs(v);
    const star =
      Math.exp(-ax * 9) * Math.exp(-ay * ay * 90) + Math.exp(-ay * 9) * Math.exp(-ax * ax * 90);
    return [1, 0.85 * Math.min(1, star + 0.8 * Math.exp(-rho * rho * 30))];
  });

  // A small five-point star for pickup bursts.
  paint(frames.star, (u, v, rho) => {
    const sector = (2 * Math.PI) / 5;
    const angle = Math.atan2(u, -v);
    const a = Math.abs((((angle % sector) + sector) % sector) - sector / 2) / (sector / 2);
    // 0 at a point, 1 half-way between two points.
    const radius = 0.86 * (1 - 0.55 * a ** 0.9);
    return [1, smoothstep(radius + 0.05, radius - 0.04, rho)];
  });

  // A thin horizontal streak, for speed lines.
  paint(frames.streak, (u, v) => {
    const along = smoothstep(1, 0.2, Math.abs(u));
    return [1, along * Math.exp(-((v / 0.12) ** 2))];
  });

  return { image: { width, height, data }, frames };
}
