/**
 * Building blocks shared by every sound: the master bus, a noise buffer, and voices (one gain
 * node per one-shot, which the pool can cut short). Everything works on any BaseAudioContext
 * so the sounds can also be rendered offline and measured.
 */

/** Seconds of noise. Long enough that a looped layer does not sound like it repeats. */
const NOISE_S = 4;

/** White noise; looping layers and one-shots read it from different offsets. */
export function createNoiseBuffer(context: BaseAudioContext, random: () => number): AudioBuffer {
  const length = Math.round(context.sampleRate * NOISE_S);
  const buffer = context.createBuffer(1, length, context.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < length; i++) data[i] = random() * 2 - 1;
  return buffer;
}

/** Volume slider to gain: squared, so the slider feels even across its travel. */
export function volumeToGain(volume: number): number {
  const v = Math.min(1, Math.max(0, volume));
  return v * v;
}

export const clamp = (value: number, lo: number, hi: number): number =>
  Math.min(hi, Math.max(lo, value));

export interface MasterBus {
  /** One-shots connect here. Its gain is the effects volume. */
  readonly effects: GainNode;
  /** The continuous layers connect here. Its gain is the ambience volume. */
  readonly ambience: GainNode;
  /** The music connects here, past the compressor so the effects never make it pump. */
  readonly music: GainNode;
  /** Everything passes through it; its gain is the master volume (and mute). */
  readonly master: GainNode;
  readonly compressor: DynamicsCompressorNode;
  readonly limiter: WaveShaperNode;
}

/**
 * effects + ambience → compressor ┐
 *                          music ─┴→ master → soft limiter → destination
 *
 * The compressor tames bursts of one-shots and ducks the water under them a little. The
 * limiter sits last, after the music joins, so the sum can never clip: its curve is linear up
 * to 0.7 and bends smoothly to never exceed 1.
 */
export function createMasterBus(context: BaseAudioContext): MasterBus {
  const effects = context.createGain();
  const ambience = context.createGain();
  const music = context.createGain();
  const master = context.createGain();
  const compressor = context.createDynamicsCompressor();
  compressor.threshold.value = -16;
  compressor.knee.value = 10;
  compressor.ratio.value = 6;
  compressor.attack.value = 0.003;
  compressor.release.value = 0.15;
  const limiter = context.createWaveShaper();
  const curve = new Float32Array(2049);
  for (let i = 0; i < curve.length; i++) {
    const x = (i / (curve.length - 1)) * 2 - 1;
    const magnitude = Math.abs(x);
    const shaped = magnitude < 0.7 ? magnitude : 0.7 + 0.3 * Math.tanh((magnitude - 0.7) / 0.3);
    curve[i] = Math.sign(x) * shaped;
  }
  limiter.curve = curve;
  effects.connect(compressor);
  ambience.connect(compressor);
  compressor.connect(master);
  music.connect(master);
  master.connect(limiter).connect(context.destination);
  return { effects, ambience, music, master, compressor, limiter };
}

/** How important a one-shot is when the pool has to cut one to make room. */
export type Priority = 0 | 1 | 2;

export interface Voice {
  readonly name: string;
  readonly priority: Priority;
  readonly startTime: number;
  readonly endTime: number;
  /** Fade out quickly and stop, for voice stealing. */
  cut(at: number): void;
}

/** Fade used when a voice is cut: short, but long enough not to click. */
const CUT_FADE_S = 0.012;
/** Envelopes decay to this fraction of their peak, which is inaudible, before stopping. */
const SILENT = 0.0005;

/**
 * Collects the parts of one one-shot: every oscillator and noise burst goes through
 * `output`, a single gain node (and panner) that `cut` can fade.
 */
export class VoiceBuilder {
  readonly output: GainNode;
  private readonly panner: StereoPannerNode;
  private readonly sources: AudioScheduledSourceNode[] = [];
  private end: number;

  constructor(
    readonly context: BaseAudioContext,
    destination: AudioNode,
    readonly when: number,
    pan: number,
    readonly noise: AudioBuffer,
    readonly random: () => number,
  ) {
    this.end = when;
    this.output = context.createGain();
    this.panner = context.createStereoPanner();
    this.panner.pan.value = clamp(pan, -1, 1);
    this.output.connect(this.panner).connect(destination);
  }

  /** Schedule `source` for [start, stop]; the voice lasts until its last source stops. */
  add(source: AudioScheduledSourceNode, start: number, stop: number, offset?: number): void {
    if (offset !== undefined) {
      (source as AudioBufferSourceNode).start(start, offset);
    } else {
      source.start(start);
    }
    source.stop(stop);
    this.sources.push(source);
    if (stop > this.end) this.end = stop;
  }

  finish(name: string, priority: Priority): Voice {
    const { output, panner, sources } = this;
    const endTime = this.end;
    let remaining = sources.length;
    const release = (): void => {
      remaining--;
      // Release the chain once everything has finished so nothing stays on the bus.
      if (remaining > 0) return;
      output.disconnect();
      panner.disconnect();
    };
    for (const source of sources) source.onended = release;
    return {
      name,
      priority,
      startTime: this.when,
      endTime,
      cut(at) {
        if (at >= endTime) return;
        output.gain.cancelScheduledValues(at);
        output.gain.setValueAtTime(output.gain.value, at);
        output.gain.linearRampToValueAtTime(0, at + CUT_FADE_S);
        for (const source of sources) source.stop(at + CUT_FADE_S + 0.005);
      },
    };
  }
}

export interface ToneSpec {
  type: OscillatorType;
  hz: number;
  /** Seconds after the voice starts. */
  at: number;
  level: number;
  attackS: number;
  /** Held at full level for this long before the decay. */
  holdS?: number;
  /** From the end of the hold to silence. */
  decayS: number;
  /** Glide to this pitch over `glideS` (from the start of the note). */
  toHz?: number;
  glideS?: number;
  /** Vibrato rate and depth in cents, starting `vibratoDelayS` after the note. */
  vibratoHz?: number;
  vibratoCents?: number;
  vibratoDelayS?: number;
  /** Optional lowpass for a darker timbre (sawtooth horns). */
  lowpassHz?: number;
  /** Lowpass resonance, and a cutoff to sweep to over the note: a "wah". */
  lowpassQ?: number;
  lowpassToHz?: number;
}

/** One enveloped oscillator. Returns when it falls silent. */
export function tone(voice: VoiceBuilder, spec: ToneSpec): number {
  const { context } = voice;
  const start = voice.when + spec.at;
  const peak = start + spec.attackS;
  const hold = peak + (spec.holdS ?? 0);
  const stop = hold + spec.decayS;
  const oscillator = context.createOscillator();
  oscillator.type = spec.type;
  oscillator.frequency.setValueAtTime(spec.hz, start);
  if (spec.toHz !== undefined) {
    oscillator.frequency.exponentialRampToValueAtTime(spec.toHz, start + (spec.glideS ?? 0.1));
  }
  const gain = context.createGain();
  gain.gain.setValueAtTime(0, start);
  gain.gain.linearRampToValueAtTime(spec.level, peak);
  gain.gain.setValueAtTime(spec.level, hold);
  gain.gain.exponentialRampToValueAtTime(spec.level * SILENT, stop);
  let last: AudioNode = oscillator;
  if (spec.lowpassHz !== undefined) {
    const filter = context.createBiquadFilter();
    filter.type = 'lowpass';
    filter.Q.value = spec.lowpassQ ?? 0.7;
    filter.frequency.setValueAtTime(spec.lowpassHz, start);
    if (spec.lowpassToHz !== undefined) {
      filter.frequency.exponentialRampToValueAtTime(spec.lowpassToHz, stop);
    }
    last = last.connect(filter);
  }
  last.connect(gain).connect(voice.output);
  if (spec.vibratoHz !== undefined && spec.vibratoCents !== undefined) {
    const lfo = context.createOscillator();
    lfo.frequency.value = spec.vibratoHz;
    const depth = context.createGain();
    // `detune` is in cents, so the depth is the same whatever the pitch.
    const vibratoStart = start + (spec.vibratoDelayS ?? 0);
    depth.gain.setValueAtTime(0, start);
    depth.gain.setValueAtTime(0, vibratoStart);
    depth.gain.linearRampToValueAtTime(spec.vibratoCents, vibratoStart + 0.08);
    lfo.connect(depth).connect(oscillator.detune);
    voice.add(lfo, start, stop + 0.02);
  }
  voice.add(oscillator, start, stop + 0.02);
  return stop;
}

/**
 * A struck bell or glockenspiel note: a sine plus a few quieter partials that die away
 * faster, so it starts bright and rings out pure.
 */
export function bell(voice: VoiceBuilder, hz: number, at: number, level: number, decayS: number) {
  tone(voice, { type: 'sine', hz, at, level, attackS: 0.002, decayS });
  tone(voice, {
    type: 'sine',
    hz: hz * 2,
    at,
    level: level * 0.35,
    attackS: 0.002,
    decayS: decayS * 0.45,
  });
  tone(voice, {
    type: 'sine',
    hz: hz * 3.01,
    at,
    level: level * 0.12,
    attackS: 0.001,
    decayS: decayS * 0.25,
  });
}

export interface NoiseSpec {
  /** Seconds after the voice starts. */
  at: number;
  level: number;
  attackS: number;
  holdS?: number;
  decayS: number;
  filter: BiquadFilterType;
  hz: number;
  /** Sweep the filter to this frequency over `sweepS` from the start. */
  toHz?: number;
  sweepS?: number;
  q?: number;
  /** Extra highpass, to keep rumble out of hisses. */
  highpassHz?: number;
}

/** One enveloped, filtered noise burst. Returns when it falls silent. */
export function noiseBurst(voice: VoiceBuilder, spec: NoiseSpec): number {
  const { context, noise, random } = voice;
  const start = voice.when + spec.at;
  const peak = start + spec.attackS;
  const hold = peak + (spec.holdS ?? 0);
  const stop = hold + spec.decayS;
  const source = context.createBufferSource();
  source.buffer = noise;
  source.loop = true;
  const filter = context.createBiquadFilter();
  filter.type = spec.filter;
  filter.Q.value = spec.q ?? 0.8;
  filter.frequency.setValueAtTime(spec.hz, start);
  if (spec.toHz !== undefined) {
    filter.frequency.exponentialRampToValueAtTime(spec.toHz, start + (spec.sweepS ?? stop - start));
  }
  const gain = context.createGain();
  gain.gain.setValueAtTime(0, start);
  gain.gain.linearRampToValueAtTime(spec.level, peak);
  gain.gain.setValueAtTime(spec.level, hold);
  gain.gain.exponentialRampToValueAtTime(spec.level * SILENT, stop);
  let last: AudioNode = source.connect(filter);
  if (spec.highpassHz !== undefined) {
    const highpass = context.createBiquadFilter();
    highpass.type = 'highpass';
    highpass.frequency.value = spec.highpassHz;
    highpass.Q.value = 0.7;
    last = last.connect(highpass);
  }
  last.connect(gain).connect(voice.output);
  // A random offset so repeated bursts do not sound identical.
  voice.add(source, start, stop + 0.02, random() * noise.duration);
  return stop;
}
