/**
 * The backdrop: a shader-drawn sky with the sun, stylised clouds, and distant land sitting
 * on the horizon. The land scrolls with the ride (slow parallax) and the clouds drift.
 */
import { Container, Sprite } from 'pixi.js';
import { NOISE_GLSL, type ShadedQuad, setQuad, shadedQuad } from './gl';
import { glsl, PALETTE as P } from './palette';
import type { StageTextures } from './textures';

const SKY_FRAGMENT = `#version 300 es
precision highp float;
in vec2 vPos;
out vec4 finalColor;
uniform float uHorizon;
uniform vec2 uSun;
uniform float uTime;
${NOISE_GLSL}
void main() {
  vec2 p = vPos;
  // Height above the horizon, in roughly "sky heights".
  float h = (uHorizon - p.y) / 620.0;
  vec3 c = mix(${glsl(P.skyHaze)}, ${glsl(P.skyHorizon)}, smoothstep(0.0, 0.06, h));
  c = mix(c, ${glsl(P.skyLow)}, smoothstep(0.04, 0.32, h));
  c = mix(c, ${glsl(P.skyHigh)}, smoothstep(0.28, 0.75, h));
  c = mix(c, ${glsl(P.skyZenith)}, smoothstep(0.7, 1.5, h));

  // The sun: a crisp disc in a warm glow, with very faint slow rays.
  vec2 d = p - uSun;
  float r = length(d);
  float glow = 0.42 * exp(-r / 300.0) + 0.5 * exp(-r / 80.0);
  c = mix(c, ${glsl(P.sunGlow)}, clamp(glow * 0.75, 0.0, 1.0));
  float a = atan(d.y, d.x);
  float rays = pow(0.5 + 0.5 * sin(a * 11.0 + uTime * 0.03), 8.0)
             * pow(0.5 + 0.5 * sin(a * 7.0 - uTime * 0.02 + 1.3), 4.0);
  c += vec3(1.0, 0.96, 0.82) * rays * 0.07 * exp(-r / 520.0) * step(46.0, r);
  float disc = smoothstep(47.0, 44.5, r);
  c = mix(c, ${glsl(P.sun)}, disc);

  c += dither(gl_FragCoord.xy);
  finalColor = vec4(c, 1.0);
}
`;

interface Drifter {
  sprite: Sprite;
  /** Position along a loop wider than the screen, world units. */
  x: number;
  /** Height above the horizon. */
  lift: number;
  /** Fraction of the ride's distance it moves by (parallax) and its own drift speed. */
  parallax: number;
  wind: number;
}

/** World width of the loop the clouds and land wrap around. */
const LOOP_MARGIN = 900;

export class SkyLayer {
  /** Sky and clouds: drawn in screen space, under the camera. */
  readonly back = new Container();
  /** Land on the horizon: inside the camera so it sits on the water. */
  readonly land = new Container();

  private readonly sky: ShadedQuad<{
    uHorizon: { value: number; type: 'f32' };
    uSun: { value: Float32Array; type: 'vec2<f32>' };
    uTime: { value: number; type: 'f32' };
  }>;
  private readonly clouds: Drifter[] = [];
  private readonly lands: Drifter[] = [];
  private width = 1920;

  constructor(textures: StageTextures) {
    this.sky = shadedQuad('sky', SKY_FRAGMENT, 'skyUniforms', {
      uHorizon: { value: 300, type: 'f32' },
      uSun: { value: new Float32Array([1400, 150]), type: 'vec2<f32>' },
      uTime: { value: 0, type: 'f32' },
    });
    this.back.addChild(this.sky.mesh);

    const cloudSpec: [number, number, number, number][] = [
      // texture, x, lift, scale
      [0, 120, 180, 0.9],
      [1, 760, 245, 0.65],
      [2, 1180, 150, 1.05],
      [1, 1900, 210, 0.75],
      [0, 2500, 160, 0.8],
    ];
    for (const [index, x, lift, scale] of cloudSpec) {
      const sprite = new Sprite(textures.clouds[index]);
      sprite.anchor.set(0.5, 1);
      sprite.scale.set(scale);
      sprite.alpha = 0.95;
      this.back.addChild(sprite);
      this.clouds.push({ sprite, x, lift, parallax: 0.012 * scale, wind: 5 * scale });
    }

    const headland = new Sprite(textures.headland);
    headland.anchor.set(0.5, 1);
    headland.scale.set(1.1, 0.9);
    this.land.addChild(headland);
    this.lands.push({ sprite: headland, x: 300, lift: 0, parallax: 0.01, wind: 0 });
    const island = new Sprite(textures.island);
    island.anchor.set(0.5, 1);
    island.scale.set(0.62);
    this.land.addChild(island);
    this.lands.push({ sprite: island, x: 1500, lift: 0, parallax: 0.025, wind: 0 });
  }

  setWidth(worldWidth: number): void {
    this.width = worldWidth;
  }

  /**
   * `horizonScreen` is where the horizon sits on screen after the camera; `horizon` the same
   * in world (camera) space; `panY` how far the camera has moved down to follow a jump.
   */
  update(
    timeS: number,
    distance: number,
    horizon: number,
    horizonScreen: number,
    panY: number,
    sunX: number,
    sunY: number,
  ): void {
    const width = this.width;
    const sky = this.sky;
    sky.uniforms.uHorizon = horizonScreen;
    sky.uniforms.uTime = timeS % 600;
    sky.uniforms.uSun[0] = sunX;
    sky.uniforms.uSun[1] = sunY;
    // Only the part above the horizon: the water covers the rest.
    setQuad(sky.geometry, 0, 0, width, Math.max(1, horizonScreen + 4));

    const loop = width + 2 * LOOP_MARGIN;
    for (const cloud of this.clouds) {
      const x = wrap(cloud.x - distance * cloud.parallax - timeS * cloud.wind, loop) - LOOP_MARGIN;
      cloud.sprite.position.set(x, horizonScreen - cloud.lift - panY * 0.25);
    }
    for (const land of this.lands) {
      const x = wrap(land.x - distance * land.parallax, loop) - LOOP_MARGIN;
      land.sprite.position.set(x, horizon + 1);
    }
  }

  dispose(): void {
    this.sky.destroy();
    this.back.destroy({ children: true });
    this.land.destroy({ children: true });
  }
}

function wrap(value: number, period: number): number {
  return ((value % period) + period) % period;
}
