/**
 * The player's own picture, cut out of the camera frame and stood on the board.
 *
 * The frame and its person mask are uploaded as two textures and drawn by one quad whose
 * shader turns the mask into alpha with a soft threshold, adds a white "sticker" outline
 * (the mask dilated by a ring of samples) and a soft drop shadow. The outline makes the
 * cutout look deliberate and hides the mask's rough, flickery edge.
 *
 * The quad's local origin is the player's feet, so whoever places it only has to put the
 * origin on the deck. Its size comes from the smoothed standing height (see placement.ts).
 */
import {
  BufferImageSource,
  Container,
  GlProgram,
  ImageSource,
  Mesh,
  MeshGeometry,
  Shader,
  Texture,
  type TextureSource,
  UniformGroup,
} from 'pixi.js';
import type { Tunables } from '../config/tunables';
import type { PersonMask } from '../core/mask';
import type { PoseFrame } from '../core/pose';
import type { FramePair } from '../vision/types';
import { QUAD_VERTEX } from './gl';
import { glsl, PALETTE as P } from './palette';
import {
  emptyMeasure,
  MaskScratch,
  measureMask,
  measurePose,
  mergeMask,
  type PersonMeasure,
  PlacementFilter,
} from './placement';

const AVATAR_FRAGMENT = `#version 300 es
precision highp float;
in vec2 vUV;
out vec4 finalColor;
uniform sampler2D uImage;
uniform sampler2D uMask;
uniform vec4 uColor;
uniform float uThreshold;
uniform float uSoft;
uniform vec2 uOutline;
uniform vec2 uShadow;
uniform vec4 uCrop;
uniform float uSticker;

float person(vec2 uv) {
  return texture(uMask, uv).r;
}

// 0..1 "is this the person", with the soft threshold applied. The model gives the
// background a small non-zero probability, so raw values must not be averaged.
float inside(vec2 uv, float lo, float hi) {
  return smoothstep(lo, hi, person(uv));
}

void main() {
  float lo = uThreshold - uSoft;
  float hi = uThreshold + uSoft;
  float m = person(vUV);
  float body = smoothstep(lo, hi, m);

  // The mask grown by the outline width: the mean over a disk round this point is above
  // a low level out to about the disk's radius past the edge, and it varies smoothly, so
  // the outline stays round even where the mask is blocky.
  float disk = body * 2.0;
  for (int i = 0; i < 8; i++) {
    float a = float(i) * 0.7854 + 0.3927;
    disk += inside(vUV + vec2(cos(a), sin(a)) * uOutline * 0.7, lo, hi) * 1.5;
  }
  for (int i = 0; i < 12; i++) {
    float a = float(i) * 0.5236;
    disk += inside(vUV + vec2(cos(a), sin(a)) * uOutline * 1.4, lo, hi);
  }
  disk /= 26.0;
  float edge = smoothstep(0.05, 0.2, disk) * uSticker;

  // A soft shadow: the grown shape, offset and blurred by averaging a wider ring.
  vec2 s = vUV - uShadow;
  float shade = smoothstep(lo, hi, person(s));
  for (int i = 0; i < 8; i++) {
    float a = float(i) * 0.7854;
    shade += smoothstep(lo, hi, person(s + vec2(cos(a), sin(a)) * uOutline * 1.6));
  }
  shade = shade / 9.0 * 0.4 * uSticker;

  // Fade out towards the crop's sides and top, so a box edge is never a hard line.
  vec2 lo2 = smoothstep(uCrop.xy, uCrop.xy + uOutline * 1.5, vUV);
  vec2 hi2 = smoothstep(uCrop.zw, uCrop.zw - uOutline * 1.5, vUV);
  float crop = lo2.x * lo2.y * hi2.x;

  vec3 picture = texture(uImage, vUV).rgb;
  // Living rooms are dim next to a sunny beach: lift the shadows a little, add a touch of
  // contrast and warmth so the picture sits in the scene.
  picture = pow(picture, vec3(0.85));
  picture = clamp((picture - 0.5) * 1.06 + 0.5 + vec3(0.02, 0.01, -0.01), 0.0, 1.0);

  vec4 c = vec4(${glsl(P.textStroke)}, 1.0) * shade;
  c = mix(c, vec4(1.0), edge);
  c = mix(c, vec4(picture, 1.0), body);
  finalColor = c * crop * uColor;
}
`;

/** Extra room round the person for the outline and shadow, world units. */
const SHADOW_OFFSET = { x: 6, y: 9 };
/** After this long without a person in the mask, the cutout gives way to the placeholder. */
const LOST_S = 1.2;

export class AvatarCutout {
  /** Origin at the player's feet. */
  readonly view = new Container();
  /** A second, flipped copy for the reflection on flat water (same shader and geometry). */
  readonly reflection: Mesh<MeshGeometry, Shader>;

  private readonly tunables: Tunables;
  private readonly geometry: MeshGeometry;
  private readonly shader: Shader;
  private readonly uniforms: { uThreshold: number; uSoft: number; uSticker: number };
  /** Uniform arrays, written in place. */
  private readonly outlineUv = new Float32Array([0.01, 0.01]);
  private readonly shadowUv = new Float32Array([0.01, 0.01]);
  private readonly cropUv = new Float32Array([0, 0, 1, 1]);
  private readonly mesh: Mesh<MeshGeometry, Shader>;
  private readonly filter = new PlacementFilter();
  private readonly scratch = new MaskScratch();
  private readonly poseMeasure: PersonMeasure = emptyMeasure();
  private readonly maskMeasure: PersonMeasure = emptyMeasure();

  private frame: VideoFrame | null = null;
  private imageSource: ImageSource | null = null;
  /** The whole camera picture, for the debug view. */
  imageTexture: Texture | null = null;
  private maskSource: BufferImageSource | null = null;
  private maskPixels = new Uint32Array(0);
  private sourceWidth = 16;
  private sourceHeight = 9;
  private sinceSeen = Number.POSITIVE_INFINITY;
  lastMask: PersonMask | null = null;
  lastPose: PoseFrame | null = null;

  constructor(tunables: Tunables) {
    this.tunables = tunables;
    this.geometry = new MeshGeometry({
      positions: new Float32Array(8),
      uvs: new Float32Array(8),
      indices: new Uint32Array([0, 1, 2, 0, 2, 3]),
    });
    const group = new UniformGroup({
      uThreshold: { value: 0.5, type: 'f32' },
      uSoft: { value: 0.08, type: 'f32' },
      uOutline: { value: this.outlineUv, type: 'vec2<f32>' },
      uShadow: { value: this.shadowUv, type: 'vec2<f32>' },
      uCrop: { value: this.cropUv, type: 'vec4<f32>' },
      uSticker: { value: 1, type: 'f32' },
    });
    this.uniforms = group.uniforms;
    this.shader = new Shader({
      glProgram: GlProgram.from({ vertex: QUAD_VERTEX, fragment: AVATAR_FRAGMENT, name: 'cutout' }),
      resources: {
        avatarUniforms: group,
        uImage: Texture.EMPTY.source,
        uMask: Texture.EMPTY.source,
      },
    });
    this.mesh = new Mesh({ geometry: this.geometry, shader: this.shader, label: 'cutout' });
    this.reflection = new Mesh({
      geometry: this.geometry,
      shader: this.shader,
      label: 'cutout-reflection',
    });
    this.view.addChild(this.mesh);
    this.mesh.visible = false;
    this.reflection.visible = false;
  }

  /** There is a person to show: a recent mask had one in it. */
  get present(): boolean {
    return this.filter.ready && this.sinceSeen < LOST_S && this.imageSource !== null;
  }

  /** Takes ownership of `pair.image`; the previous frame is closed. */
  setFrame(pair: FramePair | null): void {
    if (!pair) {
      this.releaseFrame();
      this.filter.reset();
      this.sinceSeen = Number.POSITIVE_INFINITY;
      this.lastMask = null;
      this.lastPose = null;
      return;
    }
    const { image, mask, pose } = pair;
    if (image !== this.frame) {
      this.frame?.close();
      this.frame = image;
      if (!this.imageSource) {
        this.imageSource = new ImageSource({
          resource: image,
          // Camera frames are opaque: skip the premultiply pass on every upload.
          alphaMode: 'premultiplied-alpha',
          autoGarbageCollect: false,
          scaleMode: 'linear',
          label: 'avatar-frame',
        });
        this.imageTexture = new Texture({ source: this.imageSource });
        this.shader.resources.uImage = this.imageSource;
      } else {
        this.imageSource.resource = image;
        // Also picks up a change of frame size.
        this.imageSource.update();
      }
    }
    this.sourceWidth = mask.sourceWidth || image.displayWidth;
    this.sourceHeight = mask.sourceHeight || image.displayHeight;
    this.uploadMask(mask);
    this.lastMask = mask;
    this.lastPose = pose;

    const threshold = this.tunables.maskThreshold;
    const fromMask = measureMask(mask, threshold, this.scratch, this.maskMeasure);
    let measure: PersonMeasure | null = null;
    if (pose && measurePose(pose, this.poseMeasure)) {
      measure = this.poseMeasure;
      // The mask knows about hair, fingertips and soles; use it if it is the same person.
      if (fromMask && overlaps(this.poseMeasure, this.maskMeasure)) {
        mergeMask(this.poseMeasure, this.maskMeasure);
      }
    } else if (fromMask) {
      measure = this.maskMeasure;
    }
    if (measure) this.sinceSeen = 0;
    this.filter.measure(measure);
  }

  /**
   * Per display frame: smooth the placement and lay the quad out. `alpha` fades the cutout
   * (the placeholder crossfades with it).
   */
  update(dtS: number, mirrored: boolean, alpha: number): void {
    this.sinceSeen += dtS;
    const t = this.tunables;
    this.filter.step(dtS, { scaleS: t.avatarScaleSmoothS, anchorS: t.avatarAnchorSmoothS });
    const visible = alpha > 0.004 && this.filter.ready && this.imageSource !== null;
    this.mesh.visible = visible;
    this.mesh.alpha = alpha;
    if (!visible) {
      this.reflection.visible = false;
      return;
    }
    const s = this.filter.state;
    const aspect = this.sourceWidth / Math.max(1, this.sourceHeight);
    // World units per v unit (frame heights), and per u unit with the mirror folded in.
    const scale = t.avatarHeight / Math.max(0.05, s.height);
    const sx = scale * aspect * (mirrored ? -1 : 1);
    const outline = t.avatarOutline;
    const marginV = (outline * 2 + SHADOW_OFFSET.y) / scale;
    const marginU = marginV / aspect;
    const u0 = Math.max(0, s.u0 - marginU);
    const u1 = Math.min(1, s.u1 + marginU);
    const v0 = Math.max(0, s.v0 - marginV);
    // Nothing below the feet but the outline; the board covers the bottom edge.
    const v1 = Math.min(1, Math.max(s.anchorV, s.v1) + marginV * 0.5);

    const positions = this.geometry.positions;
    const uvs = this.geometry.uvs;
    const x0 = (u0 - s.anchorU) * sx;
    const x1 = (u1 - s.anchorU) * sx;
    const y0 = (v0 - s.anchorV) * scale;
    const y1 = (v1 - s.anchorV) * scale;
    positions[0] = x0;
    positions[1] = y0;
    positions[2] = x1;
    positions[3] = y0;
    positions[4] = x1;
    positions[5] = y1;
    positions[6] = x0;
    positions[7] = y1;
    uvs[0] = u0;
    uvs[1] = v0;
    uvs[2] = u1;
    uvs[3] = v0;
    uvs[4] = u1;
    uvs[5] = v1;
    uvs[6] = u0;
    uvs[7] = v1;
    this.geometry.getBuffer('aPosition').update();
    this.geometry.getBuffer('aUV').update();

    const u = this.uniforms;
    u.uThreshold = t.maskThreshold;
    u.uSoft = t.maskSoftness / 2;
    const outlineV = outline / scale;
    this.outlineUv[0] = outlineV / aspect;
    this.outlineUv[1] = outlineV;
    // The shadow falls down and away from the sun (upper right on screen).
    const shadowX = (mirrored ? SHADOW_OFFSET.x : -SHADOW_OFFSET.x) / scale / aspect;
    this.shadowUv[0] = shadowX;
    this.shadowUv[1] = -SHADOW_OFFSET.y / scale;
    // Where the frame cuts the player off (an arm out of shot), fade instead of a hard
    // line. Never at the bottom: that edge stands on the board.
    this.cropUv[0] = u0;
    this.cropUv[1] = v0;
    this.cropUv[2] = u1;
    this.cropUv[3] = 2;
    u.uSticker = outline > 0 ? 1 : 0;
  }

  /** Height of the cutout above its feet right now, world units (for the camera). */
  get height(): number {
    return this.tunables.avatarHeight;
  }

  dispose(): void {
    this.releaseFrame();
    this.maskSource?.destroy();
    this.maskSource = null;
    this.mesh.destroy();
    this.reflection.destroy();
    this.view.destroy({ children: true });
    this.shader.destroy();
    this.geometry.destroy();
  }

  private uploadMask(mask: PersonMask): void {
    const { width, height, data } = mask;
    if (!this.maskSource || this.maskSource.width !== width || this.maskSource.height !== height) {
      this.maskSource?.destroy();
      this.maskPixels = new Uint32Array(width * height);
      this.maskSource = new BufferImageSource({
        resource: new Uint8Array(this.maskPixels.buffer),
        width,
        height,
        format: 'rgba8unorm',
        alphaMode: 'premultiplied-alpha',
        scaleMode: 'linear',
        autoGarbageCollect: false,
        label: 'avatar-mask',
      });
      this.shader.resources.uMask = this.maskSource as TextureSource;
    }
    // P(person) into every channel: RGBA rows are always 4-byte aligned, unlike R8 ones.
    const pixels = this.maskPixels;
    for (let i = 0; i < pixels.length; i++) pixels[i] = (data[i] as number) * 0x01010101;
    this.maskSource.update();
  }

  private releaseFrame(): void {
    this.frame?.close();
    this.frame = null;
    this.imageTexture?.destroy();
    this.imageSource?.destroy();
    this.imageTexture = null;
    this.imageSource = null;
    this.shader.resources.uImage = Texture.EMPTY.source;
  }
}

function overlaps(a: PersonMeasure, b: PersonMeasure): boolean {
  return a.u0 < b.u1 && b.u0 < a.u1 && a.v0 < b.v1 && b.v0 < a.v1;
}
