import { POSE_POINTS } from '../core/pose';
import {
  BODY_COLOR,
  figureJoints,
  LIMB_WIDTH,
  MARKED_JOINTS,
  MARKER_COLORS,
  MARKER_SIZE,
  POSE_FAULT_COLOR,
  POSE_FAULT_SIZE,
  type SyntheticPose,
} from './syntheticFigure';
import {
  type FrameSource,
  type FrameTick,
  type SourceInfo,
  type SyntheticBlob,
  type SyntheticControl,
  VisionError,
} from './types';

const WIDTH = 1280;
const HEIGHT = 720;
const FRAME_INTERVAL_MS = 1000 / 30;
/** The default animation: the arm tilt swings between ±this, once per period. */
const DEFAULT_TILT_RAD = (25 * Math.PI) / 180;
const DEFAULT_PERIOD_MS = 6000;

const css = ([r, g, b]: readonly [number, number, number]): string => `rgb(${r}, ${g}, ${b})`;
const BODY = css(BODY_COLOR);
const MARKERS = MARKER_COLORS.map(css);

/** The tick handed out for every frame; reused, so a frame allocates only its VideoFrame. */
class CanvasTick implements FrameTick {
  captureTimeMs = 0;
  canvas: HTMLCanvasElement | null = null;
  private readonly frameInit: VideoFrameInit = { timestamp: 0 };

  grab(): VideoFrame {
    if (!this.canvas) throw new Error('synthetic source stopped');
    this.frameInit.timestamp = Math.round(this.captureTimeMs * 1000);
    return new VideoFrame(this.canvas, this.frameInit);
  }
}

/**
 * A camera-free source: a canvas with a magenta stick figure, arms out, whose body the
 * chroma segmenter turns into a mask and whose joint markers the chroma pose engine reads
 * (see `syntheticFigure.ts`). By default the arms tilt slowly from side to side; tests pin
 * the pose with `setPose`, or show plain blobs instead with `setBlobs`.
 */
export class SyntheticSource implements FrameSource, SyntheticControl {
  readonly kind = 'synthetic' as const;
  info: SourceInfo | null = null;
  display: HTMLCanvasElement | null = null;
  readonly stream = null;

  private ctx: CanvasRenderingContext2D | null = null;
  private handler: ((tick: FrameTick) => void) | null = null;
  private readonly tick = new CanvasTick();
  private raf = 0;
  private running = false;
  private paused = false;
  private stopped = false;
  private lastFrameMs = 0;
  private blobs: SyntheticBlob[] | null = null;
  private pinned: SyntheticPose | null = null;
  private poseFault = false;
  /** The default animation's pose, updated in place each frame. */
  private readonly animated: SyntheticPose = { tiltRad: 0, armsOut: true, x: 0.5 };
  private shown: SyntheticPose | null = null;
  private readonly joints = new Float32Array(POSE_POINTS * 2);
  private background: CanvasGradient | null = null;

  async start(): Promise<SourceInfo> {
    if (typeof VideoFrame === 'undefined') {
      throw new VisionError('unsupported', 'This browser cannot capture video frames.');
    }
    const canvas = document.createElement('canvas');
    canvas.width = WIDTH;
    canvas.height = HEIGHT;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.display = canvas;
    this.tick.canvas = canvas;
    this.info = {
      kind: 'synthetic',
      width: WIDTH,
      height: HEIGHT,
      frameRate: 30,
      label: 'Synthetic',
      deviceId: null,
    };
    this.draw(performance.now());
    if (!this.paused) this.run();
    return this.info;
  }

  pause(): void {
    this.paused = true;
    this.halt();
  }

  resume(): void {
    if (this.stopped) return;
    this.paused = false;
    this.run();
  }

  stop(): void {
    this.stopped = true;
    this.halt();
    this.handler = null;
    this.tick.canvas = null;
  }

  setFrameHandler(handler: ((tick: FrameTick) => void) | null): void {
    this.handler = handler;
  }

  setEndedHandler(_handler: ((error: VisionError) => void) | null): void {
    // A synthetic source never ends.
  }

  setBlobs(blobs: SyntheticBlob[] | null): void {
    this.blobs = blobs;
  }

  setPose(pose: SyntheticPose | null): void {
    this.blobs = null;
    this.pinned = pose ? { ...pose } : null;
  }

  setPoseFault(enabled: boolean): void {
    this.poseFault = enabled;
  }

  get currentPose(): SyntheticPose | null {
    return this.shown ? { ...this.shown } : null;
  }

  private run(): void {
    if (this.running || !this.display) return;
    this.running = true;
    this.raf = requestAnimationFrame(this.loop);
  }

  private halt(): void {
    this.running = false;
    cancelAnimationFrame(this.raf);
  }

  private readonly loop = (now: number): void => {
    if (!this.running) return;
    this.raf = requestAnimationFrame(this.loop);
    if (now - this.lastFrameMs < FRAME_INTERVAL_MS - 2) return;
    this.lastFrameMs = now;
    this.draw(now);
    if (!this.handler) return;
    this.tick.captureTimeMs = now;
    this.handler(this.tick);
  };

  private draw(now: number): void {
    const ctx = this.ctx;
    if (!ctx) return;
    if (!this.background) {
      this.background = ctx.createLinearGradient(0, 0, 0, HEIGHT);
      this.background.addColorStop(0, '#16324f');
      this.background.addColorStop(1, '#0b1a2a');
    }
    ctx.fillStyle = this.background;
    ctx.fillRect(0, 0, WIDTH, HEIGHT);

    // A left/right marker makes mirroring mistakes obvious in screenshots.
    ctx.fillStyle = '#2f6f4f';
    ctx.fillRect(40, 40, 120, 60);
    ctx.fillStyle = '#d8e6f0';
    ctx.font = '36px sans-serif';
    ctx.fillText('LEFT', 52, 84);

    if (this.poseFault) {
      ctx.fillStyle = css(POSE_FAULT_COLOR);
      ctx.fillRect(WIDTH - POSE_FAULT_SIZE, 0, POSE_FAULT_SIZE, POSE_FAULT_SIZE);
    }

    ctx.fillStyle = BODY;
    if (this.blobs) {
      this.shown = null;
      for (const blob of this.blobs) {
        ctx.beginPath();
        ctx.arc(blob.x, blob.y, blob.r, 0, Math.PI * 2);
        ctx.fill();
      }
      return;
    }
    let pose = this.pinned;
    if (!pose) {
      pose = this.animated;
      pose.tiltRad = DEFAULT_TILT_RAD * Math.sin((2 * Math.PI * now) / DEFAULT_PERIOD_MS);
    }
    this.shown = pose;
    this.drawFigure(ctx, pose);
  }

  private drawFigure(ctx: CanvasRenderingContext2D, pose: SyntheticPose): void {
    const joints = figureJoints(pose, WIDTH, HEIGHT, this.joints);
    const x = (joint: number): number => joints[joint * 2] as number;
    const y = (joint: number): number => joints[joint * 2 + 1] as number;
    const line = (...path: number[]): void => {
      ctx.beginPath();
      ctx.moveTo(x(path[0] as number), y(path[0] as number));
      for (const joint of path.slice(1)) ctx.lineTo(x(joint), y(joint));
      ctx.stroke();
    };
    ctx.strokeStyle = BODY;
    ctx.lineWidth = LIMB_WIDTH * HEIGHT;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    // Torso, arms (shoulder, elbow, wrist) and legs (hip, ankle).
    ctx.beginPath();
    ctx.moveTo(x(11), y(11));
    ctx.lineTo(x(12), y(12));
    ctx.lineTo(x(24), y(24));
    ctx.lineTo(x(23), y(23));
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    line(11, 13, 15);
    line(12, 14, 16);
    line(23, 27);
    line(24, 28);
    // Neck and head.
    const shoulderX = (x(11) + x(12)) / 2;
    const shoulderY = (y(11) + y(12)) / 2;
    ctx.beginPath();
    ctx.moveTo(shoulderX, shoulderY);
    ctx.lineTo(x(0), y(0));
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(x(0), y(0) - 0.015 * HEIGHT, 0.06 * HEIGHT, 0, Math.PI * 2);
    ctx.fill();

    // Markers on whole pixels, so their colours stay pure (see MARKER_SIZE).
    const size = 2 * Math.round((MARKER_SIZE * HEIGHT) / 2);
    MARKED_JOINTS.forEach((joint, index) => {
      ctx.fillStyle = MARKERS[index] as string;
      ctx.fillRect(Math.round(x(joint) - size / 2), Math.round(y(joint) - size / 2), size, size);
    });
  }
}
