/**
 * The one place that owns segmenter recovery. It runs a chain of backends and moves to
 * the next link when the current one fails to start, stops responding, crashes, loses its
 * GPU context, or fails several frames in a row (a frame whose pose model failed counts,
 * though its mask is still delivered):
 *
 *   auto:   worker → worker (restart) → main thread (fallback) → main thread (restart)
 *   worker: worker → worker
 *   main:   main thread → main thread
 *
 * While a replacement starts, `segment()` rejects at once (the frame is dropped) instead
 * of holding frames. When the chain runs out at runtime, `onFailed` reports
 * `segmenter-failed` once. After a long healthy stretch the chain is refilled, so a few
 * passing hiccups spread over a long session never use it up.
 */
import { type Backend, SegmentFailure } from './backend';
import type { RegionLayout } from './protocol';
import {
  type SegmenterBackend,
  type SegmenterInfo,
  type SegmentJob,
  type SegmentResult,
  type StartProgress,
  VisionError,
} from './types';

/** Consecutive failed frames after which a backend is considered broken. */
export const MAX_CONSECUTIVE_FAILURES = 3;

/**
 * A backend that has run this long and segmented this many frames in a row without a
 * single failure is healthy, so the failures before it were passing hiccups (a GPU stall,
 * a display reset) and the next failure starts the chain from the top again.
 *
 * A broken backend shows itself within seconds: a wedged GPU stalls again, a bad driver
 * fails every few frames. A minute clean is far beyond that, and still short next to a
 * session. The frame count keeps time without frames (tab hidden, camera stalled) from
 * passing as health; at the normal 30 fps it is reached well before the minute.
 */
export const HEALTHY_STRETCH_MS = 60_000;
export const HEALTHY_STRETCH_FRAMES = 600;
/**
 * After a lost GPU context, time for the browser to bring its GPU process back before the
 * replacement asks for a new context; a replacement that started at once could fail too and
 * burn another link.
 */
export const CONTEXT_LOSS_BACKOFF_MS = 1_000;

export interface ResilientSegmenterOptions {
  backend: 'auto' | SegmenterBackend;
  layout: RegionLayout;
  /** Build a fresh, uninitialised backend that reports every outcome to `monitor`. */
  create(
    kind: SegmenterBackend,
    layout: RegionLayout,
    monitor: (failure: SegmentFailure | null) => void,
  ): Backend;
  /** A backend is being replaced (restart or fallback) by one of `kind`. */
  onRestart?(kind: SegmenterBackend, reason: string): void;
  /** Runtime only: every backend in the chain has failed. Not called after `dispose()`. */
  onFailed?(error: VisionError): void;
  /** Monotonic milliseconds, for the healthy stretch. */
  now?(): number;
}

export function backendChain(backend: 'auto' | SegmenterBackend): SegmenterBackend[] {
  switch (backend) {
    case 'auto':
      return ['worker', 'worker', 'main', 'main'];
    case 'worker':
      return ['worker', 'worker'];
    case 'main':
      return ['main', 'main'];
  }
}

export class ResilientSegmenter implements Backend {
  /** Times a backend was replaced, at start-up or at runtime. */
  restarts = 0;

  private readonly chain: SegmenterBackend[];
  /** Index in `chain` of the current backend; -1 when the whole chain is still available. */
  private link = -1;
  private created = 0;
  private current: Backend | null = null;
  private ready = false;
  private failures = 0;
  /** Since when, and for how many frames, the current backend has not failed once. */
  private healthySince = 0;
  private healthyFrames = 0;
  /** Bumped whenever the current backend changes, so late reports from old ones are ignored. */
  private generation = 0;
  private layout: RegionLayout;
  private lastInfo: SegmenterInfo | null = null;
  private lastError: unknown = null;
  private replacing = false;
  private failed = false;
  private disposed = false;
  /** Ends a back-off early, on dispose. */
  private wake: (() => void) | null = null;
  private readonly now: () => number;

  constructor(private readonly options: ResilientSegmenterOptions) {
    this.chain = backendChain(options.backend);
    this.layout = options.layout;
    this.now = options.now ?? (() => performance.now());
  }

  /** The running backend's info; during a restart, the previous one's. */
  get info(): SegmenterInfo | null {
    return this.lastInfo;
  }

  /** True while a backend is up and accepting frames. */
  get running(): boolean {
    return this.ready;
  }

  /** Start the first backend in the chain that works. Rejects with `segmenter-init` if none does. */
  async init(onProgress?: (progress: StartProgress) => void): Promise<SegmenterInfo> {
    const info = await this.advance('start', onProgress);
    if (info) return info;
    throw new VisionError(
      'segmenter-init',
      this.disposed ? 'The segmenter was stopped.' : 'The segmenter could not be started.',
      { cause: this.lastError },
    );
  }

  segment(frame: VideoFrame, job?: SegmentJob): Promise<SegmentResult | null> {
    const { current } = this;
    if (!this.ready || !current) {
      frame.close();
      return Promise.reject(new SegmentFailure('The segmenter is restarting.', false));
    }
    return current.segment(frame, job);
  }

  setLayout(layout: RegionLayout): void {
    this.layout = layout;
    this.current?.setLayout(layout);
  }

  recycle(data: Uint8Array): void {
    this.current?.recycle(data);
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.ready = false;
    this.generation++;
    this.wake?.();
    this.current?.dispose();
    this.current = null;
  }

  private monitorFor(generation: number): (failure: SegmentFailure | null) => void {
    return (failure) => {
      if (generation !== this.generation || !this.ready) return;
      if (!failure) {
        this.failures = 0;
        this.noteHealthy();
        return;
      }
      this.healthyFrames = 0;
      this.healthySince = this.now();
      if (!failure.fatal && ++this.failures < MAX_CONSECUTIVE_FAILURES) return;
      void this.replace(
        failure.fatal ? failure.message : `${this.failures} frames failed in a row`,
        failure.contextLost ? CONTEXT_LOSS_BACKOFF_MS : 0,
      );
    };
  }

  private noteHealthy(): void {
    this.healthyFrames++;
    if (this.link < 1 || this.healthyFrames < HEALTHY_STRETCH_FRAMES) return;
    if (this.now() - this.healthySince < HEALTHY_STRETCH_MS) return;
    // Earlier failures are forgiven: the next one starts the chain from its first link
    // (for `auto`, the worker), whichever backend is running now.
    this.link = -1;
    console.info('[vision] segmenter healthy again; recovery starts from the top next time');
  }

  private async replace(reason: string, backoffMs: number): Promise<void> {
    if (this.replacing || this.disposed || this.failed) return;
    this.replacing = true;
    this.ready = false;
    this.generation++;
    this.current?.dispose();
    this.current = null;
    console.warn(`[vision] segmenter stopped working (${reason})`);
    if (backoffMs > 0) await this.sleep(backoffMs);
    const info = await this.advance(reason);
    this.replacing = false;
    if (info || this.disposed) return;
    this.failed = true;
    this.options.onFailed?.(
      new VisionError('segmenter-failed', 'Segmentation stopped working.', {
        cause: this.lastError,
      }),
    );
  }

  private sleep(ms: number): Promise<void> {
    return new Promise<void>((resolve) => {
      const done = (): void => {
        clearTimeout(timer);
        this.wake = null;
        resolve();
      };
      const timer = setTimeout(done, ms);
      this.wake = done;
    });
  }

  /**
   * Start the remaining links in order until one works. Progress goes to every attempt;
   * the caller keeps it from going backwards.
   */
  private async advance(
    reason: string,
    onProgress?: (progress: StartProgress) => void,
  ): Promise<SegmenterInfo | null> {
    while (!this.disposed && this.link + 1 < this.chain.length) {
      const kind = this.chain[++this.link] as SegmenterBackend;
      if (this.created++ > 0) {
        this.restarts++;
        this.options.onRestart?.(kind, reason);
      }
      const generation = ++this.generation;
      const backend = this.options.create(kind, this.layout, this.monitorFor(generation));
      this.current = backend;
      try {
        const info = await backend.init(onProgress);
        if (this.disposed) {
          backend.dispose();
          return null;
        }
        // The layout may have changed while it was starting.
        backend.setLayout(this.layout);
        this.lastInfo = info;
        this.failures = 0;
        this.healthyFrames = 0;
        this.healthySince = this.now();
        this.ready = true;
        return info;
      } catch (error) {
        backend.dispose();
        if (this.current === backend) this.current = null;
        this.lastError = error;
        reason = error instanceof Error ? error.message : String(error);
        console.warn(`[vision] ${kind} segmenter failed to start (${reason})`);
      }
    }
    return null;
  }
}
