import { type FrameSource, type FrameTick, type SourceInfo, VisionError } from './types';
import {
  createVideoElement,
  playUntilFirstFrame,
  supportsVideoFrames,
  VideoTicker,
} from './videoTicker';

/** Long enough for a large remote clip to buffer its first frames. */
const FIRST_FRAME_TIMEOUT_MS = 20_000;

function labelFor(src: string | Blob): string {
  if (typeof src !== 'string') return src instanceof File && src.name ? src.name : 'Video clip';
  try {
    const name = new URL(src, location.href).pathname.split('/').pop();
    return name ? decodeURIComponent(name) : 'Video clip';
  } catch {
    return 'Video clip';
  }
}

/**
 * A looping, muted video clip from a URL, File or Blob, played in place of the camera.
 * The loop restarts on its own; while it seeks back there may be a frame or two with
 * nothing to grab, which the scheduler skips.
 */
export class ClipSource implements FrameSource {
  readonly kind = 'clip' as const;
  info: SourceInfo | null = null;
  display: HTMLVideoElement | null = null;
  readonly stream = null;

  private ticker: VideoTicker | null = null;
  private objectUrl: string | null = null;
  private handler: ((tick: FrameTick) => void) | null = null;
  private endedHandler: ((error: VisionError) => void) | null = null;
  private paused = false;
  private stopped = false;

  constructor(private readonly src: string | Blob) {}

  async start(): Promise<SourceInfo> {
    if (this.stopped || this.display)
      throw new VisionError('unknown', 'The clip source was reused.');
    if (!supportsVideoFrames()) {
      throw new VisionError('unsupported', 'This browser cannot capture video frames.');
    }
    const { src } = this;
    const video = createVideoElement();
    video.loop = true;
    video.preload = 'auto';
    this.display = video;
    if (typeof src === 'string') {
      // Frames of a cross-origin clip can only be read when it is served with CORS.
      if (!/^(blob|data):/i.test(src)) video.crossOrigin = 'anonymous';
      video.src = src;
    } else {
      this.objectUrl = URL.createObjectURL(src);
      video.src = this.objectUrl;
    }

    try {
      await playUntilFirstFrame(video, FIRST_FRAME_TIMEOUT_MS);
      if (video.videoWidth === 0 || video.videoHeight === 0) {
        throw new Error('The clip has no video track.');
      }
    } catch (cause) {
      this.stop();
      throw new VisionError(
        'clip-failed',
        `The video clip could not be played: ${describe(cause)}`,
        {
          cause,
        },
      );
    }
    if (this.stopped)
      throw new VisionError('clip-failed', 'The clip was closed while it was starting.');

    video.addEventListener('error', this.onError);
    video.addEventListener('pause', this.onPause);
    video.addEventListener('resize', this.onResize);
    this.info = this.describe();
    const ticker = new VideoTicker(video);
    ticker.handler = this.handler;
    this.ticker = ticker;
    if (this.paused) video.pause();
    else ticker.start();
    return this.info;
  }

  pause(): void {
    this.paused = true;
    this.ticker?.stop();
    // Nobody sees it while paused (the tab is hidden), so stop decoding too.
    this.display?.pause();
  }

  resume(): void {
    if (this.stopped) return;
    this.paused = false;
    if (!this.ticker) return;
    this.ticker.start();
    this.replay();
  }

  stop(): void {
    this.stopped = true;
    this.ticker?.stop();
    this.ticker = null;
    this.handler = null;
    this.endedHandler = null;
    const video = this.display;
    if (video) {
      video.removeEventListener('error', this.onError);
      video.removeEventListener('pause', this.onPause);
      video.removeEventListener('resize', this.onResize);
      video.pause();
      video.removeAttribute('src');
      video.load();
    }
    if (this.objectUrl) URL.revokeObjectURL(this.objectUrl);
    this.objectUrl = null;
  }

  setFrameHandler(handler: ((tick: FrameTick) => void) | null): void {
    this.handler = handler;
    if (this.ticker) this.ticker.handler = handler;
  }

  setEndedHandler(handler: ((error: VisionError) => void) | null): void {
    this.endedHandler = handler;
  }

  private describe(): SourceInfo {
    const video = this.display;
    return {
      kind: 'clip',
      width: video?.videoWidth ?? 0,
      height: video?.videoHeight ?? 0,
      frameRate: null,
      label: labelFor(this.src),
      deviceId: null,
    };
  }

  private replay(): void {
    const video = this.display;
    if (!video?.paused || this.stopped) return;
    video.play().catch((error: unknown) => {
      if (!this.stopped && !this.paused) console.warn('[vision] the clip could not resume', error);
    });
  }

  private readonly onError = (): void => {
    const error = this.display?.error;
    this.endedHandler?.(
      new VisionError(
        'clip-failed',
        `The video clip stopped playing: ${error?.message || 'media error'}`,
        {
          cause: error,
        },
      ),
    );
  };

  /** Something else paused the clip (a media key, the browser): keep it going. */
  private readonly onPause = (): void => {
    if (!this.paused) this.replay();
  };

  private readonly onResize = (): void => {
    const video = this.display;
    if (!video || !this.info || video.videoWidth === 0) return;
    if (video.videoWidth === this.info.width && video.videoHeight === this.info.height) return;
    this.info = this.describe();
  };
}

function describe(error: unknown): string {
  if (error instanceof Error) return error.message;
  if (typeof MediaError !== 'undefined' && error instanceof MediaError) {
    return error.message || `media error ${error.code}`;
  }
  return String(error);
}
