/**
 * The boot screen's artwork as inline SVG: a sunny beach seen from the sand, with a wave
 * curling over on the left and a surfer riding its face with arms out, and the three
 * how-to-play pictograms. Kept out of the overlay's logic, and inline so the first paint
 * needs no extra requests.
 *
 * The scene is drawn on a 1920×1080 canvas and scaled to cover the screen (cropping the
 * sides on narrower windows). Its moving parts carry `boot-anim-*` classes, animated in CSS
 * so reduced motion can switch them off.
 */

/** Horizon height as a fraction of the screen; the stylesheet lines the layout up with it. */
export const HORIZON = 0.435;

const H = Math.round(1080 * HORIZON);

/** A wave line repeating every `period` units across two screen widths, so it can scroll. */
function swell(y: number, amplitude: number, period: number): string {
  let d = `M0 ${y}`;
  for (let x = 0; x < 3840; x += period) {
    d += ` q${period / 4} ${-amplitude} ${period / 2} 0 t${period / 2} 0`;
  }
  return `${d} V1080 H0 Z`;
}

const cloud = (x: number, y: number, s: number, cls: string) => `
  <g class="boot-anim-cloud ${cls}" transform="translate(${x} ${y}) scale(${s})">
    <ellipse cx="0" cy="0" rx="92" ry="34"/>
    <circle cx="-34" cy="-22" r="38"/>
    <circle cx="22" cy="-34" r="48"/>
    <circle cx="66" cy="-8" r="30"/>
  </g>`;

const star = (x: number, y: number, r: number, delay: number) => {
  const points: string[] = [];
  for (let i = 0; i < 10; i++) {
    const radius = i % 2 ? r * 0.45 : r;
    const angle = (Math.PI / 5) * i - Math.PI / 2;
    points.push(
      `${(radius * Math.cos(angle)).toFixed(1)},${(radius * Math.sin(angle)).toFixed(1)}`,
    );
  }
  return `<g transform="translate(${x} ${y})"><polygon class="boot-anim-star" style="animation-delay:${delay}s" points="${points.join(' ')}"/></g>`;
};

