/** Line style for the pictograms: navy (the text colour) by default, orange for accents. */
const ink = (stroke = 'currentColor', width = 4) =>
  `fill="none" stroke="${stroke}" stroke-width="${width}" stroke-linecap="round" stroke-linejoin="round"`;
const INK = ink();
const ACCENT = '#ff7a45';

