/**
 * The game's sound, over Web Audio: owns the AudioContext (created on the first user gesture),
 * the master bus, the soundscape (the one-shots and continuous layers in `soundscape.ts`) and
 * the music loop. Everything stays silent until `unlock()`, and while muted or suspended.
 */
import type { Tunables } from '../config/tunables';
import { createSoundscape, type Soundscape } from './soundscape';
import { createMasterBus, createNoiseBuffer, type MasterBus, volumeToGain } from './synth';
import type { Sfx } from './types';

export { MAX_VOICES } from './soundscape';

/** Time constant for volume and mute changes, short enough to feel instant without clicks. */
const GAIN_SMOOTHING_S = 0.015;
/** The music fades in over about this long when it starts, rather than starting on a bang. */
const MUSIC_FADE_IN_S = 0.6;
/**
 * The game stops calling `update` when play ends (back to the boot screen), so the layers
 * fade out by themselves once updates have stopped for this long.
 */
export const IDLE_FADE_MS = 300;
const IDLE_CHECK_MS = 100;

/** Music is quieter than this fraction of full scale even with its slider at the top. */
export const MUSIC_HEADROOM = 0.8;

interface Engine {
  context: AudioContext;
  bus: MasterBus;
  soundscape: Soundscape;
  idleTimer: ReturnType<typeof setInterval>;
}

interface Music {
  url: string;
  source: AudioBufferSourceNode | null;
  buffer: AudioBuffer | null;
  /** Encoded bytes, kept until there is a context to decode them with. */
  encoded: ArrayBuffer | null;
}

export function createSfx(tunables: Tunables): Sfx {
  let engine: Engine | null = null;
  let muted = false;
  /** Paused by the owner (tab hidden); independent of the context's own state. */
  let suspended = false;
  let disposed = false;
  let music: Music | null = null;
  /** Volumes last applied, so a tick only touches the params when a slider moved. */
  let applied = '';
  /** When `update` last ran (performance.now), and whether the layers are faded since. */
  let lastUpdateMs = Number.NEGATIVE_INFINITY;
  let idle = true;

  const masterGain = (): number => (muted ? 0 : volumeToGain(tunables.masterVolume));
  const musicGain = (): number => volumeToGain(tunables.musicVolume) * MUSIC_HEADROOM;

  const applyGain = (force = false): void => {
    if (!engine) return;
    const { masterVolume, musicVolume, effectsVolume, ambienceVolume } = tunables;
    const key = `${muted}|${masterVolume}|${musicVolume}|${effectsVolume}|${ambienceVolume}`;
    if (!force && key === applied) return;
    applied = key;
    const { context, bus } = engine;
    const now = context.currentTime;
    bus.master.gain.setTargetAtTime(masterGain(), now, GAIN_SMOOTHING_S);
    bus.effects.gain.setTargetAtTime(volumeToGain(effectsVolume), now, GAIN_SMOOTHING_S);
    bus.ambience.gain.setTargetAtTime(volumeToGain(ambienceVolume), now, GAIN_SMOOTHING_S);
    // Until the loop starts, its fade-in owns the music gain.
    if (music?.source) bus.music.gain.setTargetAtTime(musicGain(), now, GAIN_SMOOTHING_S);
  };

  /** Start the loop once both the track and the audio context exist. */
  const playMusic = (): void => {
    const track = music;
    if (!engine || !track || track.source || disposed) return;
    const { context, bus } = engine;
    if (!track.buffer) {
      const encoded = track.encoded;
      if (!encoded) return;
      track.encoded = null;
      context.decodeAudioData(encoded).then(
        (buffer) => {
          track.buffer = buffer;
          if (music === track) playMusic();
        },
        () => {
          // Undecodable: no music.
        },
      );
      return;
    }
    const source = context.createBufferSource();
    source.buffer = track.buffer;
    // The file is cut to whole bars where the song repeats itself, so it loops seamlessly.
    source.loop = true;
    source.connect(bus.music);
    const now = context.currentTime;
    bus.music.gain.cancelScheduledValues(now);
    bus.music.gain.setValueAtTime(0, now);
    bus.music.gain.setTargetAtTime(musicGain(), now, MUSIC_FADE_IN_S / 3);
    source.start(now);
    track.source = source;
  };

  const build = (): Engine => {
    const context = new AudioContext({ latencyHint: 'interactive' });
    const bus = createMasterBus(context);
    bus.master.gain.value = masterGain();
    bus.effects.gain.value = volumeToGain(tunables.effectsVolume);
    bus.ambience.gain.value = volumeToGain(tunables.ambienceVolume);
    bus.music.gain.value = 0;
    const soundscape = createSoundscape({
      context,
      effects: bus.effects,
      ambience: bus.ambience,
      noise: createNoiseBuffer(context, Math.random),
      random: Math.random,
    });
    const idleTimer = setInterval(() => {
      if (idle || performance.now() - lastUpdateMs < IDLE_FADE_MS) return;
      idle = true;
      // Updates stopped: most likely play ended, so nothing scheduled should follow.
      soundscape.silence(context.currentTime, true);
    }, IDLE_CHECK_MS);
    return { context, bus, soundscape, idleTimer };
  };

  /** The engine, if sound may play right now. */
  const live = (): Engine | null =>
    engine && !muted && !suspended && engine.context.state === 'running' ? engine : null;

  return {
    get muted() {
      return muted;
    },

    async unlock() {
      if (disposed) return;
      try {
        if (!engine) {
          engine = build();
          applyGain(true);
        }
        playMusic();
        if (!suspended && engine.context.state !== 'running') await engine.context.resume();
      } catch {
        // No audio device, or the browser refused: the game simply stays silent.
      }
    },

    update(game, events, dtS) {
      const running = live();
      if (!running) return;
      applyGain();
      lastUpdateMs = performance.now();
      idle = false;
      running.soundscape.update(game, events, dtS, running.context.currentTime);
    },

    stopGame() {
      if (!engine) return;
      idle = true;
      engine.soundscape.stopGame(engine.context.currentTime);
    },

    startMusic(url) {
      if (disposed || music?.url === url) return;
      if (music?.source) {
        music.source.stop();
        music.source.disconnect();
      }
      const track: Music = { url, source: null, buffer: null, encoded: null };
      music = track;
      fetch(url)
        .then((response) => {
          if (!response.ok) throw new Error(`HTTP ${response.status}`);
          return response.arrayBuffer();
        })
        .then(
          (encoded) => {
            track.encoded = encoded;
            if (music === track) playMusic();
          },
          () => {
            // No music is not worth interrupting the game for.
          },
        );
    },

    applyVolume() {
      applyGain(true);
    },

    setMuted(value) {
      muted = value;
      applyGain(true);
      // Fade the layers as well, so unmuting brings them back from silence, not mid-sound.
      if (muted && engine) engine.soundscape.silence(engine.context.currentTime);
    },

    suspend() {
      suspended = true;
      if (!engine) return;
      engine.soundscape.silence(engine.context.currentTime);
      engine.context.suspend().catch(() => {});
    },

    resume() {
      suspended = false;
      engine?.context.resume().catch(() => {});
    },

    dispose() {
      disposed = true;
      music = null;
      if (engine) {
        clearInterval(engine.idleTimer);
        engine.soundscape.stop(engine.context.currentTime);
        engine.context.close().catch(() => {});
      }
      engine = null;
    },
  };
}
