import { VisionError } from './types';

/**
 * A download that receives nothing for this long has stalled (a dead connection). There is
 * deliberately no limit on the total time: a slow but moving download is left to finish.
 */
export const STALL_TIMEOUT_MS = 20_000;

/**
 * Bytes received so far and the expected total, if the server said. With a compressed
 * response the total is the compressed size, so `received` can end up larger than it.
 */
export type DownloadProgress = (received: number, total: number | null) => void;

/**
 * Download `url` into a Blob of `type`, reporting progress. The browser HTTP cache makes
 * repeat loads instant. Rejects with `model-download` (the game files could not be
 * fetched) when the request fails, stalls, or `signal` aborts it.
 */
export async function download(
  url: string,
  type: string,
  onProgress?: DownloadProgress,
  signal?: AbortSignal,
): Promise<Blob> {
  const stall = new AbortController();
  let stallTimer: ReturnType<typeof setTimeout> | undefined;
  const watch = (): void => {
    clearTimeout(stallTimer);
    stallTimer = setTimeout(() => stall.abort(), STALL_TIMEOUT_MS);
  };
  const combined = signal ? AbortSignal.any([signal, stall.signal]) : stall.signal;
  const failure = (message: string, cause?: unknown): VisionError =>
    new VisionError(
      'model-download',
      signal?.aborted
        ? 'The download was cancelled.'
        : stall.signal.aborted
          ? `The download stalled: ${url}`
          : message,
      { cause },
    );

  try {
    watch();
    let response: Response;
    try {
      response = await fetch(url, { signal: combined });
    } catch (cause) {
      throw failure(`Could not download ${url}`, cause);
    }
    if (!response.ok) throw failure(`Download failed (HTTP ${response.status}): ${url}`);

    const length = Number(response.headers.get('content-length'));
    const total = Number.isFinite(length) && length > 0 ? length : null;
    const reader = response.body?.getReader();
    if (!reader) {
      onProgress?.(0, total);
      return new Blob([await response.arrayBuffer()], { type });
    }

    const chunks: Uint8Array<ArrayBuffer>[] = [];
    let received = 0;
    onProgress?.(0, total);
    try {
      for (;;) {
        watch();
        const { done, value } = await reader.read();
        if (done) break;
        chunks.push(value);
        received += value.length;
        onProgress?.(received, total);
      }
    } catch (cause) {
      throw failure(`The download was interrupted: ${url}`, cause);
    }
    // The Blob takes the chunks as they are: no second contiguous copy of the file.
    return new Blob(chunks, { type });
  } finally {
    clearTimeout(stallTimer);
  }
}
