/**
 * Pose → steering tilt.
 *
 * Per pose (~30 Hz): pick the arm points (wrist, or elbow where the wrist is not seen),
 * measure the line through them on the screen as the player sees it, decide whether the
 * arms are out, blend towards the shoulder line when the arms are not usable, and feed the
 * result to a One Euro filter.
 *
 * Per simulation substep (≥ 60 Hz): extrapolate the filtered value along its last slope,
 * from the moment the pose became known plus `predictMs` (capped at `MAX_EXTRAPOLATE_S`,
 * and only while the arms actually move, so noise is not extrapolated), then pass it
 * through a very short first-order follow (`smoothMs`). The extrapolation cancels the wait
 * a 30 Hz sample-and-hold would otherwise add; the follow hides the small correction each
 * new pose brings. Measured end to end (see control.test.ts): ~17–23 ms at the midpoint of
 * a deliberate tilt beyond the pose latency, under 1° of drift for a still pose with 2° of
 * landmark noise (the real model on a still player is ten times quieter than that). When
 * poses stop, the tilt eases to level.
 *
 * Everything works on the screen picture: landmarks are scaled to pixels (so angles are
 * true angles on any aspect ratio) and mirrored when the view is, so "screen-right hand
 * higher" is positive in both orientations.
 */
import type { Tunables } from '../config/tunables';
import { Landmark, POSE_STRIDE, type PoseFrame } from '../core/pose';
import type { ViewTransform } from '../core/view';
import { approach, clamp, DEG, follow, smoothstep } from './math';
import { OneEuroFilter } from './oneEuro';
import type { Control } from './types';

/** Visibility at which a landmark starts to count, and where it fully counts. */
const VIS_LO = 0.35;
const VIS_HI = 0.65;
/** Arms count as out from this span (in shoulder widths); once out, until the lower one. */
const POSED_SPAN = 1.5;
const POSED_SPAN_EXIT = 1.3;
/**
 * The middle of the hands may sit this far (shoulder widths) above or below the shoulders,
 * plus a share of the span that grows with the tilt (one arm raised moves the middle).
 */
const POSED_HEIGHT_TOL = 0.8;
const POSED_HEIGHT_TILT = 0.3;
/** Seconds over which steering moves between the arms and the shoulder line. */
const SOURCE_BLEND_S = 0.15;
/** Derivative cutoff of the One Euro filter (Hz): how quickly the cutoff reacts. */
const D_CUTOFF_HZ = 2.5;
/** Arm speeds (rad/s) under this count as holding still: filter fully closed, no extrapolation. */
const SPEED_FLOOR = 0.5;
/** Extrapolation fades in between these arm speeds (rad/s), so noise is not extrapolated. */
const EXTRAPOLATE_FROM = 0.4;
const EXTRAPOLATE_FULL = 1.2;
/** Never extrapolate further than this past the newest pose (about 1.5 pose intervals). */
const MAX_EXTRAPOLATE_S = 0.05;
/** Slopes above this (rad/s) are glitches, not arms. */
const MAX_SLOPE = 10;
/** No usable pose for this long counts as lost; the tilt then eases to level. */
const STALE_S = 0.2;
const EASE_OUT_S = 0.5;
const EASE_IN_S = 0.2;
/** After this long without a usable pose, start the filter afresh. */
const RESET_S = 1;
/** Sample spacing assumed when the timestamps are useless. */
const DEFAULT_DT_S = 1 / 30;
/** Shoulder width floor (fraction of frame height) so a side-on player cannot divide by ~0. */
const MIN_SHOULDER = 0.04;

interface Point {
  x: number;
  y: number;
  /** 0..1 how much this point can be trusted. */
  w: number;
}

function point(): Point {
  return { x: 0, y: 0, w: 0 };
}

/** Line angle from `a` to `b` regardless of which is left: in [-π/2, π/2], + = right end up. */
function lineAngle(a: Point, b: Point): number {
  let dx = b.x - a.x;
  let dy = b.y - a.y;
  if (dx < 0) {
    dx = -dx;
    dy = -dy;
  }
  if (dx === 0 && dy === 0) return 0;
  return Math.atan2(-dy, dx);
}

export class ControlTracker {
  /** Published state; mutated in place. */
  readonly state: {
    tilt: number;
    source: Control['source'];
    tracked: boolean;
    posed: boolean;
    poseHold: number;
  } = { tilt: 0, source: 'none', tracked: false, posed: false, poseHold: 0 };

  private readonly filter = new OneEuroFilter();
  private manual: number | null = null;
  /** Seconds (simulation time) since the last usable pose arrived. */
  private since = Number.POSITIVE_INFINITY;
  /** 0..1: how much the tracked tilt counts (eases in on arrival, out when lost). */
  private presence = 0;
  /** Output of the short follow stage. */
  private smooth = 0;
  /** 0..1 share of the arms (vs. the shoulders) in the raw tilt. */
  private armShare = 1;
  private armSource: 'wrists' | 'elbows' = 'wrists';
  private armTilt = 0;
  private shoulderTilt = 0;
  private posedRaw = false;
  private trackedRaw = false;
  /** A pose arrived since the last frame. */
  private arrived = false;
  private lastCaptureMs = Number.NaN;
  private lastArrivalMs = Number.NaN;

  // Scratch points, reused every pose.
  private readonly lShoulder = point();
  private readonly rShoulder = point();
  private readonly lArm = point();
  private readonly rArm = point();
  private readonly elbow = point();
  // The pose being read, so the helpers below need no closure.
  private lm: Float32Array = new Float32Array(0);
  private mirrored = true;
  private width = 1;
  private height = 1;

  setManual(tilt: number | null): void {
    const value = tilt !== null && Number.isFinite(tilt) ? tilt : null;
    if (value === null && this.manual !== null) {
      // Hand back without a jump: the follow stage starts from where the keys left it.
      this.smooth = this.manual;
    }
    this.manual = value;
    if (value !== null) {
      this.state.tilt = value;
      this.state.source = 'manual';
    }
    this.publishFlags(this.since <= STALE_S);
  }

  applyPose(pose: PoseFrame | null, timeMs: number, view: ViewTransform, t: Tunables): void {
    if (!pose?.present || !pose.landmarks) {
      // Nobody in view. The staleness timer in `step` eases the tilt to level.
      this.trackedRaw = false;
      this.posedRaw = false;
      this.publishFlags(true);
      return;
    }
    this.lm = pose.landmarks;
    this.mirrored = view.mirrored;
    this.width = pose.sourceWidth > 0 ? pose.sourceWidth : 1;
    const height = pose.sourceHeight > 0 ? pose.sourceHeight : 1;
    this.height = height;

    const ls = this.read(Landmark.leftShoulder, this.lShoulder);
    const rs = this.read(Landmark.rightShoulder, this.rShoulder);
    const shoulderW = Math.min(ls.w, rs.w);
    const wristL = this.armPoint(Landmark.leftWrist, Landmark.leftElbow, this.lArm);
    const wristR = this.armPoint(Landmark.rightWrist, Landmark.rightElbow, this.rArm);
    const armW = Math.min(this.lArm.w, this.rArm.w);
    this.trackedRaw = shoulderW > 0 || armW > 0;
    if (!this.trackedRaw) {
      this.posedRaw = false;
      this.publishFlags(true);
      return;
    }

    // Arms out? Measured in shoulder widths so it does not depend on distance to camera.
    // Each source keeps its last good angle so that blending away from it is gradual.
    if (armW > 0) this.armTilt = lineAngle(this.lArm, this.rArm);
    if (shoulderW > 0) this.shoulderTilt = lineAngle(ls, rs);
    const armTilt = this.armTilt;
    let armTarget = armW;
    let posed = false;
    if (shoulderW > 0 && armW > 0) {
      const sw = Math.max(Math.hypot(rs.x - ls.x, rs.y - ls.y), MIN_SHOULDER * height);
      const span = Math.hypot(this.rArm.x - this.lArm.x, this.rArm.y - this.lArm.y) / sw;
      const dev = Math.abs((this.lArm.y + this.rArm.y - ls.y - rs.y) * 0.5) / sw;
      const tol = POSED_HEIGHT_TOL + POSED_HEIGHT_TILT * span * Math.abs(Math.sin(armTilt));
      const minSpan = this.posedRaw ? POSED_SPAN_EXIT : POSED_SPAN;
      const maxDev = this.posedRaw ? tol * 1.2 : tol;
      posed = armW >= 0.5 && shoulderW >= 0.5 && span >= minSpan && dev <= maxDev;
      // Steering trusts the arms as far as they are out; dropped arms hand over to the
      // shoulders, which a standing player holds level.
      armTarget = armW * smoothstep(1, 1.4, span) * (1 - smoothstep(tol, tol + 0.6, dev));
    } else if (shoulderW <= 0) {
      armTarget = 1;
    } else {
      armTarget = 0;
    }
    this.posedRaw = posed;
    this.publishFlags(true);
    this.armSource = wristL && wristR ? 'wrists' : 'elbows';

    // Sample spacing: capture times are the truth; arrival times are a fallback.
    const capture = pose.captureTimeMs;
    let dt = (capture - this.lastCaptureMs) / 1000;
    if (!(dt > 0 && dt <= 0.5)) dt = (timeMs - this.lastArrivalMs) / 1000;
    if (!(dt > 0 && dt <= 0.5)) dt = DEFAULT_DT_S;
    this.lastCaptureMs = Number.isFinite(capture) ? capture : Number.NaN;
    this.lastArrivalMs = Number.isFinite(timeMs) ? timeMs : Number.NaN;

    if (this.since > RESET_S) this.filter.reset();
    this.armShare = this.filter.ready
      ? approach(this.armShare, armTarget, dt / SOURCE_BLEND_S)
      : armTarget;
    const shoulderTilt = this.shoulderTilt * t.shoulderGain;
    const raw = this.armShare * armTilt + (1 - this.armShare) * shoulderTilt;
    if (!Number.isFinite(raw)) return;
    this.filter.update(
      clamp(raw, -Math.PI / 2, Math.PI / 2),
      dt,
      t.filterMinCutoff,
      t.filterBeta,
      D_CUTOFF_HZ,
      SPEED_FLOOR,
    );
    this.since = 0;
    this.arrived = true;
  }

  /**
   * Call once per frame before the substeps. A pose applied this frame became known "now",
   * at the end of the frame, so the frame's substeps start `frameS` before it. Without this
   * the extrapolation would run one frame ahead, more at 30 Hz than at 144 Hz.
   */
  beginFrame(frameS: number): void {
    if (this.arrived) this.since = -frameS;
    this.arrived = false;
  }

  /** Advance the between-pose stages by `dtS` and publish `state.tilt`. */
  step(dtS: number, t: Tunables): void {
    const { state } = this;
    this.since += dtS;
    const fresh = this.since <= STALE_S;

    this.presence = approach(this.presence, fresh ? 1 : 0, dtS / (fresh ? EASE_IN_S : EASE_OUT_S));
    this.publishFlags(fresh);
    if (this.manual !== null) {
      state.tilt = this.manual;
      state.source = 'manual';
      return;
    }
    let target = 0;
    if (this.filter.ready) {
      const ahead = clamp(this.since + t.predictMs / 1000, 0, MAX_EXTRAPOLATE_S);
      const gate = smoothstep(EXTRAPOLATE_FROM, EXTRAPOLATE_FULL, Math.abs(this.filter.speed));
      target = this.filter.value + clamp(this.filter.slope, -MAX_SLOPE, MAX_SLOPE) * ahead * gate;
    }
    this.smooth += (target - this.smooth) * follow(dtS, t.smoothMs / 1000);
    const presence = smoothstep(0, 1, this.presence);
    state.tilt = this.smooth * presence;
    state.source = !fresh ? 'none' : this.armShare >= 0.5 ? this.armSource : 'shoulders';
  }

  /** `tracked` follows the camera alone; the keyboard counts as posed. */
  private publishFlags(fresh: boolean): void {
    const { state } = this;
    state.tracked = fresh && this.trackedRaw;
    state.posed = this.manual !== null || (fresh && this.posedRaw);
  }

  /**
   * Board angle the player asks for: dead zone, then a soft limit. Small tilts map with
   * `tiltGain` (precise); big ones saturate smoothly towards `limitDeg` (tanh), so wild
   * arms ask for a steep board but not an extreme one, and there is no hard stop to feel.
   */
  command(t: Tunables, limitDeg: number): number {
    const tilt = this.state.tilt;
    const limit = Math.max(1, limitDeg) * DEG;
    const mag = Math.max(0, Math.abs(tilt) - t.tiltDeadzone * DEG) * t.tiltGain;
    return Math.sign(tilt) * limit * Math.tanh(mag / limit);
  }

  /** Landmark `index` in screen-oriented source pixels, with its trust in `w`. */
  private read(index: number, out: Point): Point {
    const o = index * POSE_STRIDE;
    const lm = this.lm;
    const x = lm[o];
    const y = lm[o + 1];
    const v = lm[o + 3];
    if (
      x === undefined ||
      y === undefined ||
      v === undefined ||
      !Number.isFinite(x) ||
      !Number.isFinite(y) ||
      !Number.isFinite(v)
    ) {
      out.w = 0;
      return out;
    }
    out.x = (this.mirrored ? 1 - x : x) * this.width;
    out.y = y * this.height;
    out.w = smoothstep(VIS_LO, VIS_HI, v);
    return out;
  }

  /**
   * Writes the wrist (or, where the wrist is not seen, the elbow) of one arm into `out`,
   * blending the two by the wrist's visibility. Returns whether the wrist dominates.
   */
  private armPoint(wristIndex: number, elbowIndex: number, out: Point): boolean {
    this.read(wristIndex, out);
    const elbow = this.read(elbowIndex, this.elbow);
    const ww = out.w;
    const we = elbow.w * (1 - ww);
    const total = ww + we;
    if (total <= 0) {
      out.w = 0;
      return false;
    }
    if (we > 0) {
      out.x = (out.x * ww + elbow.x * we) / total;
      out.y = (out.y * ww + elbow.y * we) / total;
    }
    out.w = Math.max(ww, elbow.w);
    return ww >= 0.5;
  }
}
