/**
 * The wake: the white line the board carves into the face, left behind on the water.
 *
 * A strip mesh through the board's recent positions. Each point remembers its age and how
 * hard the board was working when it was laid down, so the trail is wide and bright where
 * the rider carved or went fast, spreads and breaks up as it ages, and flows away with the
 * water. The texture runs along the strip by age (u = 0 fresh, 1 gone), not by length, so
 * the fade always takes the same time whatever the speed.
 *
 * A break in the trail (a jump, a new ride) is a pair of zero-width points, so the old and
 * new trails are never joined by a line across the face. Nothing is allocated per frame.
 */
import { Mesh, MeshGeometry, type Texture } from 'pixi.js';

/** Points in the trail; one is laid down every frame up to this rate. */
const POINTS = 64;
const STEP_S = 1 / 60;
/** Seconds a point lasts. */
export const WAKE_LIFE_S = 1.05;
/** A point this close to the newest one is not worth a new sample. */
const MIN_STEP = 2;

export class WakeTrail {
  readonly view: Mesh<MeshGeometry>;
  private readonly geometry: MeshGeometry;
  private readonly x = new Float32Array(POINTS);
  private readonly y = new Float32Array(POINTS);
  private readonly age = new Float32Array(POINTS);
  /** Width when laid down, world units; 0 marks a break. */
  private readonly width = new Float32Array(POINTS);
  private count = 0;
  private clock = 0;
  private broken = true;

  constructor(texture: Texture) {
    const indices = new Uint32Array((POINTS - 1) * 6);
    for (let i = 0; i < POINTS - 1; i++) {
      const a = i * 2;
      indices.set([a, a + 1, a + 2, a + 1, a + 3, a + 2], i * 6);
    }
    this.geometry = new MeshGeometry({
      positions: new Float32Array(POINTS * 4),
      uvs: new Float32Array(POINTS * 4),
      indices,
    });
    this.view = new Mesh({ geometry: this.geometry, texture, label: 'wake' });
    this.view.visible = false;
  }

  /** The next point laid down starts a new trail. */
  cut(): void {
    this.broken = true;
  }

  clear(): void {
    this.count = 0;
    this.broken = true;
    this.view.visible = false;
  }

  /**
   * Advance by `dtS`: points flow left by `flow` (world units) and age; while `onWater`
   * the board lays the trail at (x, y) with `width`.
   */
  update(dtS: number, flow: number, onWater: boolean, x: number, y: number, width: number) {
    const n = this.count;
    for (let i = 0; i < n; i++) {
      this.x[i] = (this.x[i] as number) - flow;
      this.age[i] = (this.age[i] as number) + dtS;
    }
    // Drop points that have faded out.
    while (this.count > 0 && (this.age[this.count - 1] as number) >= WAKE_LIFE_S) this.count--;

    this.clock += dtS;
    if (onWater) {
      if (this.broken) {
        // Zero width where the old trail ends and where the new one starts.
        if (this.count > 0) this.width[0] = 0;
        this.push(x, y, 0);
        this.push(x, y, width);
        this.broken = false;
      }
      const far = Math.hypot((this.x[0] as number) - x, (this.y[0] as number) - y) > MIN_STEP;
      if (this.clock >= STEP_S && far) {
        this.clock = 0;
        this.push(x, y, width);
      } else {
        // The newest point follows the board between samples.
        this.x[0] = x;
        this.y[0] = y;
        this.age[0] = 0;
        this.width[0] = width;
      }
    } else {
      this.broken = true;
    }
    this.build();
  }

  private push(x: number, y: number, width: number): void {
    this.x.copyWithin(1, 0, POINTS - 1);
    this.y.copyWithin(1, 0, POINTS - 1);
    this.age.copyWithin(1, 0, POINTS - 1);
    this.width.copyWithin(1, 0, POINTS - 1);
    this.x[0] = x;
    this.y[0] = y;
    this.age[0] = 0;
    this.width[0] = width;
    this.count = Math.min(POINTS, this.count + 1);
  }

  private build(): void {
    const n = this.count;
    this.view.visible = n >= 3;
    if (!this.view.visible) return;
    const positions = this.geometry.positions;
    const uvs = this.geometry.uvs;
    let lastX = 0;
    let lastY = 0;
    for (let i = 0; i < POINTS; i++) {
      const o = i * 4;
      if (i >= n) {
        // Unused points collapse onto the last one: zero-area triangles.
        positions[o] = lastX;
        positions[o + 1] = lastY;
        positions[o + 2] = lastX;
        positions[o + 3] = lastY;
        uvs[o] = 1;
        uvs[o + 1] = 0;
        uvs[o + 2] = 1;
        uvs[o + 3] = 1;
        continue;
      }
      const px = this.x[i] as number;
      const py = this.y[i] as number;
      // Direction from the neighbours on both sides, for a smooth edge round turns.
      const a = Math.max(0, i - 1);
      const b = Math.min(n - 1, i + 1);
      let dx = (this.x[a] as number) - (this.x[b] as number);
      let dy = (this.y[a] as number) - (this.y[b] as number);
      const len = Math.hypot(dx, dy) || 1;
      dx /= len;
      dy /= len;
      const t = (this.age[i] as number) / WAKE_LIFE_S;
      // It spreads as it ages; it starts at a point under the board.
      const grow = Math.min(1, i / 3);
      const half = 0.5 * (this.width[i] as number) * (0.7 + 1.5 * t) * grow;
      positions[o] = px - dy * half;
      positions[o + 1] = py + dx * half;
      positions[o + 2] = px + dy * half;
      positions[o + 3] = py - dx * half;
      uvs[o] = t;
      uvs[o + 1] = 0;
      uvs[o + 2] = t;
      uvs[o + 3] = 1;
      lastX = px;
      lastY = py;
    }
    this.geometry.getBuffer('aPosition').update();
    this.geometry.getBuffer('aUV').update();
  }

  dispose(): void {
    this.view.destroy();
    this.geometry.destroy();
  }
}
