/**
 * Frame scheduling between a source and the segmenter: which frames get segmented, who
 * owns each VideoFrame, and which results may still be delivered.
 *
 * - At most one frame is in flight. A frame that arrives meanwhile waits in a single
 *   pending slot, where a newer frame replaces (and closes) it, so at most two frames are
 *   open. With pairing on, a clone of the in-flight frame and the untaken pair's frame are
 *   held as well; clones share the original's pixels.
 * - `bumpEpoch()` (pause, source switch, dispose) invalidates everything captured before
 *   it: the pending frame is closed, an untaken mask or pair is discarded, and the
 *   in-flight result is dropped when it arrives.
 * - It never decides that the segmenter is broken; a failed frame is just dropped. Recovery
 *   is `ResilientSegmenter`'s job.
 * - The segmenter reports each frame's pose before its mask. The pose is made available to
 *   `takePose` at once, under the same epoch rule, and travels with the mask into the pair.
 *   Each frame goes in with when the next one is expected, so the segmenter can skip a mask
 *   that would hold the next pose back; such a frame settles with its pose and no mask.
 *
 * Pure (no DOM), so it is unit-tested with fake frames and a fake segmenter.
 */
import type { PersonMask } from '../core/mask';
import type { PoseFrame } from '../core/pose';
import { RateMeter, RollingPercentiles } from './stats';
import type {
  FramePair,
  FrameTick,
  FrameTrace,
  PoseResult,
  SegmentJob,
  SegmentResult,
  VisionStats,
} from './types';

export interface FrameSink {
  /**
   * Takes ownership of `frame` and closes it; always settles, with null for a skipped mask.
   * Reports the pose through `job`.
   */
  segment(frame: VideoFrame, job: SegmentJob): Promise<SegmentResult | null>;
  /** Takes back the buffer of a mask that was never handed out, for reuse. */
  recycle?(data: Uint8Array): void;
}

export function createStats(): VisionStats {
  return {
    cameraFps: 0,
    maskFps: 0,
    inferMsP50: 0,
    inferMsP95: 0,
    maskAgeMs: 0,
    openFrames: 0,
    droppedFrames: 0,
    restarts: 0,
    masksDelivered: 0,
    regionsPerFrame: 0,
    poseFps: 0,
    poseMsP50: 0,
    poseMsP95: 0,
    poseAgeMs: 0,
  };
}

/** Traces kept while tracing: about 17 s at 30 fps. */
const TRACE_SIZE = 512;

function newTrace(seq: number, captureMs: number, tickMs: number): FrameTrace {
  return {
    seq,
    captureMs,
    tickMs,
    sentMs: Number.NaN,
    receivedMs: Number.NaN,
    poseStartMs: Number.NaN,
    poseEndMs: Number.NaN,
    poseArrivedMs: Number.NaN,
    poseTakenMs: Number.NaN,
    segStartMs: Number.NaN,
    segEndMs: Number.NaN,
    maskArrivedMs: Number.NaN,
  };
}

/** A frame plus what the mask computed from it needs to know. Reused, never reallocated. */
interface Slot {
  frame: VideoFrame | null;
  seq: number;
  captureTimeMs: number;
  sourceWidth: number;
  sourceHeight: number;
  epoch: number;
  /** The frame does not follow on from the one before (see `FrameTick.discontinuity`). */
  fresh: boolean;
  /** Pairing: a clone of `frame`, kept for `takePair`. */
  pairImage: VideoFrame | null;
  /** In flight: the pose already reported for this frame. */
  pose: PoseFrame | null;
}

function emptySlot(): Slot {
  return {
    frame: null,
    seq: 0,
    captureTimeMs: 0,
    sourceWidth: 0,
    sourceHeight: 0,
    epoch: 0,
    fresh: false,
    pairImage: null,
    pose: null,
  };
}

export class FrameScheduler {
  /** Grab and segment frames only while true (running, not paused or failed). */
  accepting = false;
  /** Frames whose segmentation failed. Not part of `VisionStats`; used by tests and logs. */
  failedFrames = 0;
  /** Passed with every frame: see `SegmentJob.poseWaitFrames`. */
  maskPoseWait = 0.5;

  private epoch = 0;
  private seq = 0;
  /** When the newest source frame arrived. */
  private lastTickMs = Number.NaN;
  private busy = false;
  /**
   * The next frame submitted starts the pose tracker over: what it saw before an epoch
   * change (another source, a pause) says nothing about where the person is now.
   */
  private restartTracking = false;
  private readonly flight = emptySlot();
  private readonly waiting = emptySlot();
  private latest: PersonMask | null = null;
  private latestPose: PoseFrame | null = null;
  /** `latest` has been handed out through `takePair`, so its buffer must not be reused. */
  private latestExposed = false;
  private pair: FramePair | null = null;
  private pairing = false;
  private disposed = false;
  private readonly cameraRate = new RateMeter();
  private readonly maskRate = new RateMeter();
  private readonly inferMs = new RollingPercentiles();
  private readonly poseRate = new RateMeter();
  private readonly poseMs = new RollingPercentiles();
  /** Ring of traces by `seq % TRACE_SIZE`, while tracing. */
  private traces: FrameTrace[] | null = null;

  constructor(
    private readonly sink: FrameSink,
    /** Updated in place. */
    readonly stats: VisionStats,
    private readonly now: () => number = () => performance.now(),
    /** Called with every delivered mask, after it has become available to `takeMask`. */
    private readonly onMask?: (mask: PersonMask) => void,
  ) {}

  /** Source frame handler. */
  onTick(tick: FrameTick): void {
    const { stats } = this;
    const seq = ++this.seq;
    this.cameraRate.record(tick.captureTimeMs);
    stats.cameraFps = this.cameraRate.rate(tick.captureTimeMs);
    // Refreshed here too, so the readings fall when results stop while frames keep coming.
    const now = this.now();
    stats.maskFps = this.maskRate.rate(now);
    stats.poseFps = this.poseRate.rate(now);
    this.lastTickMs = now;
    if (!this.accepting || this.disposed) return;
    if (this.traces) this.traces[seq % TRACE_SIZE] = newTrace(seq, tick.captureTimeMs, now);

    const slot = this.busy ? this.waiting : this.flight;
    // A discontinuity on a frame that is dropped still applies to the one replacing it.
    const fresh = Boolean(tick.discontinuity) || (slot.frame !== null && slot.fresh);
    if (slot.frame) {
      // Newest wins: the waiting frame will never be segmented. Closed before the grab so
      // that not even momentarily are three frames open.
      slot.frame.close();
      slot.frame = null;
      stats.openFrames--;
      stats.droppedFrames++;
    }
    let frame: VideoFrame;
    try {
      frame = tick.grab();
    } catch {
      // E.g. a clip with no current frame while it seeks back to the start.
      stats.droppedFrames++;
      return;
    }
    stats.openFrames++;
    slot.frame = frame;
    slot.seq = seq;
    slot.captureTimeMs = tick.captureTimeMs;
    slot.sourceWidth = frame.displayWidth;
    slot.sourceHeight = frame.displayHeight;
    slot.epoch = this.epoch;
    slot.fresh = fresh;
    if (!this.busy) this.submit();
  }

  /** Invalidate everything captured so far (pause, source switch). */
  bumpEpoch(): void {
    this.epoch++;
    const { waiting, stats } = this;
    if (waiting.frame) {
      waiting.frame.close();
      waiting.frame = null;
      stats.openFrames--;
      stats.droppedFrames++;
    }
    this.dropPair();
    this.dropLatest();
    this.latestPose = null;
    this.restartTracking = true;
    this.cameraRate.reset();
    this.lastTickMs = Number.NaN;
    this.maskRate.reset();
    this.poseRate.reset();
    stats.cameraFps = 0;
    stats.maskFps = 0;
    stats.poseFps = 0;
  }

  /** Forget inference timings, e.g. after the segmenter backend changed. */
  resetTimings(): void {
    this.inferMs.reset();
    this.poseMs.reset();
  }

  /** The newest pose not taken yet. It arrives before the mask of the same frame. */
  takePose(): PoseFrame | null {
    const pose = this.latestPose;
    this.latestPose = null;
    if (pose) {
      const trace = this.traceOf(pose.seq);
      if (trace) trace.poseTakenMs = this.now();
    }
    return pose;
  }

  setTracing(enabled: boolean): void {
    if (enabled === (this.traces !== null)) return;
    this.traces = enabled ? [] : null;
  }

  readTrace(): FrameTrace[] {
    const traces = this.traces ? this.traces.filter(Boolean).map((t) => ({ ...t })) : [];
    return traces.sort((a, b) => a.seq - b.seq);
  }

  private traceOf(seq: number): FrameTrace | null {
    const trace = this.traces?.[seq % TRACE_SIZE];
    return trace && trace.seq === seq ? trace : null;
  }

  takeMask(): PersonMask | null {
    const mask = this.latest;
    this.latest = null;
    this.latestExposed = false;
    return mask;
  }

  setPairing(enabled: boolean): void {
    this.pairing = enabled;
    // A clone already in flight is closed when its result arrives.
    if (!enabled) this.dropPair();
  }

  takePair(): FramePair | null {
    const { pair } = this;
    if (!pair) return null;
    this.pair = null;
    this.stats.openFrames--;
    if (pair.mask === this.latest) this.latestExposed = true;
    return pair;
  }

  /** Stop for good. A frame still in flight is closed and its result dropped when it settles. */
  dispose(): void {
    this.accepting = false;
    this.pairing = false;
    this.bumpEpoch();
    this.disposed = true;
  }

  private submit(): void {
    const { flight, stats } = this;
    const frame = flight.frame;
    if (!frame) return;
    this.busy = true;
    flight.pairImage = null;
    flight.pose = null;
    const fresh = flight.fresh || this.restartTracking;
    this.restartTracking = false;
    flight.fresh = fresh;
    if (this.pairing) {
      try {
        flight.pairImage = frame.clone();
        stats.openFrames++;
      } catch {
        // Pairing is a debug aid; the mask still goes through.
      }
    }
    const seq = flight.seq;
    const trace = this.traceOf(seq);
    if (trace) trace.sentMs = this.now();
    const fps = stats.cameraFps;
    const job: SegmentJob = {
      fresh,
      nextFrameInMs: this.nextFrameInMs(),
      frameIntervalMs: fps > 0 ? 1000 / fps : Number.POSITIVE_INFINITY,
      poseWaitFrames: this.maskPoseWait,
      onPose: (pose) => this.acceptPose(seq, pose),
    };
    let result: Promise<SegmentResult | null>;
    try {
      result = this.sink.segment(frame, job);
    } catch (error) {
      result = Promise.reject(error);
    }
    result.then(this.onResult, this.onFailure);
  }

  /** When the source's next frame should arrive, from now; Infinity before the rate is known. */
  private nextFrameInMs(): number {
    const fps = this.stats.cameraFps;
    if (!(fps > 0) || !Number.isFinite(this.lastTickMs)) return Number.POSITIVE_INFINITY;
    return Math.max(0, this.lastTickMs + 1000 / fps - this.now());
  }

  private readonly onResult = (result: SegmentResult | null): void => {
    const { flight } = this;
    const pairImage = this.settleFlight();
    if (!result) {
      // The pose went out; the mask was skipped to keep the next pose on time.
      this.closeFrame(pairImage);
    } else if (flight.epoch === this.epoch) {
      this.deliver(result, pairImage);
    } else {
      this.sink.recycle?.(result.data);
      this.closeFrame(pairImage);
    }
    this.next();
  };

  private readonly onFailure = (): void => {
    // A frame that failed may never have reached the tracker, so the next one restarts it.
    if (this.flight.fresh) this.restartTracking = true;
    this.closeFrame(this.settleFlight());
    this.failedFrames++;
    this.next();
  };

  /** The segmenter's report of the in-flight frame's pose. */
  private acceptPose(seq: number, result: PoseResult): void {
    const { flight, stats } = this;
    // Late (the frame has settled), stale (captured before an epoch change), or a repeat.
    if (!this.busy || flight.seq !== seq || flight.epoch !== this.epoch || flight.pose) return;
    if (this.disposed) return;
    const now = this.now();
    // A new object per pose: consumers may keep poses across frames.
    const pose: PoseFrame = {
      landmarks: result.landmarks,
      present: result.present,
      seq,
      captureTimeMs: flight.captureTimeMs,
      sourceWidth: flight.sourceWidth,
      sourceHeight: flight.sourceHeight,
    };
    flight.pose = pose;
    this.latestPose = pose;
    this.poseRate.record(now);
    stats.poseFps = this.poseRate.rate(now);
    this.poseMs.add(result.poseMs);
    stats.poseMsP50 = this.poseMs.percentile(0.5);
    stats.poseMsP95 = this.poseMs.percentile(0.95);
    stats.poseAgeMs = now - flight.captureTimeMs;
    const trace = this.traceOf(seq);
    if (trace) {
      trace.receivedMs = result.receivedMs ?? Number.NaN;
      trace.poseStartMs = result.startMs ?? Number.NaN;
      trace.poseEndMs = result.endMs ?? Number.NaN;
      trace.poseArrivedMs = now;
    }
  }

  /** Release the in-flight frame (the sink has closed it) and return its pairing clone. */
  private settleFlight(): VideoFrame | null {
    const { flight } = this;
    // The sink owns the frame and has closed it; closing again is a harmless safety net.
    flight.frame?.close();
    flight.frame = null;
    this.stats.openFrames--;
    const pairImage = flight.pairImage;
    flight.pairImage = null;
    this.busy = false;
    return pairImage;
  }

  /** Move the pending frame, if any, into flight. */
  private next(): void {
    const { flight, waiting } = this;
    if (!waiting.frame || this.disposed) return;
    flight.frame = waiting.frame;
    flight.seq = waiting.seq;
    flight.captureTimeMs = waiting.captureTimeMs;
    flight.sourceWidth = waiting.sourceWidth;
    flight.sourceHeight = waiting.sourceHeight;
    flight.epoch = waiting.epoch;
    flight.fresh = waiting.fresh;
    waiting.frame = null;
    waiting.fresh = false;
    this.submit();
  }

  private deliver(result: SegmentResult, pairImage: VideoFrame | null): void {
    const { flight, stats } = this;
    const now = this.now();
    // A new object per mask: consumers may keep masks across frames.
    const mask: PersonMask = {
      data: result.data,
      width: result.width,
      height: result.height,
      seq: flight.seq,
      captureTimeMs: flight.captureTimeMs,
      sourceWidth: flight.sourceWidth,
      sourceHeight: flight.sourceHeight,
    };

    if (pairImage) {
      if (this.pairing) {
        this.dropPair();
        // The pose of this very frame: `flight` still describes it.
        this.pair = { image: pairImage, mask, pose: flight.pose };
      } else {
        this.closeFrame(pairImage);
      }
    }
    this.dropLatest();
    this.latest = mask;

    stats.masksDelivered++;
    stats.regionsPerFrame = result.regions;
    this.maskRate.record(now);
    stats.maskFps = this.maskRate.rate(now);
    this.inferMs.add(result.inferMs);
    stats.inferMsP50 = this.inferMs.percentile(0.5);
    stats.inferMsP95 = this.inferMs.percentile(0.95);
    stats.maskAgeMs = now - flight.captureTimeMs;
    const trace = this.traceOf(flight.seq);
    if (trace) {
      trace.segStartMs = result.startMs ?? Number.NaN;
      trace.segEndMs = result.endMs ?? Number.NaN;
      trace.maskArrivedMs = now;
    }
    this.onMask?.(mask);
  }

  /** Discard an untaken mask, reusing its buffer when nobody has seen it. */
  private dropLatest(): void {
    const { latest } = this;
    if (latest && !this.latestExposed && this.pair?.mask !== latest) {
      this.sink.recycle?.(latest.data);
    }
    this.latest = null;
    this.latestExposed = false;
  }

  private dropPair(): void {
    if (!this.pair) return;
    this.closeFrame(this.pair.image);
    this.pair = null;
  }

  private closeFrame(frame: VideoFrame | null): void {
    if (!frame) return;
    frame.close();
    this.stats.openFrames--;
  }
}
