/**
 * Absolute URLs of files served from `public/`.
 *
 * Always resolve these here, on the main thread, and pass the results to the worker:
 * with a relative Vite base, `import.meta.env.BASE_URL` is `./` in the build, which inside
 * a worker would resolve against `assets/` instead of the page. MediaPipe also needs an
 * absolute WASM base (a root-relative one is rejected by the Vite dev server).
 */
export interface AssetUrls {
  /** Directory holding the MediaPipe WASM files. No trailing slash. */
  wasmBaseUrl: string;
  /** Segmentation model. */
  modelUrl: string;
  /** Pose landmarker model (lite: the full one costs more and was no steadier). */
  poseModelUrl: string;
  musicUrl: string;
}

export function resolveAssetUrls(): AssetUrls {
  const base = new URL(import.meta.env.BASE_URL, document.baseURI);
  return {
    wasmBaseUrl: new URL('mediapipe/wasm', base).href.replace(/\/$/, ''),
    modelUrl: new URL('models/selfie_multiclass_256x256.tflite', base).href,
    poseModelUrl: new URL('models/pose_landmarker_lite.task', base).href,
    musicUrl: new URL('audio/surf-shimmy.ogg', base).href,
  };
}
