/**
 * Things on the face that are not to be collected: boost strips to ride over, and the two
 * hazards to avoid. The colour language is the game's: warm gold means good (the
 * creatures, the boost strips), a dark swirl or red-and-white means keep away. Hazards have
 * no faces; things worth grabbing do.
 *
 * Like the pickups, sprites come from fixed pools matched to the game's objects by id each
 * frame, so nothing is allocated while riding. Every field the game added for these is
 * read defensively: a game without them simply shows none.
 */
import { Container, Sprite, type Texture } from 'pixi.js';
import type { BoostStrip, Hazard } from '../game/types';
import type { StageTextures } from './textures';

const POOL = 8;
/** Stands in for a missing list, so a game without hazards allocates nothing per frame. */
const NONE: readonly never[] = [];
/** Seconds a new item takes to appear. */
const APPEAR_S = 0.35;

interface Slot {
  id: number;
  age: number;
  seen: boolean;
}

/** Find the slot showing `id`, or claim a free one for it. */
function slotFor<T extends Slot>(pool: T[], id: number): T | null {
  let free: T | null = null;
  for (const slot of pool) {
    if (slot.id === id) return slot;
    if (!free && slot.id === -1) free = slot;
  }
  if (free) {
    free.id = id;
    free.age = 0;
  }
  return free;
}

interface Whirl extends Slot {
  root: Container;
  funnel: Sprite;
  arms: Sprite;
  outer: Sprite;
  spin: number;
}

interface Buoy extends Slot {
  root: Container;
  body: Sprite;
  collar: Sprite;
  /** Rocking after a bonk: a damped spring. */
  rock: number;
  rockV: number;
  phase: number;
}

export class HazardView {
  /** Whirlpools, on the face under everything else. */
  readonly whirls = new Container();
  /** Buoys, floating: drawn just under the surfer. */
  readonly buoys = new Container();
  private readonly whirlPool: Whirl[] = [];
  private readonly buoyPool: Buoy[] = [];
  private timeS = 0;
  /** The strongest grip any whirlpool has on the board right now (for the wobble). */
  grip = 0;

  constructor(textures: StageTextures) {
    for (let i = 0; i < POOL; i++) {
      const root = new Container();
      const funnel = centred(textures.whirlpool);
      const outer = centred(textures.whirlArms);
      outer.alpha = 0.45;
      const arms = centred(textures.whirlArms);
      root.addChild(funnel, outer, arms);
      root.visible = false;
      this.whirls.addChild(root);
      this.whirlPool.push({ id: -1, age: 0, seen: false, root, funnel, arms, outer, spin: i });

      const buoyRoot = new Container();
      const collar = centred(textures.shadow);
      collar.tint = 0xffffff;
      const body = new Sprite(textures.buoy);
      body.anchor.set(0.5, (192 - 30) / 192);
      buoyRoot.addChild(collar, body);
      buoyRoot.visible = false;
      this.buoys.addChild(buoyRoot);
      this.buoyPool.push({
        id: -1,
        age: 0,
        seen: false,
        root: buoyRoot,
        body,
        collar,
        rock: 0,
        rockV: 0,
        phase: i * 2.3,
      });
    }
  }

  /** A buoy was hit: set it rocking. */
  bonk(id: number, fromLeft: boolean): void {
    for (const buoy of this.buoyPool) {
      if (buoy.id === id) buoy.rockV += (fromLeft ? 1 : -1) * 9;
    }
  }

  update(hazards: readonly Hazard[] | undefined, dtS: number): void {
    this.timeS += dtS;
    for (const slot of this.whirlPool) slot.seen = false;
    for (const slot of this.buoyPool) slot.seen = false;
    let grip = 0;
    for (const hazard of hazards ?? NONE) {
      if (hazard.kind === 'buoy') this.showBuoy(hazard, dtS);
      else {
        this.showWhirl(hazard, dtS);
        grip = Math.max(grip, hazard.grip || 0);
      }
    }
    this.grip = grip;
    for (const slot of this.whirlPool) {
      if (!slot.seen && slot.id !== -1) {
        slot.id = -1;
        slot.root.visible = false;
      }
    }
    for (const slot of this.buoyPool) {
      if (!slot.seen && slot.id !== -1) {
        slot.id = -1;
        slot.root.visible = false;
      }
    }
  }

  private showWhirl(hazard: Hazard, dtS: number): void {
    const slot = slotFor(this.whirlPool, hazard.id);
    if (!slot) return;
    slot.seen = true;
    slot.age += dtS;
    const grip = Math.max(0, Math.min(1, hazard.grip || 0));
    const pop = smoothstep(0, APPEAR_S, slot.age);
    // Spins faster, and pulls in tighter, while it has hold of the board.
    slot.spin += dtS * (1.8 + 6 * grip);
    const r = hazard.r;
    const pulse = 1 + 0.06 * Math.sin(this.timeS * 5) + 0.12 * grip * Math.sin(this.timeS * 14);
    const root = slot.root;
    root.visible = true;
    root.position.set(hazard.x, hazard.y);
    // Seen almost face on, a little foreshortened down the slope.
    root.scale.set(pop * pulse, pop * pulse * 0.88);
    slot.funnel.scale.set((3 * r) / 256);
    slot.funnel.alpha = 0.85 + 0.15 * grip;
    slot.arms.scale.set((2.8 * r) / 256);
    slot.arms.rotation = -slot.spin;
    slot.outer.scale.set((3.5 * r) / 256);
    slot.outer.rotation = -slot.spin * 0.55 + 1;
    slot.outer.alpha = 0.35 + 0.3 * grip;
  }

  private showBuoy(hazard: Hazard, dtS: number): void {
    const slot = slotFor(this.buoyPool, hazard.id);
    if (!slot) return;
    slot.seen = true;
    slot.age += dtS;
    const pop = smoothstep(0, APPEAR_S, slot.age);
    const w = 2 * Math.PI * 1.4;
    slot.rockV += (-w * w * slot.rock - 2 * 0.25 * w * slot.rockV) * dtS;
    slot.rock += slot.rockV * dtS;
    const t = this.timeS + slot.phase;
    const r = hazard.r;
    const root = slot.root;
    root.visible = true;
    root.position.set(hazard.x, hazard.y + 5 * Math.sin(t * 2.2));
    root.scale.set(pop);
    // The buoy art is 96 units tall; it stands about 3.2 radii out of the water.
    slot.body.scale.set((3.2 * r) / 96);
    slot.body.rotation = 0.07 * Math.sin(t * 1.7) + Math.max(-0.6, Math.min(0.6, slot.rock));
    slot.collar.scale.set((2.6 * r) / 256, 0.7);
    slot.collar.alpha = 0.55;
  }

  clear(): void {
    for (const slot of this.whirlPool) {
      slot.id = -1;
      slot.root.visible = false;
    }
    for (const slot of this.buoyPool) {
      slot.id = -1;
      slot.root.visible = false;
    }
    this.grip = 0;
  }

  dispose(): void {
    this.whirls.destroy({ children: true });
    this.buoys.destroy({ children: true });
  }
}

interface Strip extends Slot {
  root: Container;
  glow: Sprite;
  chevrons: Sprite[];
}

/** Height of a boost strip on the face, world units, and the most chevrons in one. */
const STRIP_HEIGHT = 54;
const CHEVRONS = 7;
/** A chevron every this many units along the strip. */
const CHEVRON_GAP = 62;

/**
 * Boost strips: lanes of glowing chevrons painted on the face, all pointing right, lit in
 * turn from left to right like runway lights: an obvious "this way, faster".
 */
export class BoostView {
  readonly container = new Container();
  private readonly pool: Strip[] = [];
  private timeS = 0;

  constructor(textures: StageTextures) {
    for (let i = 0; i < POOL; i++) {
      const root = new Container();
      const glow = centred(textures.glow);
      glow.blendMode = 'add';
      glow.tint = 0xffd23f;
      root.addChild(glow);
      const chevrons: Sprite[] = [];
      for (let k = 0; k < CHEVRONS; k++) {
        const chevron = centred(textures.chevron);
        chevron.scale.set(STRIP_HEIGHT / 80);
        chevrons.push(chevron);
        root.addChild(chevron);
      }
      root.visible = false;
      this.container.addChild(root);
      this.pool.push({ id: -1, age: 0, seen: false, root, glow, chevrons });
    }
  }

  update(strips: readonly BoostStrip[] | undefined, dtS: number): void {
    this.timeS += dtS;
    for (const slot of this.pool) slot.seen = false;
    for (const strip of strips ?? NONE) {
      const slot = slotFor(this.pool, strip.id);
      if (!slot) continue;
      slot.seen = true;
      slot.age += dtS;
      const pop = smoothstep(0, APPEAR_S, slot.age);
      const length = 2 * strip.r;
      const root = slot.root;
      root.visible = true;
      root.position.set(strip.x, strip.y);
      root.alpha = pop;
      const count = Math.max(2, Math.min(CHEVRONS, Math.round(length / CHEVRON_GAP)));
      const span = (count - 1) * CHEVRON_GAP;
      for (let k = 0; k < CHEVRONS; k++) {
        const chevron = slot.chevrons[k] as Sprite;
        chevron.visible = k < count;
        if (!chevron.visible) continue;
        chevron.x = -span / 2 + k * CHEVRON_GAP;
        // A wave of light running left to right along the strip.
        const chase = 0.5 + 0.5 * Math.sin(this.timeS * 9 - k * 0.9);
        chevron.alpha = 0.55 + 0.45 * chase;
        chevron.scale.set((STRIP_HEIGHT / 80) * (0.92 + 0.12 * chase));
      }
      const pulse = 0.75 + 0.25 * Math.sin(this.timeS * 6 + slot.id);
      slot.glow.width = length + 90;
      slot.glow.height = STRIP_HEIGHT * 2.2;
      slot.glow.alpha = 0.6 * pulse;
    }
    for (const slot of this.pool) {
      if (!slot.seen && slot.id !== -1) {
        slot.id = -1;
        slot.root.visible = false;
      }
    }
  }

  clear(): void {
    for (const slot of this.pool) {
      slot.id = -1;
      slot.root.visible = false;
    }
  }

  dispose(): void {
    this.container.destroy({ children: true });
  }
}

function centred(texture: Texture): Sprite {
  const sprite = new Sprite(texture);
  sprite.anchor.set(0.5);
  return sprite;
}

function smoothstep(edge0: number, edge1: number, x: number): number {
  const t = Math.min(1, Math.max(0, (x - edge0) / (edge1 - edge0)));
  return t * t * (3 - 2 * t);
}
