/**
 * The water in two shaded quads.
 *
 * `WaterLayer`, behind everything: the far sea up to the horizon, the wave face from the lip
 * down to the trough, the dark barrel and the lip's shadow at the curl, and the flat water
 * in front. Drawing it in one place keeps the seams between them smooth (a calm sea at
 * `rise` 0 is the same sea the wave grows out of) and costs one draw call.
 *
 * `CurlLayer`, in front of the surfer: the falling curtain and the white water. Its front
 * follows `curlX` from the lip to the trough, the line where the game says the curl catches
 * the board, so a board behind it is seen inside the white water, not in front of it.
 *
 * Budget: the water is one pass over roughly the lower three quarters of the screen, about
 * a dozen value-noise lookups per pixel on the face and fewer elsewhere; where the white
 * water covers it, it stops early. The curl layer covers a tenth of the screen or so, with
 * nine disc tests and two or three noise lookups per pixel. No textures.
 */
import { NOISE_GLSL, SCROLL_PERIOD, type ShadedQuad, setQuad, shadedQuad } from './gl';
import { glsl, PALETTE as P } from './palette';

/**
 * The breaking part's shape, shared by both shaders so the barrel behind and the curtain and
 * white water in front always line up. `s` is 0 at the lip and 1 at the trough; `x0` is
 * the curl line (curlX, plus any surge).
 */
const CURL_SHAPE_GLSL = `
// Leading edge of the falling curtain, seen from the front: the lip thrown out in an arc,
// bulging ahead of the curl line at mid-face and curling back to it at the top and at the
// foot of the curtain, where the white water takes over. -1e5 where there is no curtain.
float curtainX(float s, float H, float x0) {
  float k = (s - 0.44) / 0.58;
  if (abs(k) >= 1.0) return -1e5;
  return x0 - 0.02 * H + 0.13 * H * sqrt(1.0 - k * k);
}
// Top of the curtain: the lip stands up over the curl and stays up behind it.
float curtainTop(float x, float H, float x0, float lip, float formed) {
  return lip - formed * H * (0.11 * smoothstep(x0 + 0.35 * H, x0 + 0.05 * H, x)
                             + 0.05 * smoothstep(x0, x0 - 0.4 * H, x));
}
// Front of the white water: on the curl line along the bottom of the face, leaning back up
// the face and over the lip into the pile, and spilling a little onto the flats.
float foamX(float s, float H, float x0) {
  float t = clamp(1.0 - s, 0.0, 1.6);
  return x0 - 0.42 * H * pow(t, 1.5) + 0.05 * H * smoothstep(1.0, 1.2, s);
}
// Top of the heap of white water behind the curl: it rises behind the curtain, in mounds.
float pileTop(float x, float H, float x0, float lip) {
  float mounds = sin(x / (0.09 * H) + 1.3) * 0.5 + sin(x / (0.047 * H) + 0.4) * 0.3;
  float behind = smoothstep(x0 - 0.1 * H, x0 - 0.8 * H, x);
  return lip - H * (0.1 + (0.12 + 0.035 * mounds) * behind);
}
`;

const WATER_FRAGMENT = `#version 300 es
precision highp float;
in vec2 vPos;
out vec4 finalColor;
uniform float uTime;
uniform float uScroll;
uniform float uLip;
uniform float uBottom;
uniform float uHorizon;
uniform float uCurlX;
uniform float uRise;
uniform float uSunX;
uniform float uPx;
uniform float uCenterX;
uniform float uSurge;
${NOISE_GLSL}
${CURL_SHAPE_GLSL}

const vec3 SEA_HORIZON = ${glsl(P.seaHorizon)};
const vec3 SEA_FAR = ${glsl(P.seaFar)};
const vec3 SEA_NEAR = ${glsl(P.seaNear)};
const vec3 SEA_DEEP = ${glsl(P.seaDeep)};
const vec3 SEA_GLINT = ${glsl(P.seaGlint)};
const vec3 SKY_HORIZON = ${glsl(P.skyHorizon)};
const vec3 FACE_DEEP = ${glsl(P.faceDeep)};
const vec3 FACE_MID = ${glsl(P.faceMid)};
const vec3 FACE_HIGH = ${glsl(P.faceHigh)};
const vec3 FACE_LIP = ${glsl(P.faceLip)};
const vec3 FACE_BACKLIT = ${glsl(P.faceBacklit)};
const vec3 TUBE = ${glsl(P.tube)};
const vec3 FOAM = ${glsl(P.foam)};
const vec3 FOAM_SHADE = ${glsl(P.foamShade)};
const vec3 FOAM_DEEP = ${glsl(P.foamDeep)};

// Scrolling patterns: x is (world x + scroll) / cell size, and the period in cells is
// SCROLL_PERIOD / cell size so the scroll can wrap without a seam.
#define SP ${SCROLL_PERIOD.toFixed(1)}

/** The flat sea seen in perspective: paler and finer towards the horizon. */
vec3 sea(vec2 p, out float detail) {
  float dy = max(p.y - uHorizon, 0.5);
  float base = max(uBottom - uHorizon, 1.0);
  float k = base / dy;
  float t = dy / base;
  vec3 c = mix(SEA_HORIZON, SEA_FAR, smoothstep(0.0, 0.3, t));
  c = mix(c, SEA_NEAR, smoothstep(0.3, 1.0, t));
  c = mix(c, SEA_DEEP, smoothstep(1.0, 1.45, t));
  // Ground-plane coordinates: X scrolls at the wave's speed at the wave's own depth.
  float X = (p.x - uCenterX) * k + uCenterX + uScroll;
  float Z = k * 150.0;
  detail = smoothstep(0.02, 0.35, t);
  float r1 = vnoise(vec2(X / 128.0, Z / 14.0 + uTime * 0.22), SP / 128.0);
  float r2 = vnoise(vec2(X / 64.0, Z / 7.0 - uTime * 0.31), SP / 64.0);
  float ripple = 0.6 * r1 + 0.4 * r2;
  c += (ripple - 0.5) * 0.1 * detail;
  // Crests catching the sky.
  c = mix(c, SKY_HORIZON, smoothstep(0.68, 0.88, ripple) * 0.2 * detail);
  // Glitter: small flecks, mostly in a column under the sun.
  float column = exp(-pow((p.x - uSunX) / (60.0 + dy * 0.32), 2.0));
  float g = vnoise(vec2(X / 8.0, Z / 0.9 + uTime * 1.3), SP / 8.0);
  // Near the viewer the flecks would be big and many: keep them to the sun's column there,
  // so the water close by stays calm and does not fizz.
  float near = smoothstep(0.75, 1.3, t);
  float glint = smoothstep(0.85, 0.97, g) * mix(0.06 + 0.94 * column, column * column, near);
  c = mix(c, SEA_GLINT, glint * (0.35 + 0.65 * detail) * (0.9 - 0.45 * near));
  // A bright haze line right at the horizon.
  c = mix(c, SKY_HORIZON, exp(-dy / 5.0) * 0.7);
  return c;
}

/** The wave face; s runs from 0 at the lip to 1 at the trough. */
vec3 face(vec2 p, float s, float H) {
  // How far up the concave face this is: the trough is seen at a grazing angle.
  float A = s * (1.0 + 1.3 * s * s);
  vec3 c = mix(FACE_LIP, FACE_HIGH, smoothstep(0.0, 0.22, s));
  c = mix(c, FACE_MID, smoothstep(0.16, 0.62, s));
  c = mix(c, FACE_DEEP, smoothstep(0.55, 1.1, s));
  float x = p.x + uScroll;
  // Big soft reflections of the sky, and a glassy band across the upper face.
  float refl = vnoise(vec2(x / 512.0, A * 1.6 + uTime * 0.05), SP / 512.0);
  c = mix(c, FACE_HIGH * 1.12, smoothstep(0.5, 0.85, refl) * 0.3 * (1.0 - s));
  float glassy = exp(-pow((s - 0.3) / 0.12, 2.0)) * (0.5 + 0.5 * vnoise(vec2(x / 256.0, 3.0), SP / 256.0));
  c = mix(c, FACE_HIGH * 1.18, glassy * 0.16);
  // Long broken streaks along the wave, carried up the face as it draws water in. Each
  // streak has its own gaps (keyed on its index), so they read as texture, not stripes.
  float warp = 1.8 * vnoise(vec2(x / 256.0, A * 1.5), SP / 256.0)
             + 0.5 * vnoise(vec2(x / 64.0, A * 4.0), SP / 64.0);
  float lines = A * H / 30.0 + warp + uTime * 0.5;
  float streak = pow(0.5 + 0.5 * cos(lines * 6.2832), 6.0);
  float index = floor(lines + 0.5);
  float gaps = vnoise(vec2(x / 150.0 + index * 7.3, index * 0.37), SP / 150.0);
  float broken = smoothstep(0.42, 0.78, gaps);
  float fadeLow = 1.0 - smoothstep(0.5, 0.9, s);
  c += vec3(0.4, 0.86, 0.8) * streak * broken * (0.1 + 0.12 * (1.0 - s)) * fadeLow;
  // The thin lip glows where the sun shines through it.
  float sunSide = exp(-pow((p.x - uSunX) / 800.0, 2.0));
  c = mix(c, FACE_BACKLIT, (1.0 - smoothstep(0.0, 0.1, s)) * (0.3 + 0.35 * sunSide));
  return c;
}

void main() {
  vec2 p = vPos;
  float aa = uPx * 1.25;
  float H = max(uBottom - uLip, 0.0);
  float rise = uRise;
  float formed = smoothstep(0.3, 0.85, rise);

  // How close to the curl: 1 at it, fading out across the face.
  float nearCurl = exp(-max(p.x - uCurlX, 0.0) / 650.0);

  // The lip: a gentle wobble, standing up as it nears the curl so the break looms.
  float lipPeak = 0.1 * H * formed * exp(-pow(max(p.x - uCurlX, 0.0) / (0.8 * H + 1.0), 2.0));
  float lip = uLip + (3.0 * sin(p.x * 0.011 + uTime * 1.3) + 2.0 * sin(p.x * 0.027 - uTime * 2.1)) * rise - lipPeak;

  // Things that can stand up into the sky: the white water and spray over the curl.
  float reach = min(lip - 18.0 - 70.0 * rise, uLip - 0.5 * H);
  if (p.y < min(reach, uHorizon) - 4.0) {
    finalColor = vec4(0.0);
    return;
  }

  // Deep inside the white water nothing of this shows (CurlLayer covers it): stop early.
  if (formed > 0.99 && p.x < uCurlX + uSurge - 0.8 * H && p.y > uLip - 0.2 * H && p.y < uBottom) {
    finalColor = vec4(FOAM_DEEP, 1.0);
    return;
  }

  // ---- Base: sea, face, sea in front -------------------------------------------------
  // A young swell has a soft, rounded top; it sharpens into a lip as the wave forms.
  float soft = aa + (1.0 - formed) * 0.3 * H;
  float onFace = smoothstep(lip - soft, lip + soft, p.y) * step(p.y, uBottom + 0.5 * H + 40.0);
  float troughTop = uBottom - 0.22 * H - 6.0;
  float detail = 0.0;
  vec3 col = sea(p, detail);
  float alpha = smoothstep(uHorizon - aa, uHorizon + aa, p.y);

  if (H > 0.5 && onFace > 0.0) {
    float s = clamp((p.y - lip) / max(H, 1.0), 0.0, 1.0);
    vec3 f = face(p, s, H);
    // Near the curl the face is steeper and in the lip's shadow.
    f *= 1.0 - 0.22 * formed * exp(-max(p.x - uCurlX, 0.0) / (0.5 * H + 1.0)) * (1.0 - 0.6 * s);
    // A young swell is still the colour of the sea.
    f = mix(col, f, smoothstep(0.1, 0.85, rise));
    // Ease into the flat water at the trough.
    float trough = smoothstep(troughTop, uBottom + 10.0, p.y);
    f = mix(f, col, trough);
    col = mix(col, f, onFace);
    alpha = max(alpha, onFace);
  }

  // The face mirrored faintly in the flat water just in front of it.
  if (p.y > uBottom) {
    float refl = exp(-(p.y - uBottom) / (0.25 * H + 1.0)) * smoothstep(0.1, 0.8, rise);
    col = mix(col, FACE_MID * 0.9, refl * 0.3);
  }

  // ---- The lip: a thin foam edge with spray lifting off it ---------------------------
  // A thin crest line from early in the rise, so the swell reads as a wave coming up.
  float lipFoam = smoothstep(0.2, 1.0, rise) * (0.45 + 0.55 * nearCurl);
  if (lipFoam > 0.0 && p.y > lip - 140.0 && p.y < lip + 20.0) {
    float x = p.x + uScroll * 0.2;
    float n = vnoise(vec2(x / 48.0, uTime * 0.6), SP / 48.0);
    float th = (3.0 + 10.0 * n) * lipFoam + 1.0;
    float dy = p.y - lip;
    float crown = (2.0 + 6.0 * vnoise(vec2(x / 22.0, uTime * 1.2), SP / 22.0)) * lipFoam;
    float band = smoothstep(-crown - aa, -crown + aa, dy) * smoothstep(th, th * 0.3, dy);
    band *= lipFoam;
    col = mix(col, FOAM, band * 0.95);
    alpha = max(alpha, band);
    // Spray blown up off the top.
    float up = max(lip - p.y, 0.0);
    float puff = fbm3(vec2(p.x / 90.0 + uTime * 0.1, p.y / 34.0 + uTime * 0.7), 4096.0);
    float mist = exp(-up / (14.0 + 34.0 * nearCurl)) * smoothstep(0.38, 0.8, puff) * step(p.y, lip + 2.0);
    mist *= lipFoam * (0.35 + 0.4 * nearCurl);
    col = mix(col, FOAM, mist);
    alpha = max(alpha, mist);
  }

  // ---- The pocket: the dark barrel behind the falling curtain, and the lip's shadow ------
  // The curtain and the white water themselves are drawn over the surfer (CurlLayer); this
  // is what shows through and around them.
  if (H > 8.0 && p.x < uCurlX + 1.2 * H) {
    float s = (p.y - uLip) / H;
    // Behind the curtain, and behind the white water below it.
    float xc = max(curtainX(s, H, uCurlX + uSurge), uCurlX + uSurge - 0.02 * H);
    float d = xc - p.x;
    float top = curtainTop(p.x, H, uCurlX + uSurge, uLip, formed);
    float inY = smoothstep(top - aa, top + aa, p.y) * smoothstep(uBottom + 0.06 * H, uBottom - 0.04 * H, p.y);
    float barrel = smoothstep(-aa, aa, d) * inY * formed;
    // Deeper in and lower down, darker.
    vec3 tube = mix(FACE_MID * 0.75, TUBE, smoothstep(0.0, 0.22 * H, d) * (0.5 + 0.5 * clamp(s, 0.0, 1.0)));
    col = mix(col, tube, barrel);
    alpha = max(alpha, barrel);
    // The lip looms over the pocket: its shadow on the open face ahead of it.
    float ahead = exp(min(d, 0.0) / (0.4 * H)) * (1.0 - barrel) * inY * formed * (1.0 - 0.55 * clamp(s, 0.0, 1.0));
    col *= 1.0 - 0.3 * ahead;
  }

  // Foam lines left on the flat water by the broken wave.
  if (p.y > uBottom - 40.0 && rise > 0.05 && p.x < uCurlX + 1.4 * H) {
    float x = p.x + uScroll;
    float lines = vnoise(vec2(x / 40.0, p.y / 9.0), SP / 40.0) * vnoise(vec2(x / 160.0, p.y / 30.0), SP / 160.0);
    // Fades in over the trough rather than starting at a line.
    float spread = smoothstep(uCurlX + 1.3 * H, uCurlX, p.x) * exp(-max(p.y - uBottom, 0.0) / 90.0)
                 * smoothstep(uBottom - 40.0, uBottom + 10.0, p.y);
    float trail = smoothstep(0.32, 0.5, lines) * spread * formed;
    col = mix(col, FOAM_SHADE, trail * 0.8);
  }

  col += dither(gl_FragCoord.xy);
  finalColor = vec4(col * alpha, alpha);
}
`;

const CURL_FRAGMENT = `#version 300 es
precision highp float;
in vec2 vPos;
out vec4 finalColor;
uniform float uTime;
uniform float uLip;
uniform float uBottom;
uniform float uCurlX;
uniform float uFormed;
uniform float uPx;
uniform float uSurge;
${NOISE_GLSL}
${CURL_SHAPE_GLSL}

const vec3 FACE_MID = ${glsl(P.faceMid)};
const vec3 FACE_HIGH = ${glsl(P.faceHigh)};
const vec3 FACE_LIP = ${glsl(P.faceLip)};
const vec3 FACE_BACKLIT = ${glsl(P.faceBacklit)};
const vec3 FOAM = ${glsl(P.foam)};
const vec3 FOAM_SHADE = ${glsl(P.foamShade)};
const vec3 FOAM_DEEP = ${glsl(P.foamDeep)};
// The sun is up and to the right, and in front.
const vec3 LIGHT3 = vec3(0.45, -0.6, 0.66);

/** Signed distance-ish to the white water's outline, negative inside. */
float region(vec2 q, float H, float x0) {
  float s = (q.y - uLip) / H;
  return max(q.x - foamX(s, H, x0), max(pileTop(q.x, H, x0, uLip) - q.y, q.y - (uBottom + 0.12 * H)));
}

/** Premultiplied "over". */
vec4 over(vec4 top, vec4 below) {
  return top + below * (1.0 - top.a);
}

void main() {
  vec2 p = vPos;
  float H = max(uBottom - uLip, 1.0);
  float aa = uPx * 1.25;
  float x0 = uCurlX + uSurge;
  float s = (p.y - uLip) / H;
  vec4 c = vec4(0.0);

  // ---- The curtain: the thrown lip falling in a glassy sheet over the barrel ----------
  float xc = curtainX(s, H, x0);
  float wav = 5.0 * sin(p.y * 0.03 - uTime * 4.0) + 3.0 * sin(p.y * 0.071 + uTime * 2.7);
  float d = xc + wav * uFormed - p.x;
  if (d > -12.0) {
    float top = curtainTop(p.x, H, x0, uLip, uFormed);
    float inY = smoothstep(top - aa, top + aa, p.y);
    float sheet = smoothstep(-aa, aa, d) * inY;
    float fall = vnoise(vec2(p.x / 9.0, p.y / 120.0 - uTime * 2.2), 4096.0);
    float sc = clamp(s, 0.0, 1.0);
    vec3 col = mix(FACE_HIGH, FACE_MID, sc * 0.7);
    col = mix(col, FACE_LIP, smoothstep(0.55, 0.9, fall) * 0.45);
    // The top of the throw is thin and lit through by the sun.
    col = mix(col, FACE_BACKLIT, (1.0 - smoothstep(-0.12, 0.16, s)) * 0.65);
    // A bright frill of foam and spray along the leading edge.
    float n = vnoise(vec2(p.y / 14.0, uTime * 3.0), 4096.0);
    float rim = exp(-max(d, 0.0) / (6.0 + 12.0 * n));
    col = mix(col, FOAM, rim * 0.95);
    // Churned white where it lands at the foot of the face.
    float foot = smoothstep(0.55, 0.9, s) * (0.6 + 0.4 * fall);
    col = mix(col, FOAM_SHADE, foot * 0.7);
    // Thin enough to see the dark barrel through, opaque at the frill.
    float a = sheet * uFormed * mix(0.72, 1.0, max(rim, foot)) * smoothstep(1.02, 0.9, s);
    c = vec4(col * a, a);
  }

  // ---- The white water: heaped billows, lit from the sun's side ----------------------
  // A union of discs on a grid that rolls up and back with time. Each disc is shaded by
  // its own normal, so the mass reads as cauliflower foam rather than smoke. Discs grow as
  // their centres roll into the heap, so none pops in at the edge.
  float C = max(0.12 * H, 8.0);
  float body = region(p, H, x0);
  if (body < 1.2 * C) {
    vec2 roll = vec2(uTime * 24.0, uTime * 52.0);
    vec2 g = floor((p + roll) / C);
    float best = 1e5;
    float lit = -0.3;
    // Shading comes from the ball nearest the viewer here (the highest point of its
    // surface, plus a per-ball offset), so balls overlap along round outlines instead of
    // meeting in straight seams.
    float top = -1e5;
    for (int j = -1; j <= 1; j++) {
      for (int i = -1; i <= 1; i++) {
        vec2 cell = g + vec2(float(i), float(j));
        float h1 = hash12(cell);
        float h2 = hash12(cell + 19.19);
        vec2 centre = (cell + 0.5 + (vec2(h1, h2) - 0.5) * 0.4) * C - roll;
        // Smaller towards the bottom, where the heap spreads out into the flats.
        float r = C * (0.42 + 0.38 * h2 * h2) * smoothstep(-0.2 * C, 0.6 * C, -region(centre, H, x0))
                * mix(1.0, 0.8, smoothstep(uBottom, uBottom + 0.14 * H, centre.y));
        vec2 o = p - centre;
        float dd = length(o) - r;
        best = min(best, dd);
        vec2 q = o / max(r, 1.0);
        float z2 = 1.0 - dot(q, q);
        float zt = z2 > 0.0 ? (sqrt(z2) + h1) * r : -1e4 - dd;
        if (zt > top) {
          top = zt;
          // Shaded like a ball: brightest towards the sun, darkest round the far rim.
          lit = dot(vec3(q, sqrt(max(0.0, z2))), LIGHT3);
        }
      }
    }
    // A solid body behind the billows, filled with bigger billows of its own, cumulus
    // style: white balls with a cool crescent of shade on the side away from the sun, and
    // shade in the creases between them.
    // Its bottom edge is left to the billows, so it is never a ruled line.
    float solid = max(body, p.y - (uBottom + 0.02 * H)) + 0.45 * C;
    float C2 = 2.1 * C;
    vec2 roll2 = roll * 0.7;
    vec2 g2 = floor((p + roll2) / C2);
    float top2 = -1.0;
    float lit2 = 0.15;
    for (int j = -1; j <= 1; j++) {
      for (int i = -1; i <= 1; i++) {
        vec2 cell = g2 + vec2(float(i), float(j));
        float h1 = hash12(cell + 7.7);
        float h2 = hash12(cell + 31.3);
        // Radius plus jitter stays within a cell, so no ball is clipped by the 3×3 search.
        vec2 centre = (cell + 0.5 + (vec2(h1, h2) - 0.5) * 0.3) * C2 - roll2;
        float r = C2 * (0.64 + 0.2 * h2);
        vec2 o = p - centre;
        vec2 q = o / r;
        float z2 = 1.0 - dot(q, q);
        if (z2 > 0.0 && (sqrt(z2) + h1) * r > top2) {
          top2 = (sqrt(z2) + h1) * r;
          lit2 = dot(vec3(q, sqrt(z2)), LIGHT3);
        }
      }
    }
    float inner = lit2;
    if (solid < best) lit = inner;
    // Only the billows along the outline are shaded on their own; deeper in, the big ones.
    lit = mix(lit, inner, smoothstep(-0.3 * C, -1.1 * C, body));
    float dist = min(best, solid);
    // Painted foam: stepped tones, white in the sun, a cool blue in the shade.
    vec3 col = mix(FOAM_DEEP, FOAM_SHADE, smoothstep(0.02, 0.1, lit));
    col = mix(col, FOAM, smoothstep(0.3, 0.38, lit));
    // Cooler where it churns into the water at the bottom.
    col = mix(col, FOAM_DEEP * 0.92, smoothstep(uBottom - 0.1 * H, uBottom + 0.2 * H, p.y) * 0.55);
    float a = smoothstep(aa, -aa, dist) * uFormed;
    c = over(vec4(col * a, a), c);
  }

  // ---- Spray hanging over the break, blown back off the heap -------------------------
  float up = pileTop(p.x, H, x0, uLip) - p.y;
  if (up > -C && up < 0.75 * H) {
    float hz = fbm3(vec2(p.x / 110.0 + uTime * 0.08, p.y / 70.0 + uTime * 0.45), 4096.0);
    // Off the top of the heap only: it thins into the heap below and never veils the curtain.
    float haze = exp(-max(up, 0.0) / (0.24 * H)) * smoothstep(-C, 0.2 * C, up) * smoothstep(0.32, 0.8, hz);
    haze *= 0.6 * uFormed * smoothstep(x0 - 0.15 * H, x0 - 0.5 * H, p.x);
    c = over(vec4(FOAM * haze, haze), c);
  }

  finalColor = c;
}
`;

export interface WaterState {
  timeS: number;
  distance: number;
  lipY: number;
  bottomY: number;
  horizonY: number;
  curlX: number;
  rise: number;
  sunX: number;
  /** World units per device pixel at the current zoom, for anti-aliasing. */
  pixel: number;
  centerX: number;
  /** How far the white water has surged past the curl line (close calls, wipeouts). */
  surge: number;
}

export class WaterLayer {
  private readonly quad: ShadedQuad<{
    uTime: { value: number; type: 'f32' };
    uScroll: { value: number; type: 'f32' };
    uLip: { value: number; type: 'f32' };
    uBottom: { value: number; type: 'f32' };
    uHorizon: { value: number; type: 'f32' };
    uCurlX: { value: number; type: 'f32' };
    uRise: { value: number; type: 'f32' };
    uSunX: { value: number; type: 'f32' };
    uPx: { value: number; type: 'f32' };
    uCenterX: { value: number; type: 'f32' };
    uSurge: { value: number; type: 'f32' };
  }>;
  private x0 = 0;
  private y0 = 0;
  private x1 = 0;
  private y1 = 0;

  constructor() {
    this.quad = shadedQuad('water', WATER_FRAGMENT, 'waterUniforms', {
      uTime: { value: 0, type: 'f32' },
      uScroll: { value: 0, type: 'f32' },
      uLip: { value: 865, type: 'f32' },
      uBottom: { value: 865, type: 'f32' },
      uHorizon: { value: 300, type: 'f32' },
      uCurlX: { value: -500, type: 'f32' },
      uRise: { value: 0, type: 'f32' },
      uSunX: { value: 1400, type: 'f32' },
      uPx: { value: 1, type: 'f32' },
      uCenterX: { value: 960, type: 'f32' },
      uSurge: { value: 0, type: 'f32' },
    });
  }

  get view() {
    return this.quad.mesh;
  }

  /** The world rectangle the water must cover (what the camera can see, and then some). */
  setBounds(x0: number, y0: number, x1: number, y1: number): void {
    if (x0 === this.x0 && y0 === this.y0 && x1 === this.x1 && y1 === this.y1) return;
    this.x0 = x0;
    this.y0 = y0;
    this.x1 = x1;
    this.y1 = y1;
    setQuad(this.quad.geometry, x0, y0, x1, y1);
  }

  update(state: WaterState): void {
    const u = this.quad.uniforms;
    u.uTime = state.timeS % 600;
    u.uScroll = ((state.distance % SCROLL_PERIOD) + SCROLL_PERIOD) % SCROLL_PERIOD;
    u.uLip = state.lipY;
    u.uBottom = state.bottomY;
    u.uHorizon = state.horizonY;
    u.uCurlX = state.curlX;
    u.uRise = state.rise;
    u.uSunX = state.sunX;
    u.uPx = state.pixel;
    u.uCenterX = state.centerX;
    u.uSurge = state.surge;
  }

  dispose(): void {
    this.quad.destroy();
  }
}

/** The curtain and the white water, drawn over the surfer (see the top of this file). */
export class CurlLayer {
  private readonly quad: ShadedQuad<{
    uTime: { value: number; type: 'f32' };
    uLip: { value: number; type: 'f32' };
    uBottom: { value: number; type: 'f32' };
    uCurlX: { value: number; type: 'f32' };
    uFormed: { value: number; type: 'f32' };
    uPx: { value: number; type: 'f32' };
    uSurge: { value: number; type: 'f32' };
  }>;
  private x0 = 0;
  private y0 = 0;
  private x1 = 0;
  private y1 = 0;

  constructor() {
    this.quad = shadedQuad('curl', CURL_FRAGMENT, 'curlUniforms', {
      uTime: { value: 0, type: 'f32' },
      uLip: { value: 865, type: 'f32' },
      uBottom: { value: 865, type: 'f32' },
      uCurlX: { value: -500, type: 'f32' },
      uFormed: { value: 0, type: 'f32' },
      uPx: { value: 1, type: 'f32' },
      uSurge: { value: 0, type: 'f32' },
    });
  }

  get view() {
    return this.quad.mesh;
  }

  /** `left` is the left edge of what the camera sees, world units. */
  update(state: WaterState, left: number): void {
    const u = this.quad.uniforms;
    const formed = smoothstep(0.3, 0.85, state.rise);
    const H = Math.max(0, state.bottomY - state.lipY);
    const x0 = state.curlX + state.surge;
    const visible = formed > 0.002 && H > 8 && x0 + 0.3 * H > left;
    this.quad.mesh.visible = visible;
    if (!visible) return;
    u.uTime = state.timeS % 600;
    u.uLip = state.lipY;
    u.uBottom = state.bottomY;
    u.uCurlX = state.curlX;
    u.uFormed = formed;
    u.uPx = state.pixel;
    u.uSurge = state.surge;
    // Only the part of the screen the break can reach.
    const x0q = Math.floor(left - 20);
    const x1q = Math.ceil(x0 + 0.3 * H + 30);
    const y0q = Math.floor(state.lipY - 0.85 * H);
    const y1q = Math.ceil(state.bottomY + 0.3 * H);
    if (x0q === this.x0 && x1q === this.x1 && y0q === this.y0 && y1q === this.y1) return;
    this.x0 = x0q;
    this.x1 = x1q;
    this.y0 = y0q;
    this.y1 = y1q;
    setQuad(this.quad.geometry, x0q, y0q, x1q, y1q);
  }

  dispose(): void {
    this.quad.destroy();
  }
}

function smoothstep(edge0: number, edge1: number, x: number): number {
  const t = Math.min(1, Math.max(0, (x - edge0) / (edge1 - edge0)));
  return t * t * (3 - 2 * t);
}
