/**
 * MediaPipe's WASM runtime, downloaded on the main thread like the model (with progress and
 * a stall timeout) and handed to the backends, so a backend's init timeout only ever covers
 * compiling and warming up, never a slow download.
 */
import mediapipeManifest from '../../node_modules/@mediapipe/tasks-vision/package.json';
import type { WasmBuild, WasmFiles } from './backend';
import type { DownloadProgress } from './download';

/**
 * The MediaPipe release the files in public/mediapipe come from: scripts/sync-mediapipe.mjs
 * copies them out of this package. Its export map hides package.json, hence the path.
 */
export const MEDIAPIPE_VERSION: string = mediapipeManifest.version;

const NAMES: Record<WasmBuild, string> = {
  module: 'vision_wasm_module_internal',
  classic: 'vision_wasm_internal',
};

/** URLs of one build under `baseUrl` (absolute, no trailing slash). */
export function wasmUrls(
  baseUrl: string,
  build: WasmBuild,
): { loaderUrl: string; binaryUrl: string } {
  // Versioned, so that after an upgrade a cached old loader can never pair with a new
  // binary or worker.
  const path = `${baseUrl}/${NAMES[build]}`;
  const query = `?v=${encodeURIComponent(MEDIAPIPE_VERSION)}`;
  return { loaderUrl: `${path}.js${query}`, binaryUrl: `${path}.wasm${query}` };
}

export type BlobDownload = (
  url: string,
  type: string,
  onProgress: DownloadProgress | undefined,
  signal: AbortSignal,
) => Promise<Blob>;

/** Downloads each build at most once and hands it to every backend that asks for it. */
export class WasmLibrary {
  private readonly loads = new Map<WasmBuild, Promise<WasmFiles>>();
  private readonly abort = new AbortController();

  constructor(
    private readonly baseUrl: string,
    private readonly download: BlobDownload,
  ) {}

  /** `onProgress` hears about the download only if this call is the one that starts it. */
  load(build: WasmBuild, onProgress?: DownloadProgress): Promise<WasmFiles> {
    const existing = this.loads.get(build);
    if (existing) return existing;
    const { loaderUrl, binaryUrl } = wasmUrls(this.baseUrl, build);
    const load = this.download(binaryUrl, 'application/wasm', onProgress, this.abort.signal).then(
      (binary) => ({ loaderUrl, binary }),
    );
    this.loads.set(build, load);
    // A failed download is tried again by the next backend that asks.
    load.catch(() => {
      if (this.loads.get(build) === load) this.loads.delete(build);
    });
    return load;
  }

  /** Cancel downloads still running. */
  dispose(): void {
    this.abort.abort();
    this.loads.clear();
  }
}
