import { Particle, ParticleContainer, type Texture } from 'pixi.js';
import { EFFECT_RADIUS, type EffectFrameName } from './art';
import { rgbToBgr } from './color';

/**
 * What a particle does over its life. Every kind lives in the same pool; behaviour is a
 * switch on the kind, state lives in typed arrays.
 */
export const FX = {
  /** A water drop: ballistic, stretched along its motion. */
  droplet: 0,
  /** A puff of spray: grows, drifts, fades. */
  mist: 1,
  /** A clump of white water: grows a little, rides the water, fades. */
  foam: 2,
  /** A ring spreading on the water, squashed flat. */
  ring: 3,
  /** A twinkling glint. */
  spark: 4,
  /** A short soft flash. */
  flash: 5,
  /** A small spinning star flung out of a pickup. */
  star: 6,
  /** A thin line drawn out along its motion. */
  streak: 7,
} as const;

export type FxKind = (typeof FX)[keyof typeof FX];

const FRAME_OF: readonly EffectFrameName[] = [
  'droplet',
  'mist',
  'foam',
  'ring',
  'spark',
  'flash',
  'star',
  'streak',
];

/** World units per second squared. */
const GRAVITY = 1500;

/**
 * A fixed pool of particles that never leaves its container (dead ones are scaled to
 * nothing) with state in typed arrays, so spawning and updating allocate nothing.
 *
 * Positions are screen world units in the frame that travels with the wave. Things lying
 * on the water (foam, rings) also slide left with it at `waterSpeed` times their `drift`.
 */
export class Effects {
  readonly container: ParticleContainer;
  /** Scenery scroll speed, world units per second; set every frame. */
  waterSpeed = 0;

  private readonly frames: Texture[];
  private readonly radiusPx: Float32Array;
  private readonly particles: Particle[] = [];
  private readonly kind: Uint8Array;
  private readonly age: Float32Array;
  private readonly life: Float32Array;
  private readonly vx: Float32Array;
  private readonly vy: Float32Array;
  /** Start and end radius in world units. */
  private readonly size0: Float32Array;
  private readonly size1: Float32Array;
  private readonly spin: Float32Array;
  private readonly bgr: Uint32Array;
  private readonly alpha: Float32Array;
  private readonly drift: Float32Array;
  /** Gravity scale: droplets fall, mist hangs or rises a little. */
  private readonly weight: Float32Array;
  private readonly live: Int32Array;
  private liveCount = 0;
  private readonly free: Int32Array;
  private freeCount: number;
  private readonly random: () => number;

  constructor(
    textures: Record<EffectFrameName, Texture>,
    capacity: number,
    random: () => number = Math.random,
  ) {
    this.random = random;
    this.frames = FRAME_OF.map((name) => textures[name]);
    this.radiusPx = new Float32Array(
      FRAME_OF.map((name) => (EFFECT_RADIUS[name] * textures[name].frame.width) / 2),
    );
    this.kind = new Uint8Array(capacity);
    this.age = new Float32Array(capacity);
    this.life = new Float32Array(capacity);
    this.vx = new Float32Array(capacity);
    this.vy = new Float32Array(capacity);
    this.size0 = new Float32Array(capacity);
    this.size1 = new Float32Array(capacity);
    this.spin = new Float32Array(capacity);
    this.bgr = new Uint32Array(capacity);
    this.alpha = new Float32Array(capacity);
    this.drift = new Float32Array(capacity);
    this.weight = new Float32Array(capacity);
    this.live = new Int32Array(capacity);
    this.free = new Int32Array(capacity);
    this.freeCount = capacity;
    this.container = new ParticleContainer({
      // Slots are reused for different kinds, so texture frames (uvs) change too.
      dynamicProperties: { vertex: true, position: true, rotation: true, uvs: true, color: true },
    });
    for (let i = 0; i < capacity; i++) {
      const particle = new Particle({ texture: textures.droplet, anchorX: 0.5, anchorY: 0.5 });
      hide(particle);
      this.particles.push(particle);
      this.free[i] = capacity - 1 - i;
    }
    this.container.addParticle(...this.particles);
    this.container.visible = false;
  }

  get count(): number {
    return this.liveCount;
  }

  /** Free slots; continuous emitters skip optional particles when it runs low. */
  get room(): number {
    return this.freeCount;
  }

  /**
   * Start one particle. `size0`/`size1` are radii in world units at birth and death,
   * `rgb` its tint, `alpha` its peak opacity and `drift` how much it rides the water.
   */
  spawn(
    kind: FxKind,
    x: number,
    y: number,
    vx: number,
    vy: number,
    size0: number,
    size1: number,
    life: number,
    rgb: number,
    alpha = 1,
    drift = 0,
  ): void {
    // At the cap a burst simply gets fewer particles; nothing older is cut short.
    if (this.freeCount === 0 || !(life > 0)) return;
    const i = this.free[--this.freeCount] as number;
    this.live[this.liveCount++] = i;
    const particle = this.particles[i] as Particle;
    particle.texture = this.frames[kind] as Texture;
    particle.x = x;
    particle.y = y;
    const random = this.random;
    particle.rotation =
      kind === FX.foam || kind === FX.star || kind === FX.mist ? random() * Math.PI * 2 : 0;
    particle.scaleX = 0;
    particle.scaleY = 0;
    particle.color = 0;
    this.kind[i] = kind;
    this.age[i] = 0;
    this.life[i] = life;
    this.vx[i] = vx;
    this.vy[i] = vy;
    this.size0[i] = size0;
    this.size1[i] = size1;
    this.spin[i] =
      kind === FX.foam || kind === FX.mist
        ? (random() - 0.5) * 1.2
        : kind === FX.star || kind === FX.spark
          ? (random() - 0.5) * 10
          : 0;
    this.bgr[i] = rgbToBgr(rgb);
    this.alpha[i] = alpha;
    this.drift[i] = drift;
    this.weight[i] =
      kind === FX.droplet ? 1 : kind === FX.star ? 0.55 : kind === FX.mist ? -0.03 : 0;
    this.container.visible = true;
  }

  update(dtS: number): void {
    const flow = this.waterSpeed * dtS;
    for (let n = this.liveCount - 1; n >= 0; n--) {
      const i = this.live[n] as number;
      const age = (this.age[i] as number) + dtS;
      const life = this.life[i] as number;
      const particle = this.particles[i] as Particle;
      if (age >= life) {
        hide(particle);
        this.live[n] = this.live[this.liveCount - 1] as number;
        this.liveCount--;
        this.free[this.freeCount++] = i;
        continue;
      }
      this.age[i] = age;
      const t = age / life;
      const kind = this.kind[i] as number;
      // Air drag: droplets fly, puffs and foam slow quickly.
      const drag = kind === FX.droplet || kind === FX.star ? 1.4 : kind === FX.streak ? 0 : 3;
      const decay = Math.exp(-drag * dtS);
      const vx = (this.vx[i] as number) * decay;
      const vy = (this.vy[i] as number) * decay + GRAVITY * (this.weight[i] as number) * dtS;
      this.vx[i] = vx;
      this.vy[i] = vy;
      particle.x += vx * dtS - flow * (this.drift[i] as number);
      particle.y += vy * dtS;
      particle.rotation += (this.spin[i] as number) * dtS;

      const s0 = this.size0[i] as number;
      const s1 = this.size1[i] as number;
      const perPx = 1 / (this.radiusPx[kind] as number);
      let alpha: number;
      switch (kind) {
        case FX.droplet: {
          const radius = s0 + (s1 - s0) * t;
          // Streak along the motion while fast, settle into a bead as it slows.
          const speed = Math.sqrt(vx * vx + vy * vy);
          const stretch = 1 + Math.min(1.6, speed / (radius * 28 + 1));
          particle.scaleX = radius * perPx * stretch;
          particle.scaleY = (radius * perPx) / Math.sqrt(stretch);
          particle.rotation = Math.atan2(vy, vx);
          alpha = t < 0.5 ? 1 : 2 - 2 * t;
          break;
        }
        case FX.streak: {
          const radius = s0 + (s1 - s0) * t;
          particle.scaleX = radius * perPx;
          particle.scaleY = radius * perPx * 0.5;
          particle.rotation = Math.atan2(vy, vx);
          alpha = Math.sin(Math.PI * t);
          break;
        }
        case FX.ring: {
          const e = 1 - (1 - t) ** 3;
          const radius = s0 + (s1 - s0) * e;
          particle.scaleX = radius * perPx;
          particle.scaleY = radius * perPx * 0.32;
          alpha = (1 - t) * (1 - t);
          break;
        }
        case FX.spark: {
          const twinkle = Math.sin(Math.PI * t);
          particle.scaleX = particle.scaleY = s0 * perPx * twinkle;
          alpha = twinkle;
          break;
        }
        case FX.flash: {
          particle.scaleX = particle.scaleY = (s0 + (s1 - s0) * t) * perPx;
          alpha = (1 - t) * (1 - t);
          break;
        }
        default: {
          // Mist, foam and stars swell out quickly and fade away.
          const e = 1 - (1 - t) * (1 - t);
          particle.scaleX = particle.scaleY = (s0 + (s1 - s0) * e) * perPx;
          alpha = t < 0.12 ? t / 0.12 : 1 - ((t - 0.12) / 0.88) ** 1.5;
        }
      }
      const a = Math.max(0, Math.min(1, alpha * (this.alpha[i] as number)));
      particle.color = (this.bgr[i] as number) + (((a * 255) | 0) << 24);
    }
    this.container.visible = this.liveCount > 0;
  }

  /** Remove every live particle (e.g. on reset). */
  clear(): void {
    for (let n = 0; n < this.liveCount; n++) {
      const i = this.live[n] as number;
      hide(this.particles[i] as Particle);
      this.free[this.freeCount++] = i;
    }
    this.liveCount = 0;
    this.container.visible = false;
  }

  dispose(): void {
    this.clear();
    this.container.destroy();
    this.particles.length = 0;
  }
}

function hide(particle: Particle): void {
  particle.scaleX = 0;
  particle.scaleY = 0;
  particle.color = 0;
}
