/** Small colour helpers on packed 0xRRGGBB numbers: no objects or closures per call. */

/** HSL (h in degrees, s and l in 0..1) to 0xRRGGBB. */
export function hslToRgb(h: number, s: number, l: number): number {
  const a = s * Math.min(l, 1 - l);
  return packRgb(hslChannel(0, h, l, a), hslChannel(8, h, l, a), hslChannel(4, h, l, a));
}

function hslChannel(n: number, h: number, l: number, a: number): number {
  const k = (n + h / 30) % 12;
  const kk = k < 0 ? k + 12 : k;
  return l - a * Math.max(-1, Math.min(kk - 3, 9 - kk, 1));
}

/** Channels in 0..1 to 0xRRGGBB. */
export function packRgb(r: number, g: number, b: number): number {
  return (to8(r) << 16) | (to8(g) << 8) | to8(b);
}

function to8(value: number): number {
  return Math.round(Math.min(1, Math.max(0, value)) * 255);
}

/** Linear blend of two packed colours; `t` = 0 gives `a`. */
export function mixRgb(a: number, b: number, t: number): number {
  return lerpChannel(a, b, t, 16) | lerpChannel(a, b, t, 8) | lerpChannel(a, b, t, 0);
}

function lerpChannel(a: number, b: number, t: number, shift: number): number {
  const from = (a >> shift) & 255;
  const to = (b >> shift) & 255;
  return Math.round(from + (to - from) * t) << shift;
}

/** 0xRRGGBB to the 0xBBGGRR order Pixi particles store in `color`. */
export function rgbToBgr(rgb: number): number {
  return ((rgb & 0xff) << 16) | (rgb & 0xff00) | ((rgb >> 16) & 0xff);
}
