/**
 * What the game sounds like: turns each tick's events into one-shots and keeps the
 * continuous layers following the state. Every one-shot is a voice in a small pool; when the
 * pool is full the oldest of the least important voices is cut, so a burst of events stays
 * responsive and the mix never piles up.
 *
 * Time is always passed in (`when`, context time), so the same code drives a live
 * AudioContext and an OfflineAudioContext render for measurement.
 */
import type { Game, GameEvent } from '../game/types';
import {
  type Ambience,
  ambienceTargets,
  createAmbience,
  HEIGHT_FULL,
  panFor,
  SILENCE,
  speed01,
} from './ambience';
import { type Cue, PICKUP_SCALE, playCrab, playCue, playDing } from './cues';
import {
  playBoost,
  playBuoy,
  playCarve,
  playCloseCall,
  playCrash,
  playLaunch,
  playSplash,
  playWhirlpool,
} from './effects';
import { clamp, type Priority, type Voice, VoiceBuilder } from './synth';

/** Simultaneous one-shots. Most last under a second, so this covers any realistic burst. */
export const MAX_VOICES = 10;
/**
 * Pickups climb the scale with the game's combo (one step per chained pickup; a lone one
 * is the bottom note). Each in a combo is this much quieter than the one before (share of
 * full level), down to `PICKUP_FLOOR`: a ten-clam line ends about 4 dB down instead of
 * ringing on at full, and the next combo starts at full again.
 */
export const PICKUP_TAPER = 0.06;
export const PICKUP_FLOOR = 0.6;
/** Air time (s) of a small jump and of a big one: the bots' airs last 0.8–1.5 s. */
const AIR_SMALL_S = 0.7;
const AIR_BIG_S = 1.4;
/** Points of the smallest and the biggest carve (see the carve scoring in the game). */
const CARVE_POINTS_MIN = 60;
const CARVE_POINTS_MAX = 250;
/** Glide time (s) of the layers when play ends: gone in well under a second. */
const STOP_FADE_S = 0.08;
/**
 * One-shots that arrive in the same tick are spread this far apart, cycling through a few
 * slots: their transients do not stack, and a burst never trails the picture by much.
 */
const STAGGER_S = 0.012;
const STAGGER_SLOTS = 3;
/** The wipeout's jingle follows the crash; a new best's fanfare follows the jingle. */
export const JINGLE_DELAY_S = 0.45;
export const FANFARE_DELAY_S = 2.1;
/** The perfect-landing chime starts just after the splash's slap. */
const CHIME_DELAY_S = 0.04;
/** Pose cue: plays when the hold passes ON, and is re-armed when it falls back below OFF. */
const POSE_ON = 0.2;
const POSE_OFF = 0.02;
const POSE_MIN_GAP_S = 1;

export interface SoundscapeOptions {
  context: BaseAudioContext;
  /** One-shots go here. */
  effects: AudioNode;
  /** Continuous layers go here. */
  ambience: AudioNode;
  noise: AudioBuffer;
  random: () => number;
  /** Context time the layers start at (offline renders schedule ahead). */
  start?: number;
}

export interface Soundscape {
  readonly voices: readonly Voice[];
  update(game: Game, events: readonly GameEvent[], dtS: number, when: number): void;
  /**
   * Fade the continuous layers out (muted, paused, updates stopped); the next `update`
   * brings them back. With `dropPending`, one-shots scheduled to start later (a wipeout's
   * jingle and fanfare) are cut too.
   */
  silence(when: number, dropPending?: boolean): void;
  /** Play is over: everything fades out within a fraction of a second. */
  stopGame(when: number): void;
  stop(when: number): void;
}

export function createSoundscape(options: SoundscapeOptions): Soundscape {
  const { context, effects, noise, random } = options;
  const ambience: Ambience = createAmbience(
    context,
    options.ambience,
    noise,
    random,
    options.start ?? context.currentTime,
  );
  const voices: Voice[] = [];
  let poseArmed = true;
  let lastPoseCueS = Number.NEGATIVE_INFINITY;
  let slot = 0;

  /** Drop finished voices; cut the oldest of the least important if the cap is reached. */
  const makeRoom = (now: number, priority: Priority): boolean => {
    for (let i = voices.length - 1; i >= 0; i--) {
      if ((voices[i] as Voice).endTime <= now) voices.splice(i, 1);
    }
    while (voices.length >= MAX_VOICES) {
      let victim = -1;
      for (let i = 0; i < voices.length; i++) {
        const voice = voices[i] as Voice;
        if (voice.priority > priority) continue;
        const best = victim < 0 ? null : (voices[victim] as Voice);
        if (
          !best ||
          voice.priority < best.priority ||
          (voice.priority === best.priority && voice.startTime < best.startTime)
        ) {
          victim = i;
        }
      }
      // Everything playing matters more than this sound: skip it rather than cut them.
      if (victim < 0) return false;
      (voices[victim] as Voice).cut(now);
      voices.splice(victim, 1);
    }
    return true;
  };

  const play = (
    name: string,
    priority: Priority,
    now: number,
    delayS: number,
    pan: number,
    build: (voice: VoiceBuilder) => void,
  ): void => {
    if (!makeRoom(now, priority)) return;
    const voice = new VoiceBuilder(context, effects, now + delayS, pan, noise, random);
    build(voice);
    voices.push(voice.finish(name, priority));
  };

  const cue = (cueName: Cue, priority: Priority, now: number, delayS = 0, pan = 0): void =>
    play(cueName, priority, now, delayS, pan, (voice) => playCue(voice, cueName));

  const onEvent = (event: GameEvent, now: number, stagger: number): void => {
    switch (event.type) {
      case 'phase':
        if (event.phase === 'takeoff') cue('wave', 2, now);
        else if (event.phase === 'riding') cue('go', 2, now);
        else if (event.phase === 'waiting') poseArmed = true;
        return;
      case 'launch':
        play('launch', 1, now, stagger, panFor(event.x), (voice) =>
          playLaunch(voice, speed01(event.speed)),
        );
        return;
      case 'land': {
        const air = clamp((event.airS - AIR_SMALL_S) / (AIR_BIG_S - AIR_SMALL_S), 0, 1);
        const size = clamp(0.6 * (event.height / HEIGHT_FULL) + 0.4 * air, 0, 1);
        const pan = panFor(event.x);
        play('splash', 1, now, stagger, pan, (voice) => playSplash(voice, size));
        if (event.quality === 'perfect') cue('chime', 1, now, stagger + CHIME_DELAY_S, pan);
        return;
      }
      case 'carve': {
        const strength = (event.points - CARVE_POINTS_MIN) / (CARVE_POINTS_MAX - CARVE_POINTS_MIN);
        play(`carve-${event.where}`, 0, now, stagger, panFor(event.x), (voice) =>
          playCarve(voice, event.where, strength),
        );
        return;
      }
      case 'pickup': {
        const link = Number.isFinite(event.combo) ? Math.max(0, Math.round(event.combo) - 1) : 0;
        const step = Math.min(PICKUP_SCALE.length - 1, link);
        const level = Math.max(PICKUP_FLOOR, 1 - PICKUP_TAPER * link);
        const crab = event.kind === 'crab';
        play(
          `${crab ? 'crab' : 'ding'}-${step}`,
          crab ? 1 : 0,
          now,
          stagger,
          panFor(event.x),
          (voice) => (crab ? playCrab(voice, step, level) : playDing(voice, step, level)),
        );
        return;
      }
      case 'boost':
        play('boost', 1, now, stagger, panFor(event.x), (voice) => playBoost(voice));
        return;
      case 'hazard':
        if (event.kind === 'buoy') {
          play('buoy', 1, now, stagger, panFor(event.x), (voice) => playBuoy(voice));
        } else {
          play('whirlpool', 1, now, stagger, panFor(event.x), (voice) => playWhirlpool(voice));
        }
        return;
      case 'closeCall':
        // Important: it tells the player why the ride goes on, so bursts must not cut it.
        play('closeCall', 2, now, stagger, panFor(event.x), (voice) => playCloseCall(voice));
        return;
      case 'wipeout': {
        const pan = panFor(event.x);
        play('crash', 2, now, 0, pan, (voice) => playCrash(voice));
        cue('jingle', 2, now, JINGLE_DELAY_S);
        if (event.newBest) cue('fanfare', 2, now, FANFARE_DELAY_S);
        return;
      }
    }
  };

  return {
    voices,
    update(game, events, _dtS, when) {
      slot = 0;
      for (const event of events) {
        // Only one-shots that can coincide are staggered; signals keep their timing.
        const stagger = (slot++ % STAGGER_SLOTS) * STAGGER_S;
        onEvent(event, when, stagger);
      }
      // "It sees you": the first moment of the surf pose while waiting.
      const hold = game.phase === 'waiting' ? game.control.poseHold : 0;
      if (hold <= POSE_OFF) poseArmed = true;
      if (poseArmed && hold >= POSE_ON && when - lastPoseCueS >= POSE_MIN_GAP_S) {
        poseArmed = false;
        lastPoseCueS = when;
        cue('pose', 1, when);
      }
      ambience.update(ambienceTargets(game), when);
    },
    silence(when, dropPending = false) {
      ambience.update(SILENCE, when);
      if (!dropPending) return;
      for (let i = voices.length - 1; i >= 0; i--) {
        const voice = voices[i] as Voice;
        if (voice.startTime <= when) continue;
        voice.cut(when);
        voices.splice(i, 1);
      }
    },
    stopGame(when) {
      for (const voice of voices) voice.cut(when);
      voices.length = 0;
      ambience.fade(when, STOP_FADE_S);
      poseArmed = true;
    },
    stop(when) {
      for (const voice of voices) voice.cut(when);
      voices.length = 0;
      ambience.stop(when);
    },
  };
}
