/**
 * The water and air one-shots: the whoosh of a launch, the splash of a landing, the spray of
 * a carve, the white water's rescue and the crash of a wipeout. Each is built from filtered noise bursts (the water)
 * and a low sine thump (the board hitting it), with sizes that follow the event.
 */
import { clamp, noiseBurst, tone, type VoiceBuilder } from './synth';

/** Board leaves the lip: air rushing past, rising in pitch, with a flick of spray. */
export function playLaunch(voice: VoiceBuilder, speed01: number): void {
  const s = clamp(speed01, 0, 1);
  noiseBurst(voice, {
    at: 0,
    level: 0.42 + 0.22 * s,
    attackS: 0.14,
    decayS: 0.34,
    filter: 'bandpass',
    hz: 380,
    toHz: 2400 + 800 * s,
    sweepS: 0.42,
    q: 1.3,
  });
  // The spray thrown off the lip.
  noiseBurst(voice, {
    at: 0,
    level: 0.2,
    attackS: 0.004,
    decayS: 0.2,
    filter: 'highpass',
    hz: 3200,
    q: 0.7,
  });
  // A faint rising tone makes "up" unmistakable without sounding like an instrument.
  tone(voice, {
    type: 'sine',
    hz: 260,
    toHz: 560,
    glideS: 0.32,
    at: 0.02,
    level: 0.07,
    attackS: 0.08,
    decayS: 0.3,
  });
}

/**
 * Board hits the water: a low thump, a sharp slap, a wash of water that darkens as it falls
 * back, and a few droplets. `size01` grows it with the height of the jump.
 */
export function playSplash(voice: VoiceBuilder, size01: number): void {
  const size = clamp(size01, 0, 1);
  tone(voice, {
    type: 'sine',
    hz: 130,
    toHz: 52,
    glideS: 0.12,
    at: 0,
    level: 0.32 + 0.18 * size,
    attackS: 0.003,
    decayS: 0.2,
  });
  noiseBurst(voice, {
    at: 0,
    level: 0.22,
    attackS: 0.001,
    decayS: 0.07,
    filter: 'highpass',
    hz: 1600,
    q: 0.7,
  });
  noiseBurst(voice, {
    at: 0.005,
    level: 0.3 + 0.12 * size,
    attackS: 0.006,
    decayS: 0.45 + 0.35 * size,
    filter: 'lowpass',
    hz: 5200,
    toHz: 650,
    q: 0.9,
    highpassHz: 180,
  });
  droplets(voice, 3 + Math.round(size * 3), 0.08, 0.45);
}

/** Small water drops falling back: tiny rising sine chirps ("plip"). */
function droplets(voice: VoiceBuilder, count: number, fromS: number, toS: number): void {
  for (let i = 0; i < count; i++) {
    const at = fromS + (toS - fromS) * ((i + voice.random()) / count);
    const base = 1100 + 1500 * voice.random();
    tone(voice, {
      type: 'sine',
      hz: base,
      toHz: base * 1.9,
      glideS: 0.025,
      at,
      level: 0.035 + 0.025 * voice.random(),
      attackS: 0.002,
      decayS: 0.035,
    });
  }
}

/**
 * A turn at the top or bottom of the face: a short swish of spray. At the top the spray flies
 * up off the lip (brighter, rising); at the bottom the board digs in (lower, fuller).
 * `strength01` follows the carve's size: a carver makes one about every second, on top of
 * the water's own spray, so only the big ones are loud.
 */
export function playCarve(voice: VoiceBuilder, where: 'top' | 'bottom', strength01 = 1): void {
  const top = where === 'top';
  const s = 0.5 + 0.5 * clamp(strength01, 0, 1);
  noiseBurst(voice, {
    at: 0,
    level: (top ? 0.6 : 0.68) * s,
    attackS: top ? 0.035 : 0.05,
    decayS: top ? 0.24 : 0.3,
    filter: 'bandpass',
    hz: top ? 1900 : 850,
    toHz: top ? 4600 : 2500,
    sweepS: top ? 0.22 : 0.26,
    q: 0.9,
  });
  noiseBurst(voice, {
    at: top ? 0.03 : 0.05,
    level: 0.18 * s,
    attackS: 0.02,
    decayS: 0.18,
    filter: 'highpass',
    hz: top ? 6000 : 4200,
    q: 0.7,
  });
}

/**
 * Over a boost strip: a hard whoosh forward, stronger and quicker than a launch, rising,
 * with a bright zip on top so it reads as "speed", and a soft thump of the board
 * catching it. (The continuous rush layer carries the boost on after it.)
 */
export function playBoost(voice: VoiceBuilder): void {
  noiseBurst(voice, {
    at: 0,
    level: 0.55,
    attackS: 0.03,
    holdS: 0.05,
    decayS: 0.4,
    filter: 'bandpass',
    hz: 500,
    toHz: 4200,
    sweepS: 0.3,
    q: 1.1,
  });
  tone(voice, {
    type: 'triangle',
    hz: 330,
    toHz: 1320,
    glideS: 0.18,
    at: 0.01,
    level: 0.06,
    attackS: 0.02,
    decayS: 0.22,
  });
  tone(voice, {
    type: 'sine',
    hz: 110,
    toHz: 70,
    glideS: 0.1,
    at: 0,
    level: 0.22,
    attackS: 0.004,
    decayS: 0.14,
  });
}

/**
 * A whirlpool takes hold: a sucking slurp, water gurgling down into it. The swirl layer
 * carries on while it holds.
 */
export function playWhirlpool(voice: VoiceBuilder): void {
  noiseBurst(voice, {
    at: 0,
    level: 0.4,
    attackS: 0.06,
    holdS: 0.08,
    decayS: 0.45,
    filter: 'bandpass',
    hz: 1600,
    toHz: 260,
    sweepS: 0.5,
    q: 2.5,
  });
  for (let i = 0; i < 5; i++) {
    const base = 520 - 60 * i + 80 * voice.random();
    tone(voice, {
      type: 'sine',
      hz: base,
      toHz: base * 0.55,
      glideS: 0.06,
      at: 0.08 + 0.08 * i,
      level: 0.05,
      attackS: 0.004,
      decayS: 0.07,
    });
  }
}

/**
 * A buoy: a hollow bonk (a low, quickly falling knock) and the buoy's own bell ringing on,
 * an inharmonic clang that tells what was hit.
 */
export function playBuoy(voice: VoiceBuilder): void {
  tone(voice, {
    type: 'sine',
    hz: 210,
    toHz: 120,
    glideS: 0.08,
    at: 0,
    level: 0.4,
    attackS: 0.002,
    decayS: 0.18,
  });
  noiseBurst(voice, {
    at: 0,
    level: 0.18,
    attackS: 0.001,
    decayS: 0.05,
    filter: 'bandpass',
    hz: 900,
    q: 1.5,
  });
  // A ship's bell: strong partials at non-integer ratios, the higher ones dying first.
  const bellHz = 587;
  const partials: readonly [number, number, number][] = [
    [1, 0.11, 1.4],
    [2.0, 0.05, 0.9],
    [2.76, 0.04, 0.6],
    [5.4, 0.02, 0.3],
  ];
  for (const [ratio, level, decayS] of partials) {
    tone(voice, { type: 'sine', hz: bellHz * ratio, at: 0.02, level, attackS: 0.002, decayS });
  }
}

/**
 * Spat out by the white water (a close call): foam surging forward under the board, a burst
 * of bubbles, and a soft whistle falling a fifth onto A, the "phew" of relief. Rounder and
 * longer than a launch, and not a crash: nothing was lost.
 */
export function playCloseCall(voice: VoiceBuilder): void {
  // The surge: a rush of foam rising past, swelling over the shove.
  noiseBurst(voice, {
    at: 0,
    level: 0.46,
    attackS: 0.1,
    holdS: 0.1,
    decayS: 0.55,
    filter: 'bandpass',
    hz: 300,
    toHz: 1900,
    sweepS: 0.5,
    q: 0.9,
  });
  // The white water churning underneath, settling.
  noiseBurst(voice, {
    at: 0,
    level: 0.3,
    attackS: 0.03,
    holdS: 0.12,
    decayS: 0.6,
    filter: 'lowpass',
    hz: 1100,
    toHz: 280,
    q: 0.7,
    highpassHz: 80,
  });
  // Bubbles: quick rising blips, thick at first and thinning out.
  const count = 14;
  for (let i = 0; i < count; i++) {
    const u = (i + voice.random()) / count;
    const base = 420 + 760 * voice.random();
    tone(voice, {
      type: 'sine',
      hz: base,
      toHz: base * 1.7,
      glideS: 0.03,
      at: 0.03 + 0.55 * u * u,
      level: (0.035 + 0.035 * voice.random()) * (1 - 0.5 * u),
      attackS: 0.003,
      decayS: 0.05,
    });
  }
  // "Phew": E6 sliding down to A5, soft, once the rush has peaked.
  tone(voice, {
    type: 'sine',
    hz: 1318.5,
    toHz: 880,
    glideS: 0.32,
    at: 0.3,
    level: 0.075,
    attackS: 0.05,
    holdS: 0.12,
    decayS: 0.38,
    vibratoHz: 5,
    vibratoCents: 15,
    vibratoDelayS: 0.15,
  });
}

/**
 * Caught by the curl: a big, round splash. Bigger and longer than a landing, with a deep
 * "whump" rather than a hard hit, so it reads as tumbling into water, not as a bang.
 */
export function playCrash(voice: VoiceBuilder): void {
  tone(voice, {
    type: 'sine',
    hz: 95,
    toHz: 40,
    glideS: 0.3,
    at: 0,
    level: 0.45,
    attackS: 0.008,
    decayS: 0.38,
  });
  noiseBurst(voice, {
    at: 0,
    level: 0.18,
    attackS: 0.002,
    decayS: 0.12,
    filter: 'highpass',
    hz: 1300,
    q: 0.7,
  });
  noiseBurst(voice, {
    at: 0.01,
    level: 0.38,
    attackS: 0.03,
    holdS: 0.08,
    decayS: 1.1,
    filter: 'lowpass',
    hz: 4800,
    toHz: 420,
    sweepS: 1.1,
    q: 0.8,
    highpassHz: 120,
  });
  droplets(voice, 7, 0.15, 0.9);
}
