/**
 * The artwork, drawn with the 2D canvas API at init and uploaded as Pixi textures. There
 * are no image files: every shape is described here, sized in world units times the
 * texture density, so it stays crisp on a 1080p TV. Destroyed on dispose.
 */
import { BufferImageSource, CanvasSource, Rectangle, Texture, type TextureSource } from 'pixi.js';
import { type EffectFrameName, effectAtlas, smoothstep, valueNoise } from './art';
import { css, PALETTE as P } from './palette';

/** Texels per world unit for most artwork: a little over 1:1 so it survives a slight zoom. */
const DENSITY = 2;

/** The surfboard, world units. The board's middle bottom touches the water at (0, 0). */
export const BOARD = {
  length: 290,
  /** Thickness of the near rail at the middle. */
  thickness: 15,
  /** How much of the deck shows, seen from a little above. */
  deck: 14,
  /** Where the feet stand: the deck's centre line above the board's bottom. */
  standY: -22,
  /** Texture size and where the board's middle bottom sits in it, world units. */
  width: 312,
  height: 72,
  originX: 156,
  originY: 50,
} as const;

/** The placeholder surfer's texture, world units; feet at `originY`. */
export const DUMMY = { width: 300, height: 360, originX: 150, originY: 344, height0: 320 } as const;

export interface StageTextures {
  board: Texture;
  /** The near half of the deck and the near rail, drawn over the feet. */
  boardFront: Texture;
  shadow: Texture;
  wake: Texture;
  star: Texture;
  /** Sea creatures to collect: a scallop (common) and a crab (rarer, worth more). */
  clam: Texture;
  crab: Texture;
  /** Hazards: a striped buoy, and a whirlpool's dark funnel and its foam arms. */
  buoy: Texture;
  whirlpool: Texture;
  whirlArms: Texture;
  /** One chevron of a boost strip, tiled along it. */
  chevron: Texture;
  glow: Texture;
  clouds: Texture[];
  /** A green island with a lighthouse, and a hazy far headland. */
  island: Texture;
  headland: Texture;
  dummy: Texture;
  pictogram: Texture;
  /** A horizontal fade from opaque at the left edge to clear, for the curl warning. */
  edgeFade: Texture;
  effects: Record<EffectFrameName, Texture>;
  destroy(): void;
}

function makeCanvas(width: number, height: number): [HTMLCanvasElement, CanvasRenderingContext2D] {
  const canvas = document.createElement('canvas');
  canvas.width = Math.ceil(width);
  canvas.height = Math.ceil(height);
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('2D canvas unavailable');
  return [canvas, ctx];
}

// ---------------------------------------------------------------------------
// Surfboard
// ---------------------------------------------------------------------------

interface BoardProfile {
  x: number;
  bottom: number;
  rail: number;
  middle: number;
  far: number;
}

/** The board's outline sampled along its length, nose to the right. */
function boardProfile(): BoardProfile[] {
  const { length, thickness, deck } = BOARD;
  const points: BoardProfile[] = [];
  const steps = 80;
  for (let i = 0; i <= steps; i++) {
    // From a squared-off tail (-0.93) to a pointed nose (1).
    const t = -0.93 + (1.93 * i) / steps;
    const plan = Math.sqrt(Math.max(0, 1 - t * t)) * (1 - 0.3 * Math.max(0, t));
    const rocker = 13 * Math.max(0, t) ** 2.4 + 3 * Math.max(0, -t) ** 2;
    const bottom = -rocker;
    const rail = bottom - thickness * (0.35 + 0.65 * Math.min(1, plan * 1.3));
    const far = rail - deck * plan;
    points.push({ x: (t * length) / 2, bottom, rail, middle: (rail + far) / 2, far });
  }
  return points;
}

function drawBoard(front: boolean): HTMLCanvasElement {
  const [canvas, ctx] = makeCanvas(BOARD.width * DENSITY, BOARD.height * DENSITY);
  ctx.scale(DENSITY, DENSITY);
  ctx.translate(BOARD.originX, BOARD.originY);
  ctx.lineJoin = 'round';
  const profile = boardProfile();
  const first = profile[0] as BoardProfile;
  const last = profile[profile.length - 1] as BoardProfile;

  const band = (top: (p: BoardProfile) => number, bottom: (p: BoardProfile) => number) => {
    ctx.beginPath();
    ctx.moveTo(first.x, bottom(first));
    for (const p of profile) ctx.lineTo(p.x, bottom(p));
    for (let i = profile.length - 1; i >= 0; i--) {
      const p = profile[i] as BoardProfile;
      ctx.lineTo(p.x, top(p));
    }
    ctx.closePath();
  };

  if (!front) {
    // The fin under the tail, then the whole silhouette with a dark outline.
    const tail = -BOARD.length / 2;
    ctx.beginPath();
    ctx.moveTo(tail + 22, -3);
    ctx.quadraticCurveTo(tail + 18, 11, tail + 9, 17);
    ctx.quadraticCurveTo(tail + 28, 13, tail + 38, -2);
    ctx.closePath();
    ctx.fillStyle = css(P.textStroke);
    ctx.fill();

    band(
      (p) => p.far,
      (p) => p.bottom,
    );
    ctx.lineWidth = 3;
    ctx.strokeStyle = css(P.textStroke);
    ctx.stroke();

    // The deck: pale, with the far rail in shade and a stringer down the middle.
    const deck = ctx.createLinearGradient(0, -36, 0, -15);
    deck.addColorStop(0, css(0xf3dccb));
    deck.addColorStop(1, css(P.boardDeck));
    band(
      (p) => p.far,
      (p) => p.rail,
    );
    ctx.fillStyle = deck;
    ctx.fill();
    ctx.beginPath();
    for (const p of profile) ctx.lineTo(p.x, p.middle + 0.5);
    ctx.lineWidth = 1.2;
    ctx.strokeStyle = css(P.boardDark, 0.45);
    ctx.stroke();
  }

  // The near rail: coral with a yellow racing stripe and a highlight along its top.
  const rail = ctx.createLinearGradient(0, -18, 0, 0);
  rail.addColorStop(0, css(P.board));
  rail.addColorStop(1, css(P.boardDark));
  band(
    (p) => p.rail,
    (p) => p.bottom,
  );
  ctx.fillStyle = rail;
  ctx.fill();
  band(
    (p) => p.rail + (p.bottom - p.rail) * 0.38,
    (p) => p.rail + (p.bottom - p.rail) * 0.62,
  );
  ctx.fillStyle = css(P.boardStripe);
  ctx.fill();
  ctx.beginPath();
  for (const p of profile) ctx.lineTo(p.x, p.rail + 1);
  ctx.lineWidth = 1.5;
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.55)';
  ctx.stroke();

  if (front) {
    // Over the feet: the near half of the deck, so they look planted on it.
    band(
      (p) => p.middle,
      (p) => p.rail,
    );
    ctx.fillStyle = css(P.boardDeck);
    ctx.fill();
    // Outline only along the bottom and the nose, where this layer is the edge.
    ctx.beginPath();
    ctx.moveTo(first.x, first.rail);
    ctx.lineTo(first.x, first.bottom);
    for (const p of profile) ctx.lineTo(p.x, p.bottom);
    ctx.lineTo(last.x, last.far);
    ctx.lineWidth = 3;
    ctx.strokeStyle = css(P.textStroke);
    ctx.stroke();
  }
  return canvas;
}

// ---------------------------------------------------------------------------
// Water marks
// ---------------------------------------------------------------------------

/** A soft dark ellipse. */
function drawShadow(): HTMLCanvasElement {
  const [canvas, ctx] = makeCanvas(256, 64);
  ctx.translate(128, 32);
  ctx.scale(1, 0.25);
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, 124);
  g.addColorStop(0, 'rgba(4, 30, 48, 0.75)');
  g.addColorStop(0.55, 'rgba(4, 30, 48, 0.4)');
  g.addColorStop(1, 'rgba(4, 30, 48, 0)');
  ctx.fillStyle = g;
  ctx.fillRect(-128, -128, 256, 256);
  return canvas;
}

/**
 * The wake as a strip: `u` is the age of the trail (0 fresh under the board, 1 gone), `v`
 * runs across it. Fresh, it is a solid white line with a soft edge; it breaks up into lacy
 * foam as it ages and fades out. Value noise stretched along the trail keeps the holes
 * long, like foam drawn out by the water, not speckle.
 */
function drawWake(): HTMLCanvasElement {
  const width = 256;
  const height = 64;
  const [canvas, ctx] = makeCanvas(width, height);
  const image = ctx.createImageData(width, height);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const u = x / (width - 1);
      const v = ((y + 0.5) / height) * 2 - 1;
      // A lumpy edge, so the outline is never a ruled line.
      const edge = 0.8 + 0.2 * valueNoise(x / 9, y > height / 2 ? 3 : 7, 31);
      const across = smoothstep(edge, edge - 0.35, Math.abs(v));
      const lace = valueNoise(x / 14, y / 5, 21) * 0.65 + valueNoise(x / 5, y / 2.5, 22) * 0.35;
      // Holes open up with age.
      const open = smoothstep(0.25 + 0.55 * u, 0.4 + 0.55 * u, lace);
      const fade = (1 - u) ** 1.2 * smoothstep(0, 0.04, u + 0.02);
      const a = Math.min(1, across * (0.25 + 0.75 * open) * fade * 1.1);
      const i = (y * width + x) * 4;
      image.data[i] = 255;
      image.data[i + 1] = 255;
      image.data[i + 2] = 255;
      image.data[i + 3] = Math.round(a * 255);
    }
  }
  ctx.putImageData(image, 0, 0);
  return canvas;
}

// ---------------------------------------------------------------------------
// Pickups
// ---------------------------------------------------------------------------

function starPath(ctx: CanvasRenderingContext2D, outer: number, inner: number): void {
  ctx.beginPath();
  for (let i = 0; i < 10; i++) {
    const r = i % 2 === 0 ? outer : inner;
    const a = -Math.PI / 2 + (i * Math.PI) / 5;
    ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
  }
  ctx.closePath();
}

/** A chubby gold star with a white sticker edge and a little face. 1 texel = 0.5 unit. */
function drawStar(): HTMLCanvasElement {
  const size = 192;
  const [canvas, ctx] = makeCanvas(size, size);
  ctx.translate(size / 2, size / 2 + 4);
  ctx.lineJoin = 'round';
  const outer = 72;
  const inner = 38;
  ctx.shadowColor = 'rgba(10, 40, 70, 0.35)';
  ctx.shadowBlur = 8;
  ctx.shadowOffsetY = 4;
  starPath(ctx, outer, inner);
  ctx.lineWidth = 18;
  ctx.strokeStyle = '#ffffff';
  ctx.stroke();
  ctx.shadowColor = 'transparent';
  const fill = ctx.createLinearGradient(0, -outer, 0, outer);
  fill.addColorStop(0, css(P.starLight));
  fill.addColorStop(0.45, css(P.star));
  fill.addColorStop(1, css(P.starEdge));
  starPath(ctx, outer, inner);
  ctx.fillStyle = fill;
  ctx.fill();
  ctx.lineWidth = 5;
  ctx.strokeStyle = css(P.starEdge);
  ctx.stroke();
  // A soft shine on the upper left arm.
  ctx.beginPath();
  ctx.ellipse(-20, -26, 12, 7, -0.7, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(255, 255, 255, 0.75)';
  ctx.fill();
  // Eyes and a smile.
  ctx.fillStyle = css(P.textStroke);
  for (const side of [-1, 1]) {
    ctx.beginPath();
    ctx.ellipse(side * 13, 2, 5, 8, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.beginPath();
  ctx.arc(0, 12, 11, 0.2 * Math.PI, 0.8 * Math.PI);
  ctx.lineWidth = 4.5;
  ctx.lineCap = 'round';
  ctx.strokeStyle = css(P.textStroke);
  ctx.stroke();
  return canvas;
}

/** A sticker edge and soft drop shadow round whatever `shape` traces, then its fill. */
function sticker(ctx: CanvasRenderingContext2D, shape: () => void, edge = 16): void {
  ctx.save();
  ctx.shadowColor = 'rgba(10, 40, 70, 0.35)';
  ctx.shadowBlur = 8;
  ctx.shadowOffsetY = 4;
  shape();
  ctx.lineWidth = edge;
  ctx.lineJoin = 'round';
  ctx.strokeStyle = '#ffffff';
  ctx.stroke();
  ctx.fillStyle = '#ffffff';
  ctx.fill();
  ctx.restore();
}

/** Two friendly eyes and a smile, like the stars had: collectables have faces. */
function face(ctx: CanvasRenderingContext2D, x: number, y: number, spread: number, size = 1) {
  ctx.fillStyle = css(P.textStroke);
  for (const side of [-1, 1]) {
    ctx.beginPath();
    ctx.ellipse(x + side * spread, y, 5 * size, 7.5 * size, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.fillStyle = '#ffffff';
    ctx.arc(x + side * spread + 1.6 * size, y - 2.6 * size, 1.9 * size, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = css(P.textStroke);
  }
  ctx.beginPath();
  ctx.arc(x, y + 9 * size, 9 * size, 0.18 * Math.PI, 0.82 * Math.PI);
  ctx.lineWidth = 4 * size;
  ctx.lineCap = 'round';
  ctx.strokeStyle = css(P.textStroke);
  ctx.stroke();
  // Rosy cheeks.
  ctx.fillStyle = 'rgba(255, 110, 120, 0.45)';
  for (const side of [-1, 1]) {
    ctx.beginPath();
    ctx.ellipse(
      x + side * (spread + 11 * size),
      y + 9 * size,
      6 * size,
      4 * size,
      0,
      0,
      Math.PI * 2,
    );
    ctx.fill();
  }
}

/** A golden scallop shell with a face. 1 texel = 0.5 unit, same size as the old star. */
function drawClam(): HTMLCanvasElement {
  const size = 192;
  const [canvas, ctx] = makeCanvas(size, size);
  ctx.translate(size / 2, size / 2 + 34);
  const ribs = 9;
  const rim = (a: number) => 70 + 5 * Math.abs(Math.sin(((a + Math.PI) * ribs) / 1.0 / 2));
  const shell = () => {
    ctx.beginPath();
    const from = Math.PI * 1.06;
    const to = Math.PI * 1.94;
    for (let i = 0; i <= 90; i++) {
      const a = from + ((to - from) * i) / 90;
      const r = rim(a);
      ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r * 0.92);
    }
    // The hinge, with its two little ears.
    ctx.lineTo(24, 2);
    ctx.lineTo(30, 16);
    ctx.lineTo(-30, 16);
    ctx.lineTo(-24, 2);
    ctx.closePath();
  };
  sticker(ctx, shell, 18);
  const fill = ctx.createLinearGradient(0, -70, 0, 16);
  fill.addColorStop(0, css(0xffe58a));
  fill.addColorStop(0.55, css(0xffbf4d));
  fill.addColorStop(1, css(0xf08a3a));
  shell();
  ctx.fillStyle = fill;
  ctx.fill();
  // Ribs fanning out from the hinge.
  ctx.save();
  shell();
  ctx.clip();
  ctx.strokeStyle = 'rgba(200, 100, 30, 0.45)';
  ctx.lineWidth = 3;
  for (let i = 1; i < ribs; i++) {
    const a = Math.PI * (1.06 + (0.88 * i) / ribs);
    ctx.beginPath();
    ctx.moveTo(0, 6);
    ctx.lineTo(Math.cos(a) * 80, Math.sin(a) * 74);
    ctx.stroke();
  }
  ctx.restore();
  shell();
  ctx.lineWidth = 5;
  ctx.lineJoin = 'round';
  ctx.strokeStyle = css(0xd9702a);
  ctx.stroke();
  // Shine.
  ctx.beginPath();
  ctx.ellipse(-26, -46, 13, 7, -0.6, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';
  ctx.fill();
  face(ctx, 0, -28, 15);
  return canvas;
}

/** A chunky orange crab, claws up, eyes on stalks. 1 texel = 0.5 unit. */
function drawCrab(): HTMLCanvasElement {
  const size = 192;
  const [canvas, ctx] = makeCanvas(size, size);
  ctx.translate(size / 2, size / 2 + 16);
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';
  const legs = () => {
    ctx.beginPath();
    for (const side of [-1, 1]) {
      for (let i = 0; i < 3; i++) {
        const y = 4 + i * 11;
        ctx.moveTo(side * 40, y);
        ctx.quadraticCurveTo(side * 64, y + 2, side * (70 + 4 * i), y + 22);
      }
    }
  };
  const arms = () => {
    ctx.beginPath();
    for (const side of [-1, 1]) {
      ctx.moveTo(side * 38, -12);
      ctx.quadraticCurveTo(side * 62, -26, side * 58, -46);
    }
  };
  const claw = (side: number) => {
    // A chunky pincer: a round palm with an open notch at the top.
    ctx.beginPath();
    ctx.ellipse(side * 58, -58, 21, 19, side * 0.25, 0, Math.PI * 2);
  };
  const body = () => {
    ctx.beginPath();
    ctx.ellipse(0, 4, 48, 34, 0, 0, Math.PI * 2);
  };
  const stalks = () => {
    ctx.beginPath();
    for (const side of [-1, 1]) {
      ctx.moveTo(side * 14, -22);
      ctx.lineTo(side * 18, -42);
    }
  };
  // Sticker edge round everything.
  ctx.save();
  ctx.shadowColor = 'rgba(10, 40, 70, 0.35)';
  ctx.shadowBlur = 8;
  ctx.shadowOffsetY = 4;
  ctx.strokeStyle = '#ffffff';
  ctx.fillStyle = '#ffffff';
  legs();
  ctx.lineWidth = 22;
  ctx.stroke();
  arms();
  ctx.lineWidth = 26;
  ctx.stroke();
  stalks();
  ctx.lineWidth = 22;
  ctx.stroke();
  for (const side of [-1, 1]) {
    claw(side);
    ctx.lineWidth = 18;
    ctx.stroke();
    ctx.fill();
    ctx.beginPath();
    ctx.arc(side * 18, -46, 19, 0, Math.PI * 2);
    ctx.fill();
  }
  body();
  ctx.lineWidth = 18;
  ctx.stroke();
  ctx.fill();
  ctx.restore();

  const shell = ctx.createLinearGradient(0, -80, 0, 40);
  shell.addColorStop(0, css(0xffa760));
  shell.addColorStop(0.55, css(0xff7a3d));
  shell.addColorStop(1, css(0xe0552d));
  const rim = css(0xc4441f);
  legs();
  ctx.lineWidth = 8;
  ctx.strokeStyle = rim;
  ctx.stroke();
  arms();
  ctx.lineWidth = 12;
  ctx.strokeStyle = shell;
  ctx.stroke();
  stalks();
  ctx.lineWidth = 6;
  ctx.strokeStyle = rim;
  ctx.stroke();
  for (const side of [-1, 1]) {
    claw(side);
    ctx.fillStyle = shell;
    ctx.fill();
    ctx.lineWidth = 4;
    ctx.strokeStyle = rim;
    ctx.stroke();
    // The pincer's open notch.
    ctx.beginPath();
    ctx.moveTo(side * 54, -60);
    ctx.lineTo(side * 64, -80);
    ctx.lineTo(side * 72, -66);
    ctx.closePath();
    ctx.fillStyle = '#ffffff';
    ctx.fill();
    // Eyes on stalks.
    ctx.beginPath();
    ctx.arc(side * 18, -46, 11, 0, Math.PI * 2);
    ctx.fillStyle = '#ffffff';
    ctx.fill();
    ctx.lineWidth = 3.5;
    ctx.strokeStyle = rim;
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(side * 18 + side * 1.5, -45, 5.5, 0, Math.PI * 2);
    ctx.fillStyle = css(P.textStroke);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(side * 18 + side * 1.5 + 1.8, -47.5, 1.8, 0, Math.PI * 2);
    ctx.fillStyle = '#ffffff';
    ctx.fill();
  }
  body();
  ctx.fillStyle = shell;
  ctx.fill();
  ctx.lineWidth = 4;
  ctx.strokeStyle = rim;
  ctx.stroke();
  // Shine, a big smile and rosy cheeks.
  ctx.beginPath();
  ctx.ellipse(-20, -12, 12, 6, -0.4, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(255, 255, 255, 0.6)';
  ctx.fill();
  ctx.beginPath();
  ctx.arc(0, 6, 14, 0.15 * Math.PI, 0.85 * Math.PI);
  ctx.lineWidth = 4.5;
  ctx.strokeStyle = css(P.textStroke);
  ctx.stroke();
  ctx.fillStyle = 'rgba(255, 110, 120, 0.5)';
  for (const side of [-1, 1]) {
    ctx.beginPath();
    ctx.ellipse(side * 26, 12, 7, 4.5, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  return canvas;
}

/** A red-and-white striped buoy with a lamp on top. No face: hazards are things. */
function drawBuoy(): HTMLCanvasElement {
  const width = 128;
  const height = 192;
  const [canvas, ctx] = makeCanvas(width, height);
  ctx.translate(width / 2, height - 30);
  ctx.lineJoin = 'round';
  const body = () => {
    ctx.beginPath();
    ctx.moveTo(-40, 0);
    ctx.quadraticCurveTo(-44, -60, -26, -112);
    ctx.lineTo(26, -112);
    ctx.quadraticCurveTo(44, -60, 40, 0);
    ctx.quadraticCurveTo(0, 14, -40, 0);
    ctx.closePath();
  };
  // Lamp cage on top.
  ctx.fillStyle = css(P.textStroke);
  ctx.fillRect(-14, -140, 28, 30);
  ctx.beginPath();
  ctx.arc(0, -140, 14, Math.PI, 0);
  ctx.fill();
  ctx.fillStyle = css(0xffe36b);
  ctx.beginPath();
  ctx.arc(0, -134, 8, 0, Math.PI * 2);
  ctx.fill();
  body();
  ctx.fillStyle = '#ffffff';
  ctx.fill();
  ctx.save();
  body();
  ctx.clip();
  ctx.fillStyle = css(0xe8323c);
  for (const y of [-112, -62, -14]) ctx.fillRect(-60, y, 120, 26);
  // Rounded shading: dark on the left, a shine on the right.
  const shade = ctx.createLinearGradient(-44, 0, 44, 0);
  shade.addColorStop(0, 'rgba(10, 40, 70, 0.35)');
  shade.addColorStop(0.55, 'rgba(10, 40, 70, 0)');
  shade.addColorStop(0.75, 'rgba(255, 255, 255, 0.35)');
  shade.addColorStop(1, 'rgba(10, 40, 70, 0.15)');
  ctx.fillStyle = shade;
  ctx.fillRect(-60, -120, 120, 140);
  ctx.restore();
  body();
  ctx.lineWidth = 5;
  ctx.strokeStyle = css(P.textStroke);
  ctx.stroke();
  return canvas;
}

/** The whirlpool's funnel: dark in the middle, fading into the face. Seen face on. */
function drawWhirlpool(): HTMLCanvasElement {
  const size = 256;
  const [canvas, ctx] = makeCanvas(size, size);
  const g = ctx.createRadialGradient(128, 128, 0, 128, 128, 128);
  g.addColorStop(0, 'rgba(2, 16, 28, 1)');
  g.addColorStop(0.3, 'rgba(4, 32, 50, 0.92)');
  g.addColorStop(0.65, 'rgba(8, 56, 80, 0.55)');
  g.addColorStop(1, 'rgba(10, 79, 110, 0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  return canvas;
}

/** Foam arms spiralling into the funnel; spun over it at draw time. */
function drawWhirlArms(): HTMLCanvasElement {
  const size = 256;
  const [canvas, ctx] = makeCanvas(size, size);
  ctx.translate(128, 128);
  ctx.lineCap = 'round';
  const arms = 4;
  for (let k = 0; k < arms; k++) {
    const base = (k / arms) * Math.PI * 2;
    for (let i = 0; i < 60; i++) {
      // A logarithmic spiral from the rim in towards the eye.
      const t0 = i / 60;
      const t1 = (i + 1) / 60;
      const r0 = 122 * Math.exp(-2.6 * t0);
      const r1 = 122 * Math.exp(-2.6 * t1);
      const a0 = base + t0 * 4.2;
      const a1 = base + t1 * 4.2;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a0) * r0, Math.sin(a0) * r0);
      ctx.lineTo(Math.cos(a1) * r1, Math.sin(a1) * r1);
      ctx.lineWidth = 3 + 12 * (1 - t0) * Math.sin(Math.PI * Math.min(1, t0 * 1.4 + 0.1));
      const alpha = Math.sin(Math.PI * Math.min(1, t0 * 1.15)) * 0.85;
      ctx.strokeStyle = `rgba(255, 255, 255, ${alpha.toFixed(3)})`;
      ctx.stroke();
    }
  }
  return canvas;
}

/** One chevron pointing right, gold with a white-hot core; tiled along a boost strip. */
function drawChevron(): HTMLCanvasElement {
  const [canvas, ctx] = makeCanvas(96, 80);
  ctx.translate(48, 40);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  const path = () => {
    ctx.beginPath();
    ctx.moveTo(-16, -24);
    ctx.lineTo(12, 0);
    ctx.lineTo(-16, 24);
  };
  ctx.shadowColor = 'rgba(255, 200, 60, 0.9)';
  ctx.shadowBlur = 14;
  path();
  ctx.lineWidth = 20;
  ctx.strokeStyle = css(P.textStroke, 0.55);
  ctx.stroke();
  path();
  ctx.lineWidth = 15;
  ctx.strokeStyle = css(P.star);
  ctx.stroke();
  ctx.shadowColor = 'transparent';
  path();
  ctx.lineWidth = 6;
  ctx.strokeStyle = css(0xfffbe0);
  ctx.stroke();
  return canvas;
}

/** A warm round glow, drawn additively behind stars and the sun-lit lip. */
function drawGlow(): HTMLCanvasElement {
  const [canvas, ctx] = makeCanvas(128, 128);
  const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  g.addColorStop(0, 'rgba(255, 246, 190, 0.9)');
  g.addColorStop(0.35, 'rgba(255, 220, 120, 0.4)');
  g.addColorStop(1, 'rgba(255, 210, 90, 0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 128, 128);
  return canvas;
}

// ---------------------------------------------------------------------------
// Sky and land
// ---------------------------------------------------------------------------

/** A stylised cumulus: a shaded base with sunlit puffs on top. 1 texel = 0.5 unit. */
function drawCloud(seed: number, puffs: number): HTMLCanvasElement {
  const width = 640;
  const height = 240;
  const [canvas, ctx] = makeCanvas(width, height);
  const base = height - 40;
  const circles: [number, number, number][] = [];
  for (let i = 0; i < puffs; i++) {
    const t = (i + 0.5) / puffs;
    const middle = 1 - Math.abs(t - 0.5) * 2;
    const r = 34 + 56 * middle ** 0.7 * (0.75 + 0.5 * valueNoise(i * 1.7, seed, seed));
    const x = 70 + t * (width - 140) + (valueNoise(i, seed * 3, 5) - 0.5) * 30;
    circles.push([x, base - r * 0.55, r]);
  }
  const shape = (dx: number, dy: number, grow: number) => {
    ctx.beginPath();
    for (const [x, y, r] of circles) {
      ctx.moveTo(x + dx + r + grow, y + dy);
      ctx.arc(x + dx, y + dy, r + grow, 0, Math.PI * 2);
    }
    // A flat bottom.
    ctx.rect(
      circles[0]?.[0] ?? 70,
      base - 30,
      (circles.at(-1)?.[0] ?? 0) - (circles[0]?.[0] ?? 0),
      30,
    );
  };
  ctx.save();
  shape(0, 0, 0);
  ctx.clip();
  ctx.fillStyle = css(P.cloudShade);
  ctx.fillRect(0, 0, width, base);
  // Sunlit tops: the same puffs nudged up and in.
  ctx.save();
  ctx.beginPath();
  for (const [x, y, r] of circles) {
    ctx.moveTo(x + 6 + r * 0.9, y - r * 0.18);
    ctx.arc(x + 6, y - r * 0.18, r * 0.9, 0, Math.PI * 2);
  }
  ctx.fillStyle = css(P.cloud);
  ctx.fill();
  ctx.restore();
  // A cooler underside.
  const under = ctx.createLinearGradient(0, base - 40, 0, base);
  under.addColorStop(0, css(P.cloudDeep, 0));
  under.addColorStop(1, css(P.cloudDeep, 0.6));
  ctx.fillStyle = under;
  ctx.fillRect(0, base - 40, width, 40);
  ctx.restore();
  // Cut the flat bottom off below the base.
  ctx.clearRect(0, base, width, height - base);
  return canvas;
}

/** Rolling green hills with palms and a lighthouse, softened by distance. 1 texel = 0.5 unit. */
function drawIsland(): HTMLCanvasElement {
  const width = 1400;
  const height = 300;
  const [canvas, ctx] = makeCanvas(width, height);
  const ground = height - 6;
  const hill = (x: number) => {
    const t = x / width;
    const body = Math.sin(Math.PI * Math.min(1, Math.max(0, (t - 0.04) / 0.92))) ** 0.8;
    return (
      ground - body * (120 + 60 * Math.sin(t * 9.0 + 1) * 0.5 + 40 * Math.sin(t * 23 + 2) * 0.3)
    );
  };
  // Far ridge.
  ctx.beginPath();
  ctx.moveTo(0, ground);
  for (let x = 0; x <= width; x += 8) {
    const t = x / width;
    const body = Math.sin(Math.PI * Math.min(1, Math.max(0, (t - 0.22) / 0.6))) ** 1.2;
    ctx.lineTo(x, ground - body * 205);
  }
  ctx.lineTo(width, ground);
  ctx.fillStyle = css(P.landFar);
  ctx.fill();
  // Near hills.
  const green = ctx.createLinearGradient(0, ground - 180, 0, ground);
  green.addColorStop(0, css(0x6cb9a2));
  green.addColorStop(1, css(P.landGreen));
  ctx.beginPath();
  ctx.moveTo(0, ground);
  for (let x = 0; x <= width; x += 6) ctx.lineTo(x, hill(x));
  ctx.lineTo(width, ground);
  ctx.fillStyle = green;
  ctx.fill();
  // Palms on the slopes.
  const palm = (x: number, scale: number, lean: number) => {
    const y = hill(x) + 6;
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(scale, scale);
    ctx.strokeStyle = css(0x3f7f73);
    ctx.lineCap = 'round';
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.quadraticCurveTo(lean * 10, -30, lean * 18, -62);
    ctx.stroke();
    ctx.translate(lean * 18, -62);
    ctx.lineWidth = 6;
    for (let i = 0; i < 6; i++) {
      const a = -Math.PI / 2 + (i - 2.5) * 0.55;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(
        Math.cos(a) * 22,
        Math.sin(a) * 22 - 8,
        Math.cos(a) * 36,
        Math.sin(a) * 36 + 10,
      );
      ctx.stroke();
    }
    ctx.restore();
  };
  palm(260, 1, 0.6);
  palm(300, 0.8, -0.4);
  palm(820, 1.1, 0.5);
  palm(870, 0.85, -0.2);
  palm(1010, 0.9, 0.7);
  // A little lighthouse on the right shoulder.
  const lx = 1160;
  const ly = hill(lx) + 4;
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.moveTo(lx - 12, ly);
  ctx.lineTo(lx - 8, ly - 70);
  ctx.lineTo(lx + 8, ly - 70);
  ctx.lineTo(lx + 12, ly);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = css(P.warm);
  ctx.fillRect(lx - 10.5, ly - 30, 21, 12);
  ctx.fillRect(lx - 9, ly - 58, 18, 10);
  ctx.fillStyle = css(P.textStroke, 0.8);
  ctx.fillRect(lx - 10, ly - 82, 20, 12);
  ctx.beginPath();
  ctx.arc(lx, ly - 82, 10, Math.PI, 0);
  ctx.fill();
  // A pale beach line along the water.
  ctx.fillStyle = css(P.landSand);
  ctx.beginPath();
  ctx.moveTo(40, ground + 2);
  for (let x = 40; x <= width - 40; x += 10) ctx.lineTo(x, ground - 5 - 3 * Math.sin(x * 0.02));
  ctx.lineTo(width - 40, ground + 2);
  ctx.fill();
  // Distance haze: everything fades towards the sky colour at the bottom.
  const haze = ctx.createLinearGradient(0, 0, 0, height);
  haze.addColorStop(0, css(P.skyHorizon, 0.25));
  haze.addColorStop(1, css(P.skyHorizon, 0.5));
  ctx.globalCompositeOperation = 'source-atop';
  ctx.fillStyle = haze;
  ctx.fillRect(0, 0, width, height);
  return canvas;
}

/** A long, low, very hazy headland. 1 texel = 0.5 unit. */
function drawHeadland(): HTMLCanvasElement {
  const width = 1200;
  const height = 160;
  const [canvas, ctx] = makeCanvas(width, height);
  const ground = height - 2;
  ctx.beginPath();
  ctx.moveTo(0, ground);
  for (let x = 0; x <= width; x += 8) {
    const t = x / width;
    const rise = Math.min(1, t / 0.25) ** 0.6 * (1 - Math.max(0, (t - 0.7) / 0.3)) ** 2;
    ctx.lineTo(x, ground - rise * (90 + 40 * Math.sin(t * 13) * 0.4));
  }
  ctx.lineTo(width, ground);
  ctx.fillStyle = css(mix(P.landFar, P.skyHorizon, 0.45));
  ctx.fill();
  return canvas;
}

function mix(a: number, b: number, t: number): number {
  const ch = (shift: number) =>
    Math.round(((a >> shift) & 255) + (((b >> shift) & 255) - ((a >> shift) & 255)) * t);
  return (ch(16) << 16) | (ch(8) << 8) | ch(0);
}

// ---------------------------------------------------------------------------
// The placeholder surfer and the HUD pictogram
// ---------------------------------------------------------------------------

/**
 * A friendly cartoon surfer, arms out, knees bent, facing us like the player does: what
 * stands on the board while nobody is tracked. White sticker edge like the cutout's.
 */
function drawDummy(): HTMLCanvasElement {
  const s = 1.25;
  const [canvas, ctx] = makeCanvas(DUMMY.width * s, DUMMY.height * s);
  ctx.scale(s, s);
  ctx.translate(DUMMY.originX, DUMMY.originY);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  const limbs = (width: number, color: string) => {
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    // Legs: feet apart on the deck, knees bent outwards.
    ctx.beginPath();
    ctx.moveTo(-58, -6);
    ctx.quadraticCurveTo(-56, -70, -22, -136);
    ctx.moveTo(58, -6);
    ctx.quadraticCurveTo(56, -70, 22, -136);
    // Arms: out to the sides, a little bent, like the pose the game asks for.
    ctx.moveTo(-30, -222);
    ctx.quadraticCurveTo(-80, -232, -128, -214);
    ctx.moveTo(30, -222);
    ctx.quadraticCurveTo(80, -232, 128, -214);
    ctx.stroke();
  };
  const body = (grow: number) => {
    // Torso.
    ctx.beginPath();
    ctx.moveTo(-34 - grow, -232 - grow);
    ctx.quadraticCurveTo(0, -244 - grow, 34 + grow, -232 - grow);
    ctx.lineTo(30 + grow, -130 + grow);
    ctx.quadraticCurveTo(0, -122 + grow, -30 - grow, -130 + grow);
    ctx.closePath();
  };
  const head = (grow: number) => {
    ctx.beginPath();
    ctx.arc(0, -282, 34 + grow, 0, Math.PI * 2);
  };

  // The sticker edge and its shadow: everything drawn fat in white first.
  ctx.save();
  ctx.shadowColor = 'rgba(8, 40, 64, 0.35)';
  ctx.shadowBlur = 10;
  ctx.shadowOffsetX = 4;
  ctx.shadowOffsetY = 6;
  limbs(38, '#ffffff');
  ctx.fillStyle = '#ffffff';
  body(10);
  ctx.fill();
  head(10);
  ctx.fill();
  ctx.beginPath();
  for (const x of [-132, 132]) {
    ctx.moveTo(x + 20, -214);
    ctx.arc(x, -214, 20, 0, Math.PI * 2);
  }
  ctx.fill();
  ctx.restore();

  // Skin.
  limbs(22, css(P.skin));
  ctx.fillStyle = css(P.skin);
  ctx.beginPath();
  for (const x of [-132, 132]) {
    ctx.moveTo(x + 12, -214);
    ctx.arc(x, -214, 12, 0, Math.PI * 2);
  }
  ctx.fill();
  // Board shorts over the thighs.
  ctx.fillStyle = css(P.shorts);
  ctx.beginPath();
  ctx.moveTo(-32, -140);
  ctx.lineTo(32, -140);
  ctx.lineTo(48, -88);
  ctx.lineTo(10, -84);
  ctx.lineTo(0, -108);
  ctx.lineTo(-10, -84);
  ctx.lineTo(-48, -88);
  ctx.closePath();
  ctx.fill();
  // Rash vest with a stripe.
  body(0);
  ctx.fillStyle = css(P.vest);
  ctx.fill();
  ctx.fillStyle = css(P.boardStripe);
  ctx.fillRect(-32, -196, 64, 12);
  // Sleeves.
  ctx.strokeStyle = css(P.vest);
  ctx.lineWidth = 26;
  ctx.beginPath();
  ctx.moveTo(-28, -224);
  ctx.lineTo(-52, -228);
  ctx.moveTo(28, -224);
  ctx.lineTo(52, -228);
  ctx.stroke();
  // Head: face, hair, eyes and a big grin.
  ctx.fillStyle = css(P.skin);
  head(0);
  ctx.fill();
  ctx.fillStyle = css(P.hair);
  ctx.beginPath();
  ctx.arc(0, -290, 35, Math.PI * 1.02, Math.PI * 1.98);
  ctx.quadraticCurveTo(20, -300, 4, -296);
  ctx.quadraticCurveTo(-12, -300, -34, -284);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = css(P.textStroke);
  for (const x of [-12, 12]) {
    ctx.beginPath();
    ctx.ellipse(x, -280, 4, 6, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.beginPath();
  ctx.arc(0, -270, 13, 0.15 * Math.PI, 0.85 * Math.PI);
  ctx.lineWidth = 4;
  ctx.strokeStyle = css(P.textStroke);
  ctx.stroke();
  return canvas;
}

/** A stick figure with its arms out, for the "arms out" prompt. 1 texel = 0.5 unit. */
function drawPictogram(): HTMLCanvasElement {
  const [canvas, ctx] = makeCanvas(256, 256);
  ctx.translate(128, 136);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  const figure = (width: number, color: string) => {
    ctx.strokeStyle = color;
    ctx.fillStyle = color;
    ctx.lineWidth = width;
    ctx.beginPath();
    ctx.moveTo(0, -38);
    ctx.lineTo(0, 22);
    ctx.moveTo(-74, -34);
    ctx.lineTo(74, -34);
    ctx.moveTo(0, 22);
    ctx.lineTo(-30, 76);
    ctx.moveTo(0, 22);
    ctx.lineTo(30, 76);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(0, -66, 20 + (width - 16) / 2, 0, Math.PI * 2);
    ctx.fill();
  };
  figure(30, css(P.textStroke));
  figure(16, '#ffffff');
  return canvas;
}

function drawEdgeFade(): HTMLCanvasElement {
  const [canvas, ctx] = makeCanvas(256, 4);
  const g = ctx.createLinearGradient(0, 0, 256, 0);
  g.addColorStop(0, 'rgba(255, 255, 255, 1)');
  g.addColorStop(0.4, 'rgba(255, 255, 255, 0.35)');
  g.addColorStop(1, 'rgba(255, 255, 255, 0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 256, 4);
  return canvas;
}

export function createStageTextures(): StageTextures {
  const sources: TextureSource[] = [];
  const textures: Texture[] = [];
  const fromCanvas = (canvas: HTMLCanvasElement, label: string, scale: number): Texture => {
    const source = new CanvasSource({
      resource: canvas,
      // Texels per world unit: the texture is then drawn at its world size by default.
      resolution: scale,
      autoGenerateMipmaps: true,
      scaleMode: 'linear',
      label,
    });
    sources.push(source);
    const texture = new Texture({ source });
    textures.push(texture);
    return texture;
  };

  const atlas = effectAtlas();
  const effectSource = new BufferImageSource({
    resource: atlas.image.data,
    width: atlas.image.width,
    height: atlas.image.height,
    format: 'rgba8unorm',
    alphaMode: 'premultiplied-alpha',
    autoGenerateMipmaps: true,
    scaleMode: 'linear',
    label: 'effects',
  });
  sources.push(effectSource);
  const effects = {} as Record<EffectFrameName, Texture>;
  for (const name of Object.keys(atlas.frames) as EffectFrameName[]) {
    const frame = atlas.frames[name];
    const texture = new Texture({
      source: effectSource,
      frame: new Rectangle(frame.x, frame.y, frame.width, frame.height),
    });
    textures.push(texture);
    effects[name] = texture;
  }

  return {
    board: fromCanvas(drawBoard(false), 'board', DENSITY),
    boardFront: fromCanvas(drawBoard(true), 'board-front', DENSITY),
    shadow: fromCanvas(drawShadow(), 'shadow', 1),
    wake: fromCanvas(drawWake(), 'wake', 1),
    star: fromCanvas(drawStar(), 'star', 2),
    clam: fromCanvas(drawClam(), 'clam', 2),
    crab: fromCanvas(drawCrab(), 'crab', 2),
    buoy: fromCanvas(drawBuoy(), 'buoy', 2),
    whirlpool: fromCanvas(drawWhirlpool(), 'whirlpool', 1),
    whirlArms: fromCanvas(drawWhirlArms(), 'whirl-arms', 1),
    chevron: fromCanvas(drawChevron(), 'chevron', 1),
    glow: fromCanvas(drawGlow(), 'glow', 1),
    clouds: [
      fromCanvas(drawCloud(1, 6), 'cloud-1', 2),
      fromCanvas(drawCloud(2, 4), 'cloud-2', 2),
      fromCanvas(drawCloud(3, 8), 'cloud-3', 2),
    ],
    island: fromCanvas(drawIsland(), 'island', 2),
    headland: fromCanvas(drawHeadland(), 'headland', 2),
    dummy: fromCanvas(drawDummy(), 'dummy', 1.25),
    pictogram: fromCanvas(drawPictogram(), 'pictogram', 2),
    edgeFade: fromCanvas(drawEdgeFade(), 'edge-fade', 1),
    effects,
    destroy() {
      for (const texture of textures) texture.destroy();
      for (const source of sources) source.destroy();
    },
  };
}
