import { type Backend, type BackendOptions, SEGMENT_TIMEOUT_MS, SegmentFailure } from './backend';
import { MaskPacer } from './maskPacer';
import { GpuContextLost, injectedFault, type RegionLayout } from './protocol';
import type { CorePose, SegmenterCore } from './segmenterCore';
import {
  type SegmenterInfo,
  type SegmentJob,
  type SegmentResult,
  type StartProgress,
  VisionError,
} from './types';

interface Job {
  frame: VideoFrame;
  job: SegmentJob | undefined;
  /** Set once the pose step has run; the segmentation step follows in a later task. */
  pose: CorePose | null;
  /** When the job was queued (tracing). */
  queuedMs: number;
  resolve(result: SegmentResult | null): void;
  reject(error: VisionError): void;
}

/**
 * The same segmenter core as the worker, run on the main thread: the fallback when the
 * worker cannot start or keeps failing. Each step blocks the main thread while it runs, so
 * a frame runs in tasks of its own rather than inside the caller's frame callback, letting
 * the frame that triggered it paint first. The pose comes first; the segmentation waits
 * until the page has drawn its next frame, so the game steers with the pose a whole
 * segmentation earlier (a task queued straight after would nearly always run before the
 * next frame, and the pose would reach the game together with the mask).
 *
 * Like the worker, it skips a mask that would hold the next frame's pose back (maskPacer.ts),
 * and one instance is never restarted in place; the owner replaces it.
 */
export class MainThreadSegmenter implements Backend {
  info: SegmenterInfo | null = null;

  private core: SegmenterCore | null = null;
  private readonly queue: Job[] = [];
  private scheduled = false;
  private spare: Uint8Array | null = null;
  private segmentCalls = 0;
  private readonly pacer = new MaskPacer();
  private broken = false;
  private disposed = false;
  private started = false;
  /** Calls swallowed by an injected hang: their timeout timers and how to reject them. */
  private readonly hung = new Map<ReturnType<typeof setTimeout>, (error: VisionError) => void>();

  constructor(private readonly options: BackendOptions) {}

  async init(onProgress?: (progress: StartProgress) => void): Promise<SegmenterInfo> {
    if (this.started || this.disposed) {
      throw new VisionError('segmenter-init', 'A segmenter can only be started once.');
    }
    this.started = true;
    const { options } = this;
    let core: SegmenterCore;
    try {
      // The classic build: the ES-module one only works inside a module worker.
      const wasm = options.engine === 'mediapipe' ? await options.loadWasm('classic') : null;
      onProgress?.({ stage: 'wasm', fraction: null });
      // Loaded on demand: this fallback is rare, and a static import would put the whole
      // MediaPipe runtime in the main bundle that every visitor downloads.
      const { createSegmenterCore } = await import('./segmenterCore');
      core = await createSegmenterCore(
        {
          engine: options.engine,
          delegate: options.delegate,
          wasmLoaderUrl: wasm?.loaderUrl ?? '',
          wasmBuild: 'classic',
          wasmBinary: wasm?.binary ?? null,
          modelBuffer: options.modelBuffer,
          poseModelBuffer: options.poseModelBuffer,
          inputSize: options.inputSize,
          layout: options.layout,
          fault: options.fault,
        },
        () => onProgress?.({ stage: 'warmup', fraction: null }),
      );
    } catch (cause) {
      throw new VisionError('segmenter-init', describe(cause), { cause });
    }
    if (this.disposed) {
      core.dispose();
      throw new VisionError('segmenter-init', 'The segmenter was stopped.');
    }
    this.core = core;
    this.info = { backend: 'main', ...core.info };
    return this.info;
  }

  setLayout(layout: RegionLayout): void {
    this.spare = null;
    this.pacer.reset();
    this.core?.setLayout(layout);
  }

  segment(frame: VideoFrame, job?: SegmentJob): Promise<SegmentResult | null> {
    if (!this.core || this.broken) {
      frame.close();
      return Promise.reject(new SegmentFailure('The segmenter is not running.', true));
    }
    return new Promise<SegmentResult | null>((resolve, reject) => {
      const injected = injectedFault(this.options.fault, ++this.segmentCalls);
      if (injected === 'hang') {
        // Nothing on the main thread can really hang without freezing the page, so a hang
        // is a job that never runs, caught by the same deadline the worker has.
        frame.close();
        const timer = setTimeout(() => {
          this.hung.delete(timer);
          this.broken = true;
          this.fail(reject, new SegmentFailure('The segmenter stopped responding.', true));
        }, SEGMENT_TIMEOUT_MS);
        this.hung.set(timer, reject);
        return;
      }
      if (injected === 'throw') {
        frame.close();
        queueMicrotask(() => this.fail(reject, new SegmentFailure('injected fault', false)));
        return;
      }
      this.queue.push({ frame, job, pose: null, queuedMs: performance.now(), resolve, reject });
      this.schedule();
    });
  }

  recycle(data: Uint8Array): void {
    this.spare = data;
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    const stopped = new SegmentFailure('The segmenter was stopped.', true);
    for (const [timer, reject] of this.hung) {
      clearTimeout(timer);
      reject(stopped);
    }
    this.hung.clear();
    for (const job of this.queue.splice(0)) {
      job.frame.close();
      job.reject(stopped);
    }
    this.core?.dispose();
    this.core = null;
  }

  private schedule(): void {
    if (this.scheduled || this.queue.length === 0) return;
    this.scheduled = true;
    setTimeout(this.runQueue, 0);
  }

  /** One step of the oldest job per task: its pose, or its segmentation. */
  private readonly runQueue = (): void => {
    this.scheduled = false;
    const job = this.queue[0];
    if (!job) return;
    const { core } = this;
    if (!core) {
      this.queue.shift();
      job.frame.close();
      job.reject(new SegmentFailure('The segmenter was stopped.', true));
      this.schedule();
      return;
    }
    if (!job.pose) {
      const startMs = performance.now();
      try {
        const fresh = job.job?.fresh ?? false;
        // A new source or a resumed one: its costs are not the old one's.
        if (fresh) this.pacer.reset();
        job.pose = core.pose(job.frame, fresh);
      } catch (cause) {
        // A failing pose model is reported in the pose; what gets here is a lost context.
        this.queue.shift();
        job.frame.close();
        const contextLost = cause instanceof GpuContextLost;
        if (contextLost) this.broken = true;
        this.fail(
          job.reject,
          new SegmentFailure(describe(cause), contextLost, { cause, contextLost }),
        );
        this.schedule();
        return;
      }
      const { landmarks, present, poseMs } = job.pose;
      const endMs = performance.now();
      job.job?.onPose?.({ landmarks, present, poseMs, receivedMs: job.queuedMs, startMs, endMs });
      const nextFrameInMs = job.job?.nextFrameInMs ?? Number.POSITIVE_INFINITY;
      const interval = job.job?.frameIntervalMs ?? Number.POSITIVE_INFINITY;
      const wait = job.job?.poseWaitFrames;
      if (!this.pacer.shouldSegment(endMs, job.queuedMs, nextFrameInMs, interval, poseMs, wait)) {
        this.queue.shift();
        job.frame.close();
        job.resolve(null);
        this.report(job.pose);
        this.schedule();
        return;
      }
      this.scheduled = true;
      afterNextFrame(this.runQueue);
      return;
    }
    this.queue.shift();
    const out = this.spare;
    this.spare = null;
    let result: SegmentResult;
    const startMs = performance.now();
    try {
      // core.segment closes the frame in every outcome.
      result = { ...core.segment(job.frame, out, job.pose), startMs };
      result.endMs = performance.now();
      this.pacer.segmented(startMs, result.endMs);
    } catch (cause) {
      const contextLost = cause instanceof GpuContextLost;
      if (contextLost) this.broken = true;
      this.fail(
        job.reject,
        new SegmentFailure(describe(cause), contextLost, { cause, contextLost }),
      );
      this.schedule();
      return;
    }
    job.resolve(result);
    this.report(job.pose);
    this.schedule();
  };

  /** A frame settled: healthy, unless its pose model failed. */
  private report(pose: CorePose): void {
    const { error } = pose;
    this.options.monitor?.(error === null ? null : new SegmentFailure(`pose: ${error}`, false));
  }

  private fail(reject: (error: VisionError) => void, failure: SegmentFailure): void {
    reject(failure);
    if (!this.disposed) this.options.monitor?.(failure);
  }
}

/** Longest wait for the page to draw before segmenting anyway (a hidden tab draws nothing). */
const FRAME_WAIT_MS = 50;

/** Call `step` in a task of its own after the page next draws, or after `FRAME_WAIT_MS`. */
function afterNextFrame(step: () => void): void {
  let done = false;
  const run = (): void => {
    if (done) return;
    done = true;
    clearTimeout(timer);
    step();
  };
  const timer = setTimeout(run, FRAME_WAIT_MS);
  // From inside the frame's callbacks, a task: it runs once that frame has been drawn.
  if (typeof requestAnimationFrame === 'function') requestAnimationFrame(() => setTimeout(run, 0));
}

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}
