/**
 * The continuous layers that follow the game every tick:
 *
 * - water: noise rushing along the rail, louder and brighter with speed, swelling with the
 *   turn, plus a hiss of spray while the board turns hard; it cuts out in the air;
 * - wind: an airy hush while airborne, rising with height;
 * - ocean: a calm bed of slow wave wash, mostly while waiting;
 * - rumble: the wave rising under the board during takeoff;
 * - roar: the breaking curl, creeping in when the surfer gets close to it, as a warning;
 * - rush: a bright surge of air and spray while a speed boost is in effect (a strip's is
 *   strong, a pickup's small kick faint);
 * - swirl: a whirlpool's churning, sweeping round while it has hold of the board.
 *
 * `ambienceTargets` turns the game state into target levels and filter frequencies (pure, so
 * it is unit tested); `createAmbience` builds the graph and glides every parameter towards
 * its target with `setTargetAtTime`, so changes are smooth at audio rate: no zipper noise and
 * no clicks, however the game jumps.
 */
import type { Game } from '../game/types';
import { clamp } from './synth';

/*
 * The ranges below are the game's real ones, measured in whole bot rides through the pose
 * chain (src/game/testkit.ts): on the water a board never goes slower than 250 units/s,
 * cruises at 600–1000 and reaches 1350 (95th percentile) to 1550 late in a long ride;
 * |turn| is under 0.15 half the time and 0.55 in a hard carve; airs peak 80 above the lip
 * typically and 200–380 at most; the board spends most of a ride 250–700 ahead of the curl.
 * Mapping each over that span keeps the layers moving over the whole ride instead of
 * sitting at full (the first mapping saturated at 1100, the median of a carver's ride).
 */
/** Speeds (world units per second) mapped onto the water's range: quiet at the first, full at the second. */
export const SPEED_SLOW = 300;
export const SPEED_FULL = 1400;
/** |turn| of a hard carve, where the spray is at full. */
export const TURN_FULL = 0.6;
/** Height above the lip (world units) at which the wind is at full. */
export const HEIGHT_FULL = 250;
/**
 * Distance ahead of the curl (world units) where its roar starts, and where it is at full:
 * silent on the shoulder, clearly there in the pocket, at full just before it catches you.
 */
export const ROAR_FAR = 550;
export const ROAR_NEAR = 40;
/** The view is 1920 world units wide at 16:9; pans use x / this, clamped. */
const VIEW_WIDTH = 1920;
/** Pans stay gentle: sounds lean towards a side, never jump fully into one speaker. */
const PAN_WIDTH = 0.45;

export interface AmbienceTargets {
  /** All levels are 0..1 of each layer's own full level. */
  water: number;
  waterHz: number;
  spray: number;
  wind: number;
  windHz: number;
  ocean: number;
  rumble: number;
  roar: number;
  rush: number;
  swirl: number;
  /** -1..1 */
  surferPan: number;
  curlPan: number;
  /** The board is in the air: the water should cut out fast. */
  airborne: boolean;
}

export const SILENCE: AmbienceTargets = {
  water: 0,
  waterHz: 600,
  spray: 0,
  wind: 0,
  windHz: 600,
  ocean: 0,
  rumble: 0,
  roar: 0,
  rush: 0,
  swirl: 0,
  surferPan: 0,
  curlPan: 0,
  airborne: false,
};

/** Smooth 0→1 as `x` goes from `edge0` to `edge1` (either order). */
export function smoothstep(edge0: number, edge1: number, x: number): number {
  const t = clamp((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

/** 0..1 over the real speed range (see above). */
export function speed01(speed: number): number {
  return clamp((speed - SPEED_SLOW) / (SPEED_FULL - SPEED_SLOW), 0, 1);
}

export function panFor(x: number): number {
  return clamp((x / VIEW_WIDTH) * 2 - 1, -1, 1) * PAN_WIDTH;
}

type GameView = Pick<Game, 'phase' | 'surfer' | 'wave'> & Partial<Pick<Game, 'hazards'>>;

export function ambienceTargets(game: GameView): AmbienceTargets {
  const { phase, surfer, wave } = game;
  const onWave = phase === 'takeoff' || phase === 'riding';
  const speed = speed01(surfer.speed);
  const turn = clamp(Math.abs(surfer.turn) / TURN_FULL, 0, 1);
  const airborne = onWave && surfer.airborne;
  const onWater = onWave && !surfer.airborne;
  const height = clamp(surfer.height / HEIGHT_FULL, 0, 1);

  // Never quite silent while moving, soft at a crawl; about 8 dB from cruising to flat out.
  const water = onWater ? clamp((0.12 + 0.88 * speed ** 0.9) * (0.85 + 0.3 * turn), 0, 1) : 0;
  const spray = onWater ? turn ** 1.5 * (0.3 + 0.7 * speed) : 0;
  const wind = airborne ? (0.35 + 0.65 * height) * (0.6 + 0.4 * speed) : 0;
  let ocean = 0;
  if (phase === 'waiting') ocean = 1;
  else if (phase === 'takeoff') ocean = 1 - 0.7 * clamp(wave.rise, 0, 1);
  else if (phase === 'riding') ocean = 0.3;
  else ocean = 0.75;
  let rumble = 0;
  if (phase === 'takeoff') rumble = 0.15 + 0.85 * clamp(wave.rise, 0, 1);
  else if (phase === 'riding') rumble = 0.2;
  const distance = surfer.x - wave.curlX;
  const roar = onWave ? smoothstep(ROAR_FAR, ROAR_NEAR, distance) * clamp(wave.rise, 0, 1) : 0;
  const rush = onWave ? clamp(surfer.boost ?? 0, 0, 1) ** 1.3 : 0;
  let swirl = 0;
  const hazards = game.hazards;
  if (onWave && hazards) {
    for (let i = 0; i < hazards.length; i++) {
      const h = hazards[i];
      if (h && h.kind === 'whirlpool' && h.grip > swirl) swirl = h.grip;
    }
  }

  return {
    water,
    waterHz: 550 + 3300 * speed + 1400 * turn,
    spray,
    wind,
    windHz: 520 + 1400 * height,
    ocean,
    rumble,
    roar,
    rush,
    swirl: clamp(swirl, 0, 1),
    surferPan: panFor(surfer.x),
    // The curl is usually off the left edge; lean the roar left without hard-panning it.
    curlPan: panFor(Math.max(0, wave.curlX)),
    airborne,
  };
}

/** Each layer's level at 1, chosen by measuring the offline render (e2e/audio-check.mjs). */
export const LAYER_GAIN = {
  water: 0.3,
  spray: 0.13,
  wind: 0.3,
  ocean: 0.36,
  rumble: 0.8,
  roar: 0.6,
  rush: 0.32,
  swirl: 0.5,
} as const;

/** Glide times (time constants, s): fast enough to feel attached, slow enough to be smooth. */
export const SMOOTHING = {
  water: 0.07,
  /** The water cuts out this fast when the board leaves it. */
  waterCut: 0.025,
  filter: 0.09,
  windAttack: 0.08,
  windRelease: 0.2,
  ocean: 0.9,
  rumble: 0.3,
  roar: 0.3,
  /** A boost's rush comes in with the kick and fades with it. */
  rushAttack: 0.04,
  rushRelease: 0.25,
  swirl: 0.12,
  pan: 0.15,
} as const;

/** Changes smaller than these are not worth another automation event. */
const LEVEL_EPSILON = 0.002;
const RATIO_EPSILON = 0.004;

interface Smoothed {
  readonly param: AudioParam;
  last: number;
}

export interface Ambience {
  /** Glide every layer towards `targets`, starting at `when` (context time). */
  update(targets: AmbienceTargets, when: number): void;
  /** Every layer to silence with time constant `tauS` (play has ended); `update` revives. */
  fade(when: number, tauS: number): void;
  stop(when: number): void;
}

/**
 * Build the layers into `destination`. Each layer reads the shared noise buffer from its own
 * offset at a slightly different rate, so the layers are uncorrelated and the loop never
 * lines up with itself.
 */
export function createAmbience(
  context: BaseAudioContext,
  destination: AudioNode,
  noise: AudioBuffer,
  random: () => number,
  start = context.currentTime,
): Ambience {
  const sources: AudioScheduledSourceNode[] = [];
  const nodes: AudioNode[] = [];

  const noiseSource = (rate: number): AudioBufferSourceNode => {
    const source = context.createBufferSource();
    source.buffer = noise;
    source.loop = true;
    source.playbackRate.value = rate;
    source.start(start, random() * noise.duration);
    sources.push(source);
    return source;
  };
  const filter = (type: BiquadFilterType, hz: number, q = 0.7): BiquadFilterNode => {
    const node = context.createBiquadFilter();
    node.type = type;
    node.frequency.value = hz;
    node.Q.value = q;
    nodes.push(node);
    return node;
  };
  const gain = (value = 0): GainNode => {
    const node = context.createGain();
    node.gain.value = value;
    nodes.push(node);
    return node;
  };
  const panner = (): StereoPannerNode => {
    const node = context.createStereoPanner();
    node.pan.value = 0;
    nodes.push(node);
    return node;
  };
  const lfo = (hz: number, depth: number, target: AudioParam): void => {
    const oscillator = context.createOscillator();
    oscillator.frequency.value = hz;
    const amount = gain(depth);
    oscillator.connect(amount).connect(target);
    oscillator.start(start);
    sources.push(oscillator);
  };

  // Water: body (lowpass, brightness follows speed) and spray (highpass hiss).
  const surferPan = panner();
  surferPan.connect(destination);
  const waterLevel = gain();
  const waterLowpass = filter('lowpass', 600, 0.8);
  noiseSource(1).connect(filter('highpass', 160)).connect(waterLowpass).connect(waterLevel);
  // A slow, small wobble in level: water is never perfectly steady.
  const waterChop = gain(1);
  waterLevel.connect(waterChop).connect(surferPan);
  lfo(0.9, 0.12, waterChop.gain);
  lfo(2.3, 0.06, waterChop.gain);
  const sprayLevel = gain();
  noiseSource(1.07).connect(filter('highpass', 3400)).connect(sprayLevel).connect(surferPan);

  // Wind: a resonant band of noise that drifts in pitch like gusts.
  const windBand = filter('bandpass', 600, 1.1);
  const windLevel = gain();
  noiseSource(0.93).connect(windBand).connect(windLevel).connect(surferPan);
  lfo(0.37, 140, windBand.frequency);

  // Ocean: soft, dark noise whose level and brightness swell with two slow, unrelated waves.
  const oceanLowpass = filter('lowpass', 800, 0.6);
  const oceanSwell = gain(0.55);
  const oceanLevel = gain();
  noiseSource(0.97).connect(filter('highpass', 90)).connect(oceanLowpass).connect(oceanSwell);
  oceanSwell.connect(oceanLevel).connect(destination);
  lfo(1 / 7.5, 0.25, oceanSwell.gain);
  lfo(1 / 11.3, 0.1, oceanSwell.gain);
  lfo(1 / 7.5, 300, oceanLowpass.frequency);

  // Rumble: the deep body of a big wave, two lowpasses deep so it stays a rumble.
  const rumbleLevel = gain();
  noiseSource(0.9)
    .connect(filter('lowpass', 220, 0.9))
    .connect(filter('lowpass', 260, 0.7))
    .connect(rumbleLevel)
    .connect(destination);

  // Roar: the curl's white water, a dark churn with a little hiss on top, leaning left.
  const curlPan = panner();
  curlPan.connect(destination);
  const roarLevel = gain();
  const roarMix = gain(1);
  noiseSource(1.03)
    .connect(filter('lowpass', 480, 0.9))
    .connect(roarMix);
  const roarHiss = gain(0.25);
  noiseSource(1.11)
    .connect(filter('bandpass', 1500, 0.6))
    .connect(roarHiss)
    .connect(roarMix);
  roarMix.connect(roarLevel).connect(curlPan);
  lfo(0.6, 0.18, roarMix.gain);

  // Rush: air and spray tearing past, bright, on the surfer.
  const rushBand = filter('bandpass', 2600, 0.8);
  const rushLevel = gain();
  noiseSource(1.13).connect(filter('highpass', 700)).connect(rushBand).connect(rushLevel);
  rushLevel.connect(surferPan);
  lfo(3.1, 500, rushBand.frequency);

  // Swirl: churning water sweeping round (a band of noise circling in pitch, a pulse in
  // level at the same rate) over a low gurgle.
  const swirlBand = filter('bandpass', 700, 2.2);
  const swirlMix = gain(1);
  noiseSource(0.87).connect(swirlBand).connect(swirlMix);
  const gurgle = gain(0.6);
  noiseSource(0.81)
    .connect(filter('lowpass', 260, 1.4))
    .connect(gurgle)
    .connect(swirlMix);
  const swirlLevel = gain();
  swirlMix.connect(swirlLevel).connect(surferPan);
  lfo(1.6, 380, swirlBand.frequency);
  lfo(1.6, 0.3, swirlMix.gain);

  const smoothed = (param: AudioParam): Smoothed => ({ param, last: param.value });
  const params = {
    water: smoothed(waterLevel.gain),
    waterHz: smoothed(waterLowpass.frequency),
    spray: smoothed(sprayLevel.gain),
    wind: smoothed(windLevel.gain),
    windHz: smoothed(windBand.frequency),
    ocean: smoothed(oceanLevel.gain),
    rumble: smoothed(rumbleLevel.gain),
    roar: smoothed(roarLevel.gain),
    rush: smoothed(rushLevel.gain),
    swirl: smoothed(swirlLevel.gain),
    surferPan: smoothed(surferPan.pan),
    curlPan: smoothed(curlPan.pan),
  };

  const glide = (p: Smoothed, value: number, when: number, tau: number, ratio = false): void => {
    const delta = Math.abs(value - p.last);
    if (ratio ? delta <= Math.abs(p.last) * RATIO_EPSILON : delta <= LEVEL_EPSILON) return;
    p.param.setTargetAtTime(value, when, tau);
    p.last = value;
  };

  let stopped = false;
  return {
    update(t, when) {
      if (stopped) return;
      const waterTau = t.airborne ? SMOOTHING.waterCut : SMOOTHING.water;
      glide(params.water, t.water * LAYER_GAIN.water, when, waterTau);
      glide(params.waterHz, t.waterHz, when, SMOOTHING.filter, true);
      glide(params.spray, t.spray * LAYER_GAIN.spray, when, waterTau);
      const wind = t.wind * LAYER_GAIN.wind;
      const windTau = wind > params.wind.last ? SMOOTHING.windAttack : SMOOTHING.windRelease;
      glide(params.wind, wind, when, windTau);
      glide(params.windHz, t.windHz, when, SMOOTHING.filter, true);
      glide(params.ocean, t.ocean * LAYER_GAIN.ocean, when, SMOOTHING.ocean);
      glide(params.rumble, t.rumble * LAYER_GAIN.rumble, when, SMOOTHING.rumble);
      glide(params.roar, t.roar * LAYER_GAIN.roar, when, SMOOTHING.roar);
      const rush = t.rush * LAYER_GAIN.rush;
      const rushTau = rush > params.rush.last ? SMOOTHING.rushAttack : SMOOTHING.rushRelease;
      glide(params.rush, rush, when, rushTau);
      glide(params.swirl, t.swirl * LAYER_GAIN.swirl, when, SMOOTHING.swirl);
      glide(params.surferPan, t.surferPan, when, SMOOTHING.pan);
      glide(params.curlPan, t.curlPan, when, SMOOTHING.pan);
    },
    fade(when, tauS) {
      if (stopped) return;
      for (const p of [
        params.water,
        params.spray,
        params.wind,
        params.ocean,
        params.rumble,
        params.roar,
        params.rush,
        params.swirl,
      ]) {
        p.param.setTargetAtTime(0, when, tauS);
        p.last = 0;
      }
    },
    stop(when) {
      if (stopped) return;
      stopped = true;
      const { water, spray, wind, ocean, rumble, roar, rush, swirl } = params;
      for (const p of [water, spray, wind, ocean, rumble, roar, rush, swirl]) {
        p.param.setTargetAtTime(0, when, 0.02);
      }
      for (const source of sources) source.stop(when + 0.2);
      const first = sources[0];
      if (first) {
        first.onended = () => {
          for (const node of nodes) node.disconnect();
        };
      }
    },
  };
}
