/**
 * Where the player is in the camera picture, and how to stand them on the board.
 *
 * Everything here is in normalised source coordinates in camera orientation (u right,
 * v down, both 0..1 across the frame; the mirror is applied when drawing). Heights are in
 * v units, so a height of 0.5 means half the frame height. Pure maths, no Pixi, so it can
 * be unit-tested with made-up poses and masks.
 *
 * Stability matters more than exactness: the measurement can be noisy frame to frame
 * (the mask flickers at the edges, landmarks jitter), so the filter smooths the size
 * slowly and the feet quickly, and never lets one bad frame move the cutout far.
 */
import type { PersonMask } from '../core/mask';
import { Landmark, POSE_STRIDE, type PoseFrame } from '../core/pose';

export interface PersonMeasure {
  /** The point that stands on the deck: between the feet, or the lowest visible part. */
  anchorU: number;
  anchorV: number;
  /** Estimated standing height, v units. */
  height: number;
  /** Box round everything that belongs to the person. */
  u0: number;
  v0: number;
  u1: number;
  v1: number;
  /** The feet are out of frame: the anchor is where the picture cuts the body off. */
  cut: boolean;
}

export function emptyMeasure(): PersonMeasure {
  return { anchorU: 0.5, anchorV: 1, height: 0.5, u0: 0, v0: 0, u1: 1, v1: 1, cut: false };
}

/** Shoulder-to-hip is about this fraction of standing height, children and adults alike. */
export const TORSO_FRACTION = 0.3;
/**
 * Shoulder joint to shoulder joint is about this fraction of standing height. A second cue
 * because the torso foreshortens when the player bends towards the camera (a burpee, a
 * deep crouch) while the shoulders stay as wide; turning sideways does the opposite.
 */
export const SHOULDER_FRACTION = 0.25;
/** The top of the head is about this many nose-to-shoulder drops above the nose. */
const HEAD_ABOVE_NOSE = 0.8;
const VISIBLE = 0.5;
/** Landmarks this far outside the frame are guesses, not sightings. */
const FRAME_SLACK = 0.02;

/** Smallest person worth showing: this fraction of the mask's texels. */
const MIN_AREA = 0.004;
/** A row belongs to the person when it holds at least this fraction of the busiest row. */
const ROW_FRACTION = 0.06;
/** A gap of this share of the width between occupied columns separates two things. */
const COLUMN_GAP = 0.015;
/** A column is occupied with at least this share of the busiest column's texels. */
const COLUMN_FRACTION = 0.02;
/** The feet are found in this bottom share of the person's box. */
const FEET_BAND = 0.1;

/** Reusable per-row/per-column counts for `measureMask`. */
export class MaskScratch {
  rows = new Float64Array(0);
  cols = new Float64Array(0);
  feet = new Float64Array(0);

  ensure(width: number, height: number): void {
    if (this.rows.length !== height) this.rows = new Float64Array(height);
    if (this.cols.length !== width) {
      this.cols = new Float64Array(width);
      this.feet = new Float64Array(width);
    }
  }
}

/**
 * Measure the person from the mask alone. The person is the run of occupied columns round
 * the busiest one; anything separated from it by a gap (a punching bag or a coat the model
 * mistakes for a person) is left out. Within that run: a box round the mass that ignores
 * stray rows, the feet as the middle of the mass in the bottom of the box, and the height
 * as the box height. Returns false when there is nobody (too few person texels).
 */
export function measureMask(
  mask: PersonMask,
  threshold: number,
  scratch: MaskScratch,
  out: PersonMeasure,
): boolean {
  const { width, height, data } = mask;
  if (width < 2 || height < 2) return false;
  scratch.ensure(width, height);
  const { rows, cols, feet: smooth } = scratch;
  rows.fill(0);
  cols.fill(0);
  const cut = Math.max(1, Math.round(threshold * 255));
  let total = 0;
  for (let v = 0, i = 0; v < height; v++) {
    for (let u = 0; u < width; u++, i++) {
      if ((data[i] as number) >= cut) {
        cols[u] = (cols[u] as number) + 1;
        total++;
      }
    }
  }
  if (total < MIN_AREA * width * height) return false;

  // The busiest column, smoothed so one tall thin stray cannot win against a body.
  const reach = Math.max(1, Math.round(width * 0.02));
  let peak = 0;
  for (let u = 0; u < width; u++) {
    let sum = 0;
    for (let k = Math.max(0, u - reach); k <= Math.min(width - 1, u + reach); k++) {
      sum += cols[k] as number;
    }
    smooth[u] = sum;
    if (sum > (smooth[peak] as number)) peak = u;
  }
  const maxGap = Math.max(1, Math.round(width * COLUMN_GAP));
  const colMin = Math.max(1, (cols[peak] as number) * COLUMN_FRACTION);
  let left = peak;
  for (let u = peak - 1, gap = 0; u >= 0; u--) {
    if ((cols[u] as number) >= colMin) {
      left = u;
      gap = 0;
    } else if (++gap > maxGap) break;
  }
  let right = peak;
  for (let u = peak + 1, gap = 0; u < width; u++) {
    if ((cols[u] as number) >= colMin) {
      right = u;
      gap = 0;
    } else if (++gap > maxGap) break;
  }

  // Rows, counted inside the person's columns only.
  let busiest = 0;
  for (let v = 0; v < height; v++) {
    const row = v * width;
    let count = 0;
    for (let u = left; u <= right; u++) if ((data[row + u] as number) >= cut) count++;
    rows[v] = count;
    if (count > busiest) busiest = count;
  }
  const rowMin = Math.max(2, busiest * ROW_FRACTION);
  let top = 0;
  while (top < height - 1 && (rows[top] as number) < rowMin) top++;
  let bottom = height - 1;
  while (bottom > top && (rows[bottom] as number) < rowMin) bottom--;

  // The feet: the middle of the mass in the bottom band of the box.
  const band = Math.max(1, Math.round((bottom - top + 1) * FEET_BAND));
  let sum = 0;
  let mass = 0;
  for (let v = bottom - band + 1; v <= bottom; v++) {
    const row = v * width;
    for (let u = left; u <= right; u++) {
      if ((data[row + u] as number) >= cut) {
        sum += u;
        mass++;
      }
    }
  }
  const feetU = mass > 0 ? sum / mass : (left + right) / 2;

  out.u0 = left / width;
  out.u1 = (right + 1) / width;
  out.v0 = top / height;
  out.v1 = (bottom + 1) / height;
  out.anchorU = (feetU + 0.5) / width;
  out.anchorV = out.v1;
  out.height = out.v1 - out.v0;
  out.cut = bottom >= height - 2;
  return true;
}

function seen(lm: Float32Array, index: number): boolean {
  const o = index * POSE_STRIDE;
  const x = lm[o] as number;
  const y = lm[o + 1] as number;
  return (
    (lm[o + 3] as number) >= VISIBLE &&
    x >= -FRAME_SLACK &&
    x <= 1 + FRAME_SLACK &&
    y >= -FRAME_SLACK &&
    y <= 1 + FRAME_SLACK
  );
}

const lx = (lm: Float32Array, index: number) => lm[index * POSE_STRIDE] as number;
const ly = (lm: Float32Array, index: number) => lm[index * POSE_STRIDE + 1] as number;

const FEET = [
  Landmark.leftAnkle,
  Landmark.rightAnkle,
  Landmark.leftHeel,
  Landmark.rightHeel,
  Landmark.leftFoot,
  Landmark.rightFoot,
] as const;

const BODY = [
  Landmark.nose,
  Landmark.leftShoulder,
  Landmark.rightShoulder,
  Landmark.leftElbow,
  Landmark.rightElbow,
  Landmark.leftWrist,
  Landmark.rightWrist,
  Landmark.leftHip,
  Landmark.rightHip,
  Landmark.leftKnee,
  Landmark.rightKnee,
  ...FEET,
] as const;

/**
 * Measure the person from the pose: height from the torso (which does not shrink when the
 * player bends their knees like a surfer) or head-to-feet, whichever is larger; the anchor
 * between the feet, or where the frame cuts the legs off when the feet are out of view.
 * The box covers the landmarks plus room for the head, hair and hands; `mask` (if it agrees)
 * widens it. Returns false without both shoulders and both hips.
 */
export function measurePose(pose: PoseFrame, out: PersonMeasure): boolean {
  if (!pose.present) return false;
  const lm = pose.landmarks;
  const shouldersSeen = seen(lm, Landmark.leftShoulder) && seen(lm, Landmark.rightShoulder);
  const hips = seen(lm, Landmark.leftHip) && seen(lm, Landmark.rightHip);
  if (!shouldersSeen || !hips) return false;
  // Distances in v units: x is scaled by the frame's aspect ratio first.
  const aspect = pose.sourceWidth / Math.max(1, pose.sourceHeight);
  const sx = (lx(lm, Landmark.leftShoulder) + lx(lm, Landmark.rightShoulder)) / 2;
  const sy = (ly(lm, Landmark.leftShoulder) + ly(lm, Landmark.rightShoulder)) / 2;
  const hx = (lx(lm, Landmark.leftHip) + lx(lm, Landmark.rightHip)) / 2;
  const hy = (ly(lm, Landmark.leftHip) + ly(lm, Landmark.rightHip)) / 2;
  const torso = Math.hypot((sx - hx) * aspect, sy - hy);
  if (!(torso > 0.01)) return false;
  const shoulders = Math.hypot(
    (lx(lm, Landmark.leftShoulder) - lx(lm, Landmark.rightShoulder)) * aspect,
    ly(lm, Landmark.leftShoulder) - ly(lm, Landmark.rightShoulder),
  );
  // Each cue only ever underestimates (foreshortening), so the larger one is the better.
  let height = Math.max(torso / TORSO_FRACTION, shoulders / SHOULDER_FRACTION);

  const headTop = seen(lm, Landmark.nose)
    ? ly(lm, Landmark.nose) - HEAD_ABOVE_NOSE * Math.max(0, sy - ly(lm, Landmark.nose))
    : sy - 0.2 * height;

  let feetSeen = 0;
  let feetX = 0;
  let feetY = 0;
  for (const index of FEET) {
    if (!seen(lm, index)) continue;
    feetSeen++;
    feetX += lx(lm, index);
    feetY = Math.max(feetY, ly(lm, index));
  }
  const cut = feetSeen < 2;
  let anchorU: number;
  let anchorV: number;
  if (!cut) {
    anchorU = feetX / feetSeen;
    // Ankle and heel points sit a little above the sole.
    anchorV = Math.min(1, feetY + 0.01);
    height = Math.max(height, anchorV - headTop);
  } else {
    // The legs leave the frame: stand the picture's bottom edge on the deck, under the
    // hips, or under the knees if those are still in view.
    const knees = seen(lm, Landmark.leftKnee) && seen(lm, Landmark.rightKnee);
    anchorU = knees ? (lx(lm, Landmark.leftKnee) + lx(lm, Landmark.rightKnee)) / 2 : hx;
    anchorV = 1;
  }

  let u0 = anchorU;
  let u1 = anchorU;
  let v0 = headTop;
  for (const index of BODY) {
    if (!seen(lm, index)) continue;
    u0 = Math.min(u0, lx(lm, index));
    u1 = Math.max(u1, lx(lm, index));
    v0 = Math.min(v0, ly(lm, index));
  }
  // Hands and hair reach past their landmarks.
  const padU = (0.08 * height) / aspect;
  out.u0 = Math.max(0, u0 - padU);
  out.u1 = Math.min(1, u1 + padU);
  out.v0 = Math.max(0, v0 - 0.04 * height);
  out.v1 = anchorV;
  out.anchorU = anchorU;
  out.anchorV = anchorV;
  out.height = height;
  out.cut = cut;
  return true;
}

/** Widen `into`'s box to cover `other`'s (pose box plus the mask's hair and hands). */
export function unionBox(into: PersonMeasure, other: PersonMeasure): void {
  into.u0 = Math.min(into.u0, other.u0);
  into.u1 = Math.max(into.u1, other.u1);
  into.v0 = Math.min(into.v0, other.v0);
  into.v1 = Math.max(into.v1, Math.min(other.v1, into.anchorV + 0.02));
}

/**
 * Combine a pose measurement with the mask's for the same person. The pose gives the size;
 * the mask is better at the feet: its bottom is the soles (the pose has ankles), and it
 * still has the feet when the pose model loses faith in them, which it does whenever the
 * player bends over. Without this the anchor jumps to the frame edge mid-burpee and the
 * cutout floats a quarter of its height above the board.
 */
export function mergeMask(into: PersonMeasure, mask: PersonMeasure): void {
  if (!mask.cut) {
    const agree = !into.cut && Math.abs(mask.anchorV - into.anchorV) < MASK_FEET_SLACK;
    if (into.cut || agree) {
      into.anchorU = into.cut ? mask.anchorU : into.anchorU;
      into.anchorV = mask.anchorV;
      into.cut = false;
    }
  }
  unionBox(into, mask);
}

/** The mask's soles count as the pose's feet when they are within this much (v units). */
const MASK_FEET_SLACK = 0.06;

export interface FilterSettings {
  /** Time constant for the size, seconds. */
  scaleS: number;
  /** Time constant for the feet, seconds. */
  anchorS: number;
}

/** Time constant for the crop box: between the two, so it never cuts off a moving arm. */
const BOX_S = 0.12;
/** A size jump bigger than this (ratio) is followed more slowly still, in case it is noise. */
const SIZE_JUMP = 1.3;
/** How much slower the size follows a smaller measurement than a larger one. */
const SHRINK_SLOWER = 3;
/** After this long without a sighting the filter starts over at the next one. */
const STALE_S = 1.5;

/**
 * Smooths measurements that arrive at camera rate into a placement that moves at display
 * rate. Call `measure` when a new frame has been measured and `step` every display frame.
 */
export class PlacementFilter {
  /** Smoothed values, valid once `ready`. */
  readonly state: PersonMeasure = emptyMeasure();
  ready = false;
  private readonly target: PersonMeasure = emptyMeasure();
  private hasTarget = false;
  private sinceSeen = Number.POSITIVE_INFINITY;

  /** A new measurement, or null when the frame had nobody in it. */
  measure(measure: PersonMeasure | null): void {
    if (!measure) return;
    copyMeasure(measure, this.target);
    this.hasTarget = true;
    if (!this.ready || this.sinceSeen > STALE_S) {
      copyMeasure(measure, this.state);
      this.ready = true;
    }
    this.sinceSeen = 0;
  }

  step(dtS: number, settings: FilterSettings): void {
    this.sinceSeen += dtS;
    if (!this.ready || !this.hasTarget) return;
    const s = this.state;
    const t = this.target;
    const ka = alpha(dtS, settings.anchorS);
    s.anchorU += (t.anchorU - s.anchorU) * ka;
    s.anchorV += (t.anchorV - s.anchorV) * ka;
    // Size in log space, so growing and shrinking feel the same; big jumps slower still.
    const ratio = t.height / Math.max(1e-4, s.height);
    const jumpy = ratio > SIZE_JUMP || ratio < 1 / SIZE_JUMP ? 2.5 : 1;
    // Shrinking is slower than growing: a smaller measurement is far more often a bend or a
    // turn (foreshortening) than a step back, and a step back is slow anyway.
    const shrink = ratio < 1 ? SHRINK_SLOWER : 1;
    const ks = alpha(dtS, settings.scaleS * jumpy * shrink);
    s.height *= ratio ** ks;
    const kb = alpha(dtS, BOX_S);
    // The box grows at once and shrinks smoothly, so a fast arm is never clipped.
    s.u0 = t.u0 < s.u0 ? t.u0 : s.u0 + (t.u0 - s.u0) * kb;
    s.u1 = t.u1 > s.u1 ? t.u1 : s.u1 + (t.u1 - s.u1) * kb;
    s.v0 = t.v0 < s.v0 ? t.v0 : s.v0 + (t.v0 - s.v0) * kb;
    s.v1 = t.v1 > s.v1 ? t.v1 : s.v1 + (t.v1 - s.v1) * kb;
    s.cut = t.cut;
  }

  reset(): void {
    this.ready = false;
    this.hasTarget = false;
    this.sinceSeen = Number.POSITIVE_INFINITY;
  }
}

function alpha(dtS: number, tauS: number): number {
  return tauS <= 0 ? 1 : 1 - Math.exp(-dtS / tauS);
}

export function copyMeasure(from: PersonMeasure, to: PersonMeasure): void {
  to.anchorU = from.anchorU;
  to.anchorV = from.anchorV;
  to.height = from.height;
  to.u0 = from.u0;
  to.v0 = from.v0;
  to.u1 = from.u1;
  to.v1 = from.v1;
  to.cut = from.cut;
}
