/**
 * Which parts of a frame are fed to the model, and where each result lands in the mask.
 *
 * The model takes a square input and only segments people well when they are undistorted
 * and reasonably large in that input. So instead of squashing the whole wide frame into one
 * square, the default layout runs it on overlapping square tiles and stitches the results.
 *
 * Pure and worker-safe: no DOM.
 */

export type RegionLayout =
  /** One inference on the whole frame squashed to a square (non-square mask texels). */
  | { mode: 'stretch' }
  /**
   * Square tiles, neighbours overlapping by at least `minOverlap` of a tile.
   *
   * `tileHeight` 1 covers the whole frame. Tiles are as large as the frame's shorter side
   * allows: a landscape frame gets one row of them, a portrait frame one column, a square
   * frame a single tile.
   *
   * `tileHeight` below 1 zooms in so people look larger to the model: tiles are that
   * fraction of the frame height on a side (at most the frame width), in one row anchored
   * to the bottom of the frame. The strip above that row is deliberately left uncovered.
   */
  | { mode: 'tiles'; tileHeight: number; minOverlap: number }
  /**
   * One player: a single square tile the size `tiles` would use, centred horizontally on
   * the tracked person, so a wide frame takes one inference instead of two or more. Texels
   * outside the tile are 0. While there is no pose, or the person does not fit in one tile,
   * it is `tiles` with the same numbers. The mask has the same size either way.
   */
  | { mode: 'follow'; tileHeight: number; minOverlap: number };

export const DEFAULT_LAYOUT: RegionLayout = { mode: 'tiles', tileHeight: 1, minOverlap: 0.2 };

export interface Region {
  /** Source rectangle in frame pixels. */
  sx: number;
  sy: number;
  sw: number;
  sh: number;
  /** Top-left texel in the stitched mask where this region's `inputSize`² result goes. */
  dx: number;
  dy: number;
}

export interface RegionPlan {
  /** Size of the stitched mask covering the whole frame. */
  maskWidth: number;
  maskHeight: number;
  regions: Region[];
}

export function layoutsEqual(a: RegionLayout, b: RegionLayout): boolean {
  if (a.mode === 'stretch' || b.mode === 'stretch') return a.mode === b.mode;
  return a.mode === b.mode && a.tileHeight === b.tileHeight && a.minOverlap === b.minOverlap;
}

/** Side of a tile in frame pixels: `tileHeight` of the frame height, never wider than the frame. */
function tileSide(tileHeight: number, frameWidth: number, frameHeight: number): number {
  const fraction = Math.min(1, Math.max(0.3, tileHeight));
  return Math.max(1, Math.min(Math.round(fraction * frameHeight), frameWidth));
}

/**
 * The regions for `layout`. `followCenter` is where a `follow` layout's tile is centred
 * (frame pixels, from `FollowTracker`); null, or a frame one tile already covers across,
 * gives the `tiles` plan.
 */
export function planRegions(
  layout: RegionLayout,
  frameWidth: number,
  frameHeight: number,
  inputSize: number,
  followCenter: number | null = null,
): RegionPlan {
  if (layout.mode === 'stretch') {
    return {
      maskWidth: inputSize,
      maskHeight: inputSize,
      regions: [{ sx: 0, sy: 0, sw: frameWidth, sh: frameHeight, dx: 0, dy: 0 }],
    };
  }

  const fraction = Math.min(1, Math.max(0.3, layout.tileHeight));
  const overlap = Math.min(0.8, Math.max(0, layout.minOverlap));
  // At `tileHeight` 1 the side is the shorter side, so a portrait frame is covered by a
  // column of tiles.
  const side = tileSide(layout.tileHeight, frameWidth, frameHeight);
  // Texels per frame pixel: every tile maps `side` pixels onto `inputSize` texels.
  const scale = inputSize / side;
  const maskWidth = Math.max(inputSize, Math.round(frameWidth * scale));
  const maskHeight = Math.max(inputSize, Math.round(frameHeight * scale));

  const columns = spans(frameWidth, side, overlap, maskWidth, inputSize, 0.5);
  // Zoomed tiles sit in one row at the bottom, where a standing player's body is.
  const rows =
    fraction < 1
      ? [{ start: frameHeight - side, dest: maskHeight - inputSize }]
      : spans(frameHeight, side, overlap, maskHeight, inputSize, 1);

  const regions: Region[] = [];
  if (layout.mode === 'follow' && followCenter !== null && rows.length === 1 && side < frameWidth) {
    const row = rows[0] as { start: number; dest: number };
    // Placed on a whole texel, and the source rectangle derived from it, so the mask keeps
    // exactly the texel-to-pixel mapping of the tiles.
    const dx = Math.min(
      maskWidth - inputSize,
      Math.max(0, Math.round((followCenter - side / 2) * scale)),
    );
    regions.push({ sx: dx / scale, sy: row.start, sw: side, sh: side, dx, dy: row.dest });
    return { maskWidth, maskHeight, regions };
  }
  for (const row of rows) {
    for (const column of columns) {
      regions.push({
        sx: column.start,
        sy: row.start,
        sw: side,
        sh: side,
        dx: column.dest,
        dy: row.dest,
      });
    }
  }
  return { maskWidth, maskHeight, regions };
}

/**
 * Positions along one axis for tiles of `side` pixels covering `length` pixels, with at
 * least `overlap` of a tile shared between neighbours. A single tile that is shorter than
 * the axis sits at `alone` (0 start, 0.5 centre, 1 end).
 */
function spans(
  length: number,
  side: number,
  overlap: number,
  maskLength: number,
  inputSize: number,
  alone: number,
): Array<{ start: number; dest: number }> {
  const count =
    length <= side ? 1 : Math.max(2, Math.ceil((length - side * overlap) / (side * (1 - overlap))));
  const result: Array<{ start: number; dest: number }> = [];
  for (let i = 0; i < count; i++) {
    const t = count === 1 ? alone : i / (count - 1);
    result.push({
      start: Math.round(t * (length - side)),
      // Derived from the same fraction so the outer tiles land exactly on the mask edges
      // regardless of rounding.
      dest: Math.round(t * (maskLength - inputSize)),
    });
  }
  return result;
}

/** Landmarks seen at least this surely count towards the person's extent. */
const FOLLOW_VISIBILITY = 0.5;
/**
 * Room kept between the person's outermost landmarks and the tile's sides, as fractions of
 * the tile. Landmarks are joints, not outlines: hands, hair and shoulders reach beyond them.
 * The tile moves once the room on a side falls below `FOLLOW_TRIGGER`, and then far enough
 * to leave `FOLLOW_SLACK`, so a player swaying in place does not drag it along frame by
 * frame.
 */
const FOLLOW_TRIGGER = 0.08;
const FOLLOW_SLACK = 0.16;

/**
 * Where a `follow` layout's tile goes, frame after frame. Pure state: the core feeds it
 * each frame's pose before segmenting that frame.
 */
export class FollowTracker {
  /** Tile centre in frame pixels, or null when following nobody. */
  private center: number | null = null;

  /** Forget the person (new source, resumed): the next pose places the tile afresh. */
  reset(): void {
    this.center = null;
  }

  /**
   * The tile centre (frame pixels) for a frame whose pose has `landmarks` (normalised, 4
   * floats per point), or null when the frame should be covered by the normal tiles: no
   * pose, nothing seen surely, or a person wider than one tile.
   */
  update(
    landmarks: Float32Array | null,
    layout: RegionLayout,
    frameWidth: number,
    frameHeight: number,
  ): number | null {
    if (!landmarks || layout.mode === 'stretch') return this.lose();
    const side = tileSide(layout.tileHeight, frameWidth, frameHeight);
    if (side >= frameWidth) return this.lose();
    let low = Number.POSITIVE_INFINITY;
    let high = Number.NEGATIVE_INFINITY;
    for (let at = 0; at + 3 < landmarks.length; at += 4) {
      if ((landmarks[at + 3] as number) < FOLLOW_VISIBILITY) continue;
      const x = (landmarks[at] as number) * frameWidth;
      if (x < low) low = x;
      if (x > high) high = x;
    }
    if (low > high) return this.lose();
    const trigger = FOLLOW_TRIGGER * side;
    if (high - low + 2 * trigger > side) return this.lose();

    const half = side / 2;
    let center = this.center ?? (low + high) / 2;
    if (low - trigger < center - half || high + trigger > center + half) {
      // Move with slack to spare, or centre on the person if there is not that much room.
      const slack = FOLLOW_SLACK * side;
      if (high - low + 2 * slack > side) center = (low + high) / 2;
      else if (low - trigger < center - half) center = low - slack + half;
      else center = high + slack - half;
    }
    center = Math.min(frameWidth - half, Math.max(half, center));
    this.center = center;
    return center;
  }

  private lose(): null {
    this.center = null;
    return null;
  }
}
