/**
 * Frame delivery straight from a camera track (MediaStreamTrackProcessor), as soon as each
 * frame is captured.
 *
 * `requestVideoFrameCallback` only fires once the <video> element has handed the frame to
 * the compositor, in the next rendering step: measured on a 60 Hz display, 13–14 ms after
 * capture (e2e/latency-check.mjs). Every one of those milliseconds is steering latency. The
 * track processor hands the frame over a fraction of a millisecond after capture, with no
 * tie to the display's refresh. The <video> element still plays the stream for display.
 */
import type { FrameTick } from './types';

// Not in TypeScript's DOM library yet (Chrome has it on the page as well as in workers).
declare global {
  interface MediaStreamTrackProcessorInit {
    track: MediaStreamTrack;
    maxBufferSize?: number;
  }
  class MediaStreamTrackProcessor {
    constructor(init: MediaStreamTrackProcessorInit);
    readonly readable: ReadableStream<VideoFrame>;
  }
}

/** The processor's queue: one frame, so a busy page sees only the newest. */
const MAX_BUFFER = 1;
/** A frame this much older than its delivery means the clock estimate is wrong (see below). */
const MAX_AGE_MS = 1000;
/**
 * How fast (ms per ms) the clock-offset estimate may drift down, so a camera whose clock
 * runs slightly slow is followed. 0.1% is far beyond any crystal; the bias it adds to the
 * capture time between frames is about 30 µs.
 */
const OFFSET_DRIFT = 0.001;

/**
 * Maps frame timestamps to `performance.now()`. Camera frame timestamps are on the system's
 * monotonic clock; `performance.now()` is the same clock minus the page's time origin, which
 * a page cannot read. A frame is never delivered before it was captured, so
 * `timestamp - deliveredAt` is at most that offset, and the largest value seen is the best
 * estimate (short by the quickest delivery: a fraction of a millisecond in practice, which
 * makes capture times that much late). Pure, so it is unit-tested.
 */
export class CaptureClock {
  private offsetMs = Number.NaN;
  private lastDeliveryMs = 0;

  /** The capture time, on the `performance.now()` clock, of a frame delivered at `deliveredMs`. */
  captureTime(timestampMs: number, deliveredMs: number): number {
    const lead = timestampMs - deliveredMs;
    const drift = (deliveredMs - this.lastDeliveryMs) * OFFSET_DRIFT;
    this.lastDeliveryMs = deliveredMs;
    let offset = Math.max(this.offsetMs - drift, lead);
    // No estimate yet, or a clock that jumped back (or a frame delivered impossibly late):
    // start over from this frame.
    if (!Number.isFinite(offset) || offset - lead > MAX_AGE_MS) offset = lead;
    this.offsetMs = offset;
    return timestampMs - offset;
  }
}

/** True where camera frames can be read straight from the track. */
export function supportsTrackFrames(): boolean {
  return typeof MediaStreamTrackProcessor !== 'undefined' && typeof VideoFrame !== 'undefined';
}

export class TrackTicker implements FrameTick {
  captureTimeMs = 0;
  readonly discontinuity = false;
  handler: ((tick: FrameTick) => void) | null = null;

  private readonly track: MediaStreamTrack;
  private readonly reader: ReadableStreamDefaultReader<VideoFrame>;
  private frame: VideoFrame | null = null;
  private running = false;
  private disposed = false;
  private readonly clock = new CaptureClock();
  private readonly frameInit: VideoFrameInit = { timestamp: 0 };

  constructor(track: MediaStreamTrack) {
    // A clone of its own, so stopping the processor never ends the displayed track.
    this.track = track.clone();
    const processor = new MediaStreamTrackProcessor({
      track: this.track,
      maxBufferSize: MAX_BUFFER,
    });
    this.reader = processor.readable.getReader();
    void this.pump();
  }

  start(): void {
    this.running = true;
  }

  /** Paused: frames are still read (so none goes stale in the queue) but dropped at once. */
  stop(): void {
    this.running = false;
  }

  /**
   * Ending the track ends the stream once the frames still queued in it are delivered;
   * the read loop closes those. Cancelling the stream instead would drop them unclosed.
   */
  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.running = false;
    this.track.stop();
  }

  /** The current frame, on the `performance.now()` clock like every other source's frames. */
  grab(): VideoFrame {
    if (!this.frame) throw new Error('no current frame');
    return new VideoFrame(this.frame, this.frameInit);
  }

  private async pump(): Promise<void> {
    for (;;) {
      let result: ReadableStreamReadResult<VideoFrame>;
      try {
        result = await this.reader.read();
      } catch {
        return; // Cancelled, or the track ended (the camera source reports that).
      }
      const frame = result.value;
      if (result.done || !frame) return;
      if (!this.running || this.disposed || !this.handler) {
        frame.close();
        continue;
      }
      this.captureTimeMs = this.clock.captureTime(frame.timestamp / 1000, performance.now());
      this.frameInit.timestamp = Math.round(this.captureTimeMs * 1000);
      this.frame = frame;
      try {
        this.handler(this);
      } catch (error) {
        // One bad frame must not end the stream (a frame callback keeps going too).
        console.error('[vision] frame handler failed', error);
      } finally {
        this.frame = null;
        frame.close();
      }
    }
  }
}
