/**
 * Everything that is read rather than watched: the score and best, the phase messages, the
 * "hold the pose" ring, the curl warning, and the score popups that float up from events.
 *
 * Sizes are world units (1080 high), so the text is the same share of the screen on any
 * display; big enough to read from a sofa. Text is re-rendered only when what it says
 * changes, at the resolution it is actually shown at so it stays crisp under the pixel cap.
 */
import { Container, Sprite, Text, type TextStyleOptions } from 'pixi.js';
import type { Rect } from '../core/view';
import type { Game, GameEvent } from '../game/types';
import { FONT_STACK } from './fonts';
import { type ShadedQuad, shadedQuad } from './gl';
import { glsl, PALETTE as P } from './palette';
import type { StageTextures } from './textures';

function style(
  size: number,
  fill: number = P.text,
  stroke: number = P.textStroke,
): TextStyleOptions {
  return {
    fontFamily: FONT_STACK,
    fontWeight: '700',
    fontSize: size,
    fill,
    stroke: { color: stroke, width: Math.max(4, size * 0.16), join: 'round' },
    dropShadow: {
      color: P.textStroke,
      alpha: 0.35,
      blur: size * 0.06,
      distance: size * 0.07,
      angle: Math.PI / 2,
    },
    align: 'center',
    letterSpacing: size * 0.02,
    padding: size * 0.25,
  };
}

const RING_FRAGMENT = `#version 300 es
precision highp float;
in vec2 vUV;
out vec4 finalColor;
uniform vec4 uColor;
uniform float uProgress;
void main() {
  vec2 q = vUV * 2.0 - 1.0;
  float r = length(q);
  float aa = fwidth(r) * 1.2;
  float f = fract(atan(q.x, -q.y) / 6.2832 + 1.0);
  float band = smoothstep(0.75 - aa, 0.75 + aa, r) * smoothstep(0.95 + aa, 0.95 - aa, r);
  float rim = smoothstep(0.69 - aa, 0.69 + aa, r) * smoothstep(1.0 + aa, 1.0 - aa, r);
  float disc = smoothstep(0.72 + aa, 0.72 - aa, r);
  float da = aa / 5.3;
  float filled = smoothstep(uProgress + da, uProgress - da, f) * step(0.001, uProgress);
  vec3 fill = mix(${glsl(P.accent)}, ${glsl(P.good)}, smoothstep(0.6, 1.0, uProgress));
  vec4 c = vec4(${glsl(P.textStroke)}, 1.0) * 0.4 * disc;
  c = mix(c, vec4(${glsl(P.textStroke)}, 1.0), rim * 0.9);
  c = mix(c, vec4(mix(vec3(0.75, 0.86, 0.92), fill, filled), 1.0), band);
  finalColor = c * uColor;
}
`;

/** A line of text that pops in when it changes and fades out when cleared. */
class Line {
  readonly text: Text;
  private wanted = '';
  private shown = '';
  private t = 1;
  private leaving = false;
  /** Size multiplier for a little emphasis wobble. */
  pulse = 0;

  constructor(size: number, fill?: number) {
    this.text = new Text({ text: '', style: style(size, fill) });
    this.text.anchor.set(0.5);
    this.text.visible = false;
  }

  set(value: string): void {
    if (value === this.wanted) return;
    this.wanted = value;
    if (this.shown === '') this.enter();
    else this.leaving = true;
  }

  update(dtS: number): void {
    const text = this.text;
    if (this.leaving) {
      this.t -= dtS / 0.18;
      if (this.t <= 0) {
        this.t = 0;
        this.leaving = false;
        if (this.wanted === '') {
          this.shown = '';
          text.visible = false;
          return;
        }
        this.enter();
      }
      text.alpha = this.t;
      text.scale.set(0.9 + 0.1 * this.t);
      return;
    }
    if (this.shown === '') return;
    this.t = Math.min(1, this.t + dtS / 0.32);
    this.pulse = Math.max(0, this.pulse - dtS * 3);
    // Ease out with a small overshoot.
    const e = this.t;
    const pop = 1 + 0.18 * Math.sin(e * Math.PI) * (1 - e * 0.5);
    text.alpha = Math.min(1, e * 2);
    text.scale.set((0.6 + 0.4 * (1 - (1 - e) ** 3)) * pop + 0.06 * Math.sin(this.pulse * Math.PI));
  }

  private enter(): void {
    this.shown = this.wanted;
    this.text.text = this.wanted;
    this.text.visible = true;
    this.t = 0;
  }

  clear(): void {
    this.wanted = '';
    this.shown = '';
    this.leaving = false;
    this.text.visible = false;
  }
}

const POPUPS = 8;
const POPUP_S = 1.3;
/** A pickup this soon after the last one adds to its popup instead of starting another. */
const COMBO_S = 0.75;

export type PopupKind = 'small' | 'normal' | 'big' | 'shout';
const POPUP_SIZE: Record<PopupKind, number> = { small: 48, normal: 54, big: 68, shout: 66 };

/**
 * "+100" and friends, floating up from where they were earned. Screen space (world units
 * before the camera), so they can be kept inside the safe area whatever the camera does.
 * They never pile up: stars taken in a run count up in one popup, and a popup that would
 * land on another one is lifted clear of it.
 */
export class Popups {
  readonly container = new Container();
  private readonly texts: Text[] = [];
  private readonly age = new Float32Array(POPUPS);
  private readonly baseX = new Float32Array(POPUPS);
  private readonly baseY = new Float32Array(POPUPS);
  private readonly height = new Float32Array(POPUPS);
  private next = 0;
  private safe: Rect = { x: 0, y: 0, width: 1920, height: 1080 };
  /** The popup counting up a run of stars, and its total. */
  private combo = -1;
  private comboPoints = 0;

  constructor() {
    for (let i = 0; i < POPUPS; i++) {
      const text = new Text({ text: '', style: style(54, P.accent) });
      text.anchor.set(0.5);
      text.visible = false;
      this.texts.push(text);
      this.container.addChild(text);
      this.age[i] = POPUP_S;
    }
  }

  setResolution(resolution: number): void {
    for (const text of this.texts) text.resolution = resolution;
  }

  setSafeArea(safe: Rect): void {
    this.safe = safe;
  }

  /**
   * Creatures. With the game's `combo` (2 and up = chained) one popup counts the chain up,
   * "x3!" under the total, bigger with every link. Without it (an older game), a quick run
   * of pickups still shares one popup.
   */
  spawnPickup(x: number, y: number, points: number, combo: number | undefined): void {
    const i = this.combo;
    const alive = i >= 0 && (this.age[i] as number) < (combo === undefined ? COMBO_S : POPUP_S);
    const chained = combo === undefined ? alive : combo > 1 && alive;
    if (chained) {
      this.comboPoints += points;
      const link = combo ?? 0;
      const label = link > 1 ? `+${this.comboPoints}\nx${link}!` : `+${this.comboPoints}`;
      this.place(
        i,
        x,
        y,
        label,
        link >= 4 ? P.warm : P.accent,
        'small',
        1 + 0.07 * Math.min(6, link),
      );
      return;
    }
    this.comboPoints = points;
    this.combo = this.spawn(x, y, `+${points}`, P.accent, 'small');
  }

  /** Returns the slot used. */
  spawn(x: number, y: number, label: string, color: number, kind: PopupKind): number {
    const i = this.next;
    this.next = (this.next + 1) % POPUPS;
    if (i === this.combo) this.combo = -1;
    this.place(i, x, y, label, color, kind);
    return i;
  }

  private place(
    i: number,
    x: number,
    y: number,
    label: string,
    color: number,
    kind: PopupKind,
    grow = 1,
  ) {
    const text = this.texts[i] as Text;
    if (text.text !== label) text.text = label;
    text.style.fill = color;
    const size = Math.round(POPUP_SIZE[kind] * grow);
    text.style.fontSize = size;
    const lines = label.split('\n').length;
    const h = size * 1.15 * lines;
    const w = text.width / Math.max(0.01, text.scale.x);
    // Inside the safe area, with room for the rise.
    const safe = this.safe;
    const px = Math.min(safe.x + safe.width - w / 2 - 10, Math.max(safe.x + w / 2 + 10, x));
    let py = Math.min(safe.y + safe.height - h, Math.max(safe.y + 150 + h / 2, y));
    // Lift it clear of any young popup it would land on.
    for (let pass = 0; pass < 3; pass++) {
      let moved = false;
      for (let k = 0; k < POPUPS; k++) {
        if (k === i || (this.age[k] as number) >= POPUP_S * 0.6) continue;
        const other = this.texts[k] as Text;
        const gap = ((this.height[k] as number) + h) / 2 + 6;
        if (Math.abs(other.x - px) < 170 && Math.abs(other.y - py) < gap) {
          py = other.y - gap;
          moved = true;
        }
      }
      if (!moved) break;
    }
    py = Math.max(safe.y + h / 2, py);
    text.position.set(px, py);
    text.visible = true;
    this.age[i] = 0;
    this.baseX[i] = px;
    this.baseY[i] = py;
    this.height[i] = h;
  }

  update(dtS: number): void {
    for (let i = 0; i < POPUPS; i++) {
      const age = this.age[i] as number;
      if (age >= POPUP_S) continue;
      const next = age + dtS;
      this.age[i] = next;
      const text = this.texts[i] as Text;
      if (next >= POPUP_S) {
        text.visible = false;
        continue;
      }
      const t = next / POPUP_S;
      // Up by a little, quickly, then hang there to be read.
      const rise = 1 - (1 - t) ** 4;
      text.y = (this.baseY[i] as number) - 70 * rise;
      const pop = t < 0.1 ? 0.5 + 0.7 * (t / 0.1) : 1.2 - 0.2 * Math.min(1, (t - 0.1) / 0.12);
      text.scale.set(pop);
      text.alpha = t < 0.75 ? 1 : 1 - (t - 0.75) / 0.25;
    }
  }

  clear(): void {
    for (let i = 0; i < POPUPS; i++) {
      this.age[i] = POPUP_S;
      (this.texts[i] as Text).visible = false;
    }
    this.combo = -1;
  }
}

/** Seconds of coaching at the start of a ride. */
const COACH_S = 4.5;
/** The speed-up hint: shown at this curl danger, for this long, at most this often. */
const HINT_DANGER = 0.55;
const HINT_S = 2.5;
const HINT_EVERY_S = 12;
/** Seconds the takeoff's first line stays before the steering hint. */
const TAKEOFF_FIRST_S = 1.4;

export class HudView {
  readonly container = new Container();
  private readonly scoreLabel: Text;
  private readonly scoreValue: Text;
  private readonly bestLabel: Text;
  private readonly bestValue: Text;
  private readonly title = new Line(88);
  private readonly subtitle = new Line(46);
  private readonly badge = new Line(60, P.accent);
  /** Riding hints sit low, over the flat water, clear of the surfer and the lip. */
  private readonly coach = new Line(46);
  private readonly pictogram: Sprite;
  private readonly ring: ShadedQuad<{ uProgress: { value: number; type: 'f32' } }>;
  private readonly warning: Sprite;
  private worldWidth = 1920;

  private shownScore = 0;
  private scoreText = -1;
  private bestText = -1;
  private scorePulse = 0;
  private ringAlpha = 0;
  private warn = 0;
  private timeS = 0;
  private wipe: { score: number; newBest: boolean } | null = null;
  /** "Score 1,234" for the current wipeout, built once when it happens. */
  private wipeLabel = '';
  /** The "speed up" hint: seconds left on screen, and before it may come back. */
  private hintS = 0;
  private hintCoolS = 0;

  constructor(textures: StageTextures) {
    this.scoreLabel = new Text({ text: 'SCORE', style: style(30) });
    this.scoreValue = new Text({ text: '0', style: style(76) });
    this.bestLabel = new Text({ text: 'BEST', style: style(30) });
    this.bestValue = new Text({ text: '0', style: style(50) });
    this.scoreLabel.anchor.set(0, 0);
    this.scoreValue.anchor.set(0, 0);
    this.bestLabel.anchor.set(1, 0);
    this.bestValue.anchor.set(1, 0);

    this.warning = new Sprite(textures.edgeFade);
    // The curl's shadow creeping in from the left: darker, not a colour, so it never tints
    // the sky or the foam.
    this.warning.tint = P.textStroke;
    this.warning.alpha = 0;

    this.ring = shadedQuad('pose-ring', RING_FRAGMENT, 'ringUniforms', {
      uProgress: { value: 0, type: 'f32' },
    });
    this.pictogram = new Sprite(textures.pictogram);
    this.pictogram.anchor.set(0.5);

    this.container.addChild(
      this.warning,
      this.scoreLabel,
      this.scoreValue,
      this.bestLabel,
      this.bestValue,
      this.ring.mesh,
      this.pictogram,
      this.title.text,
      this.subtitle.text,
      this.badge.text,
      this.coach.text,
    );
  }

  /** Lay out in the safe area. `resolution` = device pixels per world unit. */
  setLayout(safe: Rect, worldWidth: number, worldHeight: number, resolution: number): void {
    this.worldWidth = worldWidth;
    for (const text of this.texts()) text.resolution = resolution;
    const cx = safe.x + safe.width / 2;
    this.scoreLabel.position.set(safe.x + 8, safe.y);
    this.scoreValue.position.set(safe.x + 2, safe.y + 26);
    this.bestLabel.position.set(safe.x + safe.width - 8, safe.y);
    this.bestValue.position.set(safe.x + safe.width - 4, safe.y + 26);
    this.title.text.position.set(cx, safe.y + 120);
    this.subtitle.text.position.set(cx, safe.y + 200);
    this.badge.text.position.set(cx, safe.y + 292);
    this.coach.text.position.set(cx, safe.y + safe.height - 50);
    const ringSize = 190;
    this.ring.mesh.position.set(cx - ringSize / 2, safe.y + 380 - ringSize / 2);
    this.ring.mesh.scale.set(ringSize);
    this.pictogram.position.set(cx, safe.y + 380);
    this.pictogram.scale.set(1.05);
    this.warning.position.set(0, 0);
    this.warning.width = Math.min(520, worldWidth * 0.28);
    this.warning.height = worldHeight;
  }

  /** Texts that need re-rendering when the resolution changes. */
  private texts(): Text[] {
    return [
      this.scoreLabel,
      this.scoreValue,
      this.bestLabel,
      this.bestValue,
      this.title.text,
      this.subtitle.text,
      this.badge.text,
      this.coach.text,
    ];
  }

  update(game: Game, events: readonly GameEvent[], dtS: number, curlDanger: number): void {
    this.timeS += dtS;
    for (const event of events) {
      if (event.type === 'wipeout') {
        this.wipe = { score: event.score, newBest: event.newBest };
        this.wipeLabel = `Score ${Math.round(event.score).toLocaleString('en-US')}`;
      }
      if (event.type === 'phase' && event.phase !== 'wipeout') this.wipe = null;
      if (event.type === 'pickup' || event.type === 'land' || event.type === 'carve') {
        this.scorePulse = 1;
      }
    }

    // Score: counts up to the real value, quickly for small steps.
    const target = game.score;
    if (target < this.shownScore) this.shownScore = target;
    else this.shownScore += Math.max(1, (target - this.shownScore) * Math.min(1, dtS * 8));
    if (this.shownScore > target) this.shownScore = target;
    const shown = Math.round(this.shownScore);
    if (shown !== this.scoreText) {
      this.scoreText = shown;
      this.scoreValue.text = shown.toLocaleString('en-US');
    }
    this.scorePulse = Math.max(0, this.scorePulse - dtS * 4);
    this.scoreValue.scale.set(1 + 0.12 * Math.sin(this.scorePulse * Math.PI));
    if (game.best !== this.bestText) {
      this.bestText = game.best;
      this.bestValue.text = Math.round(game.best).toLocaleString('en-US');
    }

    this.updateMessages(game, curlDanger, dtS);
    this.title.update(dtS);
    this.subtitle.update(dtS);
    this.badge.update(dtS);
    this.coach.update(dtS);

    // The pose ring, while waiting.
    const waiting = game.phase === 'waiting';
    this.ringAlpha += ((waiting ? 1 : 0) - this.ringAlpha) * Math.min(1, dtS * 6);
    const ringOn = this.ringAlpha > 0.01;
    this.ring.mesh.visible = ringOn;
    this.pictogram.visible = ringOn;
    if (ringOn) {
      const hold = waiting ? game.control.poseHold : 1;
      this.ring.uniforms.uProgress = hold;
      this.ring.mesh.alpha = this.ringAlpha;
      const nudge = game.control.posed ? 1 + 0.05 * Math.sin(this.timeS * 10) : 1;
      // Arms waggle gently to show what to do.
      this.pictogram.rotation = game.control.posed ? 0 : 0.12 * Math.sin(this.timeS * 2.4);
      this.pictogram.alpha = this.ringAlpha;
      this.pictogram.scale.set(1.05 * nudge);
    }

    // The curl warning: a warm glow pulsing in from the left edge.
    this.warn += (curlDanger - this.warn) * Math.min(1, dtS * 5);
    const pulse = 0.75 + 0.25 * Math.sin(this.timeS * (6 + 6 * this.warn));
    this.warning.alpha = 0.5 * this.warn * pulse;
    this.warning.visible = this.warning.alpha > 0.005;
  }

  private updateMessages(game: Game, danger: number, dtS: number): void {
    // The curl is catching up: say how to get away, briefly, and not every second.
    this.hintS = Math.max(0, this.hintS - dtS);
    this.hintCoolS = Math.max(0, this.hintCoolS - dtS);
    if (game.phase !== 'riding') this.hintS = 0;
    else if (danger > HINT_DANGER && this.hintCoolS === 0 && game.rideS > COACH_S) {
      this.hintS = HINT_S;
      this.hintCoolS = HINT_EVERY_S;
    }
    let title = '';
    let subtitle = '';
    let badge = '';
    let coach = '';
    switch (game.phase) {
      case 'waiting':
        title = 'Arms out like a surfer!';
        subtitle = game.control.tracked ? '' : 'Step in front of the camera';
        break;
      case 'takeoff':
        title = game.phaseS < TAKEOFF_FIRST_S ? 'Here comes the wave!' : 'Tilt your arms to steer';
        break;
      case 'riding':
        if (game.rideS < COACH_S) coach = 'Lean down to go fast, up to climb';
        else if (this.hintS > 0) coach = 'Dive down to speed away!';
        break;
      case 'wipeout':
        if (game.phaseS > 0.25) {
          title = 'Wipeout!';
          subtitle = this.wipeLabel;
          if (this.wipe?.newBest && game.phaseS > 0.6) badge = 'New best!';
        }
        break;
    }
    this.title.set(title);
    this.subtitle.set(subtitle);
    this.badge.set(badge);
    this.coach.set(coach);
    if (badge) this.badge.pulse = this.badge.pulse > 0 ? this.badge.pulse : 1;
  }

  clear(): void {
    this.shownScore = 0;
    this.scoreText = -1;
    this.title.clear();
    this.subtitle.clear();
    this.badge.clear();
    this.coach.clear();
    this.wipeLabel = '';
    this.wipe = null;
    this.hintS = 0;
    this.hintCoolS = 0;
    this.warn = 0;
    this.warning.visible = false;
  }

  dispose(): void {
    this.ring.destroy();
    this.container.destroy({ children: true });
  }

  get width(): number {
    return this.worldWidth;
  }
}
