/** Window for the frame-time percentile: about four seconds at 60 fps. */
const WINDOW = 256;
/** Recomputing the percentile means a sort, so it runs a few times a second, not per frame. */
const PERCENTILE_EVERY = 15;
/** Time constant of the fps smoothing. */
const FPS_SMOOTHING_MS = 500;

/** Smoothed fps and a rolling 95th-percentile frame time, in preallocated typed arrays. */
export class FrameStats {
  fps = 0;
  frameMsP95 = 0;

  private readonly samples = new Float32Array(WINDOW);
  private readonly sorted = new Float32Array(WINDOW);
  private count = 0;
  private next = 0;
  private sinceSort = 0;

  /** Record the time since the previous frame. */
  add(frameMs: number): void {
    if (!(frameMs > 0)) return;
    const instant = 1000 / frameMs;
    const k = 1 - Math.exp(-frameMs / FPS_SMOOTHING_MS);
    this.fps = this.count === 0 ? instant : this.fps + (instant - this.fps) * k;

    this.samples[this.next] = frameMs;
    this.next = (this.next + 1) % WINDOW;
    if (this.count < WINDOW) this.count++;
    if (++this.sinceSort >= PERCENTILE_EVERY || this.count < PERCENTILE_EVERY) {
      this.sinceSort = 0;
      this.frameMsP95 = this.percentile(0.95);
    }
  }

  /** Forget history, e.g. after the loop was stopped, so the pause is not counted as a frame. */
  reset(): void {
    this.count = 0;
    this.next = 0;
    this.sinceSort = 0;
    this.fps = 0;
    this.frameMsP95 = 0;
  }

  private percentile(p: number): number {
    const { sorted, samples, count } = this;
    sorted.set(samples);
    // Unfilled slots sort to the end, so the first `count` entries are the real samples.
    sorted.fill(Number.POSITIVE_INFINITY, count);
    sorted.sort();
    return sorted[Math.min(count - 1, Math.ceil(p * count) - 1)] ?? 0;
  }
}
