/**
 * Records the live camera stream to a downloaded file, so real play can be replayed later
 * with "Load clip" to judge detection quality. If the camera goes away mid-recording
 * (unplugged, switched), the recorder stops by itself and what it captured is still saved.
 */
import { formatDuration } from './format';

/** Cheapest encoder first: recording should take as little CPU as possible from the game it is measuring. */
const MIME_TYPES = ['video/webm;codecs=vp8', 'video/webm;codecs=vp9', 'video/webm', 'video/mp4'];
/** High enough that compression barely changes what the model sees on replay. */
const VIDEO_BITS_PER_SECOND = 8_000_000;
/** Chunks keep the size readout live and spread the encoder's output over time. */
const TIMESLICE_MS = 1000;
/** The recording is held in memory until saved: ten minutes is about 600 MB. */
export const MAX_RECORDING_MS = 10 * 60_000;
const TICK_MS = 500;
/** Long enough for the browser to start the download before the URL is revoked. */
const REVOKE_AFTER_MS = 60_000;

export interface SavedClip {
  name: string;
  bytes: number;
  durationMs: number;
  /** Why it stopped when the user did not stop it. */
  endedBy: 'user' | 'camera' | 'limit';
}

export interface RecorderListener {
  /** Started, stopped, or another half-second elapsed. */
  onChange(): void;
  onSaved(clip: SavedClip): void;
  onError(message: string): void;
}

export interface ClipRecorder {
  readonly recording: boolean;
  readonly elapsedMs: number;
  readonly bytes: number;
  /** Throws an Error with a readable message if recording cannot start. */
  start(stream: MediaStream): void;
  /** Finish and download the clip. */
  stop(): void;
  /** Stop without saving and release everything. */
  dispose(): void;
}

export function pickMimeType(isSupported: (type: string) => boolean): string | null {
  return MIME_TYPES.find((type) => isSupported(type)) ?? null;
}

/** `surf-20261003-153012-1280x720.webm`: sortable, and says what was recorded. */
export function clipFileName(start: Date, width: number, height: number, mimeType: string): string {
  const pad = (value: number) => String(value).padStart(2, '0');
  const date = `${start.getFullYear()}${pad(start.getMonth() + 1)}${pad(start.getDate())}`;
  const time = `${pad(start.getHours())}${pad(start.getMinutes())}${pad(start.getSeconds())}`;
  const extension = mimeType.includes('mp4') ? 'mp4' : 'webm';
  return `surf-${date}-${time}-${width}x${height}.${extension}`;
}

interface Session {
  recorder: MediaRecorder;
  chunks: Blob[];
  bytes: number;
  startedAt: Date;
  startedMs: number;
  width: number;
  height: number;
  endedBy: SavedClip['endedBy'];
  discard: boolean;
  ticker: ReturnType<typeof setInterval>;
  limit: ReturnType<typeof setTimeout>;
}

export function createClipRecorder(listener: RecorderListener): ClipRecorder {
  let session: Session | null = null;
  let disposed = false;
  const downloads = new Map<string, ReturnType<typeof setTimeout>>();

  const download = (blob: Blob, name: string): void => {
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = name;
    link.click();
    downloads.set(
      url,
      setTimeout(() => {
        URL.revokeObjectURL(url);
        downloads.delete(url);
      }, REVOKE_AFTER_MS),
    );
  };

  const finish = (current: Session): void => {
    clearInterval(current.ticker);
    clearTimeout(current.limit);
    if (session === current) session = null;
    if (disposed || current.discard) return;
    const durationMs = performance.now() - current.startedMs;
    if (current.bytes === 0) {
      listener.onError('Nothing was recorded: the camera sent no frames.');
    } else {
      const type = current.recorder.mimeType || current.chunks[0]?.type || 'video/webm';
      const blob = new Blob(current.chunks, { type });
      const name = clipFileName(current.startedAt, current.width, current.height, type);
      download(blob, name);
      listener.onSaved({ name, bytes: blob.size, durationMs, endedBy: current.endedBy });
    }
    current.chunks = [];
    listener.onChange();
  };

  const end = (current: Session, endedBy: SavedClip['endedBy']): void => {
    current.endedBy = endedBy;
    // Fires a last `dataavailable`, then `stop`, which saves.
    if (current.recorder.state !== 'inactive') current.recorder.stop();
  };

  return {
    get recording() {
      return session !== null;
    },
    get elapsedMs() {
      return session ? performance.now() - session.startedMs : 0;
    },
    get bytes() {
      return session?.bytes ?? 0;
    },

    start(stream) {
      if (session || disposed) return;
      if (typeof MediaRecorder === 'undefined') throw new Error('this browser cannot record video');
      const track = stream.getVideoTracks().find((candidate) => candidate.readyState === 'live');
      if (!track) throw new Error('the camera is not sending video');
      const mimeType = pickMimeType((type) => MediaRecorder.isTypeSupported(type));
      const recorder = new MediaRecorder(stream, {
        ...(mimeType ? { mimeType } : {}),
        videoBitsPerSecond: VIDEO_BITS_PER_SECOND,
      });
      const settings = track.getSettings();
      const current: Session = {
        recorder,
        chunks: [],
        bytes: 0,
        startedAt: new Date(),
        startedMs: performance.now(),
        width: settings.width ?? 0,
        height: settings.height ?? 0,
        // Anything other than our own stop() means the stream ended under us.
        endedBy: 'camera',
        discard: false,
        ticker: setInterval(() => listener.onChange(), TICK_MS),
        limit: setTimeout(() => end(current, 'limit'), MAX_RECORDING_MS),
      };
      recorder.addEventListener('dataavailable', (event) => {
        if (event.data.size === 0) return;
        current.chunks.push(event.data);
        current.bytes += event.data.size;
      });
      recorder.addEventListener('error', (event) => {
        const reason = event.error?.message ?? 'unknown error';
        if (!disposed) listener.onError(`Recording failed: ${reason}`);
      });
      recorder.addEventListener('stop', () => finish(current));
      try {
        recorder.start(TIMESLICE_MS);
      } catch (error) {
        clearInterval(current.ticker);
        clearTimeout(current.limit);
        throw error;
      }
      session = current;
      listener.onChange();
    },

    stop() {
      if (session) end(session, 'user');
    },

    dispose() {
      disposed = true;
      if (session) {
        session.discard = true;
        clearInterval(session.ticker);
        clearTimeout(session.limit);
        if (session.recorder.state !== 'inactive') session.recorder.stop();
        session = null;
      }
      for (const [url, timer] of downloads) {
        clearTimeout(timer);
        URL.revokeObjectURL(url);
      }
      downloads.clear();
    },
  };
}

/** "Stop recording (1:23)" style label for the elapsed time. */
export function recordingLabel(recorder: ClipRecorder): string {
  return recorder.recording
    ? `Stop recording (${formatDuration(recorder.elapsedMs)})`
    : 'Record clip';
}
