import type { Sfx } from '../audio';
import type { Params } from '../config/params';
import type { Tunables } from '../config/tunables';
import type { Unsubscribe } from '../core/events';
import type { PersonMask } from '../core/mask';
import type { PoseFrame } from '../core/pose';
import { createRng } from '../core/rng';
import { computeView, type ViewTransform } from '../core/view';
import type { DebugUi } from '../debug';
import { createGame, type Game } from '../game';
import type { Stage } from '../render';
import { DEFAULT_LAYOUT, type RegionLayout, type VisionPipeline } from '../vision';

/** Side of the segmentation model's square input. */
export const MODEL_INPUT_SIZE = 256;
/** Arm tilt (radians) an arrow key asks for, and how fast the keyboard tilt gets there. */
const KEY_TILT = 0.6;
const KEY_TILT_RATE = 4;

export function layoutFor(tunables: Tunables): RegionLayout {
  if (tunables.stretchInput || DEFAULT_LAYOUT.mode !== 'tiles') return { mode: 'stretch' };
  const { minOverlap } = DEFAULT_LAYOUT;
  // One tile on the player, the tiles (same size) whenever there is nobody to follow.
  const mode = tunables.followPlayer ? 'follow' : 'tiles';
  return { mode, tileHeight: tunables.tileHeight, minOverlap };
}

export interface SessionDeps {
  params: Params;
  tunables: Tunables;
  stage: Stage;
  sfx: Sfx;
  debug: DebugUi;
  /** Already started. The session owns it from here and disposes it. */
  vision: VisionPipeline;
  /** Best score so far, and where to put a new one. */
  best: number;
  saveBest(best: number): void;
}

/**
 * One run of the game, from a successful start until the camera is lost. Owns the game and
 * the per-frame order of operations: newest pose → simulation step → sounds → visuals.
 */
export class PlaySession {
  readonly vision: VisionPipeline;
  readonly game: Game;
  lastMask: PersonMask | null = null;
  lastPose: PoseFrame | null = null;
  /** Arrow keys held (`?keys`): -1 nose down, 1 nose up. */
  keySteer = 0;
  view: ViewTransform;

  private readonly tunables: Tunables;
  private readonly stage: Stage;
  private readonly sfx: Sfx;
  private readonly debug: DebugUi;
  private readonly unsubscribe: Unsubscribe[] = [];
  // The mask size depends on the layout and the camera's aspect ratio, so it is only known
  // once a mask arrives. Until then any size works because nothing samples a mask.
  private maskWidth = MODEL_INPUT_SIZE;
  private maskHeight = MODEL_INPUT_SIZE;
  private readonly keys: boolean;
  private readonly saveBest: (best: number) => void;
  private keyTilt = 0;
  private paused = false;
  private disposed = false;

  constructor(deps: SessionDeps) {
    this.vision = deps.vision;
    this.tunables = deps.tunables;
    this.stage = deps.stage;
    this.sfx = deps.sfx;
    this.debug = deps.debug;
    this.keys = deps.params.keys;
    this.saveBest = deps.saveBest;
    this.view = this.computeView();
    this.game = createGame({
      best: deps.best,
      tunables: deps.tunables,
      rng: createRng(deps.params.seed ?? Date.now() & 0xffffffff),
      view: this.view,
    });
  }

  start(): void {
    const { stage, vision } = this;
    this.unsubscribe.push(vision.onSourceChange(() => this.applyView()));
    // The player on the board is cut out of the exact frame each mask was made from.
    vision.setPairing(true);
    stage.setView(this.view);
    this.applySettings();
    stage.setTick(this.tick);
    stage.start();
  }

  /** Tab hidden: stop everything that costs CPU, GPU or attention. */
  pause(): void {
    if (this.paused || this.disposed) return;
    this.paused = true;
    this.vision.pause();
    this.stage.stop();
    this.sfx.suspend();
  }

  resume(): void {
    if (!this.paused || this.disposed) return;
    this.paused = false;
    this.vision.resume();
    this.stage.start();
    this.sfx.resume();
  }

  /** Re-read the tunables that are applied on change rather than every frame. */
  applySettings(): void {
    const { tunables, vision } = this;
    this.sfx.applyVolume();
    vision.setLayout(layoutFor(tunables));
    vision.setMaskPoseWait(tunables.maskPoseWait);
    this.applyView();
  }

  /** Recompute placement after the screen, source, mask size or view tunables change. */
  applyView(): void {
    if (this.disposed) return;
    this.view = this.computeView();
    this.stage.setView(this.view);
    this.game.setView(this.view);
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    for (const off of this.unsubscribe) off();
    // A session can end while the tab is hidden (the camera drops on wake). Leave the
    // sound running for the next session rather than suspended with nobody to resume it.
    if (this.paused) this.sfx.resume();
    const { stage } = this;
    stage.setTick(null);
    // Leave the stage as it was before this session.
    stage.clear();
    this.sfx.stopGame();
    stage.setAvatarFrame(null);
    stage.stop();
    this.vision.dispose();
  }

  private computeView(): ViewTransform {
    const source = this.vision.sourceInfo;
    return computeView({
      screenWidth: this.stage.screenWidth,
      screenHeight: this.stage.screenHeight,
      sourceWidth: source?.width ?? 16,
      sourceHeight: source?.height ?? 9,
      maskWidth: this.maskWidth,
      maskHeight: this.maskHeight,
      mirrored: this.tunables.mirror,
      safeMargin: this.tunables.safeMargin,
    });
  }

  private readonly tick = (dtMs: number, nowMs: number): void => {
    const { vision, game, stage, sfx } = this;
    const dtS = dtMs / 1000;

    // Steering first: the pose of a frame arrives before its mask.
    const pose = vision.takePose();
    if (pose) {
      this.lastPose = pose;
      game.applyPose(pose, nowMs);
    }
    if (this.keys) {
      const target = this.keySteer * KEY_TILT;
      const step = KEY_TILT_RATE * dtS;
      this.keyTilt += Math.max(-step, Math.min(step, target - this.keyTilt));
      game.setManualTilt(this.keyTilt);
    }

    const mask = vision.takeMask();
    if (mask) {
      this.lastMask = mask;
      if (mask.width !== this.maskWidth || mask.height !== this.maskHeight) {
        this.maskWidth = mask.width;
        this.maskHeight = mask.height;
        this.applyView();
      }
    }
    const pair = vision.takePair();
    if (pair) stage.setAvatarFrame(pair);

    game.step(dtS);
    const events = game.drainEvents();
    for (const event of events) {
      if (event.type === 'wipeout' && event.newBest) this.saveBest(event.best);
    }
    sfx.update(game, events, dtS);
    stage.update(game, events, dtMs);
    this.debug.update(nowMs);
  };
}
