export type PaletteName = keyof typeof PALETTE;

/** CSS colour for canvas drawing. */
export function css(rgb: number, alpha = 1): string {
  const r = (rgb >> 16) & 255;
  const g = (rgb >> 8) & 255;
  const b = rgb & 255;
  return alpha >= 1 ? `rgb(${r}, ${g}, ${b})` : `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

/** GLSL `vec3(...)` literal, for baking palette colours into shader source. */
export function glsl(rgb: number): string {
  const f = (shift: number) => (((rgb >> shift) & 255) / 255).toFixed(4);
  return `vec3(${f(16)}, ${f(8)}, ${f(0)})`;
}
