/**
 * Messages between the main thread and the segmenter worker, plus the config shared by
 * the worker and the main-thread fallback.
 *
 * This file is compiled for both DOM and WebWorker: keep it free of `document`/`window`
 * and DOM-only types.
 */

import type { RegionLayout } from './regions';

export type { RegionLayout } from './regions';

/**
 * `mediapipe` runs the real models. `chroma` reads the synthetic source's stick figure
 * instead: saturated colours are "person", and the joint markers are the pose (tests).
 */
export type SegmenterEngine = 'mediapipe' | 'chroma';

export type Delegate = 'GPU' | 'CPU';

/** MediaPipe ships one WASM build for module workers and a classic one for the page. */
export type WasmBuild = 'module' | 'classic';

/**
 * Test-only fault: after `afterFrames` segment calls, hang forever or fail every call.
 * Counted per backend instance, so a restarted or fallback segmenter works for another
 * `afterFrames` calls and then faults again: one fault walks the whole recovery chain.
 */
export interface FaultSpec {
  kind: 'hang' | 'throw';
  afterFrames: number;
}

/** What the injected fault does to the `call`-th (1-based) segment call, if anything. */
export function injectedFault(fault: FaultSpec | null, call: number): FaultSpec['kind'] | null {
  return fault && call > fault.afterFrames ? fault.kind : null;
}

/**
 * The GPU context the model runs on is gone (driver or GPU-process reset, display change).
 * It never comes back by itself, so the segmenter that owns it has to be replaced.
 */
export class GpuContextLost extends Error {
  constructor() {
    super('The graphics context of the segmenter was lost.');
    this.name = 'GpuContextLost';
  }
}

export interface SegmenterConfig {
  engine: SegmenterEngine;
  delegate: Delegate;
  /**
   * Absolute, versioned URL of MediaPipe's WASM loader script: the ES-module build inside a
   * module worker, the classic one on the main thread. Unused by the chroma engine.
   */
  wasmLoaderUrl: string;
  /** Which build `wasmLoaderUrl` is: they are loaded differently. */
  wasmBuild: WasmBuild;
  /**
   * The matching WASM binary, downloaded by the main thread and typed `application/wasm` so
   * it still compiles while streaming. Required for the `mediapipe` engine.
   */
  wasmBinary: Blob | null;
  /** Segmentation model bytes. Required for the `mediapipe` engine. */
  modelBuffer: ArrayBuffer | null;
  /** Pose landmarker model bytes (a `.task` bundle). Required for the `mediapipe` engine. */
  poseModelBuffer: ArrayBuffer | null;
  /** Side of the model's square input, in pixels. */
  inputSize: number;
  /** Which parts of each frame are fed to the model. Can be changed later with `layout`. */
  layout: RegionLayout;
  fault: FaultSpec | null;
}

export interface SegmenterCoreInfo {
  engine: SegmenterEngine;
  delegate: Delegate;
  inputSize: number;
  /** Unmasked WebGL renderer string, when available. */
  glRenderer: string | null;
  /** Duration of the warm-up inference run during init. */
  warmupMs: number;
}

export type WorkerRequest =
  | { type: 'init'; config: SegmenterConfig }
  | {
      type: 'segment';
      id: number;
      /** Transferred; the worker closes it. */
      frame: VideoFrame;
      /**
       * This frame does not follow on from the previous one (new source, resumed, clip
       * looped), so the pose tracker must look for the person afresh.
       */
      fresh: boolean;
      /** A previously returned mask buffer to reuse, if the caller has one spare. */
      recycle: ArrayBuffer | null;
      /**
       * When the next source frame is expected, in ms from when this one was sent (Infinity
       * if unknown): the mask may be skipped to keep that frame's pose on time.
       */
      nextFrameInMs: number;
      /** The source's frame interval in ms (Infinity if unknown). */
      frameIntervalMs: number;
      /** How long (frames) a mask may make the next pose wait. */
      poseWaitFrames: number;
    }
  /** Change the region layout; applies from the next `segment`. */
  | { type: 'layout'; layout: RegionLayout }
  | { type: 'dispose' };

export type WorkerResponse =
  /** The runtime and model are loaded; the warm-up inference is starting. */
  | { type: 'warmup' }
  | { type: 'ready'; info: SegmenterCoreInfo }
  | { type: 'init-error'; message: string }
  /**
   * The pose of a `segment` request's frame, sent as soon as it is known and always before
   * that request's `mask`, `skipped` (or `segment-error` for a later stage).
   */
  | {
      type: 'pose';
      id: number;
      /** `POSE_POINTS * POSE_STRIDE` floats, all zero when `present` is false. */
      landmarks: ArrayBuffer;
      present: boolean;
      /** Time the pose model took. */
      poseMs: number;
      /** Why the pose model failed on this frame (then `present` is false), or null. */
      error: string | null;
      /**
       * When the worker got the request and when the pose model started and finished, as
       * `performance.timeOrigin + performance.now()` (comparable across threads).
       */
      receivedAt: number;
      startAt: number;
      endAt: number;
    }
  | {
      type: 'mask';
      id: number;
      /**
       * P(person) as 0..255, `width * height` bytes, covering the whole frame. Transferred.
       * The size depends on the layout and the frame's aspect ratio.
       */
      data: ArrayBuffer;
      width: number;
      height: number;
      /** Total time for all regions of this frame. */
      inferMs: number;
      /** Number of model runs this frame took. */
      regions: number;
      /** When segmentation started and finished, on the same clock as the pose's. */
      startAt: number;
      endAt: number;
    }
  /** The request's final reply when its pose was sent but its mask skipped (maskPacer.ts). */
  | { type: 'skipped'; id: number }
  /** `contextLost`: the worker cannot segment any more, its GPU context is gone. */
  | { type: 'segment-error'; id: number; message: string; contextLost: boolean };
