/**
 * Helpers for the few custom-shaded meshes (sky, water, cutout, ring). Each is one quad
 * whose fragment shader does the drawing, so a whole layer costs one draw call and no
 * textures beyond what it samples.
 */
import { GlProgram, Mesh, MeshGeometry, Shader, type UniformData, UniformGroup } from 'pixi.js';

/**
 * Pixi's mesh vertex stage: `uTransformMatrix` is the mesh's own transform, the rest come
 * from the renderer. `vPos` is the vertex position in the mesh's local units (world units
 * for the scenery quads) and `vUV` runs 0..1 across the quad.
 */
export const QUAD_VERTEX = `#version 300 es
in vec2 aPosition;
in vec2 aUV;
uniform mat3 uProjectionMatrix;
uniform mat3 uWorldTransformMatrix;
uniform mat3 uTransformMatrix;
out vec2 vPos;
out vec2 vUV;
void main() {
  mat3 mvp = uProjectionMatrix * uWorldTransformMatrix * uTransformMatrix;
  gl_Position = vec4((mvp * vec3(aPosition, 1.0)).xy, 0.0, 1.0);
  vPos = aPosition;
  vUV = aUV;
}
`;

/**
 * GLSL helpers shared by the scenery shaders. The value noise tiles horizontally with a
 * given period (in lattice cells) so the scroll offset can wrap without a visible jump.
 */
export const NOISE_GLSL = `
float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
float vnoise(vec2 p, float period) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  float x0 = mod(i.x, period);
  float x1 = mod(i.x + 1.0, period);
  float a = hash12(vec2(x0, i.y));
  float b = hash12(vec2(x1, i.y));
  float c = hash12(vec2(x0, i.y + 1.0));
  float d = hash12(vec2(x1, i.y + 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
float fbm3(vec2 p, float period) {
  float v = 0.5 * vnoise(p, period);
  v += 0.25 * vnoise(p * 2.0 + vec2(17.3, 9.1), period * 2.0);
  v += 0.125 * vnoise(p * 4.0 + vec2(5.7, 31.4), period * 4.0);
  return v / 0.875;
}
// Ordered dither of +-half a level of 8-bit colour, against banding in the gradients.
float dither(vec2 frag) {
  return (hash12(floor(frag)) - 0.5) / 255.0;
}
`;

/**
 * World distance every scrolled noise pattern repeats over. Each pattern's lattice period
 * divides it, so the scroll can wrap at this value without a seam.
 */
export const SCROLL_PERIOD = 8192;

/** A quad with corners at (0,0)..(1,1) in both position and uv; place it with the transform. */
export function unitQuad(): MeshGeometry {
  return new MeshGeometry({
    positions: new Float32Array([0, 0, 1, 0, 1, 1, 0, 1]),
    uvs: new Float32Array([0, 0, 1, 0, 1, 1, 0, 1]),
    indices: new Uint32Array([0, 1, 2, 0, 2, 3]),
  });
}

/** Move a quad's corners in place (positions only; uvs keep running 0..1). */
export function setQuad(geometry: MeshGeometry, x0: number, y0: number, x1: number, y1: number) {
  const positions = geometry.positions;
  positions[0] = x0;
  positions[1] = y0;
  positions[2] = x1;
  positions[3] = y0;
  positions[4] = x1;
  positions[5] = y1;
  positions[6] = x0;
  positions[7] = y1;
  geometry.getBuffer('aPosition').update();
}

export interface ShadedQuad<U extends Record<string, UniformData>> {
  mesh: Mesh<MeshGeometry, Shader>;
  geometry: MeshGeometry;
  uniforms: UniformGroup<U>['uniforms'];
  destroy(): void;
}

/**
 * A quad drawn by `fragment`, with the uniform block `name` built from `uniforms` and any
 * textures in `textures`. Uniform values are read every draw, so set them in place.
 */
export function shadedQuad<U extends Record<string, UniformData>>(
  label: string,
  fragment: string,
  name: string,
  uniforms: U,
  textures: Record<string, unknown> = {},
): ShadedQuad<U> {
  const group = new UniformGroup(uniforms);
  const shader = new Shader({
    glProgram: GlProgram.from({ vertex: QUAD_VERTEX, fragment, name: label }),
    resources: { [name]: group, ...textures },
  });
  const geometry = unitQuad();
  const mesh = new Mesh({ geometry, shader, label });
  return {
    mesh,
    geometry,
    uniforms: group.uniforms,
    destroy() {
      mesh.destroy();
      geometry.destroy();
      shader.destroy();
    },
  };
}
